INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_isl_quran', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Holy Quran', 'top_islamic', 214, 1790964553122) ON CONFLICT(id) DO UPDATE SET total_mcqs = 214;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_62085176de03bed0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', '"Muhammad is the messenger of Allah" is stated in Surah _____?', '{"A":"Surah Al-Muzzammil","B":"Surah Muhammad","C":"Surah Ya-Seen","D":"Surah Al-Fath"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Muhammad is the Messenger of Allah…” — Surah Al-Fath, 48:29Additional information:The name Muhammad ﷺ is mentioned 4 times in the Holy Quran:Aal-e-Imran 3:144Al-Ahzab 33:40Muhammad 47:2Al-Fath 48:29The name Ahmad ﷺ is mentioned once in Surah As-Saff 61:6.Surah Al-Fath is the 48th Surah of the Quran and has 29 verses.It was revealed in Madinah in the 6th year of Hijrah, in connection with the Treaty of Hudaybiyyah.', 0, 0, 0, 1790964553222) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2c3f85d97f22d0c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which surah of the Holy Quran has Bismillah twice?', '{"A":"Al Noor","B":"Al Nahl","C":"Al Naml","D":"Al Ra’d"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Naml has Bismillah twice in the Holy Quran.It contains Bismillah at the beginning and again in Verse 30 (message of Prophet Sulaiman AS).Surah: 27thVerses: 93rdType: Makki SurahName Meaning: “The Ants”Additional information:In contrast, Surah Al-Toba starts without Bismillah.Bismillahir Rahmanir Raheem is repeated 114 times in the Quran.Last verified on 12-06-2026', 0, 0, 0, 1790964553222) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4edb4fab1980d52f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many times the word Muhammad (PBUH) as a name has been mentioned in the Holy Quran?', '{"A":"Three times","B":"Four times","C":"Five times","D":"Six times"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The name "Muhammad" appears four times in the Quran.Surah Al-Imran (3:144)Surah Al-Ahzab (33:40)Surah Muhammad (47:2)Surah Al-Fath (48:29)Additional information:The name "Ahmad" is mentioned once in the Quran:Surah As-Saff (61:6)Surah Muhammad is the 47th surah of the Quran.It has 38 verses.Last verified on 25-04-2026', 0, 0, 0, 1790964553222) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_237b367988c0f275', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Surahs are there in the Holy Quran?', '{"A":"117","B":"114","C":"112","D":"115"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total Surahs: 114Total Paras (Juz): 30Total Manzils: 7Sajda-e-Tilawat: 14First Surah: Al-FatihahLast Surah: An-NasLongest Surah: Al-BaqarahShortest Surah: Al-KawtharLast updated: 13-09-2026', 0, 0, 0, 1790964553222) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f884df24b4f3875c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which surah of the Holy Quran starts without Bismillah (Tasmia)?', '{"A":"Younas","B":"Fatiha","C":"Naml","D":"Tauba"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Tauba does not begin with Bismillah.It is known by two names - At-Taubah and Al-Baraat.Surah Tauba is in 10 Parah.The number of Rukus in Surah Tauba is 16.Additional information:Bismillah is repeated in the Holy Quran 114 Times.Surah Naml surah of the Holy Quran has Bismillah twice.Last verified on 01-04-2026', 0, 0, 0, 1790964553222) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_59aea14d1dd90fbb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Prophets mentioned in Holy Quran?', '{"A":"25","B":"26","C":"27","D":"28"}', 'B', NULL, 0, 0, 0, 1790964553222) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d251f2648ebd9313', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'At whose request, Hazrat Abu Bakr (R.A) entrusted the task of compilation of the holy Quran to Zaid bin Sabitؓ?', '{"A":"Hazart Umar (R.A)","B":"Hazart Usman (R.A)","C":"Hazart Ali (R.A)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After the Battle of Yamama (632 AD), Hazrat Umar (R.A.) suggested compiling the Quran into one collection.Hazrat Abu Bakr (R.A.) initially hesitated but later accepted the suggestion.Hazrat Zaid bin Sabit (R.A.) was appointed to undertake the compilation.The compiled manuscript was kept with Hazrat Abu Bakr (R.A.), then Hazrat Umar (R.A.), and later Hazrat Hafsa (R.A.).Last verified on 13-09-2026', 0, 0, 0, 1790964553222) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9bf731e59edb207a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which surah is known as the Heart of Holy Quran?', '{"A":"Surah Yaseen","B":"Surah Rehman","C":"Surah Al-Baqara","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Yaseen is known as the "Heart of the Holy Quran."It is the 36th chapter of the Quran.It contains 83 verses.It is regarded as an earlier Meccan surah.Additional information:Surah Ar-Rahman: "Aroos ul Quran" (the Bride of the Quran).Al-Fatihah (The Opening)Al-Baqarah (The Cow)Aali Imran (The Family of Imran)An-Nisa (The Women)Al-Maidah (The Table)Last verified on 15-07-2026', 0, 0, 0, 1790964553222) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b84ca5a6de6ca9e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which is the longest (largest) surah in the Holy Quran?', '{"A":"Kousar","B":"Baqarah","C":"Al Imran","D":"None of the above"}', 'B', NULL, 0, 0, 0, 1790964553326) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9f154b704ce60b0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Surah Nisa is a Surah focus on ________', '{"A":"Rights of orphan","B":"Rights of woman","C":"Rights of parents","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Nisa is a Surah focus on the rights of women.Classification: MedinanPosition: Juzʼ 4–6Hizb no. 8, 9, 10 and 11No. of verses: 176No. of Rukus: 24No. of words: 3745No. of letters: 16085Last updated question NS on 09-09-2026', 0, 0, 0, 1790964553326) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_04c6abad2bc4c4c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Surah was the first to be revealed upon Holy Prophet Muhammad?', '{"A":"Surah al-Alaq","B":"Surah al-Falak","C":"Surah al-Fataha","D":"Surah al-Nisa"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first revealed Surah: Al-Alaq (96th Surah) when the Holy Prophet (PBUH) was 40 years and 6 monthsFirst Word Revealed: Iqra ( means: Read)Number of verses: 5Location of the first wahi: Cave Hira (Ghar-e-Hira), MakkahAngel: Jibril (A.S.)In: 610 ADLast updated by NA on 09-09-2026', 0, 0, 0, 1790964553326) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0f034f864dd487a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Prophet has been mentioned the most in Holy Quran?', '{"A":"Prophet Ibrahim (AS)","B":"Prophet Musa (AS)","C":"Prophet Nuh (AS)","D":"Prophet Essa (AS)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Musa (A.S) is mentioned about 136 times in the Holy Qur’an.Prophet Musa (A.S) was given the Torah (Tawrat) as a divine book.He is one of the Ulul-Azm prophets (the prophets of strong determination).Additional information:Ibrahim (A.S) – about 69 timesNuh (A.S) – about 43 timesLut (A.S) – about 27 timesIsa (A.S) – about 25 timesLast verified on 14-03-2026', 0, 0, 0, 1790964553326) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_491afb331d208b68', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The shortest Surah of the Holy Quran is _____?', '{"A":"Kausar","B":"Asr","C":"Ikhlas","D":"Falaq"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortest chapter in the Quran is Surah Al-KawtharMeaning: "The Abundance"Number of Verses: 3Placement: Chapter 108 in the 30th Juz (Para) of the QuranLocation of Revelation: Makkah (Makki)Additional informationThe second shortest surah in the Quran is Surah Al-AsrSurah Baqarah is the longest surah of the Holy Quran. (286 Verses). Last updated by NS on 5-09-2026', 0, 0, 0, 1790964553326) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c6e842e27d6ab6b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Holy Prophet Muhammad (PBUH) has been mentioned as Ahmed in which Surah of the Holy Quran?', '{"A":"Muhammad","B":"Al-Jinn","C":"Mudassir","D":"As-Saff"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name “Ahmed”, one time mentioned in the whole Quran in Surah As-Saff (61:6)It appears in Surah As-Saff (61:6) in the context of the prophecy of Isa (Jesus), son of Mary, about the coming of a messenger after him.ایسا سورہ الصف (61:6) میں عیسیٰ ابن مریم کی ایک پیغمبر کے بارے میں پیشین گوئی کے تناظر میں ظاہر ہوتا ہے جو ان کے بعد آئے گا۔Additional information: The name “Muhammad” is mentioned four times in the whole Quran.Surah Ali-Imran: ayat 144.Surah al-Ahzab: ayat 40.Surah Muhammad: ayat 2.Surah al-Fath: ayat 29Last updated by NS on 01 MAY 2026', 0, 0, 0, 1790964553326) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_12f53132e129bb17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Mosques are mentioned in the Holy Quran?', '{"A":"2","B":"3","C":"4","D":"5"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Five mosques mentioned in the Holy Qur''an are:Masjid al-Haram (Makkah)Masjid al-Aqsa (Jerusalem)Masjid al-Dirar (Masjid al-Zarrar)Masjid al-Nabawi (Madinah)Masjid Quba (Madinah)Last verified on 11-07-2026', 0, 0, 0, 1790964553326) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2777f73581485b15', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many times the word “Zakat” came together with “Salat” in Quran?', '{"A":"20 times","B":"32 times","C":"40 times","D":"42 times"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total mentions: 32 timesMakki Surahs: 22 timesMadani Surahs: 10 timesStatus: Third pillar of IslamPurpose: Purification of wealth & helping poorLast verified on 12-06-2026', 0, 0, 0, 1790964553326) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_80a2d0f40fa6f45f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In which Surah the Holy Quran there is mention of Zulqarnain?', '{"A":"Surah An-Nur","B":"Surah Noon","C":"Surah Al Mujadala","D":"Surah Al Kahaf"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allah mentions Zulqarnain (AS) in Surah Kahf.He had immense wisdom to distinguish between right and wrong.Surah Kahf Meaning is "The Cave".It is the 18th chapter of the Quran It was revealed in Makkah.No. of letters: 6425No. of rukus: 12No. of verses: 110No. of words: 1583Last verified on 02-04-2026', 0, 0, 0, 1790964553430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_eacee687baa09c90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Ayat ul Kursi is in which Surah of the Holy Quran?', '{"A":"Surah Al-Baqarah","B":"Surah An-Nisa","C":"Surah Al-A’raf","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ayatul Kursi is the 255th verse of the 2nd surah of the Quran, Al-Baqarah.It is located in the third para named "تِلْكَ ٱلْرُّسُلُ."It is also known as Sardar ul Ayat or The Throne Verse.Surah Al-Baqarah is the longest Surah of the Qur''an.It was revealed after the Prophet ﷺ migrated to Madinah.Last updated by NS on 06 May 2026', 0, 0, 0, 1790964553430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2f439d59bb742468', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which surah is the Preface of the Holy Quran?', '{"A":"Surah Al-Baqarah","B":"Surah Al-Fatiha","C":"Surah Al-Yaseen","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Fatiha is regarded as the Preface (Opening) of the Holy Quran.The word Preface means دیباچہ، تمہید، مقدمہ.It is the first Surah of the Holy Quran.It consists of 7 Ayahs.It is recited in every unit (Rak‘ah) of prayer.It is also known as Umm-ul-Kitab/Umm-ul-Quran (Mother of the Book/Quran).Last verified on 23-08-2026', 0, 0, 0, 1790964553430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e7a1347301d1a8cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Hazrat Abu Bakr (R.A) entrusted the work / responsibility of compilation of the Holy Quran to whom?', '{"A":"Hazrat Amir (R.A)","B":"Hazrat Zaid bin Sabit (R.A)","C":"Hazrat Usama bin Zaid (R.A)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Bakr (R.A) entrusted the compilation of the Holy Quran to Hazrat Zaid bin Thabit (R.A).This decision was made after many Huffaz (memorizers of Quran) were martyred in the Battle of Yamama.Hazrat Umar (R.A) suggested compiling the Quran in written form for preservation.Hazrat Zaid bin Thabit (R.A) collected verses from written materials and memories of companions.This ensured the safe preservation of the Holy Quran in a single manuscript.Last verified on 25-06-2026', 0, 0, 0, 1790964553430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f71e311865b018e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Surahs of the Holy Quran start with the word “Qul”?', '{"A":"One","B":"Two","C":"Five","D":"Seven"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are 5 Surah in Holy Quran which start with the word Qul:Surah 72: Al-Jinn – قُلْ أُوحِيَ إِلَيَّSurah 109: Al-Kafirun – قُلْ يَا أَيُّهَا الْكَافِرُونَSurah 112: Al-Ikhlas – قُلْ هُوَ اللَّهُ أَحَدٌSurah 113: Al-Falaq – قُلْ أَعُوذُ بِرَبِّ الْفَلَقِSurah 114: An-Nas – قُلْ أَعُوذُ بِرَبِّ النَّاسِLast verified on 27-07-2026', 0, 0, 0, 1790964553430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_68b899b743cfc079', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which companion of the Holy Prophet is known as Tarjuman-ul-Quran (Interpreter/Translator of Qur’an)?', '{"A":"Hazrat Abdullah bin Abbas","B":"Hazrat Abu Huraira","C":"Hazrat Hanzala","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abdullah bin Abbas (RA) is known as “Tarjuman-ul-Qur’an” (Interpreter/Translator of Qur’an).He was the cousin of Prophet Muhammad (PBUH).He was the greatest early mufassir (interpreter) of the Quran.He had deep knowledge of Tafsir, Hadith, and Arabic language.Many companions and scholars learned from him.Last verified on 26-04-2026', 0, 0, 0, 1790964553430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c6ee920499ecd2e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Surah are in the Holy Quran?', '{"A":"112","B":"113","C":"114","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The total number of Surah in the Holy Quran is 114.Additional information:The number of Makki Surah is 86 and Madni is 28.The first complete Madani surah of the Quran is Al-Baqarah.There are 11 Sajdah are there in Makkah Surah.There are only 03 Sajdah are there in Medinan Surah.Last verified on 01-04-2026', 0, 0, 0, 1790964553430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_08176bed09c02d04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Surah is called Zeenat-e-Quran (Beauty of the Quran)?)', '{"A":"Surah Rehman","B":"Surah Kousar","C":"Surah Fateha","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Ar-Rahman is popularly known as "Zeenat-e-Quran" (The Beauty/Adornment of the Qur''an).It is the 55th Surah of the Qur''an.It contains 78 verses (Ayat).Additional information:Surah Al-Fatihah – Umm-ul-Kitab (Mother of the Book), Umm-ul-Quran, As-Sab''ul MathaniSurah Al-Baqarah – Fustat-ul-Quran (The Tent of the Qur''an)Surah Yasin – Heart of the Qur''an (Qalb-ul-Quran)Surah Al-Ikhlas – One-third of the Qur''an in rewardLast verified on 14-07-2026', 0, 0, 0, 1790964553430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e6baeffe646dfdfb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many verses of Surah Al-Alaq were first revealed to the Holy Prophet (PBUH) in the first Wahi (revelation)?', '{"A":"Four","B":"Seven","C":"Six","D":"Five"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Five verses were revealed in the first revelation (Wahi)Verses: 5 verses of Surah Al-Alaq (the 96th chapter of the Quran).Location: Cave of Hira (Ghar-e-Hira) on Jabal al-Noor in Makkah.Year: 610 AD.Angel: Hazrat Jibril (Gabriel).First Word: "Iqra" (Read).Additional information:At the Age of 40 years 6 monthsPrescriber of Wahi in Makkah: Sharjeel-ibn-Hasana KandiFirst writer of Wahi in Quraish: Hazrat Zaid bin Sabit (RA)Last updated by NS on 5-09-2026', 0, 0, 0, 1790964553518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_eb7134057dd5c5dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Huffaz (Hafiz-e-Quran) were martyred in the Battle of Yamama (Jang-e-Yamama)?', '{"A":"70","B":"60","C":"90","D":"80"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Around 360–70 Huffaz (Quran memorizers) were martyred (varies in reports)Year: 11 AH / 632 CE (December) during caliphate of Hazrat Abu BakrOpponent: Musaylimah the LiarMuslims Martyred: around 1,200 (including many Huffaz)Place: Yamama (Arabia)Last verified on 25-04-2026', 0, 0, 0, 1790964553518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2157892fc3848265', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Who wrote Tafheem-ul-Quran?', '{"A":"Syed Abul Ala Maududi","B":"Abdul Rahman","C":"Israr Ahmed","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Author: Syed Abul Ala MaududiWork Name: Tafheem-ul-QuranLanguage: UrduVolumes: 6 volumesWriting Period: 1942 – 1972Last verified on 18-05-2026', 0, 0, 0, 1790964553518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4aceaf2d80d5ccb2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which surah is called Ummul Kitab (Mother of the Book)?', '{"A":"Surah Fatih","B":"Surah Bakra","C":"Surah Muhammad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Fatihah is called Ummul Kitab (Mother of the Book).It is the first Surah of the Holy Quran.It is also called Ummul Quran due to its central importance.It summarizes core teachings of worship, guidance, and prayer.It is recited in every unit of Salah (Namaz).It has 7 verses.Last verified on 07-07-2026', 0, 0, 0, 1790964553518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9d1dbe49c77855e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The name of Prophet, whose age is mentioned in Quran is?', '{"A":"Prophet Ibrahim (a.s)","B":"Prophet Nuh (a.s)","C":"Prophet Isa (a.s)","D":"Prophet Dawood (a.s)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet: Nuh (A.S.)Qur''anic Reference: Surah Al-Ankabut (29:14)Mentioned Duration: 950 years (among his people)Holy Book: Qur''anStatus: One of the Ulul Azm ProphetsLast verified on 19-07-2026', 0, 0, 0, 1790964553518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9117473f98e292ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Rukus are there in the Holy Quran?', '{"A":"458","B":"558","C":"658","D":"440"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rukus in the Holy Quran: 558 / 540Verses (Ayat): 6,236 / 6,666Total Surahs: 114Makki Surahs: 86 (revealed in 13 years, mostly short Ayat)Madani Surahs: 28 (revealed in 10 years, mostly long Ayat)Total Juz'': 30Sajda Tilawat: 14Last verified on 19-07-2026', 0, 0, 0, 1790964553518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b2fce524b4f7dd96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which verse of Surah Al-Baqarah is the longest verse in the Qur''an?', '{"A":"282","B":"298","C":"286","D":"290"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Verse 282 of Surah Al-Baqarah is the longest verse in the Quran.It is known as Ayat ad-Dayn (آیت الدَّيْن).Because it deals with loans and financial transactions.Al-Baqarah (The Cow) is the second and longest Surah of the Quran.It contains 286 verses.Position: Juz 1–3Classification: MedinanRukus: 40Approximate Letters: 25,500Verified & Updated', 0, 0, 0, 1790964553518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ea1e1365827ad3bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which of the following Surah of the Holy Quran carries the injunction for utilization of Zakat?', '{"A":"Surah-e-Tauba","B":"Surah-e-Baqra","C":"Surah-e-Nisa","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The injunction for utilization of Zakat is given in Surah At-Tawbah (9:60).It clearly defines eight categories of people eligible for Zakat.The poor (Al-Fuqara).The needy (Al-Masakin).Zakat administrators.New Muslims and friends of the Muslim community.Slaves and captives.The debt-ridden.In the cause of God.The wayfarer (travelling with few resources).Last verified on 25-04-2026', 0, 0, 0, 1790964553518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_217322e8fbc401b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which of the following Surah in the Holy Quran named after insects?', '{"A":"Surah Al-Nas","B":"Surah Al-Naml","C":"Surah Al-Qadar","D":"Surah Al-Falaq"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Naml (The Ant) is named after the ants Mentioned in the story of the Prophet Sulaiman (AS).It is the 27th Surah in the Quran.No. of verses: 93No. of Rukus: 7No. of Sajdahs: 1 (verse 26)Additional information: Two surahs named after insectsSurah An-Nahl (Chapter 16) — translates to "The Bee". Surah An-Naml (Chapter 27) — translates to "The Ant".Note: Al-Ankabut (The Spider) is the 29th chapter. While it is a chapter named after an arachnid, it is often grouped together with these insect-named chapters.Last updated 17 july 2026 by NA', 0, 0, 0, 1790964553604) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_83cbf0e583507e39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'According to Shah Wali Allah, how many verses in the Quran are considered abrogated?', '{"A":"2 verses","B":"5 verses","C":"10 verses","D":"20 verses"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Shah Wali Allah: 5 abrogated versesBook: Al-Fawz al-Kabir fi Usul al-TafsirScholar: Shah Wali Allah Dehlawi (1703–1762)Subject: Naskh (Abrogation) in the Qur''anKnown for: Reforming and simplifying Qur''anic interpretationVerified & Updated', 0, 0, 0, 1790964553604) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bfd1aac1eee289f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many time the word ‘Quran’ is repeated in the Quran?', '{"A":"55","B":"75","C":"70","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Approximate occurrences: ~70 timesRoot letters: Qaf (ق), Ra (ر), Hamza (ء)Meaning: Recitation / that which is readRevealed to: Prophet Muhammad (PBUH)Language: ArabicLast verified on 16-05-2026', 0, 0, 0, 1790964553604) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1292a7aebe38d97c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The first Surah of the Holy Quran is ____?', '{"A":"Surah-e-Baqarah","B":"Surah-e-Nisa","C":"Surah-e-Nas","D":"Surah-e-Fatiha"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Surah of the Holy Quran is Surah Al-Fatiha.Total verses: 7Total words: 29Total letters: 139Position: 1st Surah of the Holy QuranRevelation: Makki SurahAdditional information:Surah Al-Fatiha is called “Umm-ul-Kitab” (Mother of the Book).It is also known as “Ash-Shifa” (The Cure) because it is considered a source of spiritual healing.It is also called “The Opening”.Last verified on 09-05-2026', 0, 0, 0, 1790964553604) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1fd989d413c6d2f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which is known as “Saloos-ul-Quran” (One-third of the Quran)?', '{"A":"Surah Nasar","B":"Surah Kausar","C":"Surah Ikhlas","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Ikhlas is known as “one-third of the Quran” (Saloos-ul-Quran).It emphasizes pure monotheism (Tawheed).It has 4 short verses.It is a Makki Surah.It explains the oneness and uniqueness of Allah.Last verified on 26-04-2026', 0, 0, 0, 1790964553604) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8f6961c88198c27a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Who is the responsible for protection of the Holy Quran?', '{"A":"Muslims","B":"Allah","C":"Angels","D":"The holy prophet (PBUH)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allah Almighty has taken the responsibility for preserving the Qur''an.As stated in Surah Al-Hijr (15:9):"Indeed, We have sent down the Reminder (the Qur''an), and surely We will guard it."Last verified on 14-07-2026', 0, 0, 0, 1790964553604) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d162daccfbb76ada', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many verses in Surah Al-Baqrah?', '{"A":"176 Ayat","B":"200 Ayat","C":"286 Ayat","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Baqarah contains 286 verses.Al-Baqarah (The Cow) is the second and longest Surah of the Quran.Verse 282 of Surah Al-Baqarah is the longest verse in the Quran.It is known as Ayat ad-Dayn (آیت الدَّيْن).Because it deals with loans and financial transactions.Position: Juz 1–3Classification: MedinanRukus: 40Approximate Letters: 25,500Last verified on 13-07-2026', 0, 0, 0, 1790964553604) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_af124eb7599945ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Surah of the Quran ends with a name of a prayer?', '{"A":"Surah Al-Fatiha","B":"Surah Al-Baqarah","C":"Surah Al-Qadar","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Qadar ends with a prayer-like phrase.The Surah ends with the words: "Salamun Hiya Hatta Matla''il Fajr" (Peace it is until the emergence of dawn).This ending conveys peace, blessings, and a supplicatory tone.Surah Number: 97Verses (Ayat): 5Revelation: Makki SurahMain Topic: Importance and blessings of Laylat al-Qadr (Night of Decree)Last verified on 11-07-2026', 0, 0, 0, 1790964553604) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_113e369cd772bbfb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which term is used for the longest Ayah (Verse) of the Holy Quran?', '{"A":"Ayat-e-Mubahala","B":"Ayat-e-Mudayana","C":"Ayat-e-Madina","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Ayat-e-Mudayana (Ayat ad-Dayn)Surah: Al-BaqarahVerse Number: 282Juz: 3Main Topic: Debt contracts, witnesses, and financial transactionsLast verified on 10-07-2026', 0, 0, 0, 1790964553694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_46d6557cb6ebc067', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The Madni Surahs have a general emphasis on?', '{"A":"Ghazwat","B":"The social and religion laws and values","C":"Laws of nature","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Madani Surahs mainly emphasize social, religious, legal, and moral laws for the Muslim community.These Surahs discuss family laws, inheritance, worship, justice, jihad, and the organization of the Islamic state.Madani Surahs are generally longer than Makki Surahs.Additional information:Makki Surahs mainly focus on Tawheed (Oneness of Allah), Prophethood, the Hereafter, and moral guidance.Last verified on 06-07-2026', 0, 0, 0, 1790964553694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f312984986d8cc75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Paradise is mentioned in Quran for _____ times.', '{"A":"150","B":"140","C":"155","D":"160"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jannah (Paradise): Mentioned 150 times in the QuranJahannam (Hell): Mentioned 77 times in the QuranMeaning of Jannah: Garden / ParadiseDescription: Beautiful gardens with rivers flowing beneath themAdditional information:Seven Levels of Jannah:Jannat-ul-Firdaws (Highest level)Jannat-ul-AdnJannat-ul-Ma''waJannat-un-Na''imDar-ul-MaqamahDar-us-SalamDar-ul-AkhirahLast verified on 02-07-2026', 0, 0, 0, 1790964553694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bc380db732a8e82d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Surah is called Aroos-ul-Quran (the Bride of the Quran)?', '{"A":"Yaseen","B":"Fatiha","C":"Rahman","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Ar-Rahman is called Aroos-ul-Quran (Bride of the Quran).“Ar-Rahman” means The Most Merciful / Beneficent.Surah Number: 55Verses: 78Type: Makki SurahTheme: Blessings of AllahRepetition: Famous repeated verse 31 timesAdditional information:Surah Yaseen is called the Heart of the Quran.Last verified on 12-06-2026', 0, 0, 0, 1790964553694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3e1e0884ce4200c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Allah says, “Wives of Prophet Muhammad ﷺ are mothers of believers” in Surah _____?', '{"A":"Surah Muhammad","B":"Surah Yaaseen","C":"Surah Ahzaab","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The verse is mentioned in Surah Al-Ahzab.Allah declares the wives of Prophet Muhammad ﷺ as “Mothers of the Believers (Umm-ul-Momineen)”.This is stated in Verse 6 (33:6).Total wives → 11First wife → Khadija (R.A) (595–619)Last wife → Maymunah (R.A) (630)Last verified on 28-04-2026', 0, 0, 0, 1790964553694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a4b78674b9fd2e19', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the name of the Surah that was last revealed on the Quran?', '{"A":"Al- Alaq","B":"Al- Nasr","C":"Al- Nas","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Name: Al-Nasr (The Help / Victory)Number: 110Verses: 3Place of Revelation: Madina (according to most scholars)Theme: Victory of Islam & preparation for Prophet’s departureAdditional information:First Surah: Al-Alaq (96:1–5)First word: Iqra (Read)Place: Cave Hira, MakkahAngel: Jibreel (AS)Prophet age: 40 yearsLast verified on 12-06-2026', 0, 0, 0, 1790964553694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3229ab1ed2deeb76', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In Surah Fatah ______ is called Fatah Al-Mubeen?', '{"A":"Sulah e Hudaibiya","B":"Ghazwa Badr","C":"Fatah-e-Makkah","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sulah-e-Hudaibiya was signed in the year 628/6 A.H.It was signed for 10 Years.It was scribed by Ali Al-Murtaza (R.A).Hudabia is the name of the tree.It was a pivotal treaty between Muhammadﷺ, representing the state of Medina, and the Qurayshi tribe.Last verified on 30-03-2026', 0, 0, 0, 1790964553694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4692bf4bccd8a5d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Holy Quran revealed on which Prophet?', '{"A":"Hazrat Muhammad","B":"Hazrat Musa","C":"Hazrat Isa","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet who received Quran: Hazrat Muhammad ﷺFirst revealed Surah: Surah Al-Alaq (96)First revealed word: Iqra (اقرأ)First revelation place: Cave of Hira, MakkahDuration of revelation: 23 yearsCompletion of revelation: 632 CELast verified on 01-07-2026', 0, 0, 0, 1790964553694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e44b19b821d13ec2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the total number of verses in Quran?', '{"A":"6666","B":"4444","C":"5555","D":"6500"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The number of verses in the Quran is 6,666.The total number of verses in Quran is 6,236 excluding Bismillah and 6349 including Bismillah.There are 114 Surahs in the Qur''an.There is Juz 30 in the Qur''an.There are Manzil 7 in the Qur''an.There are 14 Sajda talawat in the Qur''an.Last verified on 17-03-2026', 0, 0, 0, 1790964553796) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d04199ea491da7cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which was the first revealed word of the Holy Quran?', '{"A":"Naas","B":"Fatiha","C":"Iqra","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First revealed word: IqraFirst revealed Surah: Surah Al-AlaqFirst revealed verses: First 5 verses of Surah Al-AlaqRevealed through: Angel Jibril (Gabriel)Age of Prophet ﷺ: Forty (40) yearsAdditional information:Quran revelation period: 23 yearsBeginning of revelation: around 609/610 CECompletion of revelation: 632 CELast revealed Surah: Surah Al-NasrLast verified on 10-05-2026', 0, 0, 0, 1790964553796) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_906d8e1e0e2ebefc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Name the language in which the Holy Quran was translated for the first time in the subcontinent?', '{"A":"Sindhi","B":"Balochi","C":"Punjabi","D":"Persian"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Quran was first translated in the subcontinent into Persian by Shah Waliullah Dehlavi in 1738.Additional information:Language TranslatorTimeframePersianShah Waliullah Dehlavi1738 ADUrduShah Abdul Qadir / Shah RafiuddinLate 18th CenturySindhiAkhund Azizullah Muttalawi (earliest surviving published)1870 ADLast verified on 16-05-2026', 0, 0, 0, 1790964553796) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dde6c33892a667ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The event of Miraj is mentioned in the Surah of _______?', '{"A":"Baqarah","B":"Bani Israel","C":"Maida","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The event of Isra and Mi''raj is mentioned in the Qur’an.It is described in Surah Al-Isra (Bani Israel), Surah 17.The journey includes Isra (Makkah to Masjid Al-Aqsa) and Mi’raj (heavens ascent).Date: 27th RajabProphethood year: 10th year (~621 AD)During Mi’raj, 5 daily prayers (Salah) were made obligatory.Last verified on 02-05-2026', 0, 0, 0, 1790964553796) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3f402807150e1354', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The sahabi who collected the Quran verses in one place was ________?', '{"A":"Hazrat Umer (R.A.)","B":"Hazrat Usman (R.A.)","C":"Hazrat Abdullah Ibne Masud (R.A.)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Usman (R.A.) compiled the Quran into a single standardized copy.Number of copies: 5 or 6 official copies sent to major regionsCompiler lead: Hazrat Zaid bin Thabit (R.A.)Purpose: To avoid differences in Quranic recitationAdditional information:The collection of the holy Quran was completed in two terms:Hazrat Abubakar (RA)Hazrat Usman (RA)The Qur''an was first compiled into a book format by Hazrat Zaid bin Sabit.Last verified on 12-06-2026', 0, 0, 0, 1790964553796) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d4f97cab3e29e1d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Allah has mentioned ____ names of the Quran in the Quran itself.', '{"A":"70","B":"55","C":"65","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allah has mentioned 55 names of the Quran in the Quran itself.These names describe the qualities and guidance of the Holy Quran.Important names include Al-Furqan (The Criterion), Al-Huda (The Guidance), Al-Noor (The Light).It is the final divine book revealed to Prophet Muhammad (PBUH).It was revealed over 23 years (610–632 AD).Last verified on 12-06-2026', 0, 0, 0, 1790964553796) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c40967361ff784e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Surah contains the order about Wuzu, Ghusal and Tayammum?', '{"A":"Al-Maidah","B":"Al-Baqara","C":"Al-Mominoon","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Al-Maidah, the order of Wuzu, Ghusal and Tayammum is mentioned.There are 5 Sunnah and 3 Faraiz in Ghusal.Al-Maidah is the fifth chapter of the Quran:Number of verses: 120.Other names: The Feast.Number of Rukus: 16.Position: Juz 6 to 7.Last verified on 26-04-2026', 0, 0, 0, 1790964553796) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_27ce1a97d08521c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Sajdas (Prostration) are there in the holy Quran?', '{"A":"11","B":"12","C":"13","D":"14"}', 'D', NULL, 0, 0, 0, 1790964553796) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f13ce4f0b0e403e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Name of the first Muslim who recited the Quran loudly?', '{"A":"Hazrat Bilal bin Rubbah (R.A)","B":"Hazrat Abdullah Bin Masood (R.A)","C":"Hazrat Zaid Bin Haris (R.A)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Muslim who recited the Holy Quran loudly was Hazrat Abdullah Bin Masood (R.A).He was one of the earliest companions of Prophet Muhammad (PBUH).He recited Surah Ar-Rahman publicly in Makkah despite opposition.This act showed courage in spreading Islam.He is known for deep knowledge of Quran and Hadith.Last verified on 11-06-2026', 0, 0, 0, 1790964553889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_afc54c3c370bca02', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Madni Surahs are there?', '{"A":"44","B":"88","C":"28","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790964553889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c89b5a682e8251a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many number of Makki Surahs are there in the Holy Quran?', '{"A":"84","B":"85","C":"86","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Makki Surahs: 86Madani Surahs: 28Total Surahs: 114Makki Period: ~13 yearsRevelation Place: MakkahAdditional information:Makki Surahs mainly emphasize faith (Iman)Madani Surahs focus on law and social systemFirst revelation occurred in Hira Cave (610 CE)Last revelation completed in 632 CEQuran contains 11 Sajdah in Makki Surahs and 3 in Madani SurahsLast verified on 17-05-2026', 0, 0, 0, 1790964553889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6c622ba6f3c3e50b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Who is referred in the Quran as Rooh-ul-Ameen/Ar-Rooh/Rooh-al-Qudus?', '{"A":"Hazrat lzrael (AS)","B":"Hazrat Israfeel (AS)","C":"Hazra Jibrael (AS)","D":"Hazrat Mekael (AS)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rooh-ul-Qudus (The Holy Spirit) and Rooh-ul-Ameen (The Trustworthy Spirit) refer to Angel Jibreel (Gabriel).Chief angel of Allah, responsible for delivering revelations to the Prophets, especially Prophet Muhammad (PBUH).Mentioned by name only three times in the Holy Quran.Appears in verses like Surah Al-Qadr and Surah An-Nahl 16:102.Last verified on 17-03-2026', 0, 0, 0, 1790964553889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_152bdef2123f1aa4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Prophet has been called as: "Zun-Noon" in the Holy "Quran?', '{"A":"Hazrat Yousuf (AS)","B":"Hazrat Hood (AS)","C":"Hazrat Yahya (AS)","D":"Hazrat Younus (AS)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Younus (A.S) is called Zun-Noon in the Qur''an.Zun-Noon means “the one of the fish (whale)”.It refers to the incident when he was swallowed by a big fish.Mentioned in Surah Al-Anbiya (21:87) and Surah Al-Qalam (68:48).Additional information:Ibrahim (A.S) → KhalilullahMusa (A.S) → KaleemullahIsa (A.S) → RuhullahMuhammad (PBUH) → Khatam-un-NabiyyinLast verified on 28-04-2026', 0, 0, 0, 1790964553889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_aec2d40e31dd5ea5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the Duration of Makki Period?', '{"A":"12 Years","B":"13 Years 9 Months 29 days","C":"12 Years 9 Months 5 days","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Makki period refers to the time when Qur’anic revelations were given in Makkah.It started from 610 CE (Cave Hira revelation).It continued until the Hijrah to Madinah in 622 CE.Its total duration is about 12 years, 9 months, and 5 days.Makki Surahs mainly focus on faith, morals, and belief system.Last verified on 18-05-2026', 0, 0, 0, 1790964553889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5a83b35eac0b9404', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In which surah Uswah Hasna of the Prophet is mentioned?', '{"A":"Ahzab","B":"Maida","C":"Baqra","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Uswah Hasanah” means perfect example of conduct.Surah: Al-Ahzab (33)Ayah: 21Message: Prophet Muhammad ﷺ is the best role model for believers.Key Phrase: “Laqad kana lakum fi Rasulillahi uswatun hasanah”.Last verified on 18-05-2026', 0, 0, 0, 1790964553889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1a177cd64f31dac5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The current order of the Quranic Surah is _____?', '{"A":"Nuzooli","B":"Touqeefi","C":"Hukmo","D":"Sharal"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The order of Surahs in the Holy Qur’an is Tauqeefi.It means the arrangement was fixed by Allah through Prophet Muhammad (ﷺ).It is not based on personal opinion or human decision.The same order is preserved in the Qur’an today.Last verified on 18-05-2026', 0, 0, 0, 1790964553889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fdb801c4ced76580', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The word “Khatam un Nabiyeen” is found in Surah of ________ the Holy Quran.', '{"A":"Ahzab","B":"Yasin","C":"Mulk","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Phrase: خاتم النبیین (Khatam un Nabiyeen)Surah: Al-Ahzab (Surah 33)Ayah: 33:40Meaning: Last of the ProphetsRevelation: Madani SurahLast verified on 16-05-2026', 0, 0, 0, 1790964553973) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1299109b7b3894e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The surah which mentions the Islamic laws regarding marriage and divorce is?', '{"A":"Aal-e-Imran","B":"Al Nisa","C":"Al Mayedah","D":"Al Anaam"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Number: 4Name Meaning: The WomenType: Madani SurahMain Topics: Marriage, divorce, inheritance, women’s rightsRevealed in: MadinahLast verified on 16-05-2026', 0, 0, 0, 1790964553973) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a9c29e52129f8705', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Ghazwaz are described in Holy Quran?', '{"A":"10","B":"12","C":"14","D":"25"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total Ghazwat: Historical accounts list 27.Mentioned in the Quran: 12.The first ghazwa is the BattleLast Ghazwa of Holy Prophet (PBUH): Ghazwa tabookAdditional information:Battle of Badr: Mentioned in Surah Ali ''Imran and Al-Anfal.Battle of Uhud: Discussed in Surah Ali ''Imran.Battle of Ahzab (Trench): Described in Surah Al-Ahzab.Battle of Hunayn: Mentioned in Surah At-Tawbah.Battle of Tabuk: Discussed in Surah At-TawbahLast verified on 16-05-2026', 0, 0, 0, 1790964553973) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_50a6938063f1da59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In which language Shah Wali Ullah translated the Holy Quran?', '{"A":"Sindhi","B":"English","C":"Persian","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shah Wali Ullah Dehlawi translated the Holy Quran into Persian language for the first time in the Indian subcontinent.Additional information:Real Name: Qutb-ud-Din Ahmad Shah Wali UllahBorn: 21 February 1703, Phulat (Mughal Empire)Died: 20 August 1762, DelhiLast verified on 11-05-2026', 0, 0, 0, 1790964553973) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6430195fcdfd57bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the other name of Surah Fatiha?', '{"A":"Umm al-Kitab","B":"Umm al-Quran","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quran starts with Surah Al-Fatiha, which has several names.Umm al-Kitab (Mother of the Book)Umm al-Quran (Mother of the Quran)Al-Fatiha (The Opening)Additional information:Total verses: 7Total words: 29Total letters: 139Revelation place: MakkahLast verified on 10-05-2026', 0, 0, 0, 1790964553973) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_44b2ef93619299f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the term for the process of interpreting the Quran through the Quran itself?', '{"A":"Istinbat","B":"Tahlil","C":"Tawil","D":"Tafsir"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The method is called Tafsir al-Qur’an bil-Qur’an.It means explaining one verse of the Quran with another verse.This is considered the most authentic method of Tafsir.It ensures accuracy and consistency in understanding.Last verified on 20-04-2026', 0, 0, 0, 1790964553973) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4f4a1d505083350d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The name of which sahabi appears in the Surah Al-Ahzab?', '{"A":"Hazrat Ali (R.A.)","B":"Hazrat Ubaidah Bin Haris is (R.A.)","C":"Hazrat Zaid bin Haris (R.A.)","D":"Hazrat Umar (R.A.)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zaid bin Harithah is the only Sahabi mentioned by name in Surah Al-Ahzab.He was the adopted son of Prophet Muhammad (PBUH).Surah Al-Ahzab corrected the concept of adoption in Islam.It is the 33rd Surah of the Quran.It was revealed in Medina (Madani Surah).He is honored as a very close and trusted companion.Last verified on 02-05-2026', 0, 0, 0, 1790964553973) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_30df9924c6ecf8bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Surah are start with the name of Prophets?', '{"A":"6","B":"4","C":"2","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Qur''an contains 6 Surahs named after Prophets.Surah IbrahimSurah YusufSurah MuhammadSurah NuhSurah HudSurah YunusTotal Prophets mentioned in Qur’an → 25 Prophets.Last verified on 28-04-2026', 0, 0, 0, 1790964553973) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5445d0d0e1efe4ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which city of Italy has been mentioned in the Quran?', '{"A":"Rome","B":"Teharan","C":"Baghdad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The city mentioned in the Quran is Rome.It is referred to in Surah Ar-Rum (The Romans).The Surah predicts the victory of the Romans after their defeat.Chapter Number → 30th SurahTotal Verses → 60 AyatRevelation → Makki SurahHistorical Context → Byzantine–Persian warLast verified on 25-04-2026', 0, 0, 0, 1790964554052) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_686dad4248498dc3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Surah al-Dukhan means _______?', '{"A":"Water","B":"Cloud","C":"Smoke","D":"Rain"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Ad-Dukhan means “Smoke”.It is the 44th Surah of the Qur''an.It contains 59 verses.The word Dukhan (smoke) appears in verse 10.It refers to a sign/punishment sent by Allah.Para → 25th ParaLast verified on 28-04-2026', 0, 0, 0, 1790964554052) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b1c467b6b22148a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which companion of Hazrat Muhammad ﷺ is mentioned in the Holy Quran?', '{"A":"Hazrat Abu Bakar","B":"Hazrat Zaid Bin Haris","C":"Hazrat Umer","D":"Hazrat Usman"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zayd ibn Harithah (RA) is the only companion mentioned by name in the Qur’an.His name appears in Surah Al-Ahzab (33:37).He was the adopted son of Prophet Muhammad (PBUH).Birth: 581 ADDeath: 629 AD (Battle of Mu’tah, Jordan)Last verified on 27-04-2026', 0, 0, 0, 1790964554052) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e74148b694b180fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Surah of the Holy Quran throws light on the Halal and Haram of sacrificial animals?', '{"A":"Surah Al Nehal","B":"Surah Al Imran","C":"Surah Al-Ma’idah","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Ma''idah explains rules about Halal and Haram animals.It is the 5th Surah of the Holy Quran.This Surah was revealed in Madinah (Medinan Surah).It provides detailed guidance on lawful and unlawful food.It also includes laws related to sacrifice and dietary rules.Last verified on 27-04-2026', 0, 0, 0, 1790964554052) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_26ac550dd09bb09b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Who translated the Holy Quran in Urdu for the first time?', '{"A":"Shah Waliullah and Shah Abdul Aziz","B":"Shah Abdul Qadir and Shah Rafiuddin","C":"Syed Ahmad Baralvi and Shah Ismail Dehlavi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Urdu translation of the Holy Quran was done by Shah Abdul Qadir and Shah Rafiuddin.Both were sons of Shah Waliullah.Shah Rafiuddin translated more literally, word-to-word.Shah Abdul Qadir’s translation was simpler and easier to understand.Additional informationFirst time translated into Punjabi:Tauqir Amaan KhanFirst time translated into Sindhi:Aakhund AzzizullahFirst time translated into English:George SaleFirst time in IndiaSindhiFirst time in WorldPersianLast updated by NA on 25- April-2026', 0, 0, 0, 1790964554052) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0990579f37f13b1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In which night Quran was revealed?', '{"A":"27 Rajab","B":"12 Rabi-ul-Awal","C":"Lailat-ul-Qadr","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Qur’an was first revealed on Lailat-ul-Qadr.It is known as the Night of Power or Decree.It is usually sought in the odd nights (21st, 23rd, 25th, 27th, 29th) of Ramadan.It is better than a thousand months in reward.It marks the beginning of revelation to Prophet Muhammad (PBUH).Last verified on 26-04-2026', 0, 0, 0, 1790964554052) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8223f165b9d3a454', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the main message of Surah Hujurat?', '{"A":"Kind towards women","B":"Ethic","C":"Treatment with slaves","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Hujurat focuses on establishing the ethical guidelines for a healthy Muslim community Al-hujurat meaning: The Chambers49th chapter (surah) of the Quran Classification: MedinanPosition: Juzʼ 26No. of verses: 18No. of Rukus: 2No. of words: 353No. of letters 1533Last updated by NA on 25- April-2026', 0, 0, 0, 1790964554052) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_75f982d5b4cbb47a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'A verse of the Holy Quran indicates the name of _______?', '{"A":"Hazarat Muaaz (RA)","B":"Hazrat Bilal (RA)","C":"Hazrat Zaid (RA)","D":"Hazrat Saad (RA)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Zaid bin Harithah (RA) is the only companion mentioned by name in the Quran.His name appears in Surah Al-Ahzab (33:37).He was the adopted son of Prophet Muhammad (PBUH).The verse refers to his marriage situation after divorce.Last verified on 25-04-2026', 0, 0, 0, 1790964554052) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_51bc3b4277874315', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'By which name, Holy Quran calls believers of Hazrat Issa (A.S)?', '{"A":"Romans","B":"Hawari","C":"Followers","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Quran refers to the followers of Hazrat Isa (A.S) as “Al-Hawariyyun” (The Disciples).These were the close companions and helpers of Prophet Isa (A.S).They believed in him and supported his mission of preaching monotheism.Last verified on 25-04-2026', 0, 0, 0, 1790964554140) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9334ca9bb4b8a97c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Ayat of the Holy Quran is called Sardar-ul-Ayat?', '{"A":"Surah Yaseen","B":"Ayat-ul-Kursi","C":"Surah Fateh","D":"Surah Baqra"}', 'B', NULL, 0, 0, 0, 1790964554140) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_55dc8acd8d03b603', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Prophet''s story'' is named as Ahsan-ul-Qasas in the Holy Quran?', '{"A":"Hazrat Yousuf (AS)","B":"Hazrat Adam (A.S)","C":"Hazrat Musa (A.S)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The story of Prophet Yusuf (Joseph) (AS) is described as Ahsan-ul-QasasAhsan-ul-Qasas means (the best of stories) in the Holy Quran.Surah Yusuf: 12th chapter of the Qur’anMain theme: Patience and trust in AllahNation: Bani IsraelLessons: Forgiveness, honesty, patienceLast verified on 25-04-2026', 0, 0, 0, 1790964554140) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1480af02a32c54ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many times Hazrat Jibrael (AS) is mentioned in the holy Quran?', '{"A":"9","B":"6","C":"3","D":"1"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Jibrael (Gabriel) is the angel who brought revelation to prophets.His name is explicitly mentioned 3 times in the Qur''an.These references are found in Surah Al-Baqarah and Surah At-Tahrim.He is also known as Rooh-ul-Qudus (The Holy Spirit) and Rooh-ul-Ameen (The Trustworthy Spirit) in Islam.Last verified on 25-04-2026', 0, 0, 0, 1790964554140) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_73913f128faf27ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Surah Saba is a ______?', '{"A":"Makki Surah","B":"Madani Surah","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Saba (سورہ سبا) is the 34th chapter of the Qur’an.It consists of 54 ayats.It was revealed in Makki period.It addressing belief, accountability, and the stories of previous nations.Focuses on the consequences of denying Allah’s signs and lessons from Prophet Dawud (A.S.) and previous communities.Last verified on 01-04-2026', 0, 0, 0, 1790964554140) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ae2cbb0f8d09ca56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Holy Quran was revealed in how many years and months?', '{"A":"18 years and 10 months","B":"20 years and 10 months","C":"22 years and 5 months","D":"21 years and 5 months"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Beginning of revelation: 22 December 609 CEProphet’s age at start: 40 yearsCompletion of revelation: 632 CE (year of his death)Total years of revelation: ~23 yearsAdditional information:The Holy Quran was revealed to Prophet Muhammad (PBUH).First word revealed: “Iqra” (Read).First 5 verses of Surah Al-Alaq were revealed in Ghar-e-Hira.Last revealed Surah: Surah An-Nasr.Revelation was oral, through Archangel Gabriel (Jibril). Last updated NA 12-04-2026', 0, 0, 0, 1790964554140) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6595a2b5589161d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Surah Hajj consists of _____ Ayats.', '{"A":"78","B":"48","C":"28","D":"38"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Hajj (سورہ حج) is the 22nd chapter of the Qur’an.It consists of 78 ayats and 10 rukus.It was revealed in Madina, but part of it (verses 1–24) relates to the Makki period of Prophet Muhammad (PBUH).The rest (verses 25–78) was revealed during the early Madni period.Last verified on 01-04-2026', 0, 0, 0, 1790964554140) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9e7c308681d5f322', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Surah-e-Al Alaq has how many verses?', '{"A":"9","B":"19","C":"29","D":"39"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-‘Alaq is the 96th chapter of the Qur’an.It has 19 verses (āyāt).It is a Makki Surah.The first 5 verses were revealed as the first Wahy (revelation).Revelation took place in Ghar-e-Hira.It is also known as “Surat Iqra” (Read).Last verified on 01-04-2026', 0, 0, 0, 1790964554140) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a8cecd8ef87e1331', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Identify the name of the angel who is the Gatekeeper of Heaven mentioned in the Holy Quran?', '{"A":"Malik","B":"Rizwan","C":"Raad","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Angel Rizwan is appointed as the gatekeeper of Heaven (Jannah).He welcomes the righteous believers into Paradise.Additional information:Angel Malik is the chief gatekeeper of Hell (Jahannam).He oversees the punishments of the inhabitants of Hell.Last verified on 31-03-2026', 0, 0, 0, 1790964554268) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_914bc90af24b2d87', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many ayats in the Holy Quran', '{"A":"6536","B":"6636","C":"6238","D":"6236"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 6,236 Ayats ✅ – Most accepted count; Bismillah is not counted separately. 6,349 Ayats – Includes Bismillah of each Surah (except Surah Tawbah). 6,666 Ayats ❌ – Popular figure but not based on authentic scholarly counting.', 0, 0, 0, 1790964554268) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_df5ce4e36f93a73c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'After the death of Hazrat Umar (RA) a copy of Quran was passed to_________?', '{"A":"Hazrat Aysha Siddiqa (R.A)","B":"Hazrat Memona (R.A)","C":"Hazrat Hafsa (R.A)","D":"Hazrat Safia (R.A)","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After the death of Hazrat Umar (RA), the copy was kept with Hazrat Hafza bint Umar.She was the Hazrat Umar (RA )''s daughter and the wife of the Prophet (PBUH)Additonal informationAfter the compilation of the Quran, the copy was given to the caliph, Hazrat Abu Bakr (R.A).After the death of Hazrat Abu Bakr, the copy was transferred to the next caliph, Hazrat Umar (R.A).This copy is known as Mushaf-e-Hafza', 0, 0, 0, 1790964554269) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2ed87cfb93fd05b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In Holy Quran which one of the following fruits have been especially mentioned?', '{"A":"Dates","B":"Grapes","C":"Figs","D":"All the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Quran mentions several fruits as blessings from Allah.These include dates, grapes, olives, figs, pomegranates, and bananas.The fig is highlighted in Surah At-Tin (Chapter 95).The date palm is mentioned over 20 times, e.g., in Surah Maryam (19:25-26).Additional information:Olives: Mentioned as a blessed tree (Surah An-Nur 24:35)Pomegranates & Bananas: Symbols of heavenly fruits (Surah Al-Rahman 55:68)Last verified on 25-01-2026', 0, 0, 0, 1790964554269) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_73f9ce9696e17265', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many times command of the Namaz is given in the Quran?', '{"A":"600 Times","B":"500 Times","C":"700 Times","D":"400 Times"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Namaz commanded in Quran for 700 times.Salat made compulsory in 10th Hijri.Salat Juma became Farz in Madina.32 times the word Zakat occurs in the Holy Quran.22 times word Zakat is used in Makki Surahs.', 0, 0, 0, 1790964554269) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_13c4c184e98dc5ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Surah provides guidance about the distribution of Mal-e-Ghanimat (war booty)?', '{"A":"Surah Al-Baqarah","B":"Surah Al-Anfal","C":"Surah At-Tawbah","D":"Surah Al-Nisa"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The guidance about the distribution of Mal-e-Ghanimat (war booty) is provided in Surah Al-Anfal, Ayat 41The very name Al-Anfal means "The Spoils of War,"', 0, 0, 0, 1790964554269) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a7a3437466b74e05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', '"Tarjuman-ul-Quran" was written by which of the following?', '{"A":"Allama Iqbal","B":"Abul Kalam Azad","C":"Syed Ahmed Khan","D":"Maulana Rumi"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Tarjuman-ul-Quran" is a translation and commentary of the Quran.It from Arabic to Urdu by Abul Kalam Azad.It is a notable work in Islamic scholarship.', 0, 0, 0, 1790964554269) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d81f56cf46b9685a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Ayat-ul-Kursi is verse number in Surah Baqrah is _____?', '{"A":"244","B":"255","C":"265","D":"270"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ayatul Kursi is the 255th verse of the 2nd surah of the Quran, Al-Baqarah.It is located in the third para named "تِلْكَ ٱلْرُّسُلُ."It is also known as Sardar ul Ayat or The Throne Verse.Surah Al-Baqarah is the longest Surah of the Qur''an.It revealed after the Prophet ﷺ migrated to Madinah.', 0, 0, 0, 1790964554269) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a59510a6be96c302', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which surah is known to as Uroos ul Quran?', '{"A":"Surah Yaseen","B":"Surah Fatiha","C":"Surah Rehman","D":"Surah Mulk"}', 'C', NULL, 0, 0, 0, 1790964554348) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f051c11a5b0536d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In how many years Makki Surah were revealed?', '{"A":"15","B":"14","C":"13","D":"16","E":"23"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The number of Makki Surah is 86.13 years Makki Surah was revealed.The total number of Surah in the Holy Quran is 114. The number of Madni is 28.There are 11 Sajdah are there in Makkah Surah.There are only 03 Sajdah are there in Medinan Surah.', 0, 0, 0, 1790964554348) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e29c52a763b156d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Surah of the Holy Quran revealed twice in Makkah and Madina?', '{"A":"Surah Rahman","B":"Surah Alaq","C":"Surah Yaseen","D":"Surah Fatiha"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Fātiḥah was revealed twice, once in Makkah and later in Madina.Al-Fātiḥah is the first chapter of the Quran.Its seven verses are a prayer for the guidance, lordship and mercy of God.', 0, 0, 0, 1790964554348) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ec61ee0da275b1d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many surah starts with curse____?', '{"A":"1","B":"2","C":"3","D":"5","E":"7"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Three Surah Start With Curse. 1 Surah Muttaffifeen. 2 Surah Humazah. 3 Surah Lahab', 0, 0, 0, 1790964554348) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c58d78b9390065c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the meaning of Quranic surah Al-Asr?', '{"A":"The Unity","B":"The Hell","C":"Time","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al Asr Meaning is TimeSurah Al Asr is Makki Surah In 30th Para Of Holy Quran. No of Verses;3*********RY 13-12-202', 0, 0, 0, 1790964554348) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b58096eef0954c94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The Quranic surah Al-Ikhlas means ____?', '{"A":"The Straight path","B":"The Purity","C":"The Politeness","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is a short declaration of tawhid, Allah''s absolute oneness, consisting of four ayat. Al-Ikhlas means “the purity” or “the refining”.', 0, 0, 0, 1790964554348) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1b4e79c67df6d551', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many numbers of Surah in the last Para of Holy Quran?', '{"A":"30","B":"29","C":"35","D":"37","E":"31"}', 'D', NULL, 0, 0, 0, 1790964554348) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_47692d8b4b0e4524', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Total number of surah in Quran are ____?', '{"A":"109","B":"111","C":"114","D":"118"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total No Of Surah Are 114 Total No Of Verses Are 6666 Total No Of Ruku 540/558 Total No Of Sajida’s 14Stages 07Each of the 114 surahs, which vary in length from several pages to several words, encompasses one or more revelations received by Muhammad from Allah (God).AGM 08-01-2023RY 16-01-2023', 0, 0, 0, 1790964554348) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6ed5f0c0baad8331', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which famous Ghazwa is mentioned in Surah Al-Imran?', '{"A":"Ghazwah Ohad","B":"Ghazwah Badar","C":"Ghazwah Khaibar","D":"Ghazwah Khandaq"}', 'B', NULL, 0, 0, 0, 1790964554425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bead164b77a2ffa9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which surah ends with two Prophets name?', '{"A":"Surah Mujadila","B":"Surah Ibrahim","C":"Surah Al-Ala","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Quran has 25 Prophets names mentioned and there are 6 Surahs titled with their names. Surah Ibrahim Surah Yusuf Surah Mohammed Surah Nuh Surah Hood Surah Younus (Jonah).Surah Al-A’la ends with which two prophets'' names? Hazrat Ibrahim & MusaND7-5-2023', 0, 0, 0, 1790964554425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d0d853f39d0f6704', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many surahs of the Holy Quran start with the word Ha-meem?', '{"A":"3","B":"2","C":"7","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are seven surah start Ha-meem 1. Surah Ghafir, 2. Surah Fussilat, 3. Surah Shuraa, 4. Surah Zukhruf, 5. Surah Dukhan, 6. Surah Jathiyah 7. Surah Ahqaf.', 0, 0, 0, 1790964554425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a165fe725f760449', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many surahs of the Holy Quran starts with broken letters (Huruf muqatta''at)', '{"A":"14","B":"7","C":"29","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation حروف مقطعات سورۃ کا نام حروف مقطعات سورۃ کا شمار نمبر شمار البقرہ الم 2 1 آل عمران الم 3 2 الاعراف المص 7 3 یونس الر 10 4 ہود الر 11 5 یوسف الر 12 6 الرعد المر 13 7 ابراہیم الر 14 8 الحجر الر 15 9 مریم كهيعص 19 10 طٰہٰ طه 20 11 الشعراء طسم 26 12 النمل طس 27 13 القصص طسم 28 14 العنکبوت الم 29 15 الروم الم 30 16 لقمان الم 31 17 السجدہ الم 32 18 یس يس 36 19 ص ص 38 20 غافر حم 40 21 فصلت حم 41 22 الشوری حم۔ عسق 42 23 الزخرف حم 43 24 الدخان حم 44 25 الجاثیہ حم 45 26 الاحقاف حم 46 27 ق ق 50 28 القلم ن 68 29', 0, 0, 0, 1790964554425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e4a6c27ae4bdd5b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Who collected the Quran in the form of book?', '{"A":"Hazrat Abu Bakar (R.A)","B":"Hazrat Umar (R.A)","C":"Hazrat Abdullah Bin Abbas (R.A)","D":"Hazrat Zaid bin Sabit (R.A)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Qur''an was first compiled into a book format by Hazrat Zaid bin Sabit and other scribes under the first caliph Hazrat Abu Bakar.Hazrat Usman (R.A.) was the first Hafiz of the Holy Quran. Umal Mumneen Hafsah bint-e-Umar (R.A) was the first Hafiz of the Holy Quran in women.', 0, 0, 0, 1790964554425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_303a74f1a101a882', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many verses in surah ikhlas?', '{"A":"2","B":"3","C":"4","D":"5"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Ikhlāṣ, also known as the Declaration of God''s Unity and al-TawhidAlternate titles (Ar.): At-TawḥīdClassification: MeccanNo. of letters: 47No. of verses: 4 No. of words: 15********** VU CBT FIA PAPER 25-12-2021ND18-5-2023', 0, 0, 0, 1790964554425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_96e73925b85f276d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Sahabi name written in Quran?', '{"A":"Hazart Abdullah bin Massoud ( R.A)","B":"Hazart Abu Bin Talib ( R.A)","C":"Hazart Zaid bin Sabit ( R.A)","D":"Hazart Zaid Bin Haris ( R.A)","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zayd Bin Harith (R.A) name mentioned in the Surah Al-Ahzab, 33rd Surah of the Quran, verse number 37.He was the adopted son and Sahabi of Prophet Muhammad ﷺHe was commonly regarded as the fourth person to have accepted Islam, Born: 581 AD Died: 629 AD, Mutah, Jordan', 0, 0, 0, 1790964554425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_35c4c3779e1595c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The major part of Holy Quran is revealed at _______ time?', '{"A":"Night","B":"Day","C":"Both A and B","D":"Midnight"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The major part of the Holy Quran was revealed at Night Laylat al-Qadr, or the Night of Power, is the night when the Qur''an was first revealed Holy Quran was revealed to Hazrat Muhammad was 40 years oldIqra was the first revealed 5 verses of Surah Al-Alaq were first revealed by the Holy Prophet (PBUH)Surah Al Nasr was last revealedRevealed through the archangel Gabriel (Jibril),23 قرآن کا نزول کتنے سالوں میں مکمل ہوا: سالLast updated question NS on 09 MAY 2026', 0, 0, 0, 1790964554425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_29b6f09bd80eaf12', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Punishment of false accusation of Zina is mentioned in which surah of Holy Quran?', '{"A":"Al-Nisa","B":"Al-Qamar","C":"An-Nur","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790964554499) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b98b011a9a3d7fb5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Who collected verses of Quran?', '{"A":"Hazrat Abu Bakra RA","B":"Hazrat Umar RA","C":"Hazrat Ali","D":"Hazrat Usman RA"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Usman colleted the verses of Quran.Hazrat Usman (R.A), the third caliph of Islam was martyred at the age of 82 Hazrat Usman was the first Hafiz of the Holy Quran. people who have completely memorized the Quran is called Hafiz Quran. ...............Hazrat Ali (R.A), the fourth caliph of Islam was martyred at the age of 60.', 0, 0, 0, 1790964554499) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_382d3d93865b92c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many times Kalima Tayiba is mentioned in the Holy Quran ?', '{"A":"6 times","B":"3 times","C":"2 times","D":"4 times","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tehlil" means Recitation of Kalima.In the 23rd para the kalimah comes and in the 26th para the risaalat i.e. Muhammadur Rasulullah appears.', 0, 0, 0, 1790964554499) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2d8462af65215bf9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Surah namal means?', '{"A":"The Ants","B":"The Camels","C":"The Goats","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah An-Naml is the 27th chapter of the Quran. The surah titled in English means “The Ants”.The bird Hudhud (hoopoe) appears twice in Surah An-Naml.Surah Al Naml of the holy Quran Bismillah is addedto the entire Bismillahir Rahmani Raheem in the 30th verse.This is why Surah Naml is known as the Surah with two bismillahs.Surah Naml is an earlier "Meccan surah".', 0, 0, 0, 1790964554499) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9cd6c2bb311c6d3f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the meaning of word Quran?', '{"A":"To Hear","B":"To Read","C":"To Speak","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "Quran" is derived from the Arabic root "q-r-a," which means "to read" or "to recite."It signifies the recitation of the divine message revealed to Prophet Muhammad (PBUH).', 0, 0, 0, 1790964554499) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e565ccaafa5e3d00', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Surah of Holy Quran, the list of the beneficiaries of Zakat has been specifically given?', '{"A":"Al-Tauba","B":"Al-Yusaf","C":"Al-Ana''m","D":"Al-Kahf"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Tawba, there are eight categories of people (asnaf) who qualify to benefit from zakat funds.Allah has clearly mentioned the masarif of zakat and sadaqah in Quran in these words:اِنَّمَا الصَّدَقٰتُ لِلْفُقَرَآءِ وَالْمَسٰکِیْنِ وَالْعٰمِلِیْنَ عَلَیْھَا وَالْمُؤَلَّفَۃِ قُلُوْبُھُمْ وَ فِی الرِّقَابِ وَالْغَارِمِیْنَ وَفِیْ سَبِیْلِ اللّٰہِ وَابْنِ السَّبِیْلِ ؕ فَرِیْضَۃً مِّنَ اللّٰہِ ط وَاللّٰہُ عَلِیْمٌ حَکِیْمٌ۔', 0, 0, 0, 1790964554499) ON CONFLICT(id) DO NOTHING;
