INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ab11be3b3dd8a908', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many manzils (Stages) are there in Quran?', '{"A":"9","B":"7","C":"5","D":"2"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The list of the 7 stages of the Quran:Al-Fatihah (chapter 1) through An-Nisa'' (chapter 4): 4 chaptersAl-Ma''ida (chapter 5) through At-Tawba (chapter 9): 5 chaptersYunus (chapter 10) through An-Nahl (chapter 16): 7 chaptersAl-Isra'' (chapter 17) through Al-Furqan (chapter 25): 9 chaptersAsh-Shuara'' (chapter 26) through Ya-Seen (chapter 36): 11 chaptersAs-Saaffat (chapter 37) through Al-Hujurat (chapter 49): 13 chaptersQaf (chapter 50) through An-Nas (chapter 114): 65 chapters', 0, 0, 0, 1790964554563) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7533594652e8b834', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The last surah of the holy Quran is?', '{"A":"Surah Naas","B":"Surah Yaseen","C":"Surah Al Falaq","D":"None of thesse"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An Nas is the 114 chapter of the Holy Quran.It is a short six-verse invocationNo. of letters: 80No. of verses: 6No. of words: 20Other names: The Men, PeopleAdditional information:Al Falaq is the 113th chapter of the Holy Quran.Surah Baqarah is longest surah of Holy QuranThe Surah Al Kawthar is the shortest surah of Holy Quran', 0, 0, 0, 1790964554563) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_80244c35f3e59638', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Who is known as the “Compiler of Quran”?', '{"A":"Hazrat Abu Bakar (R.A)","B":"Hazrat Umer (R.A)","C":"Hazrat Ali (R.A)","D":"Hazrat Usman (R.A)","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Usman (R.A) is known as Jami-ul-Quran (compiler of Quran).He was the third caliph of Islam.', 0, 0, 0, 1790964554564) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f507e423a0ec039c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many years did it take for the complete revelation of the Quran?', '{"A":"23","B":"21","C":"12","D":"22"}', 'A', NULL, 0, 0, 0, 1790964554564) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4748d0a52db87841', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Surah Al-Qadr is a Surah of which number in the Holy Quran?', '{"A":"122","B":"120","C":"97","D":"41"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Qadr is the 97th chapter (surah) of the Holy Quran, with 5 verses (ayahs).It is a Meccan surah, which celebrates the night when the first revelation of what would become the Quran was sent down.', 0, 0, 0, 1790964554564) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9a82642eba12e231', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Surah e Muzammil means ______?', '{"A":"Cover","B":"Wrapped in garments","C":"Iron","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muzammil means “Wrapped One” or “Enshrouded One”. It is a Makki Surah. The starting 19 verses of this Surah were revealed in Makkah and the rest were revealed in Medina.', 0, 0, 0, 1790964554564) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b7771a880de108f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which surah is considered the Mother of the Qur’an (Umm al-Quran)?', '{"A":"Surah Iklass","B":"Surah \tFatiha","C":"Surah \tBaqara","D":"Surah \tYaseen"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Fatiha is also known as Al-Hamd (The Praise).It has 7 verses, 29 words, and 139 letters.It is also referred to as:As-Salah (The Prayer)Umm al-Kitab (Mother of the Book)Umm al-Quran (Mother of the Quran)Sab''a min al-Mathani (Seven Repeated Ones)Ash-Shifa'' (The Cure).', 0, 0, 0, 1790964554564) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_924fb18cbbaaf23b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Ayatul Kursi is located in which Para of the Holy Quran?', '{"A":"2nd","B":"3rd","C":"4th","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ayatul Kursi is the 255th verse of the 2nd surah of the Quran, Al-Baqarah.It is located in the third para named "تِلْكَ ٱلْرُّسُلُ."It is also known as Sardar ul Ayat or The Throne Verse.Surah Al-Baqarah is the longest Surah of the Qur''an.It revealed after the Prophet ﷺ migrated to Madinah.', 0, 0, 0, 1790964554564) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d6e8b2ce771baf39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'دوسری وحی میں قرآنِ پاک کی کون سی سورت کی ابتدائی 7 آیات نازل ہوئیں؟', '{"A":"سورۃ العلق","B":"سورۃ المدثر","C":"سورۃ الفاتحہ","D":"ان میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation پہلی وحی: سورۃ العلق (آیات 1 تا 5)دوسری وحی: سورۃ المدثر (آیات 1 تا 7)', 0, 0, 0, 1790964554650) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6649571a9dcb11a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The Commandment for observing Fast has been stipulated in the Surah _______?', '{"A":"Surah Baqarah","B":"Surah Fateh","C":"Surah Namal","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Baqarah is the second and longest chapter of the Quran. It consists of 286 verses, 6,201 words and 25,500 letters.', 0, 0, 0, 1790964554650) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_38f2fd559699e2ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Who Translated Holy Quran the first time in Persian?', '{"A":"Hazrat Majdad Alif Sani","B":"Shah Wali Ullah","C":"Sheikh Abdul Qadir Jillani","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Quran was first time translated into Urdu:Shah Abdul Qadir and Shah Rafiuddin (Mozah Al-Quran)***The Holy Quran was first time translated into Punjabi:Tauqir Amaan Khan****The Holy Quran was first time translated into Sindhi:Aakhund Azzizullah****The Holy Quran first time translated into English:George Sale**Holy Quran was translated for the first time in IndiaPersian***Holy Quran was translated for the first time in the WorldPersian', 0, 0, 0, 1790964554650) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e5f7f13bf4baae79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the Subject of Holy Quran?', '{"A":"Universe","B":"Earth","C":"Animal","D":"Human"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Subject of the Holy Quran is human being.The Quranic content primarily addresses basic Islamic principles.The total number of verses in the Quran is 6,236, excluding Bismillah, and 6,349, including Bismillah.There are 114 Surahs in the Quran.The Quran contains Juz 30.There are 7 Manazil in the Quran.There are 14 Sajda-e-Tilawat in the Quran.', 0, 0, 0, 1790964554650) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1f12bdde546df8bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which is an extremely imporant and precise surah on the oneness of God?', '{"A":"Surah Namal","B":"Surah Akhlas","C":"Surah Baqara","D":"Surah Toba"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Ikhlāṣ, also known as the Declaration of God''s Unity and al-Tawhid, is the 112th chapter of the QuranPosition: Juzʼ 30Alternate titles (Ar.): At-TawḥīdNo. of letters: 47No. of verses: 4No. of words: 15***', 0, 0, 0, 1790964554650) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b43cf4e2dcf749d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In which Surah of the Holy Quran, the story of Kahf is mentioned?', '{"A":"Surah Ankaboot","B":"Surah Kahf","C":"Surah Maida","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The story of the People of the Cave (Ashab-e-Kahf) is mentioned in Surah Kahf (Chapter 18) of the Holy Quran.It narrates the tale of young men who took refuge in a cave to protect their faith and were made to sleep for centuries by Allah.', 0, 0, 0, 1790964554650) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1124cfcf11e5e7a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In which Surah is the mention of the elephant found?', '{"A":"Surah Al-Fil","B":"Surah Al-Baqarah","C":"Surah Al-Ikhlas","D":"Surah Al-Nas"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The mention of the elephant is in Surah Al-Fil, the 105th chapter of the Quran.It describes how Allah thwarted the army of the Elephant, led by Abraha, in a miraculous event.The Surah consists of 5 verses.It is written in the form of a question.', 0, 0, 0, 1790964554650) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9f72b300f372cf4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In surah Kahf, which animal is mentioned along with the Ashaab-e-Kahf?', '{"A":"Horse","B":"Cat","C":"Dog","D":"Woodpecker"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "kahf" means "the cave in the mountain"the sura is named "kahf" because it speaks about the story of the Companions of the CaveQitmeer is the name of the dog in Surah Kahf.whileThe cave of Ashab e Kahaf is located in Jordan.Ashab e Kahf slept for 309 yearsThe number of Ashab-e-Kahf was 7The story of Ashab al-Kahf is narrated in the eighteenth chapter of the Quran, called “al-Kahf” In verses 9-26****RY30012023ND5-2-2023ND10-3-2023SH26-8-2023', 0, 0, 0, 1790964554650) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_610d42eb60c2d232', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which surah was recited by Holy Prophet at the time of migration (Hijrat-e-Madina)?', '{"A":"Surah-e-Rehman","B":"Surah-e-Yasin","C":"Surah-e-Tawbah","D":"Surah-e-Kausar"}', 'B', NULL, 0, 0, 0, 1790964554729) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5e8e3ad18c606e7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The recitation of Bismillah is called ____?', '{"A":"Tasmiah","B":"Tehleel","C":"Tahajjud","D":"Tashhad"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The recitation of Bismillah is called Tasmiah.Bismillahir Rahmanir Raheem (Arabic: ''بِسْمِ ٱللَّٰهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ) is an Arabic phrase meaning "in the name of God, Most Gracious, Most Merciful"Additional information:The recitation of auzubillah is called ta''awwudh (تَعَوُّذ).The meaning is “I seek refuge in Allah from the outcast Shaitan”.', 0, 0, 0, 1790964554729) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_695235995e8c3a92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Al Furqan meaning Quran name?', '{"A":"The Criterion","B":"Matchless","C":"Figurative","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The name Al-Furqan, or "The Criterion" refers to the Qur''an itself as the decisive factor between good and evil.The Criterion means معیار، فرق ڈالنے والی کتاب', 0, 0, 0, 1790964554729) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_284a4a2047b6b966', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which of the following is the biggest Sin in Quran?', '{"A":"Shirk","B":"Non performance of Hajj","C":"Black magic","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shirk (associating partners with Allah) is the greatest sin in Islam, as mentioned in Surah An-Nisa (4:48). It is the only sin that Allah does not forgive if a person dies without repentance.', 0, 0, 0, 1790964554729) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_50e96e1e0c171ecd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Prophet has been called by the name of "Imam-un-Nas" in the Holy Quran?', '{"A":"Hazrat Adam (AS)","B":"Hazrat Noah (AS)","C":"Hazrat Ibrahim (AS)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ibrahim (AS) is referred to as "Imam-un-Nas" (Leader of Mankind) in the Holy Quran.In Surah Al-Baqarah (2:124), Allah mentions making him an Imam (leader) for the people.', 0, 0, 0, 1790964554729) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d0941aae571282de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The serial number of Surah Yaseen with respect to Surahs in Quran is ____?', '{"A":"36th","B":"34th","C":"32th","D":"30th"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The serial number of Surah Yaseen with respect to Surahs in the Quran is 36th.It is the 36th chapter of the Quran.It has 83 verses.It has 5 rukus.It is regarded as an earlier "Meccan surah."It is known for its significant spiritual and religious importance in Islam.', 0, 0, 0, 1790964554729) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5f656fcd4bee5d34', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the meaning of the word "Quran"?', '{"A":"Frequently Recited","B":"Rarely Recited","C":"Recited Once","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word Qur''an comes from the Arabic word "Qaraa" which means to read, " to recite"The total number of Surah in the Holy Quran is 114The Medinan Surahs typically have more and longer ayat The Makki Surahs typically have more and short ayat Madani Surahs revealed in Year = 10Makki Surahs revealed in Year = 13the number of Makki Surah is 86 the number of Madni is 28', 0, 0, 0, 1790964554729) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_da55b15cf81ea813', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Makki and Madni surah in Holy Quran?', '{"A":"113","B":"114","C":"116","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation the number of Makki Surah is 86 the number of Madni is 28Madani Surahs revealed in Year = 10Makki Surahs revealed in Year = 13The Medni Surahs typically have more and longer ayat The Makki Surahs typically have more and short ayat Additional InformationThe number of verses in the Quran is 6,666.The total number of verses in Quraan is 6,236 excluding Bismillah and 6349 including Bismillah.The total number of Surah in the Holy Quran is 114There is Juz 30 in the Qur''an.There are 14 Sajda talawat in the Quran.D19-3-2023ND29-5-2023', 0, 0, 0, 1790964554729) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_84e328d0fc75ffcd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Surahs name is only one letter?', '{"A":"Four","B":"Three","C":"Two","D":"Five","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Three Sorahs in Quran that starts only one letter: Surah 50 — qaaf (ق) Surah 38 — saad (ص). Surah 68 — nune (ن).', 0, 0, 0, 1790964554812) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a7c8ddeb4dcbb9a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the name of Hadis, which is according to the Holy Quran and reason?', '{"A":"Hadith Qauli","B":"Hadith Mauzoo","C":"Hadith Sahih","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hadith Sahih refers to a saying or action of the Prophet Muhammad (PBUH) that is verified to be authentic and trustworthy.It is considered the most reliable type of Hadith, as it is based on a continuous chain of narration from the Prophet SAW himself.', 0, 0, 0, 1790964554812) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_66138f2a6058aee3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In which surah Quran name of Hazrat Zaid Bin Haris is mentioned?', '{"A":"Baqra","B":"Nisa","C":"Al-Ahzab","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Mu''tah in September 629, where Zayd was killed.Hazrat Zaid bin Haris the adopted son of the Islamic Prophet Muhammad.Hazrat Zaid bin Haris is commonly regarded as the fourth person to have accepted IslamZayd Bin Harith''s (R.A) name is mentioned in the Al-Ahzab 33rd Surah of the Quran Hazrat Zaid was the first adult male to become a Muslim and the only Muslim apart from Muhammad to be mentioned by name in the QuranThe Holy Prophet (PBUH) gave the title of Hub Rasool-Ullah to Hazrat Usama bin Zaid R.A ND21-2-2023', 0, 0, 0, 1790964554812) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bc5979c403cc07a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Hazrat Umar R.A embraced Islam, influenced by which Surah of Holy Quran?', '{"A":"Surah Fateh","B":"Surah Yaseen","C":"Surah Taha","D":"Surah Almaedah"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The verses recited before Hazrat Umar (R.A) were from Surah TahaEmbraced by Islam in 616 AD at the age of 32 years.He later became the second Caliph (634–644 AD).He belonged to the Banu Adi clan of Quraysh.Last updated by NS on 01 MAY 2026', 0, 0, 0, 1790964554812) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4f0d044818b704d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which surah of the Holy Quran in which Allah has promised to protect the Holy Quran?', '{"A":"Surah Al-Hijr","B":"Al-Maida","C":"Surah Al-Baqarah","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allah, the Almighty, says in the Quran: “Indeed, it is We who sent down the Quran, and indeed, We will be its guardian.” (Surah Al-Hijr, 15:9).This verse is a testament to the divine promise that the Quran will remain unchanged and preserved in its original form.', 0, 0, 0, 1790964554812) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f3463a32a5b615bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the name of Surah of Holy Quran which mentions the rights of the parents?', '{"A":"Surah Mudassar","B":"Surah Luqman","C":"Surah Ahzab","D":"Surah Al Maeda"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Surah Luqman, Verse 14, it says: "We have enjoined upon man to be kind to his parents."Similarly, in Surah Al-An''am, Verse 151, it says: "You have to be kind to your parents."', 0, 0, 0, 1790964554812) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2fb29806a6d1593e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Most of Hafiz Quran were martyred in which battle?', '{"A":"Khyber","B":"Yamama","C":"Badr","D":"Uhud"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation More than 70 huffaz were martyred at the Battle of Yamama in December 632.This battle, fought between the forces of Hazrat Abu Bakr and Musaylimah, a self-proclaimed prophet.It motivated Hazrat Abu Bakr to complete the compilation of the Qur''an.', 0, 0, 0, 1790964554812) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6a52bfdd78a7a4e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which surahs are called Mauzatain?', '{"A":"Last four surahs","B":"First two surahs","C":"Last two surahs","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mauzatain meaning the two [surahs] seeking refugeThe last two surahs (chapters) of the Qur''an:Al-Falaq (ch. 113)An-Nās (ch. 114)ND16-3-2023', 0, 0, 0, 1790964554812) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5f66167de71f5653', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which Surah of the Quran has the name “Allah” in every single verse?', '{"A":"Surah Al-Ikhlas [112]","B":"Surah Al-Mujadila [58]","C":"Surah Muhammad [47]","D":"Surah Al-Fatihah [1]"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Mujadila [58] is the Surah of the Quran that has the name “Allah” in every single verse.This unique feature distinguishes it from other Surahs.Surah Al-Mujadila means "The Woman Who Disputes" or "The Pleading Woman."', 0, 0, 0, 1790964554880) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_33b1e74e1f508647', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'According to the Holy Quran, there are ______ recipients of “Zakat”.', '{"A":"7","B":"6","C":"8","D":"10","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are 8 categories (Masarif) for the distribution of Zakat.These categories are outlined in Surah Al-Taubah (9:60) of the Quran.These are:The poor (Al-Fuqara).The needy (Al-Masakin).Zakat administrators.New Muslims and friends of the Muslim community.Slaves and captives.The debt-ridden.In the cause of God.The wayfarer (travelling with few resources).', 0, 0, 0, 1790964554880) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_707cbd72c9cb47cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Verses are in Surah “Al Fatiha”?', '{"A":"7","B":"5","C":"6","D":"3","E":"10"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation surah Al Fatiah Other names: The Key, The Openersurah Al Fatiah No. of verses: 7surah Al Fatiah No. of words: 29surah Al Fatiah No. of letters: 139', 0, 0, 0, 1790964554880) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e7afc399feab4d9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The Shortest Surah Al-Kawthar has ______ verses?', '{"A":"5","B":"4","C":"3","D":"2"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Surah Al Kawthar is the shortest surah of Holy Quran(3 Verses).The Surah Baqarah is longest surah of Holy Quran(286 Verses).', 0, 0, 0, 1790964554880) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_57ebaecaa5d87c68', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', '"There is no compulsion in religion" contained in which of the following Surah?', '{"A":"Al-Baqarah","B":"Al-Akhlas","C":"Al-Fateh","D":"Al-Noor"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "There is no compulsion in religion" is contained in Surah Al-Baqarah, Ayat 256.The full quote is:"There is no compulsion in religion, the right direction is henceforth distinct from error."(Surah Al-Baqarah, 2:256)This verse emphasizes the importance of freedom of choice in matters of faith and religion.', 0, 0, 0, 1790964554880) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d05aa4b2766197db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In which Surah of the Holy Quran, the word "Khatimun Nabiyen" is mentioned?', '{"A":"Al Falq","B":"Al Fateha","C":"Al Tauba","D":"Al Ahzab"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Ahzab is the 33rd chapter of the Quran with 73 verses.It is named after the confederates who fought the Muslims at the Battle of the Trench.It is also known as the Battle of the Parties or the Siege of Madina.', 0, 0, 0, 1790964554880) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e8aa1b2280396ea9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which of following the Quran considered as unpardonable sin?', '{"A":"Shirk","B":"Lie","C":"Jealousy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Islam, shirk is the sin of idolatry or polytheism. Islam teaches that God does not share His divine attributes with any partner.', 0, 0, 0, 1790964554880) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a6f20512ad927ec9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The short period between two Sajda’s is called _____?', '{"A":"Qayaam","B":"Jalsa","C":"Qauma","D":"Qaada"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Rakat is one complete cycle of standing (Qa''adah), bending (Rukoo), prostration (Sajdah), and subsequent sitting (Jalsa).It also includes standing up again in the Salat.', 0, 0, 0, 1790964554880) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4f4a7ff3ddecbc36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'According to the teachings of Quran how many witnesses are required for the financial affairs of transaction?', '{"A":"Two Men","B":"Two Men and Two Women","C":"One Female and One Male","D":"4 Men"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Quran specifies that for financial transactions, "two men" should serve as witnesses. Alternative option: If two men are not available, the requirement can be fulfilled by "one man and two women".', 0, 0, 0, 1790964554961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2e4241756d783977', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The great book "Al-Itqan fi Uloom al-Quran" was composed by whom?', '{"A":"Muhammad Ali Al-Sabuni","B":"Muhammad Hussain Zahid","C":"Imran Ghazail","D":"Jalal al-Din Suyati"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Itqan fi Uloom al-Quran was composed by Jalal uddin Suyati.He was a scholar and writer.In this book, he explained the revelation time of Surahs and Ayats of the Holy Quran.', 0, 0, 0, 1790964554961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3080c092f13b2fbd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The Holy Quran contains the Makki and Madni Surah’s. The Madni surah’s have a general emphasis on _____?', '{"A":"Social & Religious laws & values","B":"Ghazwat (Battles participated by the Prophet (PBUH)","C":"Laws of nature","D":"The Historical facts"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Madni Surahs, revealed in Madina, focus on:The social and religious lawsValues for the Muslim communityIncluding rules for personal and collective behavior, worship, and relationships.Makki Surahs, revealed in Mecca, focus on:The Oneness of God (Tawheed)The Hereafter (Akhirah)The Prophethood of Muhammad (PBUH)The struggle against polytheism and disbeliefThe basic principles of faith and morality', 0, 0, 0, 1790964554961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d322cd0d5bcae0f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'What is the meaning of Al Hadi mentioned in the Holy Quran?', '{"A":"The Guide","B":"The Rich","C":"The Light","D":"The Eternal"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the Holy Quran, "Al-Hadi" means "The Guide or The Way."It refers to Allah as the one who guides humanity to the right path and truth.', 0, 0, 0, 1790964554961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9a764e717bcc3497', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which surah is called "Al-Hamd''?', '{"A":"Al-Baqarah","B":"Al-Yasin","C":"Al-Fatiha","D":"Al-Rehman"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Fatiha is also known as Al-Hamd (The Praise).It has 7 verses, 29 words, and 139 letters.It is also referred to as:As-Salah (The Prayer)Umm al-Kitab (Mother of the Book)Umm al-Quran (Mother of the Quran)Sab''a min al-Mathani (Seven Repeated Ones)Ash-Shifa'' (The Cure).', 0, 0, 0, 1790964554961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_adac640f0dc521c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Bird Hudhud (Woodpecker) is mentioned in which Surah?', '{"A":"Surah Qasas","B":"Surah Namal","C":"Surah Nahl","D":"Surah Saba","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The bird Hudhud (hoopoe) appears twice in Surah An-Naml (27th chapter) of the Quran.It played a crucial role in carrying messages between Prophet Sulayman (AS) and the Queen of Sheba.', 0, 0, 0, 1790964554961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e1ae98a8b0bed706', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many Rukus are there in Surah Al-Baqrah?', '{"A":"40","B":"39","C":"38","D":"35"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Baqarah (The Cow or The Heifer) is the second and longest chapter of the Quran, with 286 verses.It derives its name from the story of the cow (vv. 67-73).Verse 282, the longest verse, is known as ''āyatu d-dayn.It consists of 25,500 letters and is positioned in Juzʼ 1–3.The chapter has 40 Rukus and is classified as Medinan.Hazrat Ibrahim (علیہ السلام) is mentioned 13 times.The verse 183 describes the obligation of fasting (soam).', 0, 0, 0, 1790964554961) ON CONFLICT(id) DO NOTHING;
