INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_de80c84ca308d373', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In which surah is Muhammad name mentioned?', '{"A":"Surah Aal Imraan","B":"Surah Al-Ahzaab","C":"Surah Muhammad","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muhammad is the 47th surah of the Quran with 38 verses The name "Muhammad" is mentioned four times in the Quran, and the name "Ahmad" is mentioned one time.************Name “Muhammad”, four times mentioned in the whole Quran.Aal Imraan 3: 144;Al-Ahzaab 33: 40;Muhammad 47: 2; andAl-Fatah 48: 29Name “Ahmed”, one time mentioned in the whole Quran.Al-Saff 61: 6.', 0, 0, 0, 1790964555052) ON CONFLICT(id) DO NOTHING;
