INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5ca6762e790458c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'There are verses in Surah Al Ahzab?', '{"A":"70","B":"73","C":"76","D":"80"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Ahzab means the confederates, or "the clans", "the coalition", or "the combined forces"Al-Ahzab is the 33rd chapter (surah) of the Quran Al-Ahzab 73 verses (Ayat).', 0, 0, 0, 1790964555052) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8a86cb7990125214', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Madni surahs are?', '{"A":"Short","B":"longer","C":"Both","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Medinan Surahs occur mostly at the beginning and in the middle of the Qur''anThe Medinan Surahs typically have more and longer ayat The Madni Surahs were revealed at Medina after Muhammad''s hijra from Mecca.Madani Surahs revealed in Year = 10the first complete Madani surah of the Quran is Al-BaqarahThe total number of Surah in the Holy Quran is 114 the number of Makki Surah is 86 the number of Madni is 28******', 0, 0, 0, 1790964555052) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ab06f994ec4ca11f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Tayammum (Ablution with sand) order is in surah?', '{"A":"Nisa","B":"Maidah","C":"Al-i-Imran","D":"Al-Baqara","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tayammum (Ablution with sand) order is in surah Maidah.Wazu (Ablution) was ordered on 5 A.HThe acts which break the ablution are called Nawaqiz-e-WazuThere are 6 Sunnah acts of ablutionThere are 4 obligations for ablution.13 Sunnah are in four obligations of AblutionBy Hazrat Jibrail (علیہ), Prophet ﷺ learnt Salat & ablutionوضو کے چار فرائض ہیں۔نمبر 1: چہرہ دھونانمبر 2: دونوں ہاتھوں کو کہینیوں تک دھونانمبر 3: چوتھائی سر کا مسح کرنانمبر 4:پاوں کا ٹخنیوں سمیت دھونا****', 0, 0, 0, 1790964555052) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_905228c500c40f34', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Mubahila verse is in surah?', '{"A":"Baqarah","B":"Al-Imran","C":"Nisa","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Mubāhala verse is verse 61 of Chapter 3 of the Holy Qur''an (Sura Al ''Imran) which is about the Prophet''s (s) encounter with Christians of Najran.', 0, 0, 0, 1790964555052) ON CONFLICT(id) DO NOTHING;
