INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b9131f3859b6b10a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In whch surah are the 27 Attributes of God mentioned?', '{"A":"Surah Al-Qalam","B":"Surah Al-Mulk","C":"Surah Hadeed","D":"Surah At-Talaq","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Attributes of God خدا کی صفات al-Ḥadīd is the 57th chapter of the Quran with 29 verses.This is an Al-Musabbihat surahit begins with the glorification of Allah.Classification: MedinanNo. of letters: 2475No. of Rukus: 4No. of verses: 29No. of words: 575ND7-1-2023', 0, 0, 0, 1790964555140) ON CONFLICT(id) DO NOTHING;
