INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c0373daf60d1c16c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which is the best night mentioned in Holy Quran?', '{"A":"Shab-e-Qadar","B":"Shab-e-Miraj","C":"Shab-e-Bara’at","D":"All of these","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shab-e-Qadar is the best night mentioned in the holy Quran***find in Ramzan last ten days night like 21, 23, 25, 27, 29Shab e Qadr, also known as Laylat al-Qadr, is an important night for Muslims since it is this night when Allah revealed the Holy Quran from heaven.As stated in the verses of the Quran, Allah states in verse 1 of Surah Qadar, “Indeed, we sent the Quran down in the Night of Decree.”RK03-12-2022', 0, 0, 0, 1790964555140) ON CONFLICT(id) DO NOTHING;
