INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9364de85eb2840a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'In which Surah of the Holy Quran, the word ” Khatimun Nabiyen ” is mentioned?', '{"A":"Al Tauba","B":"Al Fateha","C":"Al Falq","D":"AL Ahzab","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Ahzab is the 33rd chapter of the Quran with 73 verses. The sūrah takes its name from the mention of the parties, or confederates, who fought the Muslims at the Battle of the Trench, also known as the Battle of the Parties and as the Siege of Madinah', 0, 0, 0, 1790964555216) ON CONFLICT(id) DO NOTHING;
