INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8387daf634996427', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which words of the Holy Quran are not explained by a common person?', '{"A":"Shamsi","B":"Qamari","C":"Muqte’aat","D":"All of them","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation these word are called Muqte’aat alif أ, hā هـ, ḥā ح, ṭā ط, yā ي, kāf ك, lām ل, mīm م, nūn ن, sīn س, ʿain ع, ṣād ص, qāf ق, rā ر.', 0, 0, 0, 1790964555288) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_79bceecacdf4d715', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which is the second longest Surah?', '{"A":"Baqarah","B":"Aal-e-Amran","C":"Yaseen","D":"Rahman"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Aal-e-Amran is the second longest surah of Holy Quran. Surah Aal-e-Amran has 227 verses. Al-Baqarah is the second and longest chapter of the Quran.AL-BAQARAH is named after the story of the Cow occurring in Surah (vv. 67-73).ItAL-BAQARAH consists of 286 verses282 verse of Al-Baqara is the longest verse of the QuranThe 282 verse of Surah Al Baqara is known as ayatu d-daynAl-Baqara. Position: Juz 1–3Al-Baqara is Medinan surahAl-Baqara. No. of Rukus: 40 Al-Baqara. has 25,500 letters*******VU CBT FIA SI ASI PAPER 13-12-2021', 0, 0, 0, 1790964555288) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c2cca03da4a44265', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'According to Holy Quran What is the chosen religion of Allah?', '{"A":"Islam","B":"Fire worship","C":"Idol worship","D":"Sun worship","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Arabian polytheism, the dominant form of religion in pre-Islamic Arabia, was based on veneration of deities and spirits. Worship was directed to various Gods and goddesses, including Hubal and the goddesses al-Lāt, al-''Uzzā, and Manāt, at local shrines and temples such as the Kaaba in Mecca.', 0, 0, 0, 1790964555288) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_93c0280f2f9d14e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The word Quran literally means:', '{"A":"nobel","B":"restriction","C":"instructions","D":"right","E":"recitation"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word Qur''an comes from the arabic word "Qaraa" which means to read,So the Qur''an is a noun from the verb qaraa .The Quran is a Holy Book that is revealed to the prophet Mohammed peace be upon him through which he was asked by Allah (God) to spread His word of peace and guidance that is known by Islam.', 0, 0, 0, 1790964555288) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dc3447d044508d38', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Which term is for the longest Ayah of the Holy Quran?', '{"A":"Ayat e Mubahala","B":"Ayat e Mudayana","C":"Ayat e Madina","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah-e-Baqrah has 286 Ayats and 40 Rukus', 0, 0, 0, 1790964555288) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5851f0906ba19afc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'Al Quran ul Hakeem is mentioned which surah?', '{"A":"Surah Yaseen","B":"Surah Al-Baqrah","C":"Al Imran","D":"Surah Al-Waqia","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the very beginning of Surah Yaseen, Allah takes an oath: By the Hakeem Quran. Allah says that the Quran is hakeem.AGM 02.05.2023', 0, 0, 0, 1790964555288) ON CONFLICT(id) DO NOTHING;
