INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9d1468fd66156785', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The largest Madni Surah in Quran is:', '{"A":"Surah Al Falaq","B":"Surah Al Fatiha","C":"Surah Al Baqarah","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest Madni Surah of the Quran is Al Baqarah*****40 Rukus in Surah Al-BaqarahAl-Baqarah means: "The Heifer" or "The Cow" Al-Baqarah is the second and longest surah of the Quran.Al-Baqarah consists of 286 ayat, 6,201 words, and 25,500 letters***', 0, 0, 0, 1790964555357) ON CONFLICT(id) DO NOTHING;
