INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_95870ee06a48fb98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'The Holy Quran contains ______Makki Surahs and _________ Madani Surahs______?', '{"A":"88  -- 26","B":"90  -- 24","C":"86  -- 28","D":"100 -- 14"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The total number of Surah in the Holy Quran is 114 the number of Makki Surah is 86 and Madni is 28There are 11 Sajdah are there in Makkah SurahThere are only 03 Sajdah are there in Medinan Surah13 years Makki Surah was revealed**ND13-1-2023', 0, 0, 0, 1790964555357) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5edac6b4f173c0af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many surah are named with animal names?', '{"A":"5","B":"6","C":"2","D":"3"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are more than 200 verses in the Quran dealing with animalsThe biggest animal mentioned in Holy Quran Elephant.The smallest animal mentioned in Holy Quran Mosquito.The six chapters of the Quran are named after animals or insects:1. Surat 2, Al Baqarah (The Cow);2. Surat 6, Al Anaam (The Cattle),3. Surat 16, Al Nahl (The Bees);4. Surat 27, Al Naml (The Ants);5. Surat 29, Al Ankabut (The Spider);6. Surat 105, Al Fil.****nd9-2-2023', 0, 0, 0, 1790964555426) ON CONFLICT(id) DO NOTHING;
