INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a53fdc8464bfb7d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The Zakat and Ushr Ordinance was promulgated on _____?', '{"A":"29th June 1981","B":"20th June 1980","C":"21st August 1979","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: 20 June 1980Introduced by: General Muhammad Zia-ul-HaqZakat Rate: 2.5% on savingsUshr: Tax on agricultural producePurpose: Poverty alleviation and welfare distributionLast verified on 12-06-2026', 0, 0, 0, 1790964555596) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c4db47e94bcacca8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'First Azan was called out in ______ A.H.', '{"A":"1 A.H.","B":"2 A.H.","C":"3 A.H.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Azan: 1 A.H., after the migration to Madinah.First Muezzin: Bilal ibn Rabah (RA).Chosen by: Prophet Muhammad (PBUH) Title: Sayyid al-Mu’azzinin (Leader of Muezzins).Last updated by NA ON 16-09-2026', 0, 0, 0, 1790964555596) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2cf3615fd9402340', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'In Hajj, Stoning of the Devil, is called ____?', '{"A":"Ramee","B":"Tawaf","C":"Istilam","D":"Sayee"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ramee (Ramy al-Jamarat) is the ritual of stoning the Devil during Hajj.Place: MinaJamarat: 3Days: 10th, 11th & 12th Dhul-HijjahOptional 13th: For pilgrims who stay in MinaMinimum Pebbles: 49Purpose: Commemorates Prophet Ibrahim (AS) rejecting Satan’s temptation.', 0, 0, 0, 1790964555596) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_690042520a4d467d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Hazrat ______ levied zakat on horses?', '{"A":"Hazrat Umer","B":"Hazrat Usman","C":"Hazrat Abu Bakar","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Umar (RA) levied Zakat on horses during his caliphate, Prophetic Era: Horses were exempt from Zakat under the Prophet (PBUH) and Abu Bakr (RA).Hazrat Ali (RA): He later removed the Zakat requirement on horses', 0, 0, 0, 1790964555596) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ce471337e90b2d20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Salat-e-Kasoof is offered at the time of ____?', '{"A":"Earthquake","B":"Lunar eclipse","C":"Solar (Sun) eclipse","D":"Heavy rain"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Namaz-e-Kasoof (نماز کسوف) is offered during a solar eclipse.Rakahs: 2Adhan/Iqamah: Not givenPurpose: Worship Allah and seek forgiveness during the eclipseAdditional information:Namaz-e-Khasoof (نماز خسوف) is offered during a lunar eclipse.Last verified on 07-07-2026', 0, 0, 0, 1790964555596) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e2021ac69a68faea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Nisab of zakat for gold is _____?', '{"A":"7.5 tola","B":"8 tola","C":"5 tola","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nisab (minimum limit) for gold is 7.5 tola (87.48 grams).The ratio/nisab of Zakat is 2.5%.Zakat was made obligatory in 2 A.H.It was fully implemented in 9 A.H.Additional information:Silver Nisab: 52.5 tola = 612.36 gramsThe word “Zakat” occurs 32 times in the Holy Quran.Zakat means purification and growth of wealth.“Zakat is the treasure of Islam” is a famous saying of the Holy Prophet (PBUH).Last verified on 11-05-2026', 0, 0, 0, 1790964555596) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3ad501e0aa65dd78', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many farz Wuzu (ablution) has?', '{"A":"Three","B":"Five","C":"Two","D":"Four"}', 'D', NULL, 0, 0, 0, 1790964555596) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_766000a86452af57', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What type of prayer is Nimaz-e-Janaza?', '{"A":"Fera-e-Ain","B":"Sunnat","C":"Farz-e-Kaffaya","D":"Wajib"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation No Sajdas in Salat-e-Janaza.Namaz-e-Janazah is performed standing in line.It includes 4 Takbeers.It is Farz-e-Kifaya.The first Namaz-e-Janazah performed by the Holy Prophet ﷺ was for Asad bin Zaraara (RA).Last verified on 18-05-2026', 0, 0, 0, 1790964555596) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_34d52fbecc964eb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What is the distance required for Qasr in prayer ___ ?', '{"A":"58 km","B":"85 km","C":"78 km","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Minimum distance: Approximately 77–78 kmQasr applies to: 4-rakat obligatory prayersZuhr: 4 → 2 rakatsAsr: 4 → 2 rakatsIsha: 4 → 2 rakatsFajr: Remains 2 rakatsMaghrib: Remains 3 rakatsQasr is for a traveler (musafir) meeting the required travel conditions.Last updated NA on 10-09-2026', 0, 0, 0, 1790964555685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9626b04c463afa46', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The Namaz e Janaza is ___', '{"A":"Farz e Kaffaya","B":"Sunnat","C":"Wajab","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Namaz-e-Janaza is Farz-e-KifayaNo Sajdas are in Salat-e-JanazaNamaz-e-Janazah is performed by standing in line4 Takbeers are in Namaz-e-Janaza The first Namaz-e-Janazah performed by the Holy Prophet ﷺ was for Asad bin Zaraara SahabiLast updated question NS on 10-09-2026', 0, 0, 0, 1790964555685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0c4eb7efdeb3a5ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Name the Kalima which is recited in a funeral procession?', '{"A":"Shahadat","B":"Tamjeed","C":"Astaghfaar","D":"Tauheed"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kalima Shahadat is the Kalima recited in a funeral procession.Shahadat means testimony or bearing witness.It declares belief in the Oneness of Allah and the Prophethood of Muhammad ﷺ.Last verified on 23-08-2026', 0, 0, 0, 1790964555685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7903ebf8a5ac6204', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Who was the first mu''azzin (prayer caller) of Islam?', '{"A":"Hazrat Bilal","B":"Hazrat Umer","C":"Hazrat Usman","D":"Hazrat Abubakar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Bilal called the first Azan of Fajar prayerFirst Azan was called out in 1 A.HThe Title of Bilal ibn Rabah: Sayyid al-MuʾaḏḏinBorn: 580 AD, Mecca, Saudi ArabiaDied: on March 2, 640 AD, in Damascus, SyriaPlace of burial: Bab el Saghir Cemetery, Damascus, SyriaHazrat ''Umar was the first person to suggest the calling of the Azan.', 0, 0, 0, 1790964555685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_98ba809e8d55d8ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'When Hajj was made compulsory (obligatory)?', '{"A":"8 A.H","B":"7 A.H","C":"10 A.H","D":"9 A.H"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hajj was made compulsory in 9 A.H.It is the fifth pillar of Islam.It is obligatory once in a lifetime for Muslims who can afford it physically and financially.The word Hajj means “to intend” or “to set out for a journey.”Hajj is performed in Makkah during the Islamic month of Dhul-Hijjah.Mentioned in: Quran (Surah Al-Baqarah and Surah Aal-e-Imran)Additional information:The first Hajj in Islam led by Muslims took place in 9 A.H.Prophet Muhammad performed the Farewell Hajj in 10 A.H.Last verified on 10-05-2026', 0, 0, 0, 1790964555685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_533c50d58004244a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'When did the Holy Prophet (SAW) performed Hajjatul-Wada (Farewell (Last) Sermon)?', '{"A":"10 AH (632 AD)","B":"9 AH (631 AD)","C":"8 AH (630 AD)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet (SAW) performed Hajjat-ul-Wida in the 10th Hijri (March 6, 632 A.D)It was performed on Friday, the 9th of Dhu al-Hijjah.The Prophet (PBUH) delivered his final sermon during the Hajj on Mount Arafat.It is also known as Farewell Sermon.This final pilgrimage included his renowned Farewell Sermon.Last verified on 11-06-2026', 0, 0, 0, 1790964555685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_24911215fa6c040b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'When was Fasting (Sawm/Roza) made obligatory in Islam?', '{"A":"8th Shaban, 2 A.H","B":"7th Shaban, 2 A.H","C":"10th Shaban, 2 A.H","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When fasting was made obligatory:Timing: Second year of Hijrah (2 AH / 624 CE), in the month of Sha''banFirst fast: Ramadan 2 AHKey verse: Surah Al-Baqarah (183–185)Prophet''s practice: Fasted Ramadan for 9 years (until 11 AH)Before Ramadan: Muslims fasted on Ashura (10th Muharram) and three days each monthLast updated by NS on 5-09-2026', 0, 0, 0, 1790964555685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0b4bbe39af40bbd1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Zakat is how much percentage on wealth?', '{"A":"1.5%","B":"2.5%","C":"3.5%","D":"5%"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zakat is a compulsory 2.5% (or 1⁄40) levy on net qualifying wealthLast updated by NA on 22-April-2026', 0, 0, 0, 1790964555685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f819a0391ca87f07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What is the fundamental pillar of Islam which requires both physical and financial sacrifices ?', '{"A":"Hajj","B":"Zakat","C":"Salat","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hajj requires both physical effort and financial expenditure.Hajj is the fifth pillar of Islam.It is obligatory once in a lifetime for Muslims who are physically and financially capable.Hajj is performed in Makkah during the month of Dhul-Hijjah.Last verified on 04-09-2026', 0, 0, 0, 1790964555771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d9d764ebd4e14c7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which is the Second pillar of Islam?', '{"A":"Namaz","B":"Roza","C":"Zakat","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are five pillars of Islam:First Pillar: Shahadatain (شہادتیں) – declaration of faith: “There is no god but Allah, Muhammad ﷺ is His Messenger”Second Pillar: Namaz (نماز) – five daily prayersThird Pillar: Zakat (زکوٰۃ) – obligatory charity, 2.5% of wealth above NisabFourth Pillar: Fasting (Sawm / روزہ) – during Ramadan, abstaining from food, drink, and bad deedsFifth Pillar: Hajj (حج) – pilgrimage to Makkah at least once in a lifetime if ableLast verified on 22-03-2026', 0, 0, 0, 1790964555771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_63b9220252ba7c1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What is the verbal meaning of "Zakat"?', '{"A":"Purification","B":"Prayer","C":"Fasting","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The verbal meaning of “Zakat” is Purification.It comes from the Arabic root meaning “to purify” and “to grow”.In Islam, Zakat purifies wealth and increases blessings.It is the 3rd fundamental pillar of Islam.It was made compulsory in 2 AH.It is mentioned 32 times in the Holy Quran.Last verified on 25-04-2026', 0, 0, 0, 1790964555771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9b02637af25bcae6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many basic pillars of Islam are there?', '{"A":"4","B":"6","C":"5","D":"7"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are five pillars of Islam:First Pillar: Shahadatain (شہادتیں) – Faith declarationSecond Pillar: Namaz (نماز) – five daily prayersThird Pillar: Zakat (زکوٰۃ) – Obligatory charity (2.5% of wealth above Nisab)Fourth Pillar: Fasting (Sawm / روزہ) – Ramadan fastingFifth Pillar: Hajj (حج) – Pilgrimage to Makkah once in a lifetime, if ableLast updated by NS on 5-09-2026', 0, 0, 0, 1790964555771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_25feed1372bd49e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The name of second Kalimah is _____?', '{"A":"Kalimah Istighfar","B":"Kalimah Sahadat","C":"Kalimah Tauheed","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Six Kalimas are commonly taught to Muslims:1. Kalimat at-Tayyibah — كَلِمَاتْ اَلطَّيِّبَةMeaning: Word of Purity2. Kalimat ash-Shahadah — كَلِمَاتْ اَلشَّهَادَةMeaning: Word of Testimony3. Kalimat at-Tamjeed — كَلِمَاتْ اَلتَّمْجِيدْMeaning: Word of Majesty4. Kalimat at-Tawheed — كَلِمَاتْ اَلتَّوْحِيدْMeaning: Word of Oneness5. Kalimat al-Istighfar — كَلِمَاتْ إِسْتِغْفَارْMeaning: Word of Penitence / Seeking Forgiveness6. Kalimat Radd al-Kufr — كَلِمَاتْ رَدّْ اَلْكُفْرMeaning: Word of Rejection of DisbeliefLast verified on 01-09-2026', 0, 0, 0, 1790964555771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_47b0916ba9fae5f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many pebbles are needed at a minimum for the ritual of stoning during Hajj?', '{"A":"21","B":"49","C":"70","D":"50"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اس سوال کو اچھے سے سمجھیں کم از کم 49 کنکریاں(10 ذوالحجہ = 711 ذوالحجہ = 2112 ذوالحجہ = 21) زیادہ سے زیادہ 70 کنکریاںاگر حاجی 13 ذوالحجہ کو بھی رمی کرے (3 دنِ تشریق پورے کرے) تو13 ذوالحجہ کو = 21کل = 49 + 21 = 70 Last verified on 28-08-2026', 0, 0, 0, 1790964555771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d23aaf1840c77d92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many pebbles are needed at a meximum for the ritual of stoning during Hajj?', '{"A":"70","B":"49","C":"60","D":"39"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maximum pebbles required: 70 pebblesBreakdown:10th Dhul-Hijjah: 7 pebbles11th Dhul-Hijjah: 21 pebbles12th Dhul-Hijjah: 21 pebbles13th Dhul-Hijjah (if stayed): 21 pebblesTotal Maximum = 70 pebblesکم سے کم 49 چاہیے ہوتے ہیں۔Last verified on 28-08-2026', 0, 0, 0, 1790964555771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_05f3aca811293d10', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What is the meaning of Hajj?', '{"A":"To plain","B":"To aim","C":"To determine","D":"To intend"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hajj means "to intend a pilgrimage".It referring to the annual Islamic pilgrimage to Makkah.To intend a pilgrimage means زیارت کا قصد کرنا It is one of the five pillars of Islam, obligatory for Muslims who can afford it.حج کے متعلق ان سولات کو ضرور پڑھیںClick here', 0, 0, 0, 1790964555771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5fbca0cdf8947087', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'There are _____ types of Hajj.', '{"A":"Four","B":"Three","C":"Two","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are three types of Hajj in Islam.Hajj-ul-Ifrad — Hajj is performed separately without Umrah.Hajj-ul-Qiran — Hajj and Umrah are performed together in one Ihram.Hajj-ul-Tamattu — Umrah is performed first, followed by Hajj in the same Hajj season.Last verified on 28-08-2026', 0, 0, 0, 1790964555859) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_13ce9a95d1b896a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'First pillar of Islam is ____?', '{"A":"Salat","B":"Hajj","C":"Shahadatain","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are five pillars of Islam:First Pillar: Shahadatain (شہادتیں) – declaration of faith: “There is no god but Allah, Muhammad ﷺ is His Messenger”Second Pillar: Namaz (نماز) – five daily prayersThird Pillar: Zakat (زکوٰۃ) – obligatory charity, 2.5% of wealth above NisabFourth Pillar: Fasting (Sawm / روزہ) – during Ramadan, abstaining from food, drink, and bad deedsFifth Pillar: Hajj (حج) – pilgrimage to Makkah at least once in a lifetime if ableLast verified on 22-03-2026', 0, 0, 0, 1790964555859) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ab566e97ab779b36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Zakat was made compulsory in which Hijri?', '{"A":"2 Hijri","B":"3 Hijri","C":"4 Hijri","D":"None of the above"}', 'A', NULL, 0, 0, 0, 1790964555859) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4896d4741887e6a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many times did Muhammad PBUH perform hajj?', '{"A":"1","B":"2","C":"9","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet Muhammad (ﷺ) performed only one Hajj in his lifetime.He performed this Hajj in 10 A.H. (632 CE).It was his first and last Hajj.It was known as Hujjat-ul-Wada (The Farewell Pilgrimage).Additional information:The Holy Prophet (ﷺ) performed 4 Umrahs in his lifetime.His first Umrah after the Hijrah to Madinah was performed in 7 A.H. (629 CE) (Umrah al-Qada).Last verified on 23-07-2026', 0, 0, 0, 1790964555859) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_af13fc79278a4845', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many camels did Prophet Muhammad (ﷺ) sacrifice with his own hands on the occasion of Hajj?', '{"A":"63 camels","B":"67 camels","C":"83 camels","D":"65 camels"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad (ﷺ) sacrificed 63 camels with his own hands during Hajj.The total number of camels sacrificed was 100.The remaining 37 camels were sacrificed by Hazrat Ali (RA) on the Prophet''s (ﷺ) behalf.This took place during Hajjat-ul-Wada (Farewell Pilgrimage) in 10 AH (632 AD).The sacrifice is the basis of the practice of Qurbani during Eid-ul-Adha.Last verified on 22-07-2026', 0, 0, 0, 1790964555859) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e54ac0980fe31b76', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Who started the practice of Tarawih prayers in congregation?', '{"A":"Hazrat Abu Bakr","B":"Hazrat Ali","C":"Hazrat Umar","D":"Hazrat Usman"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Umar (R.A.) started the practice of offering Tarawih prayers in congregation during Ramadan.This was organized in 14 AH during his Caliphate.He gathered the Muslims behind Hazrat Ubayy ibn Ka''b (R.A.) as the Imam.Tarawih is a Sunnah Mu''akkadah (Emphasized Sunnah).It is offered after Isha and before Witr during the month of Ramadan.Last verified on 18-07-2026', 0, 0, 0, 1790964555859) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ca2b23214128291f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'When the Holy Prophet (PBUH) offered his first Eid prayer?', '{"A":"1 A.H","B":"2 A.H","C":"3 A.H","D":"4 A.H"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Eid prayer: 2 A.H.Rak''ahs in Eid prayer: 2Additional Takbirs: 6Additional information:First Jumu''ah prayer: 12 Rabi'' al-Awwal, 1 A.H.Farewell Hajj performed: 10 A.H.Last verified on 06-07-2026', 0, 0, 0, 1790964555859) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4ef6a858b635d8a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'When ﬁve prayers became Farz?', '{"A":"12th Nabvi","B":"10th Nabvi","C":"13th Nabvi","D":"11th Nabvi"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Five prayers were declared compulsory in the 10th NabviNamaz was commanded in the Quran 700 times.On the night of Miraj (Isra and Miraj)Additional informationSalat Juma became Farz in Madina.Hajj was made compulsory in the 09th Hijri.Last update 0n 21-07-2026 by NA', 0, 0, 0, 1790964555859) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_796c1dc00151d1f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Tawaf-e-Rukn is which component of Hajj?', '{"A":"Nafl","B":"Wajib","C":"Obligatory (Farz)","D":"Sunnat"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tawaf-e-Rukn is an obligatory (Farz) component of Hajj.It is also known as Tawaf-e-Ziyarat or Tawaf al-Ifadah.It is performed after Waqoof-e-Arafat (9th Dhul Hijjah) during Hajj.Without performing this Tawaf, Hajj is not completed.Last verified on 30-06-2026', 0, 0, 0, 1790964555940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0a87fdd4812a7cbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many Takbeers are in Namaz-e-Janaza?', '{"A":"Two","B":"Four","C":"Six","D":"One"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Namaz-e-Janazah includes 4 Takbeers.No Sajdas in Salat-e-Janaza.It is performed standing in line.It is Farz-e-Kifaya.The first Namaz-e-Janazah performed by the Holy Prophet ﷺ was for Asad bin Zaraara (RA).Last verified on 18-05-2026', 0, 0, 0, 1790964555940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_49c854089baa6816', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The Holy Prophet (PBHU) performed Hajj in ____?', '{"A":"9 Hijri","B":"10 Hijri","C":"8 Hijri","D":"11 Hijri"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hajj year: 10 A.HGregorian date: March 6, 632 A.DDay of sermon: 9th Dhul-Hijjah (Friday)Event name: Hajjat-ul-Wida (Farewell Pilgrimage)Number of Hajj by Prophet SAW: 1 (only once)Last verified on 01-04-2026', 0, 0, 0, 1790964555940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a8e7410ad37805bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many Words are there in First Kalimah?', '{"A":"7","B":"6","C":"8","D":"9"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are 7 words in the First Kalimah (Kalimah Tayyibah).The Arabic text is: لَا إِلٰهَ إِلَّا اللهُ مُحَمَّدٌ رَسُولُ اللهِThe breakdown of the words is:La (لَا)Ilaha (إِلٰهَ)Illa (إِلَّا)Allahu (ٱللَّٰهُ)Muhammadun (مُحَمَّدٌ)Rasulul (رَسُولُ)Allah (ٱللَّٰهِ)Additional information:There are 26 letters in the First Kalimah.There are zero dots in the First Kalimah.Last verified on 18-07-2026', 0, 0, 0, 1790964555940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_40643bd5d9464430', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'During Hajj, pilgrims shave their heads as a symbol of humility and submission. What is this act called?', '{"A":"Sa''i","B":"Tawaf","C":"Halq","D":"Ihram"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The act of shaving the head during Hajj is called Halq (حلق).It is performed after completing the major rituals of Hajj.Halq symbolizes humility, obedience, and submission to Allah.It marks the completion of the state of Ihram.Men usually shave the entire head, while women trim a small portion of their hair (Taqsir).Last verified on 12-07-2026', 0, 0, 0, 1790964555940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5be4c05110b92f57', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which article of the constitution of 1973 is related to the affairs of Zakat?', '{"A":"46","B":"44","C":"31","D":"20"}', 'C', NULL, 0, 0, 0, 1790964555940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_77a2e5907b7f0717', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The Khutba of Hajj (Hajj sermon) is delivered in which mosque?', '{"A":"Masid-e-Nimra","B":"Masjid Haram","C":"Masjid Khaif","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Khutba of Hajj is delivered at Masjid an-Namirah (Masjid-e-Nimra) on the Day of Arafah.It is delivered on 9th Dhul-Hijjah before the Dhuhr and Asr prayers.Masjid an-Namirah is located on the Plain of Arafat near Mount Arafat.Last verified on 09-07-2026', 0, 0, 0, 1790964555940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_affc2d85f8bb3b86', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Who builds the first structure of the Holy Kaaba?', '{"A":"Hazrat Adam AS","B":"Hazrat Ibrahim AS","C":"Hazrat Moosa AS","D":"Hazrat Shoaib AS"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Islamic belief, the first structure of the Kaaba was built by Hazrat Adam (A.S).Later, it was rebuilt by Hazrat Ibrahim (A.S) and his son Hazrat Ismail (A.S).The Kaaba is located in Makkah.It is the holiest site in Islam.It is the direction (Qibla) for Muslim prayers.Last verified on 25-04-2026', 0, 0, 0, 1790964555940) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b426cf31623846b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which date of Zil-Hajj is called Yaum-e-Arfat?', '{"A":"9 Zil-Hajj","B":"7 Zil Hajj","C":"10 Zil Hajj","D":"11 Zil Hajj"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Day of Arafah falls on the 9th day of Dhul Hijjah.It is the second day of the Hajj pilgrimage.The following day marks the start of Eid al-Adha.Additional information:Hajj was made compulsory in 9 A.H.The first Hajj was performed in the same year.Hajj is ordained in Surah Al-Baqarah.There are three types of Hajj.The Kalima Tauheed is recited during Hajj.Last verified on 06-07-2026', 0, 0, 0, 1790964556013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bc709bd6970f85ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Who added second Azan for Friday prayers?', '{"A":"Hazrat Ali (RA)","B":"Hazrat Abu Bakr (RA)","C":"Hazrat Usman (RA)","D":"Hazrat Umar (RA)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The second Azan for Jumuah was started by Hazrat Usman (RA).It was introduced during his caliphate.He was the third Caliph of Islam (644–656 CE).The purpose was to inform more الناس as the population increased.The practice is mentioned in Sahih al-Bukhari (Friday Prayer section).Last verified on 26-04-2026', 0, 0, 0, 1790964556013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3e83cac0ebb6ee22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Eid Prayer is ___?', '{"A":"Sunnat","B":"Farz","C":"Wajib","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Eid prayer is Wajib according to the Hanafi school of thought.It consists of 2 Rak''ahs with 6 additional Takbirs (3 in each Rak''ah).The first Eid prayer was offered by the Holy Prophet ﷺ in 2 AH after the migration to Madinah.It is performed on both Eid-ul-Fitr and Eid-ul-Adha.Last verified on 03-07-2026', 0, 0, 0, 1790964556013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_57cdb236b4562956', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What is the number of Zakat among pillars?', '{"A":"First","B":"Second","C":"Third","D":"Fourth"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are five pillars of Islam:First Pillar: Shahadatain (شہادتیں) – declaration of faith: “There is no god but Allah, Muhammad ﷺ is His Messenger”Second Pillar: Namaz (نماز) – five daily prayersThird Pillar: Zakat (زکوٰۃ) – obligatory charity, 2.5% of wealth above NisabFourth Pillar: Fasting (Sawm / روزہ) – during Ramadan, abstaining from food, drink, and bad deedsFifth Pillar: Hajj (حج) – pilgrimage to Makkah at least once in a lifetime if ableLast verified on 22-03-2026', 0, 0, 0, 1790964556013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d9b04ad056a078db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', '“Namaz-e-Istisqa” is prayer for _____?', '{"A":"COVID-19","B":"Lunar eclipse","C":"Solar eclipse","D":"Rain"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Namaz-e-Istisqa pray for rain at local mosques.Additional information:Namaz-e-Khasoof (نماز خسوف) is offered at the time of Lunar eclipse.Namaz-e-Kasoof (نماز کسوف) is offered at the time of Solar eclipse.Last verified on 01-07-2026', 0, 0, 0, 1790964556013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4229a3b9a3adb901', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Hajj is not completed unless you go to _____?', '{"A":"Makkah","B":"Madina","C":"Arafat","D":"Mina"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hajj is not completed unless you go to Arfat.Additional information:The word Hajj means to intend.There are 3 Farz, 10 Sunnat and 6 Wajibat in Hajj.Hajj was made compulsory in 9 A.H.First Hajj is offered in 9 A.H.Hajj was ordained in Surah Bakr.The Holy Prophet SAW performed only 1 Hajj in 10th A.H.There are 3 types of Hajj.Last verified on 01-07-2026', 0, 0, 0, 1790964556013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1ae84a8124197289', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', '“Dua-e-Qunoot” is recited in which prayer?', '{"A":"Kasoof","B":"Khasoof","C":"Witr","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dua-e-Qunoot is recited in the Witr prayer.Witr is an odd-numbered night prayer performed after Isha prayer and before Fajr.In Hanafi practice, Dua-e-Qunoot is recited in the third rak‘ah of Witr before Rukoo.Last verified on 30-06-2026', 0, 0, 0, 1790964556013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bd777b2a25805427', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Jalsa in Namaz is ____?', '{"A":"Nafal","B":"Sunnah","C":"Farz","D":"Wajib"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jalsa in Namaz is Wajib Jalsa means sitting briefly between the two Sajdahs (prostrations).Additional information:Qiyam → Standing positionRukoo → Bowing positionFirst Sajdah → ProstrationLast updated by NS on 5-09-2026', 0, 0, 0, 1790964556013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4437290893c4301b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Pick out the name of the prayer which is preceded by Azaan?', '{"A":"Zuhar","B":"Namaz-e-Janaza","C":"Eid ul Fitr","D":"Eid Ul Azha"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zuhar, one of the five daily prayers in Islam.It is preceded by the Azaan, which is the call to prayer.Zuhr prayer usually has 4 Fard Rakats.Last verified on 16-05-2026', 0, 0, 0, 1790964556086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c890024a1bf7f63e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many Heads/Masarifs of Zakat?', '{"A":"5","B":"6","C":"7","D":"8"}', 'D', NULL, 0, 0, 0, 1790964556086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e5a04be4def4e4e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The Hajj pilgrims are required to Wear Ihram at a place called?', '{"A":"Miqat","B":"Mina","C":"Makkah","D":"Madina"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Miqat is the designated boundary for entering the state of Ihram.Pilgrims must wear Ihram before crossing Miqat.It applies to both Hajj and Umrah.Different regions have different Miqat points.Crossing Miqat without Ihram requires compensation (Dum).Last verified on 26-04-2026', 0, 0, 0, 1790964556086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dac4eae5e144f793', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Nisab of Zakat for Silver is?', '{"A":"40 Tolas","B":"50 Tolas","C":"50 ½ Tolas","D":"52 ½ Tolas"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nisab of zakat for silver is 52 1/2 tola612.36 grams of silver is the Ratio of Zakat in grams of SilverThe ratio / Nisab of Zakat is 2.5%52.5 Tola silver7 tola GoldAdditional information: Zakat means Purification. When Zakat was made compulsory in 2 A.H. (properly implemented in 8 Hijri. The word Zakat occurs 32 times in the Holy Quran. Hazrat Abu Baker did Jihad on the issue of Zakat. One who disbelievers in Zakat is a Kafir “Zakat” is the treasure of Islam, who said this? Holy Prophet (PBUH)*******Last updated by NA on 25- April-2026', 0, 0, 0, 1790964556086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_66634a41ecc56680', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which prayers are performed for rain?', '{"A":"Namaz-e-Khasoof","B":"Namaz-e-Kasoof","C":"Namaz-e-Istisqa","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Namaz-e-Istisqa is the special prayer offered to seek rain from Allah.It is performed when there is drought or lack of rainfall.Muslims gather and pray collectively for mercy and rain.Additional information:Namaz-e-Kasoof → Solar eclipse prayerNamaz-e-Khusuf → Lunar eclipse prayerLast verified on 18-05-2026', 0, 0, 0, 1790964556086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_aa6efce634706ee6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Five prayers were declared compulsory in _____?', '{"A":"10th Nabvi","B":"9th Nabvi","C":"11th Nabvi","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Five daily prayers (Salat) were made compulsory during the event of Miraj (Ascension).This event occurred on 27 Rajab, 10th Nabvi year.Allah initially prescribed 50 prayers, later reduced to 5, but reward remains equal to 50.It is one of the five pillars of Islam.Last verified on 02-04-2026', 0, 0, 0, 1790964556086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_93644d6ad1db3b24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Zakat is given on goat?', '{"A":"40 goats","B":"49 goats","C":"30 goats","D":"50 goats"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nisab for goats/sheep: 40 animals over 1 year old → Zakat becomes obligatory.If less than 40 goats/sheep: No Zakat.Additional information:Camels: Zakat payable starting at 5 camels.Sheep: Zakat payable starting at 40 sheep.Gold: Zakat payable on 7.5 tolas and above.Silver: Zakat payable on 52.5 tolas and above.Last verified on 10-03-2026', 0, 0, 0, 1790964556086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_60b31529c3feabbb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which is the third fundamental pillar of Islam?', '{"A":"Zakat","B":"Hajj","C":"Fasting","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The third pillar of Islam is Zakat (charity).Zakat means purification of wealth by giving a fixed portion to the poor.It was made compulsory in 2 AH.Additional information:Five Pillars of Islam (In Order)Shahadatain – Declaration of faithNamaz (Salah) – PrayerZakat – Charity (Obligatory almsgiving)Roza (Fasting) – During RamadanHajj – Pilgrimage to MakkahLast verified on 11-05-2026', 0, 0, 0, 1790964556086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e1d2fa7b5b0eb1f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Hazrat Bilal (RA) called first Azan of ______ prayer.', '{"A":"Isha","B":"Asr","C":"Zuhar","D":"Fajar"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Azan (Fajr Prayer) in Islam was called in 1 A.H.It was established after the migration to Madinah.Bilal ibn Rabah (RA) was the first Muezzin.He is known as Sayyid al-Mu’azzinin (Leader of Muezzins).He was chosen by Prophet Muhammad (PBUH).The purpose was to call Muslims to prayer.Last verified on 28-04-2026', 0, 0, 0, 1790964556162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_efbd495bed58fb07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'As a result of Hazrat Zakariya (A.S) prayer the following Prophet was born?', '{"A":"Hazrat Essa (A.S)","B":"Hazrat Imran (A.S)","C":"Hazrat Yahya (A.S)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zakariya (A.S) prayed to Allah for a child in old age.Allah granted him a son, Hazrat Yahya (A.S), as a gift.This is mentioned in the Qur''an (Surah Maryam → 19th Surah).Hazrat Yahya (A.S) was a righteous and noble prophet.Last verified on 28-04-2026', 0, 0, 0, 1790964556162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a3d0140ae2635898', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What is the minimum amount of gold required for Zakat?', '{"A":"85 grams","B":"87.48 grams","C":"87.49 grams","D":"100 grams"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zakat becomes obligatory when wealth reaches the Nisab level.For gold, Nisab is 87.48 grams (7.5 tola).Nisab for silver is 612.36 grams (52.5 tola).Zakat is 2.5% of total eligible wealth annually.Last verified on 27-04-2026', 0, 0, 0, 1790964556162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d5bb2f2d6de22b7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The Holy Prophet Hazrat Muhammad (PBUH) performed first Friday Prayer (Namaz-e-Juma) in the year?', '{"A":"1 A.H","B":"2 A.H","C":"3 A.H","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Jumuah prayer was performed by Prophet Muhammad (PBUH) after Hijrah.It took place in the year 1 A.H during the migration to Madinah.The Prophet (PBUH) led the prayer at Banu Salim ibn Awf area.This was the first official Friday congregation in Islam.Last verified on 25-04-2026', 0, 0, 0, 1790964556162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a22613e893ca2f60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which Companion did the Prophet allow speculation while appointing him as Governor of Yemen with the responsibility of collecting Zakat?', '{"A":"Hazrat Ali (R.A)","B":"Hazrat Ma’az bin Jabal (R.A)","C":"Hazrat Zaid bin Sabit (R.A)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad (PBUH) appointed Hazrat Muadh bin Jabal (RA) as Governor of Yemen.He was given the responsibility of collecting Zakat and administering justice.The Prophet (PBUH) allowed him to use ijtihad (independent reasoning).He was one of the most knowledgeable companions in Islamic law.This shows trust in his understanding of Qur’an and Sunnah.Last verified on 26-04-2026', 0, 0, 0, 1790964556162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2108c9951c58565d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which two essential prayers were obligatory on Muslims before Mairaj-un-Nabi (SAW) or early days of Islam?', '{"A":"Fajar & Maghrib","B":"Isha & Maghrib","C":"Isha & Fajar","D":"Fajar & Asar"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Before Mairaj (Ascension), five daily prayers were not yet obligatory.Early Muslims used to offer two prayers regularly.These were Fajar (morning) and Asar (evening) prayers.After Mairaj, five daily prayers became compulsory.This happened around 10th year of Prophethood.Salah became a fundamental pillar of Islam afterward.Last verified on 26-04-2026', 0, 0, 0, 1790964556162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5b6f28419c5d3219', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The important part of Hajj is?', '{"A":"Saee","B":"Waqoof e Arafat","C":"Tawaf","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The most important part of Hajj is the Day of ''ArafahThis takes place on the 9th day of Dhul-HijjahIt is often described as the heart of Hajj,Pilgrims travel from Mina to the plains of ArafatLast updated by NA on 25- April-2026', 0, 0, 0, 1790964556162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_06d3f7ca67a31a99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The cover of the Kaaba is called _____?', '{"A":"Sitara Kaaba","B":"Kiswah","C":"Rida","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cover of the Holy Kaaba is called Kiswah.It is also known as Ghilaf-e-Kaaba in Urdu.It is made of black silk with golden embroidery.The Kiswah is replaced every year in Makkah.It is prepared with great care and religious respect.Last verified on 25-04-2026', 0, 0, 0, 1790964556162) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_57e8c0990d446bb7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many obligatory Acts of Hajj are there?', '{"A":"Four","B":"Three","C":"Two","D":"Five"}', 'B', NULL, 0, 0, 0, 1790964556235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_99e5c4d7acd77a01', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Salat-e-Istasqa is offered on the occasion of _____?', '{"A":"Shortage of Rain","B":"Solar eclipse","C":"Famin","D":"None of them"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salat-ul-Istisqa: Prayer to ask Allah for rain during drought or low rainfall.Rakat: 2Specials: No Adhan or Iqamah; Quran recited aloud in both rakats.Meaning: Istisqa = seeking water from Allah.Additional information:Namaz-e-Khusuf (نماز خسوف): Offered during a lunar eclipse.Namaz-e-Kusoof (نماز کسوف): Offered during a solar eclipse.Last verified on 03-04-2026', 0, 0, 0, 1790964556235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e62583642ceffc93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What is the ratio / Nisab of Zakat?', '{"A":"2.50%","B":"2.00%","C":"100%","D":"7.5%"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zakat is an obligatory charity in Islam, calculated as 2.5% of wealth above the Nisab threshold.Additional information:Gold: 7.5 tola (~87.48 g)Silver: 52.5 tola (~612.36 g)Last verified on 22-03-2026', 0, 0, 0, 1790964556235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_173de08eecebea93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Who performed first Hajj Bait-Ullah?', '{"A":"Hazrat Adam and Hazrat Hawa","B":"Hazrat Ibrahim and Hazrat Hajra","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Hajj: Hazrat Adam (A.S) and Hazrat Hawwa (A.S)Kaaba rebuilt by: Hazrat Ibrahim (A.S) and Hazrat Ismail (A.S)Hajj became obligatory: 9 HijriProphet Muhammad (PBUH) performed Hajj: 10 Hijri (632 AD)Hajjat-ul-Wada: The first and last Hajj of Prophet Muhammad (PBUH)The Prophet (PBUH) performed Umrah four times in his life.Last verified on 14-03-2026', 0, 0, 0, 1790964556235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7739649f993c2764', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'When was Zakat made compulsory?', '{"A":"5 AH","B":"3 AH","C":"2 AH","D":"4AH"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zakat was made compulsory in 2. A.H. 7-1/2 is the nasab of gold and 52-half tolas for silver. Injunction of utilization of zakat is in Surah-al Tauba. Zakāt or "alms giving", one of the five Pillars of Islam, is the giving 2.5% of one''s possessions to charity, normally to the terrible and needy.', 0, 0, 0, 1790964556235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_47261364cf14345d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'When Zakat become obligatory?', '{"A":"2 AH","B":"4 AH","C":"5 AH","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790964556235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_db9e2f6908b82e9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Zakat is given on Camels?', '{"A":"4 camels","B":"5 camels","C":"6 camels","D":"9 camels"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The amount of zakat paid on capital assets (e.g. money) and stock-in-trade and jewelry is customarily 2.5% How many camels render are to par Zakat? 5 How many goats render are to pay zakat? 40 How many sheep render are to pay zakat? 40 Zakat is payable on gold of_________7.5 tolas Zakat is payable on silver of_______52.5 tolas', 0, 0, 0, 1790964556235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ea11edbf55897cb4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'When Wazu (Ablution) was ordered?', '{"A":"2 A.H","B":"3A.H","C":"4A.H","D":"5 A.H"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wazu (Ablution) was ordered on 5 A.HThe acts which break the ablution are called Nawaqiz-e-WazuThere are 6 Sunnah acts of ablutionThere are 4 obligations for ablution.13 Sunnah are in four obligations of AblutionBy Hazrat Jibrail (علیہ), Prophet ﷺ learnt Salat & ablutionوضو کے چار فرائض ہیں۔نمبر 1: چہرہ دھونانمبر 2: دونوں ہاتھوں کو کہینیوں تک دھونانمبر 3: چوتھائی سر کا مسح کرنانمبر 4:پاوں کا ٹخنیوں سمیت دھونا****', 0, 0, 0, 1790964556235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dca4db56ab97b2ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Pillars of Islam are called _____?', '{"A":"Faraiz-e-Islam","B":"Arkan-e-Islam","C":"Ulama-e-Islam","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are five pillars of Islam:The first pillar of Islam is ____? Shahadatain The second pillar of Islam is------? Namazthe third fundamental pillar of Islam? ZakatThe fourth pillar of Islam is--------? Fasting (Soam)5th pillar of Islam is ? Hajj****Which pillar of Islam is declared as armor? Fasting (Soam)Which pillar of Islam washes sin like water? HajjND08-3-2023', 0, 0, 0, 1790964556306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0c795fa5137c5d03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Nisab of Zakat?', '{"A":"2.2%","B":"2.6 %","C":"2.5%","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nisab of zakat for silver is 52 1/2 tolaZakat literally means Purification.When Zakat was made compulsory in 2 A.H (properly implemented in 8 Hijri.The word Zakat occurs 32 times in the Holy Quran.Hazrat Abu Baker did Jihad on the issue of Zakat.Without which act the prayer is useless? ZakatOne who disbelievers in Zakat is a Kafir“Zakat” is the treasure of Islam, who said this? Holy Prophet (PBUH)****612.36 grams of silver is the Ratio of Zakat in grams of SilverND7-5-2023', 0, 0, 0, 1790964556306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9d5e097cac384179', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'In which month does Zakat perform?', '{"A":"Rajab","B":"Ramdan","C":"Shawal","D":"Muharam"}', 'B', NULL, 0, 0, 0, 1790964556306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_687e2f540faee02c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'In which mosque was the order of keeping the Qibla (direction of prayer) changed from Jerusalem to Kaaba in Makkah?', '{"A":"Masjid al-Quba","B":"Masjid al-Haram","C":"Banu Salma Mosque","D":"Masjid an-Nabawi"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Banu Salma Mosque, also known as Masjid al-Qiblatayn, is located in Medina It is the mosque where the Prophet Muhammad (PBUH) received the revelation to change the direction of prayer from Jerusalem to the Kaaba in Mecca.The change occurred in 624 CE after the revelation of Surah 2, verses 144 and 145 of the Quran', 0, 0, 0, 1790964556306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fdd39e90aa1eeebb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many Takbeer are offered in Eid Prayer?', '{"A":"4","B":"2","C":"6","D":"3"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Eid literally means a “festival” or “feast” in Arabic. Doing ghusl on Eid is mustahabb. It was narrated that the Prophet ﷺ did ghusl on the day of Eid. Eid Prayer is WajibEid Salat consists of two ''Rakats'' and six ''Takbirs''.There are two Eid prayers in a year, Eid-ul-fitr and Eid-ul-adha.first Eid Prayer offered by the Holy prophet in 2nd A.H', 0, 0, 0, 1790964556306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0d400ceea06eab99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'In which Islamic month Hajj is performed?', '{"A":"Zlqad","B":"Muharram","C":"Zilhajj","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hajj is performed in the Islamic month of Zilhajj.It specifically from the 8th to the 12th of this month.Hajj was made Farz in the 9th Hijri year.', 0, 0, 0, 1790964556306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_97312fdb83ad1355', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'In Hajj, touching the Black Stone, is known as ____?', '{"A":"Sayee","B":"Istilam","C":"Ramee","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Istilam is the act of kissing Hajar al-Aswad or gesturing towards it at the beginning and at the end of each circuit of the Kaaba during the rite of Tawaf. In Hajj, touching the Black Stone is called Istilam. Istilam is an established sunna action of the Tawaf*****', 0, 0, 0, 1790964556306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fe382395abd73de0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which of the following prayers does not include Azan?', '{"A":"Eid","B":"Fajr","C":"Janaza","D":"Both A and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Eid and Janaza prayers do not include Azan.Azan is specifically recited for the five daily prayers.But is not part of the Eid or Janaza services.', 0, 0, 0, 1790964556306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d4b4a9f3ffe87072', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Kalima Tauheed is at ________ number.', '{"A":"Fifth","B":"Third","C":"First","D":"Fourth"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation List of six Kalimas1 كَلِمَاتْ اَلطَّيِّبَة‎Kalimat aṭ-Ṭayyibah (Word of Purity)***2 كَلِمَاتْ اَلشَّهَادَة‎Kalimat ash-Shahādah (Word of Testimony)****3 كَلِمَاتْ اَلتَّمْجِيدْ‎Kalimat at-Tamjīd (Word of Majesty)***4 كَلِمَاتْ اَلتَّوْحِيدْ‎Kalimat at-Tawḥīd (Word of Oneness)****5 كَلِمَاتْ إِسْتِغْفَارْ‎Kalimat ʾIstighfār (Word of Penitence)***6 كَلِمَاتْ رَدّْ اَلْكُفْرْ‎Kalimat Radd al-Kufr ("Word of Rejection of Disbelief")***ND 30-03-2923', 0, 0, 0, 1790964556372) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fe6a7d496d13e865', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What is the rate/ratio of Zakat on silver, gold, and currency (money)?', '{"A":"2.5%","B":"1%","C":"3%","D":"5%"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The standard rate of Zakat on silver, gold, and currency is 2.5% (or 2 ½ %)........Zakat money can be spent on Poor MuslimsZakat became obligatory in 2 AHList of Heads of Zakat1. Al-Fuqara (The poor)2. Al-Masakin (The needy)3. Zakat collectors4. Who converted to Islam5. Freeing captives6. Debtors7. In the path of Allah8. Wayfarer (Traveler)', 0, 0, 0, 1790964556372) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1b604e4e91e69c5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which companion taught Hazrat Bilal (RA) the words of Azan?', '{"A":"Hazrat Abdullah bin Zayd bin Abd Rabbah","B":"Hazrat Umar bin Khattab","C":"Hazrat Ubaid bin Tayyihan","D":"Hazrat Abdullah bin Tayyihan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abdullah bin Zayd bin Abd Rabbah (RA) had a dream in which he saw a man wearing green garments reciting the words of Azan. He told the Prophet Muhammad (PBUH) about the dream, and the Prophet (SAW) instructed him to teach the words to Bilal, who then called the first Azan.', 0, 0, 0, 1790964556372) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_115ac2a91ae12d06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Qurbani during hajj is performed at?', '{"A":"Safa","B":"Muzaldaffa","C":"Arafat","D":"Mina"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qurbani means sacrifice.Qurbani during hajj is performed at MinaQurbani marks the completion of HajjThe act of Qurbani is carried out between the 10th and 12th of Dhul Hijjahfollowing on from the pilgrimage of Hajj and Eid-ul-Adha prayersThey represent Prophet Ibrahim''s (AS) and Ismail''s loyalty to their religion', 0, 0, 0, 1790964556372) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bab17d5138c3060c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'There are ______ farz in prayer?', '{"A":"13","B":"12","C":"11","D":"17","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are the following 17 Farz in Namaz. 2 Farz = Fajr 4 Farz = Zuhar 4 Farz = Asar 3 Farz = Magrib 4 Farz = IshaTotal Farz Namaz = 17', 0, 0, 0, 1790964556372) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_57f201d026d4ff0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'At which occasion Salat became obligation (Farz)?', '{"A":"Boycott","B":"Migration","C":"Miraj","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Five prayers were declared compulsory in the 10th Nabvi.Namaz commanded in Quran 700 times.Salat was made compulsory at the event of 27 Rajab ( Miraj )****Salat Juma became Farz in Madina.Hajj was made compulsory in the 09th Hijri.**', 0, 0, 0, 1790964556372) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4d338fbc2ae85cdd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Zakat is payable on the minimum of ____ tolas of gold.', '{"A":"7 & 1/2","B":"5 & 1/2","C":"6 & 1/2","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zakat is payable on a minimum of 7½ or 7.5 tolas (approximately 87.48 grams) of gold.This is the nisab threshold for gold, above which zakat must be paid at 2.5%.', 0, 0, 0, 1790964556372) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_913ce5f3582917fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which Kalimah is recited after the Wuzu?', '{"A":"Kalimah-e-Astaghfar","B":"Kalimah-e-Shahadat","C":"Kalimah-e-Tauba","D":"Kalimah-e-Tauheed"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Kalimah recited after performing Wudu (ablution) is Kalimah-e-Shahadat.It is the declaration of faith in Islam.Before wudu, you should say Bismillah.', 0, 0, 0, 1790964556372) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_730ff6e2d4893107', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Salat-e-Khasoof is performed at the occasion of _____?', '{"A":"Solar eclipse","B":"Shortage of rain","C":"Lunar eclipse","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salat-e-Khasoof is performed on the occasion of the Lunar eclipse (چاند گرہن)It occurs in two or Four zakaah prayer It is a Nafli, not an obligatory prayer.Additional information:Salat ul Kusuf (نمازكسوف)is a two or Four-zakaah prayer performed during a solar eclipseسورج گرہن,', 0, 0, 0, 1790964556440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8560614e0ef5ace7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many Meeqat of Hajj for outsider Hujjaj?', '{"A":"6","B":"7","C":"5","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790964556440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7eb4bf203c6d3458', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The "Rukn-e-Azam" of Hajj is ______?', '{"A":"Tawaaf","B":"Waqoof-e-Arafah","C":"Ihraam","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Most important step of Hajj after assuming Ahram is Wuquf.• Waqoof-e-Arfah is the Rukn-e-Azam of Hajj. • With the performance of Rami on the 10th Zil-Hajj.', 0, 0, 0, 1790964556440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_23ac6f0c5c855a96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Salat-e-Istakhara is performed for _____?', '{"A":"Hajat","B":"Knowledge","C":"Fear","D":"Rain"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Namaz-e-Istikhara is a prayer offered when Muslims seek guidance from Allah (God) regarding a decision they are facingSalat became farz on 10th Nabavi.10th Nabavi, also called "the year of sorrow"Because Hazrat Muhammad''s wife, Khadijah, and his uncle and protector, Abu Talib, died.', 0, 0, 0, 1790964556440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_21bd746613ebea2d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The name of the sixth Kalimah is _____?', '{"A":"Kalimah Shahadat","B":"Kalimah Tauheed","C":"Kalimah Tamjeed","D":"Kalimah Radd-i-Kufar"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1. كَلِمَاتْ اَلطَّيِّبَةKalimat aṭ-Ṭayyibah (Word of Purity)2. كَلِمَاتْ اَلشَّهَادَةKalimat ash-Shahādah (Word of Testimony)3. كَلِمَاتْ اَلتَّمْجِيدْKalimat at-Tamjīd (Word of Majesty)4. كَلِمَاتْ اَلتَّوْحِيدْKalimat at-Tawḥīd (Word of Oneness)5. كَلِمَاتْ إِسْتِغْفَارْKalimat ʾIstighfār (Word of Penitence)6. كَلِمَاتْ رَدّْ اَلْكُفْرْKalimat Radd al-Kufr ("Word of Rejection of Disbelief")', 0, 0, 0, 1790964556440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4dea077d3c713a67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The Act of Shortening ones prayer while on journey is called?', '{"A":"Qasr","B":"Khusar","C":"Wajib","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qasr refers to the practice of shortening the prayer when traveling over long distances.It involves shortening the Fardh components of Dhuhr, Asr, and Isha prayers to two Rakats.', 0, 0, 0, 1790964556440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f4923114ffc675ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The ratio of zakat on natural irritating land is ______?', '{"A":"1/10","B":"1/20","C":"5%","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Naturally irrigated land: 10% (1/10) zakat is due.Artificially irrigated land: 5% (1/20) zakat is due.Hadith Reference:"On land watered by rain or natural sources, the Ushr (10%) is due, and on land watered by irrigation, half of Ushr (5%)."(Sahih Bukhari 1483, Sunan Abu Dawud 1596)', 0, 0, 0, 1790964556440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_58de5d25e9d6233e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What is the Ratio of Zakat in grams on Silver?', '{"A":"610.36 grams of silver","B":"612.36 grams of silver","C":"620.36 grams of silver","D":"636.36 grams of silver"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gold: 7.5 tola / 3 ounces / 87.48 grams.Silver: 52.5 tola / 21 ounces / 612.36 grams.Cash Equivalent: The same value as gold or silver.Zakat: 2.5% should be paid if you possess the equivalent for a full lunar year.Sahib-e-Nisab: A person with the above wealth is considered eligible to pay Zakat.', 0, 0, 0, 1790964556440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f0eedafa5dcf9b65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'According to Zakat and Usher Ordinance all banks of the country were to deduct Zakat from the Saving accounts on the _______?', '{"A":"1st Ramzan","B":"2nd Ramzan","C":"3rd Ramzan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zakat and Ushr Ordinance, 1980, deduct Zakat on the 1st of Ramadan It is meant to fulfill the religious obligation of Zakat. Last updated 12 april 2026', 0, 0, 0, 1790964556532) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9b099c10939f5c73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many farz in Hajj?', '{"A":"2","B":"3","C":"4","D":"5"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are 3 Farz, 10 Sunnat and 6 Wajibat in Hajj.Farz in Hajj are Three (3)Hajj was made compulsory in 9 A.H.• First Hajj offered in 9 A.H.• Hajj ordained in Surah Bakr.• The holy prophet performed only 1 Hajj in 10th A.H.• There are 3 types of Hajj.The verbal meaning of Hajj is The will to visitwhileFarz in Umrah are Four (4)There are the following 17 Farz in Namazغسل کے تین فرائض ہیں۔وضو کے چار فرائض ہیں۔NA-6-09-2023', 0, 0, 0, 1790964556532) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_da78a87457d98c4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'When was Friday prayer obligatory?', '{"A":"After Hijrah","B":"After Conquest of Makkah","C":"After Al-Hudaibiyah Treaty","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Friday prayer was made obligatory in Medina, after the Hijrah (migration) of the Prophet Muhammad (PBUH) from Mecca to Medina in 622 CE.The first Friday prayer was led by Prophet Muhammad (PBUH) in Quba.', 0, 0, 0, 1790964556532) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_42267ce1624839ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Namaz-e-Taraweeh is _____?', '{"A":"Sunnat","B":"Farz","C":"Wajib","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Taraweeh means To Rest.نماز تراویح سنّت مؤکدہ ہےTaraweeh prayer is performed in congregation during Ramadan after Isha and before Witr.Tarawih prayers are special Muslim prayers involving reading long portions of the Quran.Tarawih is prayed in sets of two rakyats each.', 0, 0, 0, 1790964556532) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cdc0eadfdc41f3a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'On which of the following occasion, Muslim offers ''Namaz-e-Kusuf?', '{"A":"For the sake of rain","B":"At the time of eclipse of sun","C":"At the time of eclipse of the moon","D":"At the time of drought"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salat ul-Kusuf is a prayer of two rakaaht performed during a solar eclipse.Namaz-e-Khasoof (نماز خسوف) is offered during a lunar eclipse.Namaz-e-Kasoof (نماز کسوف) is offered during a solar eclipse.', 0, 0, 0, 1790964556532) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_58e3a272a9637fa4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The reward of which prayer is equal to the reward of Hajj or Umrah?', '{"A":"Namaz-e-Janaza","B":"Namaz-e-Khasoof","C":"Namaz-i-Ishraq","D":"Namaz-e-Istasqa"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Ishraq prayer is an optional prayer, or salah, that is done about 15-20 minutes after the sun rises. Before you go to bed, research what time the sun will rise in your city for the next day, and set an alarm for that time. If you lose track of time, just look at the position of the sun over the horizon.', 0, 0, 0, 1790964556532) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d836f1e957ab3430', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Who was the first caller to the prayers of Islam?', '{"A":"Hazrat Bilal (RA)","B":"Hazrat Ibne Ume Makhtoom (RA)","C":"Hazrat Abu Mahzoora (RA)","D":"Hazrat Abu Ayub Anas (RA)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Bilal called the first Azan of Fajar prayerFirst Azan was called out in 1 A.HBilal ibn Rabah is considered to have been the first muezzin, chosen by Hazrat Muhammad himself.The Title of Bilal ibn Rabah: Sayyid al-MuʾaḏḏinBilal ibn Rabah Born: 580 AD, Mecca, Saudi ArabiaisBilal ibn Rabah Died: on March 2, 640 AD, in Damascus, SyriaBilal ibn Rabah''s Place of burial: Bab el Saghir Cemetery, Damascus, Syriawhile Hazrat ''Umar was the first person to suggest the calling of the Azan.ND23-6-2023', 0, 0, 0, 1790964556532) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b821700edee58e8b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The Holy Prophet SAW performed Hajjat-ul-Wada in _____?', '{"A":"9th Hijri","B":"10th Hijri","C":"11th Hijri","D":"8th Hijri"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet (SAW) performed Hajjat-ul-Wida in the 10th Hijri.It was performed on Friday, the 9th of Dhu al-Hijjah (March 6, 632 A.D).This final pilgrimage included his renowned Farewell Sermon.', 0, 0, 0, 1790964556532) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5de78a2591ac88f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Name the prayer in which there is no change in Farz Rakaats in cast of Qasr?', '{"A":"Maghrib","B":"Zuhr","C":"Isha","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the case of Qasr (shortened prayer for travelers), there is no change in the number of Farz rakaats for Fajr, Maghrib, and Witr prayers.Qasr refers to the practice of shortening the prayer when traveling over long distances.It involves shortening the Farz components of Dhuhr, Asr, and Isha prayers to two Rakats.', 0, 0, 0, 1790964556599) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5ea165e523234336', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Prophet Muhammed (PBHU) performed a total of ______ Umrahs.', '{"A":"Two","B":"One","C":"Four","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet SAW performed only 1 Hajj in the 10th A.H and 4 Umrahs:First Umrah (6th Hijri): Resulted in the Treaty of Hudaibiya.Second Umrah (7th Hijri): As set out in the Treaty of Hudaibiya.Third Umrah (8th Hijri): After returning from the Battle of Hunain.Fourth Umrah (10th Hijri) along with the Hajj, known as Hujjat al-Wada.', 0, 0, 0, 1790964556600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e9782ae2697e6815', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The name of the fifth Kalimah is?', '{"A":"Kalimah Shahdat","B":"Kalimah Istighfar","C":"Kalimah Tamjeed","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation List of six Kalimas 1 كَلِمَاتْ اَلطَّيِّبَة‎ Kalimat aṭ-Ṭayyibah (Word of Purity) 2 كَلِمَاتْ اَلشَّهَادَة‎ Kalimat ash-Shahādah (Word of Testimony) 3 كَلِمَاتْ اَلتَّمْجِيدْ‎ Kalimat at-Tamjīd (Word of Majesty) 4 كَلِمَاتْ اَلتَّوْحِيدْ‎ Kalimat at-Tawḥīd (Word of Oneness) 5 كَلِمَاتْ إِسْتِغْفَارْ‎ Kalimat ʾIstighfār (Word of Penitence) 6 كَلِمَاتْ رَدّْ اَلْكُفْرْ‎ Kalimat Radd al-Kufr ("Word of Rejection of Disbelief")', 0, 0, 0, 1790964556600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e93b442a02343430', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which Sahabi did Jehad on the issue of Zakat?', '{"A":"Hazrat Abu Bakar","B":"Hazrat Usman","C":"Hazrat Ali","D":"None of the above"}', 'A', NULL, 0, 0, 0, 1790964556600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dbafd5d2832c5f41', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'A person who is liable to pay Zakat is called __________?', '{"A":"Affluent persons","B":"Sahib-e-Nisab","C":"Influential persons","D":"Wealthy members of society"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The nisab by the gold standard is 3 ounces of gold (87.48 grammes) or its equivalent in cash. The nisab by the silver standard is 21 ounces of silver (612.36 grammes) or its equivalent in cash.', 0, 0, 0, 1790964556600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7776e82416e0e751', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Hajr-e-Aswad is installed on the wall of Kaaba. What is the meaning of Aswad?', '{"A":"Holy","B":"Heavenly","C":"Heavy","D":"Black"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aswad means کالا یا سیاہ رنگ کا Hajr-e-Aswad is a rock set into the eastern corner of the Kaaba, the ancient building in the center of the Grand Mosque in Makkah.', 0, 0, 0, 1790964556600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_13fa54cca10c36d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'At what occasion all the six kalimahs are recited by the Muslims?', '{"A":"Birth","B":"Nikah","C":"Death","D":"Migration"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Six Kalimas are broadly speaking taken from hadiths, now not from the Qur''an. The Six Kalimahs (from Arabic كلمة‎ kalimah "word") in Islam in South Asia are six significant elements of 1''s non secular perception, typically taken from hadiths (in some traditions, six phrases, then called the six kalimas).six kalimas are recited in Nikah', 0, 0, 0, 1790964556600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b640037e35b7e783', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'During drought, which Namaz is performed?', '{"A":"Salaat al Istasqa","B":"Salaat e Kisoof","C":"Salaat e Khasoof","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salat ul istasqa is a prayer to ask God for rain. It consists of two Rakat.Salatul-Istisqaa is no Adhan or Iqamah – only recitation of the Quran in both rakats out loud. Al-Istisqa''means seek water (rain) from Alla during times of low rainfall.*****whileNamaz-e-Khasoof (نماز خسوف) is offered at the time of Lunar eclipse Namaz-e-Kasoof (نماز کسوف) is offered at the time of Solar eclipse***ND27-12-2022ND03-12-2022ND22-6-2023', 0, 0, 0, 1790964556600) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fcf34e0cd280f9ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The name of third kalimah is ______?', '{"A":"Kalimah-e-Tauba","B":"Kalimah-e-Tauheed","C":"Kalimah-e-Saalis","D":"Kalimah-e-Tamjeed"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The third kalima is also referred to as tamjeed.This is referred to as word of praise, word of glorification, or word of glory to Allah.', 0, 0, 0, 1790964556692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3ef0aaab6425af82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What is the name of first Kalima?', '{"A":"Kalimah Tauheed","B":"Kalimah Tamjeed","C":"Kalimah Radd-i-Kufar","D":"Kalimah Tayeeba"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The name of the first Kalimah is Kalimah TayeebaSeven Words are there in the First Kalimah.48 letters in the first Kalima.There is no doots in first kalimaAdditional informationList of six Kalimas1كَلِمَاتْ اَلطَّيِّبَة‎(Word of Purity)2كَلِمَاتْ اَلشَّهَادَة‎(Word of Testimony)3كَلِمَاتْ اَلتَّمْجِيدْ‎(Word of Majesty)4كَلِمَاتْ اَلتَّوْحِيدْ‎(Word of Oneness)5كَلِمَاتْ إِسْتِغْفَارْ‎(Word of Penitence)6كَلِمَاتْ رَدّْ اَلْكُفْرْ‎("Word of Rejection of Disbelief")', 0, 0, 0, 1790964556692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3e0a8d2a0d08dddc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which Prophet is associated with the building of the Kaaba, which is central focus of the Hajj pilgrimage?', '{"A":"Prophet Ibrahim (Abraham)","B":"prophet Musa (Moses)","C":"Prophet Muhammad","D":"Prophet Isa (Jesus)"}', 'A', NULL, 0, 0, 0, 1790964556692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7cf222f8c4e15517', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'On which time the Holy Prophet (PBUH) was gifted with Namaz?', '{"A":"Miraj","B":"Hijrat","C":"Badr","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Namaz commanded in Quran for 700 times.Salat made compulsory in 10th Nabvi.Salat Juma became Farz in Madina.', 0, 0, 0, 1790964556692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fd1e298ef6522f56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many letters in first Kalima?', '{"A":"26","B":"36","C":"48","D":"58"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Seven Words are there in the First Kalimah.26 letters in first Kalima.’لاَ اِلٰہَ اِلَّا اﷲُ مُحَمَّدٌ رَّسُوْلُ اﷲAdditonal information:List of six Kalimas1كَلِمَاتْ اَلطَّيِّبَةKalimat aṭ-Ṭayyibah(Word of Purity)2كَلِمَاتْ اَلشَّهَادَة‎Kalimat ash-Shahādah(Word of Testimony)3كَلِمَاتْ اَلتَّمْجِيدْ‎Kalimat at-Tamjīd(Word of Majesty)4كَلِمَاتْ اَلتَّوْحِيدْ‎Kalimat at-Tawḥīd(Word of Oneness)5كَلِمَاتْ إِسْتِغْفَارْ‎Kalimat ʾIstighfār(Word of Penitence)6كَلِمَاتْ رَدّْ اَلْكُفْرْ‎Kalimat Radd al-Kufr("Word of Rejection of Disbelief")', 0, 0, 0, 1790964556692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bfb6ef60e2bc3159', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Kalmah is__________ pillar of Islam?', '{"A":"1st Pillar of Islam","B":"2nd Pillar of Islam","C":"3rd Pillar of Islam","D":"4th Pillar of Islam"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are the Five Pillars of Islam:1) Shahadatain (Touheed) (Kalmah)2) Salat 3) Zakat 4) Soam 5) Hajj', 0, 0, 0, 1790964556692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_93d02e459b592ebb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Order of Fasting in Ramadhan was revealed in?', '{"A":"1st Hijri","B":"2nd Hijri","C":"3rd Hijri","D":"4th Hijri"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790964556692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fae4af758842ec80', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'In administration under the Holy prophet Zakat was levied on :', '{"A":"Fruits","B":"Grains","C":"Camels","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zakat During the Prophetic Era —Zakat is levied on five categories of property.Cash & Precious Metals: Gold, silver & savingsLivestock: Camels, cattle, sheep & goatsAgricultural Produce: Grains, fruits & cropsMerchandise: Goods for trade/businessMines & Rikaz: Minerals & discovered treasures', 0, 0, 0, 1790964556692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a47f4ac493ba3ddf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Salat-e-Jumma was made compulsory in ____?', '{"A":"Makkah","B":"Madina","C":"Habsha","D":"Muzdalfa","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 2nd Hijri Events· Regular calls for prayer.· Change direction of prayer from Jerusalem to the Kabah.· Fasting made compulsory.· Introduction of Zakat.· Hazrat Fatima Marries Hazrat Ali.· Death of Hazrat Ruqayya.· Battle of Badr took place.* Salat-e-Jumma was made compulsory in Madina.', 0, 0, 0, 1790964556751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ba2435e872c16763', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Maghrib and Isha both prayers are offered togethor at:', '{"A":"Muzdalfa","B":"Mina","C":"Arafat","D":"Madina","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maghrib-Isha prayers are offered together at Muzdalifa on 9th Zill Hajj...Muzdalifah was the place where Prophet Adam (AS) the Maghrib and Isha prayers together.Muzdalifah is also called Al-Ibtah, meaning flat area....between 49 and 70 pebbles are collected from the ground at Muzdalifah and thrown at the three pillars at Mina, which represent the devil.Muzdalifah (Arabic: مزدلفة) which is also known as al-Mashʿar or al-Mashʿar al-Ḥarām (المشعر الحرام) is a region between ''Arafat and Mina', 0, 0, 0, 1790964556752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d6634faab7b5dc2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The Prayer offered during a lunar eclipse is……?', '{"A":"Namaz e Istasqa","B":"Namaz e Hajaat","C":"Namaz e Khauf","D":"Namaz e Khusoof"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prayer offered during a lunar eclipse is Namaz e Khusoofand Namaz-e-Kasoof (نماز کسوف) is offered at the time of the solar eclipse. ****************The lunar eclipse takes place when The shadow of the earth falls on the moonThere are three types of lunar eclipses: a total lunar eclipse, a penumbral lunar eclipse and a partial lunar eclipse.***ND4-12-2022', 0, 0, 0, 1790964556752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5b2607cc84b37bd0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many Sunnah are in four obligations of Ablution (Wazu)?', '{"A":"18","B":"13","C":"10","D":"15","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wazu (Ablution) was ordered on 5 A.HThe acts which break the ablution are called Nawaqiz-e-WazuThere are 6 Sunnah acts of ablutionThere are 4 obligations for ablution.13 Sunnah are in four obligations of AblutionBy Hazrat Jibrail (علیہ), Prophet ﷺ learnt Salat & ablutionوضو کے چار فرائض ہیں۔نمبر 1: چہرہ دھونانمبر 2: دونوں ہاتھوں کو کہینیوں تک دھونانمبر 3: چوتھائی سر کا مسح کرنانمبر 4:پاوں کا ٹخنیوں سمیت دھونا****', 0, 0, 0, 1790964556752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c006aa3e3078e8e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Verbal meaning of Hajj ___?', '{"A":"The will to visit","B":"which is not accepted","C":"which is accepted","D":"which is performed with deficiencies","E":"which is observed correctly"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hajj is a pilgrimage made to the Kaaba, the "House of Allah"It is one of the Five Pillars of IslamHajj is a sacred pilgrimage that is required of every Muslim at least once in their lifetimesverbal meaning of Hajj is The will to visitThere are 3 Farz, 10 Sunnat and 6 Wajibat in HajjFarz in Hajj are Three (3)Farz in Umrah are Four (4)There are three different types of Hajj namely:Hajj-ul-Ifrad.Hajj-ul-Qiran.Hajj-ul-Tamattu.ND29-5-2023', 0, 0, 0, 1790964556752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f0d284dd4b67bb2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The Amount of Zakat cannot be used in ______.', '{"A":"Madrassah","B":"Mosque","C":"Hospital","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790964556752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fd3fd5e8f4efa80c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Minimum Persons required for Namaz Ba-Jamaat?', '{"A":"4","B":"2","C":"1","D":"7","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Two Person is very necessary for Ba-Jamaat.', 0, 0, 0, 1790964556752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fec24a55c475f860', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What is the Ratio of Zakat in grams on Gold?', '{"A":"64.14 grams of gold","B":"87.48 grams of gold","C":"92.62 grams of gold","D":"74.23 grams of gold"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If you have 7.5 tola/3 ounces/87.48 grams of gold or52.5 tota/21 ounces/612.36 grams of silver orits cash equivalent for a full lunar year,then you are considered Sahib-e-Nisab and should pay Zakat 2.5%', 0, 0, 0, 1790964556752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dc7b0718dc44839a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Additional Takbeers are offered in which of the following prayer?', '{"A":"Salat-e-Hajat","B":"Salat-e–Istasqa","C":"Salat-e-Istakhara","D":"Salat-e-Eid","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation عید الفطر اور عید الأضحى کی دو رکعات نماز جو چھہ زائد تکبیرات سے ادا کی جاتی ہے. پہلی رکعت میں ثنا کے بعد قرأت سے پہلے تین (٣) زائد تکبیرات کہی جاتی ہیں، اور دوسری رکعت میں قرأت کے بعد تین (٣) زائد تکبیرات کہہ کر رکوع کی تکبیر کہتے رکوع میں چلے جاتے ہیں.', 0, 0, 0, 1790964556838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fd6aad7b82d9adaf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'What is the Nisab of Zakat on diamonds?', '{"A":"2.5%","B":"5%","C":"0%","D":"7.5%"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation there is no Zakat on diamonds or coloured gemstones while one owns them as adorns or decorations in regular quantities and not in measures of identified extravagance, or in forbidden paperwork, or for prohibited makes use of. via a long way, women''s jewelry money owed for his or her most commonplace Zakat exemption.', 0, 0, 0, 1790964556838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_352696e9435f4f1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many prayers have no Azan ?', '{"A":"4","B":"3","C":"2","D":"1","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are the following two prayers have no Azan (آذان) Eid-ul-Fitr Eid-ul-AzhaJanaza*******VU CBT FIA SI ASI PAPER 13-12-2021ND7-5-2023', 0, 0, 0, 1790964556838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f2177a84bf08649c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'In Hajj, traveling seven times between Mount Safa and Mount Marwah, is called _____?', '{"A":"Ramee","B":"Sayee","C":"Istilam","D":"Tawaf","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muslims travel back and forth between them seven times known as Sayee.Sayee is an integral part of the Hajj and Umrah in Islam. It is done to symbolize Hajar''s (Wive of Prophet Ibraheem, Peace be upon them both) search for water for her son Prophet Ismael (Peace be upon Him).****RY 8-01-2023ND8-1-2023*****RY17012023***ND5-2-2023', 0, 0, 0, 1790964556838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_57fcb0e9657eaeb9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Qurbaani is made during Hajj at:', '{"A":"Arafat","B":"Mina","C":"Muzdalifa","D":"Safa"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qurbani Takes place at the end of Hajj rituals in Mina on the 10th of Dhu al-Hijjah.', 0, 0, 0, 1790964556838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fb9b6feca8989b0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', '5th pillar of Islam is?', '{"A":"Namaz","B":"Roza","C":"Hajj","D":"Zajat"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are five pillars of Islam:The first pillar of Islam is ____? Shahadatain The second pillar of Islam is------? Namazthe third fundamental pillar of Islam? ZakatThe fourth pillar of Islam is--------? Fasting (Soam)**5th pillar of Islam is? Hajj****Which pillar of Islam is declared as armor? Fasting (Soam)Which pillar of Islam washes sin like water? HajjND08-3-2023', 0, 0, 0, 1790964556838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e7c0d421bb23e7b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The fourth pillar of Islam is--------?', '{"A":"Fasting","B":"Zakat","C":"Hajj","D":"All"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are five pillars of Islam:The first pillar of Islam is ____? Shahadatain The second pillar of Islam is------? Namazthe third fundamental pillar of Islam? ZakatThe fourth pillar of Islam is--------? Fasting (Soam)**5th pillar of Islam is? Hajj****Which pillar of Islam is declared as armor? Fasting (Soam)Which pillar of Islam washes sin like water? HajjND08-3-2023', 0, 0, 0, 1790964556838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_16d565fd3af0f3fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Fasting during Ramadan is which of the 5 pillars of Islam?', '{"A":"First","B":"Second","C":"Third","D":"Forth"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are five pillars of Islam:The first pillar of Islam is ____? Shahadatain The second pillar of Islam is------? Namazthe third fundamental pillar of Islam? ZakatThe fourth pillar of Islam is--------? Fasting (Soam)**5th pillar of Islam is? Hajj****Which pillar of Islam is declared as armor? Fasting (Soam)Which pillar of Islam washes sin like water? HajjND08-3-2023', 0, 0, 0, 1790964556838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_53185eed49deda6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which pillar of Islam washes sin like water?', '{"A":"Hajj","B":"Roza","C":"Namaz","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word Hajj means to intendhajj was the 5th fundamental pillar of IslamHajj is obligatory for Muslims Those who can affordHajj was made compulsory in which Hijrah 9th HijrahThree obligatory Acts of Hajj are therehajj should be performed by Muslims at least once in a lifetime.ND08-3-2023', 0, 0, 0, 1790964556918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fb0bca04fd676b36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which pillar of Islam is declared as armour?', '{"A":"Salat","B":"Soam","C":"Zakat","D":"Hajj"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fasting was the 4th fundamental pillar of IslamFasting (Soam) is declared as armorFasting was made obligatory in 10th Shaban,2 A.HThe function of fasting is To Make the Sacrifice of Body and SoulSaum (fasting) resembles Hadith with a Shield5 days are prohibited ممنوع for fasting throughout the YearRY 16-01-2023ND08-3-2023', 0, 0, 0, 1790964556918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_844c327d1a8551f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'The Salat-e-Shukar is ______?', '{"A":"Mustahab","B":"Nafal","C":"Farz","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salat e Shukar is MustahabMustahab means favored or virtuous actionsMustahabb actions are those whose ruling in Islamic law falls between mubah and wajibSalat e Shukar is also known as Sajdah ShukrShukr prayer (Prayer of thanks) is performed in order to thank Allah (swt) It doesn''t have a specific time. It is at least 2 rakahs. ND18-2-2023', 0, 0, 0, 1790964556918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c498e6c2fb606649', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'To stay in which ground is the major part of Hajj?', '{"A":"Arafaat","B":"Mina","C":"Muzdalfa","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is an important place in Islam because, during the Hajj, pilgrims spend the afternoon there on the ninth day of Dhu al-Hijjah. Failure to be present in the plain of Arafat on the required day invalidates the pilgrimage.', 0, 0, 0, 1790964556918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6a71c17750b63dc3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Which two prayers are offered together at Muzdalifa on the 9th Zil-ul-Hajj?', '{"A":"Isha-Fajar","B":"Maghrib-Isha","C":"Fajar-Zuhar","D":"Zuhar-Asar","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maghrib-Isha prayers are offered together at Muzdalifa on 9th Zill Hajj...Muzdalifah was the place where Prophet Adam (AS) the Maghrib and Isha prayers together.Muzdalifah is also called Al-Ibtah, meaning flat area....between 49 and 70 pebbles are collected from the ground at Muzdalifah and thrown at the three pillars at Mina, which represent the devil.Muzdalifah (Arabic: مزدلفة) which is also known as al-Mashʿar or al-Mashʿar al-Ḥarām (المشعر الحرام) is a region between ''Arafat and Mina AGM 09-2-2023ND16-8-2023', 0, 0, 0, 1790964556918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1760d426a182edaa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'There are _____________ obligations for ablution.', '{"A":"4","B":"9","C":"8","D":"10","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation غسل کے تین فرائض ہیں۔کلی کرناناک میں پانی ڈالناسارے جسم پر پانی بہاناوضو کے چار فرائض ہیں۔نمبر 1: چہرہ دھونانمبر 2: دونوں ہاتھوں کو کہینیوں تک دھونانمبر 3: چوتھائی سر کا مسح کرنانمبر 4:پاوں کا ٹخنیوں سمیت دھونا****RY30012023', 0, 0, 0, 1790964556918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8b1538feb2499981', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'Salat-e-Juma became Farz in which city _______?', '{"A":"Makkah","B":"Maddina","C":"Taif","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 2nd Hijri Events· Regular calls for prayer.· Change direction of prayer from Jerusalem to the Kabah· Fasting made compulsory.· Introduction of zakat.· Hazrat Fatima Marries Hazrat Ali.· Death of Hazrat Ruqayya. · Battle of Badr took place.* Salat e Jumma was made compulsory in Madina', 0, 0, 0, 1790964556918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c1dbf0233a051634', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_pillars', 'How many Arkan Roza has?', '{"A":"4","B":"3","C":"2","D":"5","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are the Three Arkan of Roza 1) To Restrict Eating 2) Drinking 3) Sexual Intercourse', 0, 0, 0, 1790964556918) ON CONFLICT(id) DO NOTHING;
