INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ea9ff96399f6e095', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Battle field Badar is situated near the City of', '{"A":"Makkah","B":"Jaddah","C":"Taaiff","D":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Location: Badr, on the Madinah–Yanbu roadDistance: About 180 km from MadinahDate: 17 Ramadan, 2 AH / 624 CEFirst major battle of IslamAlso called: Yawm al-Furqan (Day of the Criterion)Muslim Forces: About 313Muhajirun: 82–85Ansar: 231Non-Muslim Forces: About 1,000Muslim Martyrs: 14Non-Muslims killed: 70Angels: 1,000 angels assisted the MuslimsMentioned in: Surah Al-Anfal', 0, 0, 0, 1790964557064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b6e72e826c5e691f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'How many Muslims fought in the battle of Badr?', '{"A":"213","B":"313","C":"314","D":"320"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muslims: around 313 soldiersNumber of Muslim martyrs: 14Battle Name: Ghazwa-e-BadrDate: 17 Ramadan, 2 AH / 624 CEPlace: Badr (near Madinah)Between: Muslims and Makkans (Quraysh)Muslim Leader: Muhammad (SAW)Additional information:Quraysh Army: around 1000 soldiersMuslim horses: 2Muslim camels: around 70Last verified on 17-05-2026', 0, 0, 0, 1790964557064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6976c1d6e226e47f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The Battle of Uhud was fought in which Hijri?', '{"A":"4 Hijri","B":"2 Hijri","C":"3 Hijri","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: 23 March 625 AD (3 AH)Place: Valley of Uhud, near MadinaMuslim Army: ~1000Enemy Army: ~300050 skilled archers were placed on Mount Uhud by Prophet MuhammadIt was between Muslims and the Quraish of Makkah.The leader of the Quraish was Abu Sufyan.The battle is mentioned in the Qur''an (Surah Aal-e-Imran).Last verified on 25-04-2026', 0, 0, 0, 1790964557064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_992b13e524436f90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Ghazwa Ahzab is also called _____?', '{"A":"Battle of Winds","B":"Battle of Mind","C":"Battle of Trench","D":"Battle of Words"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Khandaq is also known as the Battle of the Trench and the Battle of the Confederates.It was a 27-day-long defense by Muslims of Yasrab (now Medina). Took place in Shawwal – Dhu al-Qi''dah, 5 A.H (627 C.E).Last updated by NA on 22-April-2026', 0, 0, 0, 1790964557064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c201a45332aca9e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'When did the Conquest of Makkah (Fatah Makkah) by the Holy Prophet Muhammad (ﷺ) take place?', '{"A":"8 AH (630 AD)","B":"9 AH (631 AD)","C":"10 AH (632 AD)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: 20 Ramadan, 8 AHGregorian date: December 629 / January 11, 630 ADLeader: Prophet Muhammad (ﷺ)Place: Makkah (Saudi Arabia)Occasion: Victory of Muslims over QurayshAdditional information:Prophet Muhammad (ﷺ) entered Makkah on his favorite camel Al-Qaswa (القصواء).Usama Ibn Zaid (RA) was sitting behind him.On the way, Prophet Muhammad (ﷺ) recited Surah Al-Fath (48th Surah of the Quran).Last verified on 01-07-2026', 0, 0, 0, 1790964557064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7a2076bf37b6b64c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Ghazwa-e-Badr occurred in which hijrah?', '{"A":"2 A.H","B":"3 A.H","C":"4 A.H","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Badr was fought in the year 2 AH (After Hijrah)Islamic Date: 17 Ramadan, 2 AHGregorian Date: March 13, 624 CEPlace: Badr (near Madinah)Between: Muslims and Makkans (Quraysh)Muslim Leader: Muhammad (SAW)Muslims: around 313 soldiersNumber of Muslim martyrs: 14Quraysh Army: around 1000 soldiersMuslim horses: 2Muslim camels: around 70Last updated by NA on 09-09-2026', 0, 0, 0, 1790964557064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fd45a6bbe93a40a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Hazrat Ali (RA) did not participate in the battle of _____?', '{"A":"Yarmuk","B":"Tabook","C":"Hunain","D":"Mutta"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali (RA) did not participate in the Battle of Tabuk.He was ordered by the Prophet Muhammad (PBUH) to stay in Madinah.He acted as a caretaker of the Muslim community and Ahl-e-Bait.The expedition of Tabuk took place in 9 AH (630 AD).It was a major military campaign against the Byzantine forces.Last verified on 25-04-2026', 0, 0, 0, 1790964557064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_31e313f261df3c3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'How many infidels were killed in Ghazwa Badr?', '{"A":"80","B":"70","C":"60","D":"100"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 70 infidels were killed in Ghazwa Badr.Number of Muslim martyrs: 14Date: 17 Ramadan, 2 AH / 624 CEPlace: Badr (near Madinah)Between: Muslims and Makkans (Quraysh)Muslim Leader: Muhammad (SAW)Additional information:Muslims: around 313 soldiersQuraysh Army: around 1000 soldiersMuslim horses: 2Muslim camels: around 70Last verified on 17-05-2026', 0, 0, 0, 1790964557064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bb19996192d6b557', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Which was the first battle between Muslims and Kuffars?', '{"A":"Ghazwa Abwa","B":"Ghazwa Badr","C":"Ghazwa Khundaq","D":"Ghazwa Tabook"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Ghazwa (Battle) took place between Muslims and Kuffar is Ghazwa Abwa.Ghazwa Abwa is the First Ghazwa of Islam. Ghazwa Wadan is another name for this battle. Abwa is the first expedition, in which the Holy Prophet (PBUH), with 60 Muhajireen, left Madinah with the goal of jihad for the first time in the month of Safar 2 AH.Last verified 09-09-2026', 0, 0, 0, 1790964557153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fd674f1b8f57a3c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'What is the other name of Ghazwa-e-Khandaq (Trench)?', '{"A":"Akhraj","B":"Qanaqa","C":"Kuraza","D":"Ahzab"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Also called Ghazwa-e-Ahzab or Battle of the Trench.It was fought in 5 A.H (627 CE).Additional information:Muslims: ~3,000; Kufar: ~10,000; Munafiqeen: ~10,000 involved.Lasted 30 days; fought by Arabian & Jewish tribes of Yathrib.Hazrat Salman Al-Farsi suggested digging the trench to defend the city.Last verified 13-03-2026', 0, 0, 0, 1790964557153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_79736fc3a0fed19d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Which was the first battle of Islam?', '{"A":"Battle of Badr","B":"Battle of Uhad","C":"Battle of Khyber","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Badr is the first battle of IslamOn 17 Ramadan, 2 AH (March 13, 624 CE)"Badr" means "full moon" in Arabic.Also called Furqan and The Day of the Criterion.Took place in the valley of Badr, located in the Hejazi regionMuslims: Approx. 313 men (82 Muhajirun and 231 Ansar).Quraysh: Approx. 1000 soldiers led by Abu Jahl.82-85 Muhajirun and 231 Ansar (61 from Aws and 170 from Khazraj).2 horses and 70 camels.Fourteen Muslims were killed, while 70 Kufar were killed and 70 captured.Last updated question by NA 22-April-2026', 0, 0, 0, 1790964557153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7368306e459ebf16', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In which Hijri Ghazwa-e-Khyber was fought?', '{"A":"7 Hijri","B":"6 Hijri","C":"5 Hijri","D":"8 Hijri"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ghazwa-e-Khyber was fought in 7 Hijri (628 AD).It was a battle between Muslims and the Jews of Khaybar.The battle began and ended in 629 AD.Location: Khaybar, Saudi Arabia.Result: Muslim victory.15 Muslims were martyred, and 93 Jews were killed in the battle.Additional InformationFamous Ghazwat — Important for MCQs Ghazwa-e-Badr — 2 AH Ghazwa-e-Uhud — 3 AH Ghazwa-e-Khandaq (Ahzab) — 5 AH Ghazwa-e-Banu Quraiza — 5 AH Ghazwa-e-Khaybar — 7 AH Ghazwa-e-Fath-e-Makkah — 8 AH Ghazwa-e-Hunain — 8 AH Ghazwa-e-Taif — 8 AH Ghazwa-e-Tabuk — 9 AH', 0, 0, 0, 1790964557153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_09b2afe11f928bfc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Which Sahabi face features (Facsimile) were similar to Holy Prophet (PBUH) in battle Uhad?', '{"A":"Hazrat Musab bin Umair","B":"Hazrat Hassan","C":"Hazrat Hussain","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Musab bin ''Umair (RA) possessed a stature similar to the Holy Prophet (PBUHMusab ibn Omair means “the Good”He embraced Islam in 614 CE and was the first ambassador of Islam.During the Battle of Uhud, he fought fiercely to protect the Prophet (PBUH).When he was martyred, the enemy and some Muslims thought it was the Prophet (PBUH) Last updated question by NA on 07 May 2026', 0, 0, 0, 1790964557153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_830cb19c8301ef3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The Battle of Motah was fought against which empire?', '{"A":"Sasanian Empire","B":"Byzantine (Roman) Empire","C":"Persian Empire","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Opponents: Muslims vs Byzantine Empire (Romans)Fought in 629 AD (8 AH)Location: Mu’tah (Jordan)Commanders martyred: Zaid bin Harithah, Jafar ibn Abi Talib, Abdullah bin RawahaLeadership later taken by Khalid ibn al-WalidLast verified on 23-04-2026', 0, 0, 0, 1790964557153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f10f14f13e65775d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In which battle did the Holy Prophet (ﷺ) participate before Prophethood?', '{"A":"Fijar War (Harb al-Fijar)","B":"Battle of Badr","C":"Battle of Uhud","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet (ﷺ) participated in the Fijar War (Harb al-Fijar) before Prophethood.The war took place during his youth, around 590 AD.He assisted his uncles by collecting and handing them arrows.Age of the Prophet (ﷺ): About 15–20 years.Harb al-Fijar means "The Sacrilegious War" because fighting took place during the sacred months.Verified & Updated', 0, 0, 0, 1790964557153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_acf5e4a40df1ce23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'How many army commander(s) were martyred in the Battle of Mu''tah?', '{"A":"3","B":"2","C":"1","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Three army commanders were martyred in the Battle of Mu''tah in 629 AD (8 AH).Zayd ibn HarithahJa''far ibn Abi TalibAbdullah ibn RawahahAfter their martyrdom, Khalid ibn al-Walid took command and safely led the Muslim army back.Last verified on 11-07-2026', 0, 0, 0, 1790964557153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e1825759f9892764', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'When the battle of Motah was fought?', '{"A":"8 AH (629 AD)","B":"9 AH (630 AD)","C":"10 AH (631 AD)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fought in 629 AD (8 AH)Location: Mu’tah (Jordan)Opponents: Muslims vs Byzantine Empire (Romans)Commanders martyred: Zaid bin Harithah, Jafar ibn Abi Talib, Abdullah bin RawahaLeadership later taken by Khalid ibn al-WalidLast verified on 23-04-2026', 0, 0, 0, 1790964557243) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d6558e6901ddfe3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In which Ghazwa was Hazrat Ayesha’s (RA) scarf used as a flag?', '{"A":"Ghazwa-e-Uhud","B":"Ghazwa-e-Khandaq","C":"Ghazwa-e-Badr","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ayesha’s (RA) white scarf was used as a flag during Ghazwa-e-Badr.The scarf was reportedly tied as a banner and carried by Ali ibn Abi Talib (RA).Additional information:Date: 17 Ramadan, 2 AH (13 March 624 CE)Location: Badr (near Madinah)Muslim Army: About 313 soldiersQuraysh Army: About 1,000 soldiersFirst major battle between: The Muslims and the Quraysh of MakkahLast verified on 09-07-2026', 0, 0, 0, 1790964557243) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9fdf9100b8cacc2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The battle of Badr was fought in the month of?', '{"A":"Muharram","B":"Ramazan","C":"Shawal","D":"Zil-Hajj"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: 17 Ramadan, 2 AH / 624 CEBattle Name: Ghazwa-e-BadrPlace: Badr (near Madinah)Between: Muslims and Makkans (Quraysh)Muslim Leader: Muhammad (SAW)Additional information:Muslims: around 313 soldiersNumber of Muslim martyrs: 14Quraysh Army: around 1000 soldiersMuslim horses: 2Muslim camels: around 70Last verified on 17-05-2026', 0, 0, 0, 1790964557243) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4674ffc97ca6d04a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In which year battle of Qadsia was fought?', '{"A":"15 Hijri","B":"12 Hijri","C":"14 Hijri","D":"16 Hijri"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Battle of Qadsia was fought in 15 Hijri (16–19 November 636 AD).It took place during the caliphate of Hazrat Umar (RA).It was a major battle between Muslims and the Persian Empire.Location: Al-Qādisiyyah, IraqCommander (Muslims): Sa’d ibn Abi Waqqas (RA)Last verified on 12-06-2026', 0, 0, 0, 1790964557243) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_78ca7120ae6221d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Who was the last Commander-in-Chief of the Battle of Mu''tah?', '{"A":"Hazrat Khalid ibn al-Walid (R.A.)","B":"Hazrat Zaid bin Harithah (R.A.)","C":"Hazrat Ja''far bin Abi Talib (R.A.)","D":"Hazrat Abdullah bin Rawahah (R.A.)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Khalid ibn al-Walid (R.A.) was the last Commander-in-Chief of the Battle of Mu''tah.He was also known as "Saifullah" (The Sword of Allah).Additional information:Year: 8 AH / 629 ADMuslim Army: 3,000First 3 Commanders: Zaid bin Harithah (R.A.), Ja''far bin Abi Talib (R.A.), Abdullah bin Rawahah (R.A.)This was the first major battle between the Muslims and the Byzantine (Roman) Empire.Last verified on 02-08-2026', 0, 0, 0, 1790964557243) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5a1825a1e01431c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In which CE year did the Prophet Muhammad (PBUH) migrate (Hijrah) from Makkah to Madinah?', '{"A":"610 CE","B":"620 CE","C":"622 CE","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Year of Hijrah: 622 CEFrom: MakkahTo: MadinahReason: Persecution of Muslims by QurayshIslamic Calendar Started: 1 AH (Anno Hegirae)Additional information:Prophet Muhammad stayed in the Cave of Thawr during the migration journey.Hazrat Abu Bakr (RA) accompanied the Prophet ﷺ during Hijrah.Last verified on 10-05-2026', 0, 0, 0, 1790964557244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6f2f007b61c97b66', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'When was Ghazwa-e-Tabook fought?', '{"A":"7 A.H. (628 CE)","B":"8 A.H. (629 CE)","C":"9 A.H. (630 CE)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Year: 630 AD / 9 AH (Rajab)Location: Tabook (northwest Arabia)Muslim army: around 30,000 soldiersType: Ghazwa (Prophet PBUH participated)Outcome: No direct battle (bloodless)Also known as: Expedition of UsraReason: Rumors of Byzantine attackAdditional information:“Ghazwa” = battle in which Prophet Muhammad (PBUH) participatedFirst Ghazwa = Ghazwat-ul-Abwa (Waddan)Last verified on 16-03-2026', 0, 0, 0, 1790964557244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3e00001aaa81e6e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'When was the Battle of Khandaq (Battle of the Trench) fought?', '{"A":"3 A.H. (625 CE)","B":"4 A.H. (626 CE)","C":"5 A.H. (627 CE)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ghazwa-e-Ahzab or Battle of the Trench was fought in 5 A.H (627 CE).Additional information:Muslims: ~3,000; Kufar: ~10,000; Munafiqeen: ~10,000 involved.Lasted 30 days; fought by Arabian & Jewish tribes of Yathrib.Hazrat Salman Al-Farsi suggested digging the trench to defend the city.Last verified 13-03-2026', 0, 0, 0, 1790964557244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_69b749ae32cded3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In which Battle Abu Jahl was killed?', '{"A":"Trench","B":"Uhad","C":"Badr","D":"Tabook"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Battle: BadrDate: 13 March 624 CE (17 Ramadan, 2 AH)Real Name: Amr ibn Hisham al-MakhzumiInitially wounded by: Mu''awwidh ibn ''Afrā'' and Mu''ādh ibn ''Amr ibn al-JamūḥFinally killed by: Abdullah ibn Mas''ud (RA)Last verified on 14-07-2026', 0, 0, 0, 1790964557331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_455754c5ad9f839f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The decisive battle of Qadsiya was fought by Muslims with?', '{"A":"Persian Empire","B":"Roman Empire","C":"Russians","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Qadisiyah was fought between the Muslims and the Persian (Sassanian) Empire.Year: 636 AD (15 AH)Caliph: Hazrat Umar (R.A.)Muslim Commander: Hazrat Sa''d ibn Abi Waqqas (R.A.)Persian Commander: Rostam FarrokhzadLast verified on 19-07-2026', 0, 0, 0, 1790964557331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_124195473b9d2686', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Who gave the suggestion of digging the trench around the city of Madinah at the time of Battle of Khandaq?', '{"A":"Hazrat Abu Bakr Siddique (R.A)","B":"Hazrat  Umar (R.A)","C":"Hazrat Salman Al-Farsi (R.A)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Suggested by: Hazrat Salman Al-Farsi (R.A)Battle Name: Battle of Khandaq (Battle of the Trench)Start Date: March 627 AD (5 AH)Duration: 27 daysPlace: Madinah (Yathrib)Last verified on 19-07-2026', 0, 0, 0, 1790964557331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f56d58341ef878a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'For how many days did Prophet Muhammad (ﷺ) stay in Makkah after its conquest?', '{"A":"10 days","B":"15 days","C":"5 days","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Stay in Makkah: 15 daysEvent: Conquest of Makkah (Fatah Makkah)Date: 20 Ramadan, 8 AH (630 AD)Companions: 10,000Camel: Al-Qaswa (Al-Kaswa) with Hazrat Usama bin Zaid (RA) riding behind him.Last verified on 19-07-2026', 0, 0, 0, 1790964557331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fff9f5be53839070', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In which battle was Hazrat Hamza (RA) martyred?', '{"A":"Battle of Badr","B":"Battle of Uhud","C":"Battle of Khandaq","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Battle: Battle of UhudYear: 3 AH (625 AD)Location: Mount Uhud, MadinahMartyr: Hazrat Hamza (RA)Killed by: Wahshi ibn HarblThe Holy Prophet (ﷺ) gave him the title "Sayyid al-Shuhada" (Leader of the Martyrs).Last verified on 19-07-2026', 0, 0, 0, 1790964557331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fdce98b18481092b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The Battle of Safeen (Saffin) was fought in 37 A.H. between Hazrat Ali (RA) and _______?', '{"A":"Hazrat Ayesha (RA)","B":"Hazrat Muawia (RA)","C":"Hazrat Abdullah bin Zubair (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Siffin was fought between Caliph Hazrat Ali (RA) and Muawiyah ibn Abi Sufyan (RA).It was fought in 37 AH (657 CE).The battle took place near the Euphrates River at Siffin (present-day Syria).Additional information:Battle of the Camel (Jamal): 36 AH (656 CE)Battle of Nahrawan: 38 AH (658 CE)Last verified on 15-06-2026', 0, 0, 0, 1790964557331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_96e3d95ec018a58c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In Battle of Khybar, Jew warrior Marhab was killed by?', '{"A":"Hazrat Ali (RA)","B":"Hazrat Abdullah Ansaari (RA)","C":"Hazrat Ja’far ibn Abu Talib (RA)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Jewish warrior Marhab was killed by Hazrat Ali (RA) during the Battle of Khybar.The Battle of Khybar took place in 7 AH (628 AD).Hazrat Ali (RA) was given the Muslim army''s flag by the Holy Prophet (ﷺ).After defeating Marhab, the Muslims captured the forts of Khybar.Last verified on 19-07-2026', 0, 0, 0, 1790964557331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fa0b8e07c65d9b3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The Battle of Tabook is also known as ______?', '{"A":"The Expedition of Urwa","B":"Expedition of Usra","C":"The Expedition of Makkah","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Also known as: Expedition of UsraYear: 630 AD / 9 AH (Rajab)Location: Tabook (northwest Arabia)Muslim army: around 30,000 soldiersType: Ghazwa (Prophet PBUH participated)Outcome: No direct battle (bloodless)Reason: Rumors of Byzantine attackAdditional information:“Ghazwa” = battle in which Prophet Muhammad (PBUH) participatedFirst Ghazwa = Ghazwat-ul-Abwa (Waddan)Last verified on 16-03-2026', 0, 0, 0, 1790964557331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1bcaacb0445d5ac4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'How many Muslims/Sahaba (RA) Martyred in Battle of Badr?', '{"A":"7","B":"10","C":"14","D":"22"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Number of Muslim martyrs: 14Battle Name: Ghazwa-e-BadrDate: 17 Ramadan, 2 AH / 624 CEPlace: Badr (near Madinah)Between: Muslims and Makkans (Quraysh)Muslim Leader: Muhammad (SAW)Additional information:Muslims: around 313 soldiersQuraysh Army: around 1000 soldiersMuslim horses: 2Muslim camels: around 70Last verified on 17-05-2026', 0, 0, 0, 1790964557418) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_66bfecbfdb3d630e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Which battle is referred to as Yaumul Furqan?', '{"A":"Hunayn","B":"Badr","C":"Uhad","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790964557418) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_934d13009d0fc90c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The Battle of Camel was fought in?', '{"A":"30 A.H","B":"33 A.H","C":"34 A.H","D":"36 A.H"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Camel (جنگِ جمل) took place on 13 Jumada Al-Awwal 36 A.H (7 November 656 AD).It was fought at Basra (Iraq).The battle was between Ali ibn Abi Talib (R.A) and forces led by Aisha bint Abi Bakr (R.A).It is also called the Battle of Basra or Jamal.Named “Camel” because Hazrat Aisha (R.A) was on a camel during the battle.It was the first major civil war (Fitna) in Islam.The battle ended with victory of Hazrat Ali (R.A).Last verified on 28-04-2026', 0, 0, 0, 1790964557418) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_be1c9c3b07fd7851', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The Battle of Yarmouk was fought between Muslims and _____?', '{"A":"Iranis","B":"Jews","C":"Romans (Byzantine Empire)","D":"Christians"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Battle of Yarmouk: Fought between the Byzantine Empire and Muslim forces under Khalid bin Waleed.Dates: August 15 to August 20, 636 AD.Location: Near the Yarmouk River.Caliphate: During the reign of Hazrat Umar (RA).Result: Decisive victory for the Muslims, marking the end of Byzantine rule in Syria.Last verified on 12-06-2026', 0, 0, 0, 1790964557418) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d3b6ab396b67f792', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Who was the self proclaimed Prophet against whom the battle of Yamama was fought?', '{"A":"Muslaymiah","B":"Ikrimah","C":"Shurabil","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Yamama was fought against Musaylimah al-Kadhdhab, a self-proclaimed prophet.The battle took place in 11 AH (632 CE) during the caliphate of Hazrat Abu Bakr (RA).It was part of the Ridda Wars (Wars of Apostasy) against false prophets and rebels.The battle occurred in the region of Yamama (Najd, Arabia).Muslims defeated Musaylimah’s forces.Military commander: Hazrat Khalid bin Walid (RA)Last verified on 12-06-2026', 0, 0, 0, 1790964557418) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4edb4cf625f8ed1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The battle of Hunain was fought in _____ AH.', '{"A":"6","B":"7","C":"8","D":"9"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Year: 8 AH (630 CE)Month: Shawwal (1st)Location: Valley of Hunain (near Ta’if)Opponents: Hawazin and Thaqif tribesMuslim army: About 12,000 soldiersLast verified on 12-06-2026', 0, 0, 0, 1790964557418) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_078cd7c447946d9b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The Holy Prophet (PBUH) spent how many years in Makkah?', '{"A":"50","B":"53","C":"55","D":"58"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet Muhammad (PBUH) spent 53 years in Makkah.Additional information:Birth: 571 AD (Makkah)Prophethood began: 610 ADMigration (Hijrah): 622 ADTime in Madinah: 10 years (622–632 AD)Last verified on 10-06-2026', 0, 0, 0, 1790964557418) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7de44fee3e767408', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'When was the Battle of Yarmouk fought between Muslims and Romans?', '{"A":"236 AD","B":"336 AD","C":"636 AD","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Battle of Yarmouk: Fought between the Byzantine Empire and Muslim forces under Khalid bin Waleed.Dates: August 15 to August 20, 636 AD.Location: Near the Yarmouk River.Caliphate: During the reign of Hazrat Umar (RA).Result: Decisive victory for the Muslims, marking the end of Byzantine rule in Syria.Last verified on 27-04-2026', 0, 0, 0, 1790964557418) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_92ed97030ebe56d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Prophet SAW recited ______ at the conquest of Makkah.', '{"A":"Surah Al-Fatha","B":"Surah Al-Kausar","C":"Surah Al-Anfal","D":"Surah Al-Ankaboot"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad ﷺ primarily recited Surah Al-Fath (Chapter 48) Riding his camel, and frequently recited verse 17:81 from Surah Al-Isra,The conquest of Mecca occurred in December 629 or January 630 AD (Julian), 20 Ramadan, 8 AH.The Prophet SAW entered on his favorite camel, Al-Kaswa, with Usama Ibn Zaid (R.A.) sitting behind him.Last updated by NS on 06 May 2026', 0, 0, 0, 1790964557508) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5702127143363d8a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Hazrat Ali (R.A) changed capital from Madina after the battle of Jamal to?', '{"A":"Kuffa","B":"Baghdad","C":"Makkah","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ali ibn Abi Talib (656 to 661 CE) shifted the capital from Madinah to Kufa.This change happened around 657 CE (36 AH) after internal conflicts like the Battle of Jamal.Earlier, Madinah was the capital during the first three caliphs.He is buried in Najaf.Last verified on 30-04-2026', 0, 0, 0, 1790964557508) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2a3a9db7a08f07df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The Battle of Yarmouk was fought during the caliphate of ______?', '{"A":"Hazrat Umar (RA)","B":"Hazrat Usman (RA)","C":"Hazrat Abu Bakar (RA)","D":"Hazrat Ali (RA)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Battle of Yarmouk: Fought between the Byzantine Empire and Muslim forces under Khalid bin Waleed.Dates: August 15 to August 20, 636 AD.Location: Near the Yarmouk River.Caliphate: During the reign of Hazrat Umar (RA).Result: Decisive victory for the Muslims, marking the end of Byzantine rule in Syria.Last verified on 27-04-2026', 0, 0, 0, 1790964557508) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4824db5eb2ce47e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The battle of Nehruwan was fought between Hazrat Ali (R.A) and ______?', '{"A":"Hazrat Aisha (R.A)","B":"Hazrat Ameer Muawia (R.A)","C":"The Kharijites","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Nahrawan took place in 658 CE (37 AH).It was fought between Ali ibn Abi Talib (R.A) and the Kharijites.It occurred after the Battle of Siffin.The Kharijites opposed Hazrat Ali’s leadership.Hazrat Ali (R.A) defeated them decisively.Last verified on 27-04-2026', 0, 0, 0, 1790964557508) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_69c8313d6543c9ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The Battle of Khyber was fought between _____?', '{"A":"Muslims and Romans","B":"Muslims and Jews","C":"Muslims and Hindus","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790964557508) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_442819a80960827e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Which Sahabi killed his father in a battle of Badr?', '{"A":"Ali ibn Abi Talib","B":"Abu Ubaidah ibn al-Jarrah","C":"Sa’d ibn Abi Waqqas","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Battle: BadrYear: 2 AH (624 AD)Sahabi: Abu Ubaidah ibn al-Jarrah (RA)Father: Fought against Muslims (Quraysh side)Principle shown: Faith above blood relationLast verified on 27-06-2026', 0, 0, 0, 1790964557508) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_55963532e4cb3f12', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Identify the last ghazwa in which Holy prophet (PBUH) participated?', '{"A":"Ghazwa Hunain","B":"Ghazwa Mutah","C":"Ghazwa Ahzab","D":"Ghazwa Tabuk"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Expedition of Tabuk, also known as the Expedition of Usra.Muslims forces was 30,000.Start date: October 630 ADDate: October 630 CE (Rajab AH 9)Result: Bloodless battleLocation: north to Tabuk, near the Gulf of Aqaba, in present-day northwestern Saudi Arabia Ghazwa means that war in which our PROPHET (PBUH) took part while in which PROPHET (PBUH) did not took part is known as war.The first ghazaw was ghazawa Al abawa.Last verified on 16-03-2026', 0, 0, 0, 1790964557508) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d0ec0a3dbd704304', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Hazrat Ali (R.A) was appointed as caretaker of Madina when the Prophet (PBUH) left for Ghazwa?', '{"A":"Tabuk","B":"Badr","C":"Uhud","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali (RA) was appointed caretaker of Madinah during the expedition of Tabuk.The Prophet Muhammad (PBUH) left him to manage the city.He was responsible for the families and affairs of Muslims in Madinah.Battle of Tabuk took place in 9 AH (630 AD).This shows the trust of the Prophet (PBUH) in Hazrat Ali (RA).Last verified on 26-04-2026', 0, 0, 0, 1790964557508) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_746b20bcbc6a5352', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In which Ghazwa Hazrat Ali (RA) was awarded Zulfiqar?', '{"A":"Mota","B":"Ahazab","C":"Badr","D":"Uhad"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The famous sword Zulfiqar was awarded to Hazrat Ali (R.A) in the Battle of Uhud.It was given by Prophet Muhammad (PBUH) after his bravery in battle.Zulfiqar became a symbol of courage and Islamic strength.Hazrat Ali (R.A) is known as “Lion of Allah (Asadullah)” for his bravery.Last verified on 25-04-2026', 0, 0, 0, 1790964557598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e7dbaa89bea44616', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The battle of Uhud was fought in?', '{"A":"624 AD","B":"622 AD","C":"625 AD","D":"627 AD"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: 23 March 625 AD (3 AH)Place: Valley of Uhud, near MadinaMuslim Army: ~1000Enemy Army: ~300050 skilled archers were placed on Mount Uhud by Prophet MuhammadIt was between Muslims and the Quraish of Makkah.The leader of the Quraish was Abu Sufyan.The battle is mentioned in the Qur''an (Surah Aal-e-Imran).Last verified on 25-04-2026', 0, 0, 0, 1790964557598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5f7445ab936531eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Who was the leader of pagans (non Muslims) in the Battle of Badr?', '{"A":"Abu Sufyan","B":"Utba","C":"Abu Jehal","D":"Hind bint Utbah"}', 'C', NULL, 0, 0, 0, 1790964557598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c90a4da4a3b57c30', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Who led Muslims in the Battle of Yarmouk?', '{"A":"Abu Bakr (RA)","B":"Khalid bin al-Waleed (RA)","C":"Umar Bin al-Khittab (RA)","D":"Ali ibn-e- Abi Talib (RA)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Battle of Yarmouk: Fought between the Byzantine Empire and Muslim forces under Khalid bin Waleed.Dates: August 15 to August 20, 636 AD.Location: Near the Yarmouk River.Caliphate: During the reign of Hazrat Umar (RA).Result: Decisive victory for the Muslims, marking the end of Byzantine rule in Syria.', 0, 0, 0, 1790964557598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8eaa7462751f76e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The battle of Qudasiya was fought during the reign of _______?', '{"A":"Ali (R.A)","B":"Usman (R.A)","C":"Umar Farooq (R.A)","D":"Abu Bakkar Saddique (R.A)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The battle of Qudasiya was fought during the reign of Umar Farooq (R.A)***The battle of Qudasiya was fought between Umar (R.A) and Iran.This Battle was fought in Quads, Therefore its name is Battle of Qudasiya.', 0, 0, 0, 1790964557598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1cab63794e0a39e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The Battle of Badr was fought in ____?', '{"A":"15 April 623 CE","B":"13 March 624 CE","C":"17 June 625 CE","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790964557598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_01c48e23c1e32a6c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'At the time of Ghazwa-e-Khandaq there was only one Jewish tribe left in Madina name it?', '{"A":"Banu Naeem","B":"Banu Quraizah","C":"Banu Qainqua","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During Ghazwa-e-Khandaq, Banu Quraizah was the only Jewish tribe remaining in Madina.They broke their treaty with the Muslims during the battle, leading to a significant confrontation afterward.', 0, 0, 0, 1790964557598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_748e483d1f6a82d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The battle of Hunain was fought between ______?', '{"A":"The Prophet (PBUH) & his companions and Hawazin (Hawazin and Thaqif)","B":"The Prophet(PBUH) & his companions with Banu Quraish","C":"The Prophet (PBUH) & his companions & Banu Taheem","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 1st Shawwal, 8th Hijra (630 CE), a force of 12,000 Muslims approached the valley of Hunain.The Battle of Hunain, fought near al-Ta''if.It was fought between the Prophet Muhammad (PBUH) and his companions against the Hawazin and Thaqif tribes.It took place shortly after the conquest of Makkah.The Battle of Hunain resulted in a Muslim victory over the Bedouin tribes.', 0, 0, 0, 1790964557598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a7068ae6888d4724', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Ghazwa-e-Badr was fought in _____?', '{"A":"17th Ramzan, 2 Hijri","B":"17th Ramzan, 3 Hijri","C":"17th Ramzan, 4 Hijri","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790964557684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1c5057915f5ee012', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In which Ghazwa did Hazrat Khalid bin Walid receive the title Saifullah?', '{"A":"Ghazwa Badr","B":"Ghazwa Uhud","C":"Ghazwa Khaybar","D":"Ghazwa Muta"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation حضرت خالد بن ولیدؓ مسلمانوں کے درمیان ایک سرکاری فوجی کمانڈر کے طور پر شامل کیا اور حضرت محمد مصطفیٰ صلی اللہ علیہ وسلم نے خالد بن ولید کو سیف اللہ (اللہ کی تلوار) کا خطاب دیاآٹھ ہجری میں حضرت خالد بن ولیدؓ مسلمان ہونےHe was a Muslim commander in the service of the:Prophet MuhammadCaliph Abu BakrUmarHe was born in 592 AD, in MeccaHe Died: in 642 AD, in Homs‎, SyriaThey were Buried in Khaled Ibn Walid Mosque, in Syria', 0, 0, 0, 1790964557684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_756db5c6160b15f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Makkah was also known as _____?', '{"A":"Bakkah","B":"Baladul Ameen","C":"Ummul Qura","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Makkah was conquered on 8th Hijri. Battle of Motah fought also 8th Hijri.', 0, 0, 0, 1790964557684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e6aef9d872d54c3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Who was the commander of Muslims in the battle of Muta?', '{"A":"Zayd Bin Harithah","B":"Hazrat Abu Bakar","C":"Hazrat Ali","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The army was led by Zayd ibn HarithahThe second-in-command was Jafar ibn Abi Talib And the third-in-command was Abd Allah ibn Rawahah.', 0, 0, 0, 1790964557684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_be4d150634b5f011', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'What is the second name of Ghazwa e Khandak?', '{"A":"Ghazwa e Ahzab","B":"Ghazwa e Tabook","C":"Ghazwa e Badr","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ghazwa-e-Khandaq is also known as Ghazwa-e-Ahzab and the Battle of the TrenchDuration: a 27-day-long defence by Muslims of Yathrib.Means: the Battle of the ConfederatesFought in Shawwal – Dhu al-QidahIt took place in 5 AH (627 CE)Muslims 3000Kufar 10000Last updated question NS on 10-09-2026', 0, 0, 0, 1790964557684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_93155fae7351997c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'When was Makkah conquered by the Holy Prophet ﷺ?', '{"A":"628 A.D","B":"629 A.D","C":"630 A.D","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad conquered Mecca in January 630 AD (8Hajri). On this day, Mecca was opened for and conquered by Muslims.', 0, 0, 0, 1790964557684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_862a91bb2f394cc4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'When the Ghazwa of Banu Nadhir took place?', '{"A":"2 Α.Η","B":"3 Α.H","C":"4 A.H","D":"5 A.H"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Ghazwa of Banu Nadhir (Nuzair) took place in May 625 CE, which is equivalent to Rabi'' al-awwal 4 AH.Banu Nadir, a Jewish tribe, was expelled from Medina after being accused of plotting to assassinate the Islamic Prophet Muhammad (SAW).The event is described in Surah Al-Hashr, Chapter 59 of the Quran.', 0, 0, 0, 1790964557684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0ce1b362ba2d7da3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In which battle a tooth (or part of it according to some sources) of the Holy Prophet (PBUH) was broken?', '{"A":"Uhad","B":"Khandaq","C":"Badr","D":"Hunain"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A tooth of the Holy Prophet (PBUH) was broken at the Battle of Uhud.The Battle of Uhud was a battle fought in 625 CE, where the Prophet Muhammad (SAW) was wounded and had two teeth broken.', 0, 0, 0, 1790964557684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bdf7063c4c36d81b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'How many week(s) were spent in digging the trench in the Ghazwa-e-Khandaq?', '{"A":"1","B":"2","C":"3","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Khandaq (Ahzab) was fought on 5 A. H (627).Ghazwa e Ahzab and Battle of the Trench is the second name of Ghazwa-e-Khandak Muslims 3000Kufar 1000010000 Munafiqeen were in Ghazwa-e-KhandaqAdditional information: it was the 30-day-long fight of Yathrib by Arabian and Jewish tribesHazrat Salman Al-Farsi suggests digging the trench at the time of the Battle of Khandaq***', 0, 0, 0, 1790964557782) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_36e00525e176abff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Which mosque is located at the site of the Battle of Uhud?', '{"A":"Al-Qiblatain Mosque","B":"Al-Nabawi Mosque","C":"Al-Fasih Mosque","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid al-Fasih is located near Mount Uhud, where the Prophet Muhammad (PBUH) offered prayer during the battle.It is historically linked to the Battle of Uhud as a site of reflection and strategy.', 0, 0, 0, 1790964557782) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5947a77f108ef65b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Battle of Uhud was fought in the month of?', '{"A":"Muharram","B":"Shaban","C":"Shawal","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Uhud was fought on Saturday, 23 March 625 AD, in the valley north of Mount Uhud.Abu Sufyan commander of the infidels in Uhad Ghazwa***It was fought in 3 Hijri Ohad is the name of a mountain1000 Muslims participated in the battle of Uhad3000 Infidels participated in the battle of Uhad Infidel means کفارIn the battle of Uhad Prophet Muhammad (PBUH) selected 50Skillful archers to stay on the mountain', 0, 0, 0, 1790964557782) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_257406f1d51c8f76', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Hazrat Khalid Bin Waleed (R.A) participated for the first time in which battle?', '{"A":"Battle of Trench","B":"Battle of Mutah","C":"Battle of Tabook","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Khalid bin Waleed (R.A) first participated in the Battle of Mutah in 629 CE (8 A.H).He earned the title "Saifullah" (the Sword of Allah).Due to his heroic efforts in that battle, which was fought against the the Byzantine Empire.', 0, 0, 0, 1790964557782) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f5e229d94ca5f446', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The Battle of Uhud was fought in the month of _____?', '{"A":"Ramadan, 2 Hijri","B":"Muharram, 1 Hijri","C":"Shawwal, 3 Hijri","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Uhud was fought on 23 March 625 (7 Shawwal 3 AH) at Mount Uhud, in what is now north-western Saudi Arabia.', 0, 0, 0, 1790964557782) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1157aa675b05adc2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', '_____ Muslims fought in Ghazwa-e-Badr.', '{"A":"313","B":"300","C":"1000","D":"1909"}', 'A', NULL, 0, 0, 0, 1790964557782) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d29fceaad4bb080d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'How many Angels participated in the Battle of Badr?', '{"A":"1000","B":"32","C":"13","D":"20"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Badr also referred to as The Day of the Criterion.It was fought on Tuesday, 13 March 624 CE (17 Ramadan, 2 AH), near city of Badr.14 Muslims were killed in Battle of Badr.70 Kufar killed, 70 prisoners.It is mentioned in Surat Al-Anfal while talking about the battle of Badr that Allah Almighty promised the Muslims to reinforce them with 1,000 angels.', 0, 0, 0, 1790964557782) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_47abd32e0ab3d7be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'How many Munafiqeen were in Ghazwa-e-Khandaq?', '{"A":"2500","B":"5000","C":"10000","D":"12000"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 10000 Munafiqeen were in Ghazwa-e-Khandaq.Muslims 3000Kufar 10000Additional information:The Battle of Khandaq (Ahzab) was fought on 5 A.H (627).Ghazwa e Ahzab and Battle of the Trench is the second name of Ghazwa-e-Khandak.It was the 30-day-long fight of Yathrib by Arabian and Jewish tribes.Hazrat Salman Al-Farsi suggests digging the trench at the time of the Battle of Khandaq.', 0, 0, 0, 1790964557782) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1f25d222ce285d51', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'How many Muslims were martyred in the Battle of Uhud?', '{"A":"70","B":"60","C":"80","D":"75"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the Battle of Uhud, 70 Muslims were martyred.The Battle of Uhud occurred on Saturday, 23 March 625 AD (3 Hijri) in the valley north of Mount Uhud.Prophet Muhammad (PBUH) led around 1000 Muslims in the Battle of Uhud.They faced 3000 Qurayshi Meccans commanded by Abu Sufyan ibn Harb.Abdullah bin Jubair was appointed by Prophet Muhammad (PBUH) to lead the 50 skilled archers positioned on Uhud Mountain.', 0, 0, 0, 1790964557868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b15984e9d3d29bb9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'What is the distance between Madina and Khyber?', '{"A":"150","B":"172","C":"168","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The distance between Madina and Khyber is approximately 168/172 kilometers (104 miles) by modern roads.This aligns with historical Islamic sources that describe Khyber as a 2–3 day journey from Madina.Khyber was the site of the Battle of Khaybar (628 CE), where Prophet Muhammad (PBUH) led Muslims to victory.The journey took 3 days on foot/camel, matching the 168 km distance.', 0, 0, 0, 1790964557868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_10c37ffef5dd8a86', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Who killed the pagan Amr ibn Abd al-Wud in the Battle of the Trench (Ghazwa Ahzab)?', '{"A":"Hazrat Umar (RA)","B":"Hazrat Ali (RA)","C":"Hazrat Abu Bakr (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The battle of Trench was fought in fifth HijriThe Battle of the Trench, also known as the Battle of Khandaq and the Battle of the Confederates. It is 27-day-long defense.Muslims of Yathrib from Arab and Jewish tribes.', 0, 0, 0, 1790964557868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ce3e177bb2f8b985', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Who was the commander of 50 archer at Uhud mountain?', '{"A":"Abdullah bin Jubair","B":"Saad bin abi waqas","C":"Abdull Rahman bin Kaab","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The commander of the 50 archers at Mount Uhud during the Battle of Uhud was Abdullah ibn Jubayr. Date: 23 March 625 AD (3 AH)Location: Near Mount Uhud, MadinahMuslims: About 1,000, led by Prophet Muhammad (PBUH)Quraysh: About 3,000, led by Abu SufyanLast updated 25-07-2026 by NA', 0, 0, 0, 1790964557868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_31e2657f7a481206', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In which cave Muhammad PBUH stay during the migration from Makkah to Madina?', '{"A":"Ghar-e-Sor","B":"Ghar-e-Hira","C":"Ghar-e-Alperovitz","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During the migration from Makkah to Madina, Prophet Muhammad (PBUH) stayed in Ghar-e-Sor (Cave of Thawr) with Hazrat Abu Bakr (RA).They hid there for three days to escape the Quraish who were searching for them.It is located in the lower part of Makkah in the South of the district of MisfalahMuhammad PBUH stays here to escape from the tribe of Quraish.', 0, 0, 0, 1790964557868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_34ce7cff8aa7b633', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Bab-ul-Fatah is also known as _____?', '{"A":"Door of Madina","B":"Door of Paradise","C":"Door of Victory","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bab ul-Fatah is also known as Door of Victory. Bab ul-Fatah at which Prophet (PBUH) entered during the conquest of Makkah on Friday, 20 Ramzan 8 AH.', 0, 0, 0, 1790964557868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3b23e2ac113d9e0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Which was the second major battle fought by Muslims under the command of the Holy Prophet (SAW)?', '{"A":"Uhad","B":"Badr","C":"Khyber","D":"Khandaq"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Uhud, the second battle of Islam.It was fought in 3 Hijri (625 AD).Abu Sufyan was the commander of the infidels.Ohad is the name of a mountain.In this battle, 1,000 Muslims faced 3,000 infidels.', 0, 0, 0, 1790964557868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_99ea9be16564f804', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In which battle Hazrat Zaid bin Haris was martyred?', '{"A":"Mutah","B":"Badar","C":"Uhad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Mu''tah in September 629, where Zayd was killed.Hazrat Zaid bin Haris the adopted son of the Islamic prophet Muhammad.Hazrat Zaid bin Haris is commonly regarded as the fourth person to have accepted IslamZayd Bin Harith''s (R.A) name is mentioned in the Al-Ahzab 33rd Surah of the Quran Hazrat Zaid was the first adult male to become a Muslim and the only Muslim apart from Muhammad to be mentioned by name in the QuranThe Holy Prophet (PBUH) gave the title of Hub Rasool-Ullah to Hazrat Usama bin Zaid R.A ND21-2-2023', 0, 0, 0, 1790964557868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c6db904856c2cc7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Ghazwa Abwa was also known as ____ ?', '{"A":"Ghazwa Widdan","B":"Ghazwa Mota","C":"Ghazwa Ohad","D":"Ghazwa Badar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Al-Abwah also known as the Battle of Waddan.It was the first military expedition organized by the Prophet (ﷺ) to disrupt the trade routes between Makkah and Syria.These caravan raids between 623 and 624 led to the Battle of Badr.', 0, 0, 0, 1790964557937) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a87ba330f80cfb7d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Ghazwa Tabook is fought against _____?', '{"A":"Jews","B":"Kufar e makkah","C":"Romans","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Tabuk is known as the last Gazwa of the Holy ProphetGhazwa Tabook is fought against: RomansGhazwa e Tabook was fought in the year: 9 Hijriinitiated by Muhammad in October 630 AD.It took place During Rajab and Sha''ban in the region of Tabuk20 days Hazrat Muhammad PBUH stayed during Tabook Battle***ND29-1-2023', 0, 0, 0, 1790964557937) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_79dde6269a2476c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Who conquered the last fort of Khyber?', '{"A":"Hazrat Hamza (R.A)","B":"Hazrat khalid bin waleed (R.A)","C":"Hazrat Ali bin Abu Talib (A.S)","D":"None of These"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Battle of Khyber fought against Jews of Khyber.Battle of Khyber began in Muharram on 7/628.Hazrat Ali killed Marhab while conquering the Qamus fort.', 0, 0, 0, 1790964557937) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_01066b60b345c8ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Name the Ghazwa in which wine was prohibited?', '{"A":"Uhd","B":"Trench","C":"Bani Nuzair","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alcoholic drinks were banned in the fourth year of the Hijra (4 A.H), when Bani Nadeer Jews were driven into exile from their lands.', 0, 0, 0, 1790964557937) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_787bfbae7077446c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'During Ghazwa ____ to Tayammum was revealed?', '{"A":"Banu Mustaliq","B":"Trench","C":"Abwa","D":"Badr"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tayammum is the Islamic act of dry Ritual purification using purified sand or dustThe verse of Tayammum (dry ablution) was revealed during Battle of Banu Al-Mustaliqin Al-Ma''idah contains the order of wuzu, Ghusal, and TayammumTayammum is valid only for one obligatory SalahTayammum is obligatory on 4 (AH)while Wazu is obligatory on 5(AH)ND23-6-2023', 0, 0, 0, 1790964557937) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_60039aa3173d68d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Which battle led to the birth of the Khawarij?', '{"A":"Battle of Nahrawan","B":"Battle of Siffin","C":"Battle of Kharijites","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Khawarij sect emerged as a result of the Battle of Siffin (657 CE).It was fought between the forces of Caliph Hazrat Ali and those of Muawiyah ibn Abu Sufyan. The battle ended in a stalemate, and the arbitration process that followed led to a group of rebels, who would later become known as the Khawarij, to break away from Hazrat Ali''s camp.', 0, 0, 0, 1790964557937) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_609ddba2bb8415bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'After the Battle of Yarmouk, which was won by the Muslims Khalid bin Waleed was removed by the Caliph Umar (RA) from his supreme command. The new Supreme Commander was:', '{"A":"Saad bin Abi Waqas (RA)","B":"Abu Ubaydah (RA)","C":"Amr bin Al Aas (RA)","D":"Hazrat Bilal (RA)","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Ubaidah ibn al-Jarrah, fully Abū ''Ubaydah ''Āmir ibn ''Abdillāh ibn al-Jarāḥ was one of Companions of the Islamic prophet Muhammad.', 0, 0, 0, 1790964557937) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_14205a89b0dfe885', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Who killed Prophet''s uncle Hamza bin Abdul Mutalib (RA)?', '{"A":"Hind bint Utbah","B":"Abu Jahl","C":"Wahshi bin Harb","D":"Musaylimah-al-Kadhab","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abyssinian slave Wahshi ibn Harb martyred Prophet''s uncle Hamza bin Abdul Mutalib (RA)Hazrat Hamza Died: on 22 March 625; Mount Uhud, Medina, Arabiawhat is the relationship of Hazrat Hamza With Hazrat Muhammad (PBUH)?Answer: Uncle***When did Hazrat Hamza embrace Islam?Fifth Nabvi***Ameer Hamza (R.A) was martyred in __________ Ghazwa.Uhad***Hamza ibn Abdul Muttalib Paternal Uncle of Hazrat Muhammad.***', 0, 0, 0, 1790964557937) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_988d1240b23536eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Name the Uncle of the Holy Prophet (PBUH) who was martyred in the battle of Uhud?', '{"A":"Hazrat Saad (RA)","B":"Hazrat Abbas (RA)","C":"Hazrat Hamza (RA)","D":"Hazrat Talib (RA)","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Uncle of the Holy Prophet (PBUH) named Hazrat Hamza (RA) was martyred in the battle of Uhad.Abyssinian slave Wahshi ibn Harb martyred Hazrzat Hamza bin Abdul Mutalib (RA)Hazrat Hamza Died: on 22 March 625; Mount Uhud, Medina, Arabia Additional infoBattle of Uhad was fought in third Hijra in the month of Shawal. ****', 0, 0, 0, 1790964558031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_efcfe687632aa3cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'How many days Hazrat Muhammad PBUH stayed during Tabook Battle?', '{"A":"8","B":"20","C":"10","D":"18"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad (PBUH) stayed for 20 days in TabukThe Battle of Tabuk, the last major expedition of the Prophet Muhammad (PBUH).It was fought against the Romans in 9 Hijri (630 AD).It took place in the region of Tabuk during Rajab and Sha''ban.Last updated by NS on 06 May 2026', 0, 0, 0, 1790964558031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_34bf32d4dc5d2163', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Who was the commanders of the Infidels in the Battle of Uhud?', '{"A":"Abu Sufyan","B":"Abu Jahal","C":"Shaiba","D":"Khalid bin Walid"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Uhud occurred on Saturday, 23 March 625 AD (3 Hijri) in the valley north of Mount Uhud.Prophet Muhammad (PBUH) led around 1000 Muslims in the Battle of Uhud.They faced 3000 Qurayshi Meccans commanded by Abu Sufyan ibn Harb.Abdullah bin Jubair was appointed by Prophet Muhammad (PBUH) to lead the 50 skilled archers positioned on Uhud Mountain.', 0, 0, 0, 1790964558031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6c5602dea0addd4c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'At the time of conquer of Makkah, 1st man who embraced Islam?', '{"A":"Abu Bakr","B":"Hazrat Ali","C":"Abu Sufyan ibn Haris","D":"Hazrat Umar"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Sufyan ibn Harb converts to IslamUpon their arrival, the Muslims were furious at the sight of Abu Sufyan and sought to kill him.', 0, 0, 0, 1790964558031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e33232b319947198', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Which daughter of the Holy Prophet (PBUH) died the day of the victory of battle of Badr?', '{"A":"Ruqayyah (RA)","B":"Umm-e-Kulthum (RA)","C":"Zainab (RA)","D":"Fatima (RA)","E":"None of these"}', 'A', NULL, 0, 0, 0, 1790964558031) ON CONFLICT(id) DO NOTHING;
