INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bc0a145017f6c4d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Name the first Battle between Muslims and Kafirs in Which Muhammad(PBUH) took part?', '{"A":"Ghazwa- Uhud","B":"Ghazwa-e- Abwa","C":"Ghazwa- Khyber","D":"Ghazwa- Badr"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Wadan also known as the Battle of Abwa, was the first battle involving an Islamic army led by the Prophet Muhammad. These caravan raids between 623 and 624 led to the Battle of Badr.', 0, 0, 0, 1790964558031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ca6aa0249f2eab3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Khyber was a stronghold of ?', '{"A":"Jews","B":"Naim","C":"Muslim","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There is a fort known as ''Khyber'' 64 km to the west of medina (Saudi Arabia). This was a stronghold of Jews in the pre-Islamic days', 0, 0, 0, 1790964558031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_084f187fcd500376', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Abu jahal was killed in the battle of_____?', '{"A":"Badar","B":"Khandaq","C":"Uhad","D":"Moata","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Jahal was killed in the battle of BadarAbu Jahl was fatally wounded by Muadh ibn Afra and Muadh ibn Amr but was finally killed by Abdullah ibn Masud.Abu Jahal was known as Abu Hakam (“Father of Wisdom”)Additional Information:battle Of Badar was fought 2nd Hijri.Muslim Participated in 313 and Kufars 1000. Muslim Martyred: 14', 0, 0, 0, 1790964558087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4dd510e1ca040559', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Which of the following Gazwa is known as the last Gazwa of Holy Prophet?', '{"A":"Uhad","B":"Badr","C":"Tabook","D":"Yamama"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Tabuk is known as the last Gazwa of Holy ProphetGhazwa Tabook is fought against: RomansGhazwa e Tabook was fought in the year: 9 Hijriinitiated by Muhammad in October 630 AD. It took place During Rajab and Sha''ban in the region of Tabuk20 days Hazrat Muhammad PBUH stayed during Tabook Battle***ND29-1-2023', 0, 0, 0, 1790964558087) ON CONFLICT(id) DO NOTHING;
