INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_838df929edff5073', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The battle of Trench was fought in which Hijrah___?', '{"A":"Fourth Hijrah","B":"Fifth Hijrah","C":"Seventh Hijrah","D":"First Hijrah"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Khandaq (Ahzab) was fought on 5 A. H (627).Ghazwa e Ahzab and Battle of the Trench is the second name of Ghazwa-e-Khandak Muslims 3000Kufar 1000010000 Munafiqeen were in Ghazwa-e-KhandaqAdditional informationit was the 30-day-long fight of Yathrib by Arabian and Jewish tribesHazrat Salman Al-Farsi suggests digging the trench at the time of the Battle of Khandaq***', 0, 0, 0, 1790964558087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_39c69ff052ae178b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'In battle of Hunain Muslims were more than ____', '{"A":"Enemy","B":"Quraish","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Hunayn was fought against the Bedouin tribe .Date 630 (8 AH)Location Hunain, near al-Ta''if in south-western ArabiaResult Muslim victory', 0, 0, 0, 1790964558087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c0aaafc49bbb1f4f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Battle of Khyber was fought against?', '{"A":"Muslime Kazab","B":"Yemeni tribes","C":"Quresh","D":"Jewish Tribe","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The battle of Khyber was fought against the Jewish tribeIt was fought between Muslims and the Jews living in the oasis of Khaybar,It was fought on 7 Hijri93 Jews were killed 15 Muslims got martyrdom 3 caliphs were martyred due to the lake of waterThe Battle of Khaybar Result: Muslim victory', 0, 0, 0, 1790964558087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1074dc963ac6d5a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'The Colour of the Flag of the Islamic Army in Ghazwa Badr was____?', '{"A":"Pink","B":"Yellow","C":"Green","D":"None","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Colour of the Flag of the Islamic Army in Ghazwa Badr was Green, and Mslims Win.', 0, 0, 0, 1790964558154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3a2fdac8b5441bb8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', '____________,was The Oldest In Age and was in the Front Line in Battle of Badr ?', '{"A":"HAZRAT USMAN R.A","B":"HAZRAT UBAIDA R.A","C":"HAZRAT ABBAS R.A","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Ubaidah ibn al-Jarrah, was one of the Companions of the Islamic prophet Muhammad.Known for being one of the "Ten Promised Paradise". He remained commander of a large section of the Rashidun Army during the time of the Rashid Caliph Umar and was on the list of Umar''s appointed successors to the Rashidun Caliphate.', 0, 0, 0, 1790964558154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_37ea3fd0cf60644c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Abdul Mutalib died in ___ A.D.', '{"A":"579","B":"578","C":"577","D":"600"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abd al-Muttalib Shaybah ibn Hashim was the grandfather of Muhammad.Hazrat Abdullah was Father of Hazrat Muhammad SAAWAbd al-Muttalib was Born 497Abd al-Muttalib Died 578For 2 years Abdul Matlab took care of Prophet After the death of his mother.Place of burial: Jannat Al Muallaa Cemetery, Mecca, Saudi ArabiaND5-2-2023', 0, 0, 0, 1790964558154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9ca813ab50d02872', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'How many Muhajar in Ghazwa e Badr', '{"A":"1000","B":"82-85","C":"231","D":"61"}', 'B', NULL, 0, 0, 0, 1790964558154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_38f25622addb146d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Who raised the flag in Ghazwa for the first time?', '{"A":"Hazrat Umar (رضہ)","B":"Hazrat abu Salman (رضہ)","C":"Hazrat Hamza (رضہ)","D":"Hazrat Saad bin Maaz (رضہ)","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ḥamzah ibn ʿAbd al-Muṭṭalib was a foster brother, and paternal uncle of the prophet Muhammadﷺ. He was killed in the Battle of Uhud on 22 March 625 (3 Shawwal 3 hijri).', 0, 0, 0, 1790964558154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ca0daf44a801f959', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Name the first prescriber of wahi in Makkah?', '{"A":"Sharjeel-ibn-Hasana Kandi","B":"Hazrat Usman (R.A.)","C":"Hazrat Abu Bakar (R.A.)","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abū ʿAbd Allāh Shuraḥbīl ibn Ḥasana was an early Muslim convert, sahaba and a key commander in the Rashidun army.-----Name the first prescriber of wahi in Makkah.Sharjeel-ibn-Hasana Kandi***Who was the first writer of “Wahi” in Quraish?Hazrat Zaid bin Sabit (RA)', 0, 0, 0, 1790964558154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0a4425f7c063e1b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_battles', 'Name the battle in which Holy Prophet awarded a sword namely "Zulfiqar" to Hazrat Ali?', '{"A":"Hunain","B":"Uhad","C":"Khandaq","D":"Khyber"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Zulfiqar was one of the 7th or 9th swords of the Prophet. He came into its possession either by taking it from a conquered enemy at the battle of Badr.The Holy Prophet (PBUH) awarded a sword namely "Zulfiqar" to Hazrat Ali in the battle of Uhad.ND5-07-2023', 0, 0, 0, 1790964558154) ON CONFLICT(id) DO NOTHING;
