INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_60733e10c6c52e34', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'How many days did Holy Prophet''s PBUH spend at Abu Ansari (A.S) house?', '{"A":"Seven month","B":"Eight-month","C":"Nine month","D":"Ten month"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Host: Hazrat Abu Ayyub al-Ansari (RA)Duration: Approximately 7 months (about 210 days)After: Hijrah to MadinahUntil: Completion of Masjid an-Nabawi ﷺ and adjoining roomsAdditional information:Abu Ayyub al-Ansari (RA)Real Name: Khalid bin Zayd (RA)Tribe: Banu Khazraj, Banu Najjar', 0, 0, 0, 1790964558305) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dacf13dc50745450', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who was given the title of "Speaker of the Prophets" (Khatib-ul-Anbiya)?', '{"A":"Hazrat Hood (A.S)","B":"Hazrat Shoaib (A.S)","C":"Hazrat Zakariya (A.S)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Hazrat Shoaib (A.S)Title: Khatib-ul-Anbiya (Speaker of the Prophets) due to his powerful speech and preaching style.Nation: People of Madyan and AykahMain message: Truthfulness, fair business, worship of AllahRelationship: Father-in-law of Hazrat Musa (A.S)Last verified on 11-06-2026', 0, 0, 0, 1790964558305) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_89844cf5dfb5e099', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Holy Prophet Muhammad (PBUH) belongs to the tribe ______?', '{"A":"Banu Hashim (Quresh)","B":"Banu Ummaya","C":"Banu Asad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad (PBUH) was born in 570 A.D. in Mecca.He belonged to the Banu Hashim clan of the Quraish tribe, the most powerful tribe in Mecca at that time.His great-grandfather was Hashim ibn Abd Manaf, after whom the clan is named.Last verified on 09-02-2026', 0, 0, 0, 1790964558305) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_38ec8091f5e66a9b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Name the wife of Prophet Muhammad (PBUH) who was daughter of Umar Farooq (R.A)?', '{"A":"Hazrat Hafsah (رضہ)","B":"Hazrat  Juwairyyah (رضہ)","C":"Hazrat  Aisha (رضہ)","D":"Hazrat  Maimoonah (رضہ)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Umm al-Mu''minin Hafsah, daughter of Umar (رضي الله عنه).She was the wife of Prophet Muhammad ﷺ.She was the first woman known as a "Hafiz e Quran."Her marriage to the Prophet ﷺ took place in 3 A.H.She was born in 605 AD in Mecca.She was passed away in 665 AD in Medina.Last verified on 30-03-2026', 0, 0, 0, 1790964558305) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d001fd3b534d324c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'How many signs of a hypocrite (Munafiq) did Prophet Muhammad (SAW) mention?', '{"A":"Two","B":"Three","C":"One","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad ﷺ mentioned three signs of a hypocrite (Munafiq) in Sahih al-Bukhari and Sahih Muslim.These signs help identify someone whose faith does not match actions.Lying – speaks falsehood even in ordinary mattersBreaking promises – does not keep commitmentsBetraying trust – dishonest in trusts or responsibilitiesLast verified on 19-03-2026', 0, 0, 0, 1790964558305) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0616605416d1bf65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which companion of Prophet (PBUH) was awarded with the title of Saifullah (Sword of Allah)?', '{"A":"Hazrat Umar R.A","B":"Hazrat Ali R.A","C":"Khalid bin Waleed R.A","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Khalid bin Waleed (R.A) was given the title “Saifullah” (Sword of Allah).Given by: Holy Prophet Muhammad (PBUH)Born: 592 AD (Makkah)Died: 642 AD (Homs, Syria)Served under: Prophet Muhammad (PBUH), Abu Bakr (R.A), Umar (R.A)Last verified on 10-06-2026', 0, 0, 0, 1790964558305) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_706e0f6edced24ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who tried to poison the Holy Prophet Muhammad (ﷺ)?', '{"A":"Hind bint Utba","B":"Zaynab bint Al-Harith","C":"Umm Jamil","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zaynab bint al-Harith tried to poison the Holy Prophet Muhammad (ﷺ)She was a Jewish woman from KhaybarThe Event: The attempt happened after the Battle of KhaybarYear: 7 A.H. (628 AD)Poison Used In: Roasted lamb (shoulder)Companion Martyred: Hazrat Bishr ibn al-Bara'' (RA)Last updated NS on 13-09-2026', 0, 0, 0, 1790964558305) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_adfcd0c5e58a5363', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'In which month did Prophet Muhammad (PBUH) die?', '{"A":"Ramadan","B":"Rabi al-Awwal","C":"Rabi al-Thani","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad (PBUH) passed away in Rabi al-AwwalDate: 12 Rabi al-Awwal (commonly observed)Place: MadinahYear: 11 AHAdditional information:Born: 570 CEBirth Month: Rabi al-AwwalBirthplace: MakkahFather: AbdullahMother: Amina (رضی اللہ عنہا)Grandfather: Abdul MuttalibFirst Revelation: Cave of HiraProphethood: Age 40Migration (Hijrah): 622 CE', 0, 0, 0, 1790964558305) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b8e17602198499ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Injeel was revealed on which Prophet by Allah?', '{"A":"Hazrat Moosa","B":"Hazrat Ibrahim","C":"Hazrat Isa","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Injeel is the holy book revealed by Allah to Hazrat Isa (A.S).Meaning: “Good News”; also called Gospel (means Truth)It was revealed in Hebrew.Additional information:Tawrat: Revealed to Hazrat Musa (A.S)Zabur: Revealed to Hazrat Dawud (A.S)Quran: Revealed to Prophet Muhammad (PBUH)Last verified on 14-03-2026', 0, 0, 0, 1790964558378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a54c57b40f22b6e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'To which country did Prophet Muhammad (PBUH) have his first business trip?', '{"A":"Taif","B":"Syria","C":"Ethiopia","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Prophet''s first business trip was to Syria.He was 12 years oldTraveled with his uncle, Abu Talib (RA).On this journey, he met a monk named Bahira in Basra, Syria.Last updated NA on 10-09-2026', 0, 0, 0, 1790964558378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b2d36a7cebff822c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The number of Ghazwat in which the Holy Prophet (SAW) took part?', '{"A":"25","B":"26","C":"27","D":"28"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad personally participated in 27 to 29 total military GhazwatThe battles led by the Holy Prophet (PBUH) are called Ghazwas.Holy Prophet (PBUH) personally participated in about 9 of themBadr (fought three times)UhudBani MustalaqKhandaqBani QuraizhahKhayberFathu MakkahHunain TaifLast updated question NS on 10-09-2026', 0, 0, 0, 1790964558378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_23274dcb8a2fcd59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Umm-ul-Masakeen (Mother of the Poor) was the title given to one of the wives of the Prophet (SAW)?', '{"A":"Harat Sauda (RA)","B":"Hazrat Zainab benet Jehash (RA)","C":"Hazrat Zainab benet Khuzima (RA)","D":"Hazrat Safia (RA)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Zainab bint Khuzaymah (RA) was given the title Umm-ul-Masakeen (Mother of the Poor).Because of her generosity and care for the needy.Husband: Prophet Muhammad (ﷺ)Marriage: Approximately 3 monthsDeath: 4 AH / 625 CE, approximately 30 years of ageBurial: Jannat al-Baqi, MadinahLast verified on 09-09-2026', 0, 0, 0, 1790964558378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5aab57fa784eacee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Where is the grave of Hazrat Ibrahim (A.S)?', '{"A":"Israel","B":"Palestine","C":"Syria","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The grave of Hazrat Ibrahim (A.S) is located in the city of Hebron.This place is historically known as Al-Khalil.It lies in present-day Palestine (West Bank).The site is inside the famous Ibrahimi Mosque (Cave of the Patriarchs).Last verified on 23-04-2026', 0, 0, 0, 1790964558378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_594da308a3a43332', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Pick out the name of Sahabi who supplied food to the Holy Prophet (PBUH) for three years in the Shoab-e-Abi Talib?', '{"A":"Hakim ibn Hizam","B":"Hazrat Ali (RA)","C":"Hazrat Umar (RA)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sahabi who secretly supplied food to the Holy Prophet (PBUH) during the boycott was Hakim ibn Hizam.He was the nephew of Hazrat Khadija (RA).Boycott period: 619–622 AD (3 years).Location: Valley of Abi Talib (Makkah).Last verified on 02-06-2026', 0, 0, 0, 1790964558378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e45d2bd1a1cb511b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which companion of Prophet Muhammad (PBUH) is known as "As-Siddiq (The Truthful)"?', '{"A":"Hazrat Uthman (R.A)","B":"Hazrat Ali (RA)","C":"Hazrat Abu Bakr (RA)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Bakr (R.A)Title: As-Siddiq (The Truthful) and Atiq (The Freed One)Companion of: Muhammad (PBUH)Status: First Caliph of IslamKnown For: Faith, honesty, and loyaltyLast verified on 17-05-2026', 0, 0, 0, 1790964558378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_784ea777885b0591', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What was the relation between Prophet Ismail (A.S) and Prophet Ishaq (A.S)?', '{"A":"Brothers","B":"Cousins","C":"Prophet Ishaq (A.S) was father of Prophet Ismail (A.S)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Ismail (A.S) and Prophet Ishaq (A.S) are Brothers.Hazrat Sara (RA) was the mother of Hazrat Ishaq (RA).Hazrat Hajra was the mother of Hazrat Ismail (A.S).Hazrat Ibrahim (AS) was the father of Prophet Ismail (A.S) and Prophet Ishaq (A.S).Last verified on 30-03-2026', 0, 0, 0, 1790964558378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3df9d8c3a173b435', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Where did Prophet Muhammad (PBUH) delivered his last sermon?', '{"A":"Arafat","B":"Mecca","C":"Madina","D":"Mina"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Prophet (PBUH) delivered his final sermon during the Hajj on Mount Arafat.It is also known as Farewell Sermon.The Holy Prophet (SAW) performed Hajjat-ul-Wida in the 10th Hijri.It was performed on Friday, the 9th of Dhu al-Hijjah (March 6, 632 A.D).This final pilgrimage included his renowned Farewell Sermon.Last verified on 11-06-2026', 0, 0, 0, 1790964558463) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_585e6f844d28dd43', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The first revelation on the holy prophet (PBUH) happened at which place?', '{"A":"Cave Toor","B":"Cave Hira","C":"Madina Cave","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Location of the first wahi: Cave Hira (Ghar-e-Hira), MakkahNumber of verses: 5Surah: Al-Alaq (96th Surah)Angel: Jibril (A.S.)First Word Revealed: Iqra (Read)In: 610 ADAdditional information:At the Age of 40 years 6 monthsPrescriber of wahi in Makkah: Sharjeel-ibn-Hasana KandiFirst writer of Wahi in Quraish: Hazrat Zaid bin Sabit (RA)Last verified on 27-04-2026', 0, 0, 0, 1790964558463) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_311bee6256a6cbc8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Zaboor was revealed on which Prophet?', '{"A":"Hazrat Mossa (a.s)","B":"Hazrat Issa (a.s)","C":"Hazrat Dawood (a.s)","D":"Hazrat Muhammad (a.s)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zaboor (Psalms) was revealed to Hazrat Dawood (AS).Zaboor was revealed in the Syriac language.Zaboor mainly contains praises of Allah, supplications, and guidance.Additional information:Tawrat (Torah) → Hazrat Moosa (AS)Injeel (Gospel) → Hazrat Isa (AS)Holy Qur''an → Prophet Muhammad (ﷺ)Last verified on 22-07-2026', 0, 0, 0, 1790964558463) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a84ce2d481436f73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Name the uncle of Prophet Muhammad (PBUH) who was also his foster brother?', '{"A":"Hazrat Hamza (RA)","B":"Hazrat Ali (RA)","C":"Hazrat Saad bin Muadh (RA)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Hamza ibn Abdul MuttalibRelationship: Uncle + Foster brotherFoster mother: Suwaiba (RA)Title: Asadullah (Lion of Allah)Martyrdom: Battle of Uhud (625 CE)Additional information:There are 3 foster mothers of the Holy Prophet SAW:Hazrat Halema Saadia (RA)Hazrat Khola (RA)Hazrat Suwaiba (RA)Hazrat Haris was the foster father of Hazrat Muhammad SAW.Last verified on 11-06-2026', 0, 0, 0, 1790964558463) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1c1c33cee60c0bbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'When did the Holy Prophet (PBUH) migrate to Madina after declaration of Prophethood?', '{"A":"12th Year","B":"13th Year","C":"10th Year","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet (PBUH) migrated from Mecca to Medina in 622 CE, It was in the 13th year of his Prophethood. This marks the beginning of the Islamic calendar.This event, known as the Hijra.Last updated by NA on 25- April-2026', 0, 0, 0, 1790964558463) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8f0de756a6c4c437', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who was the father of Hazrat Ishaq (AS)?', '{"A":"Hazrat Noah (AS)","B":"Hazrat Ibrahim (AS)","C":"Hazrat Essa (AS)","D":"Hazrat Lut (AS)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ishaq (AS) was the son of Hazrat Ibrahim (AS).Hazrat Ishaq (AS) was born to Hazrat Sarah (RA), the wife of Hazrat Ibrahim (AS).Hazrat Ishaq (AS) was a Prophet of Allah.He was an ancestor of many Prophets of Bani Israel.Hazrat Yaqub (AS) was the son of Hazrat Ishaq (AS).Last verified on 22-07-2026', 0, 0, 0, 1790964558463) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3e2e4ea31031a13a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Kaleemullah (One who spoke to Allah) was the title of which Prophet?', '{"A":"Hazrat Ibrahim A.S","B":"Hazrat Musa A.S","C":"Hazrat Dawood A.S","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Title: Kaleemullah (One who spoke to Allah)Prophet: Hazrat Musa (A.S)Holy Book: TawratPlace of Revelation: Mount Sinai (Toor)Nation: Bani IsraelLast verified on 17-05-2026', 0, 0, 0, 1790964558463) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5909056f8999bda5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'How many wives were alive at the time of the Prophet Muhammad''s (ﷺ) death?', '{"A":"5","B":"7","C":"9","D":"10"}', 'C', NULL, 0, 0, 0, 1790964558463) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_64897ce2bf5edacc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What was the age of the Holy Prophet Muhammad (ﷺ) bestowed with Prophethood / when he received the first Wahi (Revelation)?', '{"A":"35 years 6 months","B":"40 years 6 months","C":"42 years 6 months","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet Muhammad (ﷺ) received the first Wahi (Revelation) at the age of 40 years 6 months.Number of verses: 5Surah: Al-Alaq (96th Surah)Location of the first wahi: Cave Hira (Ghar-e-Hira), MakkahAngel: Jibril (A.S.)First Word Revealed: Iqra (Read)In: 610 ADAdditional information:Prescriber of wahi in Makkah: Sharjeel-ibn-Hasana KandiFirst writer of Wahi in Quraish: Hazrat Zaid bin Sabit (RA)Last verified on 27-04-2026', 0, 0, 0, 1790964558546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5eabf84625af5341', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'After Hijrat (migration) from Mecca to Madina, the Holy Prophet Muhammad’s (PBUH) camel kneeled at the door of?', '{"A":"Hazrat Amaar Yasir","B":"Hazrat Jaffar","C":"Hazrat Ayub Ansari","D":"Hazrat Jabbar Ansari"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After the Hijrah (622 AD), the Prophet''s (ﷺ) camel knelt near the house of Hazrat Abu Ayub Ansari (RA).He hosted the Holy Prophet (ﷺ) for about 7 months.He hosted the Prophet SAW until Masjid-e-Nabawi and the Prophet''s rooms were completed.His original name was Khalid bin Zayd of the Banu Najjar tribe.Last verified on 21-07-2026', 0, 0, 0, 1790964558546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0ea14d45a344a8ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The nation of which Prophet was exterminated through the scourge of floods?', '{"A":"Hazrat Nooh (A.S)","B":"Hazrat Yaqoob (A.S)","C":"Hazrat Dawood (A.S)","D":"Hazrat Uzair (A.S)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The nation of Hazrat Nooh (A.S) was exterminated through the scourge of floods (Toofan-e-Noah).The flood was a divine punishment due to their disbelief and corruption.Hazrat Nooh (A.S) built an Ark and was saved along with his followers.The flood event is mentioned in the Holy Quran in Surah Hud and Surah Al-Mu’minun.Additional information:Title: Shaikh-ul-Ambiya, Naji Ullah, Abu-ul-Bashar SaniLifespan: 950 years (mentioned in Quran, Surah Al-Ankabut 29:14)Last verified on 21-07-2026', 0, 0, 0, 1790964558546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f14c80325d8c6456', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which companion of the Holy Prophet Muhammad ﷺ is entitled as Syed-ul-Shuhada (Leader of the Martyrs)?', '{"A":"Hamza (R.A)","B":"Umar (R.A)","C":"Usman (R.A)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The title ''Sayyid al-Shuhada'' "the Master / Leader of Martyrs", was given to Hamza ibn ''Abd al-Muttalib.He was the uncle of the Holy Prophet (PBUH).He was martyred and mutilated in the Battle of Uhud. He was killed by Wahshi Ibn-e-Harb, a slave of Hind bint Utba.Last verified on 25-04-2026', 0, 0, 0, 1790964558546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cef18199e62c4ca3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which was the first mosque built in the history of Islam by the Holy Prophet (PBUH)?', '{"A":"Masjid-ul-Haram","B":"Masjid-e-Quba","C":"Masjid-e-Aqsa","D":"Masjid-e-Nabavi"}', 'B', NULL, 0, 0, 0, 1790964558546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cf0e0ce69e6dbe9f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet(s) gave the glad tidings (Basharat) of the coming of Prophet Muhammad (ﷺ)?', '{"A":"Hazrat Musa (AS)","B":"Hazrat Isa (AS)","C":"Hazrat Sulaiman (AS)","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Both Hazrat Musa (AS) and Hazrat Isa (AS) gave glad tidings (Basharat) of the coming of Prophet Muhammad (ﷺ).Hazrat Musa (AS): Mentioned in the Torah (Deuteronomy 18:18).Hazrat Isa (AS): Mentioned in Surah As-Saff (61:6), giving the glad tidings of Ahmad.Final Prophet: Prophet Muhammad (ﷺ).Title Mentioned: Ahmad.Holy Books: Torah and Injil.Last verified on 19-07-2026', 0, 0, 0, 1790964558546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_98107939f1d7e768', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The original/real name of the host of Holy Prophet Abu Ayub Ansari is _____?', '{"A":"Zaid bin Sabit (R.A)","B":"Qais bin Saad (R.A)","C":"Hanzla bin Aamir (R.A)","D":"Khalid bin Zaid (R.A)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Original Name: Khalid bin Zaid (RA)Famous Name (Kunyah): Abu Ayyub Ansari (RA)Tribe: Banu NajjarHosted the Prophet (ﷺ): 1 AH / 622 CECity: MadinahLast verified on 09-07-2026', 0, 0, 0, 1790964558546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4cfae83c48f95701', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Companion of the Holy Prophet SAW is known "Bāb-ul-Ilm" (The Gate / Gateway of Knowledge)?', '{"A":"Hazrat Usman R.A","B":"Hazrat Umar R.A","C":"Hazrat Ali R.A","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali (RA) is widely known as "Bāb-ul-Ilm" (The Gate of Knowledge).This title is associated with the famous narration: "I am the city of knowledge, and Ali is its gate."He was renowned for his deep knowledge, wisdom, and justice.Additional information:Fourth Caliph: 656–661 AD (35–40 AH)Father: Abu TalibRelation to the Prophet (ﷺ): Cousin and son-in-lawLast verified on 19-07-2026', 0, 0, 0, 1790964558546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_41db5c2bf5b4655b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Bani Israel was the nation of which Prophet (AS), who is also known by the title Israel?', '{"A":"Hazrat Musa (AS)","B":"Hazrat Yaqoob (AS)","C":"Hazrat Yousuf (AS)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bani Israel (Children of Israel) refers to the descendants of Hazrat Yaqub (AS).He was also known by the title "Israel", meaning "Servant of Allah."Father: Hazrat Ishaq (AS)Mother: Rafqa (Rebecca)Number of sons: 12Last verified on 06-07-2026', 0, 0, 0, 1790964558628) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_163494ee1caa278b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who was the first Poet of Islam (Poet of the Prophet (PBUH)?', '{"A":"Hassan bin Sabit","B":"Hazrat Abu Bakar","C":"Hazrat Ali","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Hassan ibn Thabit (RA) was the first Poet of Islam and the Poet of the Prophet (ﷺ).An Arabian poet and companion of the Prophet Muhammad SAW.He was renowned for his poetry defending and promoting Islam.He was born in 563 AD.He was died in 674 AD, aged 110 or 111.Verified & Updated', 0, 0, 0, 1790964558629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_65ad8c09cce6d6d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The first wife of Prophet Muhammad (ﷺ) died in which year of Prophethood (during Ramadan)?', '{"A":"3","B":"8","C":"24","D":"10"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Khadijah (RA) passed away in Ramadan of the 10th year of Prophethood.She died in 619 AD at the age of 65 years.The 10th year of Prophethood is known as the Year of Sorrow (ʿĀm al-Ḥuzn).In the same year, Abu Talib also passed away.Hazrat Khadijah (RA) was the first wife of Prophet Muhammad (ﷺ).She was the first woman to embrace Islam.Last verified on 15-07-2026', 0, 0, 0, 1790964558629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e8ea395468d5ddbd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The place chosen to sacrifice Hazrat Ismail (AS) was ____?', '{"A":"Muzdalfa","B":"Safa","C":"Mina","D":"Meeqat"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Place: Mina, Saudi ArabiaNearby City: MakkahProphet: Hazrat Ibrahim (AS)Son: Hazrat Ismail (AS)Substitute Sacrifice: A ram sent by Allah (SWT)Verified & Updated', 0, 0, 0, 1790964558629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_370908950cb79e3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Holy Prophet PBUH was born in?', '{"A":"571 AD","B":"577 AD","C":"632 AD","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Holy Prophet was born in 571 A.D 22nd April (Day-Monday).Mother: Amina Father: Abdullah Family: QuraishBorn: MakkahDied: 632 ADLast verified on 12-06-2026', 0, 0, 0, 1790964558629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d404dba91c70a3b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet of Allah is dignified with the special title Khalil Ullah (Friend of God)?', '{"A":"Hazrat Adam (AS)","B":"Hazrat Nuh (AS)","C":"Hazrat Ibrahim (AS)","D":"Hazrat Essa (AS)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ibrahim (A.S) is known as Khalil Ullah (Friend of Allah).This honorable title is directly referenced in the Quran (Surah An-Nisa 4:125)He is called the Father of Many Prophets.He was born in Iraq (ancient Mesopotamia).Son: Hazrat Ismail (A.S)Name mentioned in Quran: 67 timesAdditional information:Kalim Ullah → Hazrat Musa (A.S)Ruh Ullah → Hazrat Isa (A.S)Last verified on 13-06-2026', 0, 0, 0, 1790964558629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8438a5a44079aac6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which type of Hadith are the sayings of the Prophet Muhammad (SAW) as revealed to him by the Almighty Allah?', '{"A":"Hadith Qudsi","B":"Hadith Quali","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hadith Qudsi – Meaning from Allah, words narrated by the Prophet (ﷺ)Additional information:Hadith Quali (Qawli) – Sayings of the Prophet (ﷺ)Hadith Fili – Actions of the Prophet (ﷺ)Hadith Taqriri – Approvals/silent consent of the Prophet (ﷺ)Last verified on 14-07-2026', 0, 0, 0, 1790964558629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_128fc47cac30b366', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What was the name of the nation of Hazrat Hud (A.S.)?', '{"A":"Thamud","B":"''Ad (Aad)","C":"Madyan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet: Hazrat Hud (A.S.)Nation: ''Ad (Aad)Place: Al-Ahqaf (Southern Arabia)Sin: Idol worship and arrogancePunishment: A severe windstorm lasting 7 nights and 8 daysLast verified on 13-07-2026', 0, 0, 0, 1790964558629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_89be162822de2a23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Where was Holy Prophet Muhammad (PBUH) born?', '{"A":"Ridyah","B":"Jerusalem","C":"Mecca","D":"Madina"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Holy Prophet Muhammad (PBUH) was born in Makkah (Mecca), Saudi Arabia.His birth took place in 571 AD, known as the Year of the Elephant.He belonged to the Quraysh tribe, specifically the Banu Hashim clan.His father Abdullah died before his birth and his mother was Amina bint Wahb.Last verified on 13-03-2026', 0, 0, 0, 1790964558719) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2b1af196a5637ceb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'For how long did the Prophet Muhammad and his companion remain in the siege in Shi’ab-e-Abi-Talib?', '{"A":"1 year","B":"2 years","C":"3 years","D":"4 years"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Duration: 3 yearsStart: Muharram, 7th year of ProphethoodEnd: 10th year of ProphethoodPlace: Shi''ab-e-Abi Talib (Makkah)Waq wasAffected Tribes: Banu Hashim and Banu Al-MuttalibVerified & Updated', 0, 0, 0, 1790964558719) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_404e4c6d8eafb5f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What was the name of Hazrat Ibrahim''s (AS) father?', '{"A":"Āzar","B":"Harun","C":"Imran","D":"Qasim"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Father: Azhar (Āzar)Mother: MahalathTitle: Khalilullah (Friend of Allah)Mentioned in: Surah Al-An''am, Verse 74Prophet after him: Hazrat Ismail (AS) and Hazrat Ishaq (AS) were his sons.Verified & Updated', 0, 0, 0, 1790964558719) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b196ce086228e6c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'In Holy Torat which name Prophet Muhammad (ﷺ) mentioned?', '{"A":"Tahir","B":"Farooq","C":"Ahmed","D":"Tayyab"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad (ﷺ) is mentioned in the Torah (Torat) by the name "Tayyab".Additional information:Name "Muhammad" in the Holy Qur''an (4 Times):Surah Aal-e-Imran (3:144)Surah Al-Ahzab (33:40)Surah Muhammad (47:2)Surah Al-Fath (48:29)Name mentioned in the Qur''an: AhmadSurah: As-Saff (61:6)Meaning of Ahmad: "The Most Praised"Mentioned in the Qur''an: OnceGlad tidings given by: Prophet Isa (A.S.)Last verified on 11-07-2026', 0, 0, 0, 1790964558719) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c1bbbc41c5b520dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The first Prophet (person) who learnt to write with a pen?', '{"A":"Hazrat Musa (A.S)","B":"Hazrat Ibrahim (A.S)","C":"Hazrat Idrees (A.S)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Idris (A.S) is considered the first person who learned writing.He is also known for knowledge, wisdom, and early civilization development.He is also associated with astronomy and mathematics.Additional information:Total major Prophets (Ulul Azm): 5 (Nuh, Ibrahim, Musa, Isa, Muhammad)Last verified on 27-04-2026', 0, 0, 0, 1790964558719) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ecc96f5edaa66775', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet was swallowed by a whale (fish) and remained in its abdomen?', '{"A":"Hazrat Ibrahim AS","B":"Hazrat Musa AS","C":"Hazrat Younas AS","D":"Hazrat Dawood AS"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Younas (AS) was swallowed by a giant fish (whale) and remained in its abdomen for about 40 days.He prayed to Allah while inside the fish, and Allah accepted his repentance.He is also known as Dhun-Nun (ذوالنون), meaning "the man of the fish."His story teaches patience, repentance, and trust in Allah.Last verified on 07-07-2026', 0, 0, 0, 1790964558719) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_90889c9aa7dd4932', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What is the name of the camel which the Holy Prophet (SAW) was riding in the migration of Madina?', '{"A":"Buldul","B":"Anza","C":"Qaswa","D":"Zulifqar"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qaswa was the name of the camel on which Prophet Muhammad (ﷺ) migrated to Madina.After reaching Madina, Qaswa stopped at the place where Al-Masjid an-Nabawi was later built.The Hijrah took place in 622 AD.The Prophet (ﷺ) also had other well-known she-camels, including Al-Jad''aa and Al-Adbaa.Last verified on 07-07-2026', 0, 0, 0, 1790964558719) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_052aa26ada711f13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet is called Abu-ul-Ambiya (Father of Prophets)?', '{"A":"Hazrat Adam (A.S)","B":"Hazrat Abraheem (A.S)","C":"Hazrat Nooh (A.S)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abraham (A.S) is called Abu-ul-Ambiya / Jadd-ul-Anbiya (Father of Prophets).His name is mentioned in the Qur’an 67 times.He was sent to Jordan / Sham region after leaving Hazrat Hajar (A.S) and Hazrat Ismail (A.S) in Makkah valley (Bakkah).He had two wives: Hajar and Sarah.He had two famous sons: Ishmael (A.S) and Isaac (A.S).He is known as Khalilullah (Friend of Allah).He built the Kaaba with Hazrat Ismail (A.S).Last verified on 28-04-2026', 0, 0, 0, 1790964558719) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4f7b073bf6bf951d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Hazrat Isa (AS) was sent to preach the message of Allah to the people of ____?', '{"A":"Islam","B":"Whole World","C":"Israel","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Isa (AS) was sent by Allah to the Children of Israel (Bani Israel).Allah revealed the Injeel (Gospel) to Hazrat Isa (AS).He is one of the five greatest Messengers (Ulul Azm) in Islam.He was born miraculously without a father by the command of Allah.Mother: Maryam ASMention in the Quran: 25 timesLast verified on 06-07-2026', 0, 0, 0, 1790964558804) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_66a8d75240684e07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Age of Hazrat Adam (A.S) at Sheesh’s (A.S) birth was ______ years.', '{"A":"160","B":"130","C":"100","D":"190"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Adam (AS) was 130 years old when Hazrat Sheesh (AS) was born.Hazrat Adam (AS) was the first human being and the first Prophet of Allah.According to Islam, all Prophets preached the religion of Islam.Hazrat Sheesh (AS) was blessed after the death of Habil (Abel).Last verified on 02-07-2026', 0, 0, 0, 1790964558804) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_52bab2142d07d8b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which prophet died while standing with the support of a stick?', '{"A":"Hazrat Haroon A.S","B":"Hazrat Musa A.S","C":"Hazrat Suleman A.S","D":"Hazrat Essa A.S"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Sulaiman (AS) passed away while standing, supported by his staff (stick).Allah concealed his death until a termite ate through the staff, causing him to fall.This event is mentioned in the Quran (Surah Saba, 34:14).It showed that the jinn did not possess knowledge of the unseen (Ghayb).Hazrat Sulaiman (AS) was both a Prophet and a King of Bani Israel.Last verified on 06-07-2026', 0, 0, 0, 1790964558804) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_36adc8f9b7bdc763', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Biography Of Holy Prophet (SAW) entitled “Sirat Rasul Ullah (Life of the Messenger of God)” was written by?', '{"A":"Ibn-e-Ishaq","B":"Ibn-e-Hisham","C":"Ibn-e-Khaldun","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Author: Ibn IshaqTitle: Sirat Rasul Ullah (Life of the Messenger of God)Written: 767 CE (150 AH)Original manuscript: LostPreserved by: Ibn Hisham and Muhammad ibn Jarir al-TabariLast verified on 03-07-2026', 0, 0, 0, 1790964558804) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d32a380b0b156ca1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'When did the lady named Zainab poisoned Holy Prophetﷺ?', '{"A":"Ghazw-e-Uhd","B":"Conquest of Khyber","C":"Conquest of Makkah","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Incident: Poisoning after the Conquest of KhyberYear: 7 AH (628 AD)Place: KhyberWoman''s name: Zainab bint Al-HarithFood used: Poisoned roasted sheep (lamb)Last verified on 03-07-2026', 0, 0, 0, 1790964558804) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bb9969cf649d2f9b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Holy Prophet (SAW) was died on ______?', '{"A":"15th June 632 AD","B":"18th June 632 AD","C":"8th June 632 AD","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Holy Prophet Muhammad (ﷺ) passed away on Monday, 8 June 632 CE (12 Rabiʿ al-Awwal, 11 AH).He was buried in the room of Hazrat Aisha (RA), which is now part of Al-Masjid an-Nabawi.The Prophet (ﷺ) was died at the age of 63 years.Additional information:Birth: 12 Rabiʿ al-Awwal, 571 CEMother (Hazrat Amina RA) passed away: When he was 6 years oldGrandfather (Abdul Muttalib) passed away: When he was 8 years oldMigration (Hijrah) to Madinah: 622 CELast verified on 03-07-2026', 0, 0, 0, 1790964558804) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a79c70c6ccf0ca5d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet was thrown into fire by his own people but did not burn?', '{"A":"Hazrat Ibrahim (AS)","B":"Hazrat Yousaf (AS)","C":"Hazrat Nooh (AS)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet: Hazrat Ibrahim (AS)King: Nimrod (Namrud)Kingdom: BabylonMiracle: Allah made the fire cool and safe for Hazrat Ibrahim (AS).Quran Mention: The name Ibrahim appears 69 times in the Holy Quran.Last verified on 02-07-2026', 0, 0, 0, 1790964558804) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d4fc690cbce45f25', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who is the only sahabi without seeing the Holy Prophet (PBUH)?', '{"A":"Abdullah ibn Umar (RA)","B":"Salman Farsi (RA)","C":"Awais Qarni (RA)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Awais Karni (RA) in the history of Islam only sahabi without seeing Holy Prophet (ﷺ).He was born in Asir region of Saudi Arabia in 594 CE.He was 28 years of age when the Holy Prophet (ﷺ) migrated to Madinah.Last verified on 01-07-2026', 0, 0, 0, 1790964558804) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a099c6444a4e211f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Prophet Muhammad (PBUH) had _____ Daughters.', '{"A":"1","B":"4","C":"2","D":"3"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Holy Prophet SAW had Four Daughters from Hazrat Khadija.Hazrat Zainab (married to Abual Bin Aas Bin Rabbi)Hazrat Ruqayah (married to Hazrat Usman bin Affan)Hazrat Umme Kalsoom (married with Hazrat Usman bin Affan after the death of Hazrat Ruqayah)Hazrat Fatima (married to Hazrat Ali)Additional information:Prophet Muhammad ﷺ had three sons:Hazrat QasimHazrat AbdullahHazrat IbrahimHazrat Qasim (RA) and Hazrat Abdullah (RA) were born to Hazrat Khadijah (RA).Hazrat Ibrahim (RA) was born to Hazrat Maria al-Qibtiyah (RA).Last verified on 26-06-2026', 0, 0, 0, 1790964558882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c12bf436de9ca803', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The action or saying in the front of Holy Prophet Mohammad (SAW) on which Holy Prophet Mohammad (SAW) kept silence is called?', '{"A":"Hadith Taqreeri","B":"Hadith Failee","C":"Hadith Qawle","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Taqreer refers to the silent approval or consent of Prophet Muhammad (SAW).Taqreer means the Prophet (SAW) saw or knew an action and did not object to it.There are three Types of Ahadith:Qaul (قول) → Saying of Prophet (SAW)Fe’l (عمل) → Actions of Prophet (SAW)Taqreer (تقرير) → Silent approval of Prophet (SAW)Last verified on 25-06-2026', 0, 0, 0, 1790964558882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d35216564c1a571b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'After the death of Hazrat Khadija, Prophet Muhammad (SAW) married?', '{"A":"Sawdah bint Zam''ah (RA)","B":"Hazrat Asma (RA)","C":"Hazrat Aisha (RA)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First marriage after Khadija (RA): Hazrat Sawdah bint Zam’ah (RA)Year: After 619 AD (Year of Sorrow)Place: MakkahStatus: Widow of Sakran ibn AmrKnown for: Simple life and devotionLast verified on 23-06-2026', 0, 0, 0, 1790964558882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a3557b1c944c5121', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Hazrat Sulaiman (AS) founded the following mosque?', '{"A":"Al-Aqsa","B":"Al-Kartaba","C":"Blue Mosque","D":"Masjid Hanifia"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Sulaiman is associated with the construction and expansion of Al-Aqsa Mosque.Al-Aqsa Mosque is one of the holiest sites in Islam after Masjid al-Haram.It is located in Jerusalem (Bait-ul-Maqdis).It is believed that many prophets prayed in this sacred place.He was the son of Hazrat Dawood (A.S).He was gifted with the ability to communicate with animals and control Jinns.Last verified on 26-04-2026', 0, 0, 0, 1790964558882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_718dcb1bf0fb2794', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Nation of which Prophet committed embezzlement in trusts?', '{"A":"Hazrat Shoaib A.S","B":"Hazrat Musa A.S","C":"Hazrat Haroon A.S","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The nation of Hazrat Shoaib (A.S.) was known for dishonesty in trade, cheating in measurements, and breach of trust.He was sent to the people of Madyan (Midian).Also known as: Jethro in the BibleMentioned in the Quran: 11 timesLast verified on 11-06-2026', 0, 0, 0, 1790964558882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1de789289820bb22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Where Hazrat Ibrahim (A.S) was born?', '{"A":"Palestine","B":"Saudi Arabia","C":"Iran","D":"Iraq"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abraham (A.S) was born in Iraq (Babylon region).He lived during the time of King Namrud.He was thrown into fire on Namrud’s order, but Allah saved him.He is called Khalilullah (Friend of Allah).His name is mentioned 67 times in the Qur’an.Last verified on 28-04-2026', 0, 0, 0, 1790964558882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1cb13cb80d206e2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The last War fought against non-believers in era of Prophet (PBUH) was?', '{"A":"Ghazwa Hunain","B":"Ghazwa Khyber","C":"Ghazwa Tabuk","D":"Ghazwa Taif"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The last expedition against non-believers during the time of Prophet Muhammad (PBUH) was Ghazwa-e-Tabook.Year: 630 AD / 9 AH (Rajab)Location: Tabook (northwest Arabia)Muslim army: around 30,000 soldiersType: Ghazwa (Prophet PBUH participated)Outcome: No direct battle (bloodless)Also known as: Expedition of UsraReason: Rumors of Byzantine attackAdditional information:“Ghazwa” = battle in which Prophet Muhammad (PBUH) participatedFirst Ghazwa = Ghazwat-ul-Abwa (Waddan)Last verified on 16-03-2026', 0, 0, 0, 1790964558882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5718ee32732d188c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Boat of Hazrat Noah (A.S) is called _____?', '{"A":"Arrow","B":"Ark","C":"Arrec","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790964558882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_afd3913be312bd58', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Najeebullah is the title of which Prophet?', '{"A":"Hazrat Moosa","B":"Hazrat Ibrahim","C":"Hazrat Dawood","D":"Hazrat Younis"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Najibullah is the title of Hazrat Dawood (AS).The holy book Zaboor revealed to Hazrat Dawood (AS).He is buried in Israel.He is called caliph of Allah.He is mentioned in the Holy Quran for 16 times.Last verified on 23-04-2026', 0, 0, 0, 1790964558955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8969e1b248cefc9f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'By how many brothers was Hazrat Yusuf (A.S.) thrown into the well?', '{"A":"10","B":"11","C":"12","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Yusuf (A.S.) was thrown into the well by 10 of his brothers.He had a total of 11 brothers, but the youngest, Binyamin, was not involved.The act was driven by jealousy due to their father’s love for Yusuf (A.S.).Last verified on 11-06-2026', 0, 0, 0, 1790964558955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fbd37c66f83231d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Rooh Ullah is a title of which Prophet?', '{"A":"Hazrat Musa","B":"Hazrat Isa","C":"Hazrat Ibrahim","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Roohullah is the title of Prophet Isa (A.S.)The meaning of Roohullah is ''Spirit of Allah.Isa is called Rooh Ullah 11 times in the Quran. Isa (A.S. is mentioned 78 times in the QuranAdditional informationIt signifies his miraculous creation without a father. Isa (A.S.)and his mother, Maryam, were the only two people whom Shaitan did not touchHe is called a pure boy ( 9 times in the Quran)He is called kalima (word) or Kalimat Allah (word of God) six times in the Quran.Last updated by NA on 27 April 2026', 0, 0, 0, 1790964558955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_196ea281a06c8367', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet cured the victims of leprosy as a miracle?', '{"A":"Hazrat Yahya (A.S)","B":"Hazrat Issa (A.S)","C":"Hazrat Idrees (A.S)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Isa (A.S) was given miracles related to healing.He cured lepers and blind people by Allah’s permission.These miracles proved his prophethood to the people.Last verified on 16-05-2026', 0, 0, 0, 1790964558955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_99cfbac33a5923c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The actions, sayings, and messages of Prophet Muhammad (PBUH) during his lifetime are known as _____?', '{"A":"Hadith","B":"Tafsir","C":"Fiqh","D":"Sharia"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hadith Meaning: Saying, action, approval of Prophet (PBUH)Sources: Prophet Muhammad (PBUH)Narrators: Sahaba (companions)Purpose: Guidance for MuslimsRelation to Quran: Explains and supports Quranic teachingsLast verified on 16-05-2026', 0, 0, 0, 1790964558955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6cd4569a2e912398', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Holy Prophet SAW was a direct descendant of ____?', '{"A":"Hazrat Da’ood (AS)","B":"Hazrat Eesaa (AS)","C":"Hazrat lsmaeel (AS)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad (PBUH) belongs to the noble lineage of Prophet Ismail (A.S).Prophet Ismail (A.S) was the son of Prophet Ibrahim (A.S).The lineage continued in the Arab tribe of Quraysh.Prophet Muhammad (PBUH) is from the Banu Hashim clan.Last verified on 16-05-2026', 0, 0, 0, 1790964558955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7c73f476d052edb4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'On of the following mosques was demolished on the order of the Holy Prophet (PBUH)?', '{"A":"Masjid e Nabvi","B":"Masjid e Harmain","C":"Masjid e Zarar","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid-e-Zarar was a mosque built by hypocrites in Madinah.It was used to create division among Muslims and harm Islam.Allah informed Prophet Muhammad (PBUH) about its true purpose.The Prophet (PBUH) ordered its demolition after the Battle of Tabuk.It is mentioned in Surah At-Tawbah in the Holy Quran.Last verified on 16-05-2026', 0, 0, 0, 1790964558955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ca72843fff7fdff8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which prophet of Allah is called Abu Al-Bashar?', '{"A":"Hazrat Muhammad ﷺ","B":"Hazrat Ibrahim (AH)","C":"Hazrat Nooh (AH)","D":"Hazrat Adam (AH)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Title: Abu Al-Bashar (Father of Mankind)Prophet: Hazrat Adam (A.S)Wife: Hawwa (Eve)Status: First human being and first prophetReligion: Islam (submission to Allah)Last verified on 16-05-2026', 0, 0, 0, 1790964558955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c169b762e4a2ece1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who is named as Shaikh-ul-Anbia?', '{"A":"Hazrat Musa (عليهم السلام)","B":"Hazrat Essa (عليهم السلام)","C":"Hazrat Noah (عليهم السلام)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Noah (A.S) is called Shaikh-ul-Anbia (Elder of the Prophets).Because of his long life and great patience in preaching Islam.He preached to his people for about 950 years as mentioned in the Quran.He was sent to the people of Iraq to guide them toward worship of Allah.His famous titles include:Naji UllahAbu ul Bashr Sani (Second Father of Humanity)Last verified on 09-05-2026', 0, 0, 0, 1790964559030) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a9f9644d13ac0a59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'At what age of the Holy Prophet (PBUH) Hajr-e-Aswad incident occurred?', '{"A":"25","B":"40","C":"32","D":"35","E":"53"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet (SAW) was 35 when he solved the conflict of placing the Hajj-e-Aswad.Resolved a severe dispute among the Quraysh tribesHe wisely placed the stone on a cloth, had all tribal leaders lift it, and then placed it himself.Black is the color of Hijra e AswadAswad means کالا یا سیاہ رنگ کا Last updated question by NA on 07 May 2026', 0, 0, 0, 1790964559030) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f77aa50b3624aa21', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Hazrat Sara (RA) the wife of Hazrat Ibrahim (AS) and the mother of Hazrat Ishaq (AS) and the sister of Prophet ____?', '{"A":"Hazrat Loot A.S","B":"Hazrat Saleh A.S","C":"Hazrat Yousaf A.S","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sarah was the wife of Prophet Ibrahim (A.S).She was the mother of Isaac (A.S).She was the sister of Prophet Lut (A.S).Her name is mentioned in the Qur’an in Surah Hud and Surah Al-Hijr.She was lived in Hebron (Al-Khalil).She was passed away at the age of 127 years.Last verified on 02-05-2026', 0, 0, 0, 1790964559030) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f4d8a1e127548f24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'When the army of Pharaoh was pursuing the Israelites, Hazrat Musa (AS) crossed the following sea?', '{"A":"The Mediterranean Sea","B":"Red Sea","C":"Dead Sea","D":"Black Sea"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Musa (A.S) led Bani Israel out of Egypt.Allah split the Red Sea (Baḥr al-Qulzum) for them.Bani Israel crossed safely, while Pharaoh’s army drowned.This miracle is mentioned in the Qur''an.Hazrat Musa (A.S) is called Kaleemullah (One who spoke to Allah).Mentioned in Qur’an → 136 timesMajor miracles → 9 miraclesBook revealed → Tawrat (Torah)Last verified on 28-04-2026', 0, 0, 0, 1790964559030) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e40f75819b96145e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'He knew the language of the birds (except Hazrat Sulaiman AS)?', '{"A":"Hazrat Ilyas (AS)","B":"Hazrat Salih (AS)","C":"Hazrat Shoaib (AS)","D":"Hazrat Dawood (AS)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Dawood (A.S) was blessed by Allah with special knowledge and wisdom.Along with his son Hazrat Sulaiman (A.S), he was connected with animals and nature.Hazrat Dawood (A.S) could understand birds’ communication (to some extent) by Allah’s will.He was also given beautiful voice and authority.His story is mentioned in the Qur''an (27:16).Last verified on 28-04-2026', 0, 0, 0, 1790964559030) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1e427f3ab1b35c35', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet''s nation was destroyed by a rain of stones?', '{"A":"Hazrat Ibrahim A.S","B":"Hazrat Aalih A.S","C":"Hazrat Loot A.S","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The nation of Hazrat Loot (AS) was destroyed by a punishment from Allah.Their cities were overturned and destroyed by stones (sijjil).This punishment came due to their major sins and disobedience.The destroyed قوم is known as the people of Sodom and Gomorrah.Last verified on 27-04-2026', 0, 0, 0, 1790964559030) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_614eb0ec11d4894d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What was the relation between Hazrat Shoaib and Hazrat Musa (AS)?', '{"A":"Shoaib was Musa''s brother","B":"Shoaib was Musa''s father","C":"Shoaib was Musa''s father-in-law","D":"Shoaib was Musa''s uncle"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Shoaib (Jethro) is traditionally believed to be connected to Hazrat Musa (Moses).In Islamic tradition, Hazrat Musa (A.S) married the daughter (Safura) of Hazrat Shoaib (A.S) while staying in Madyan.Therefore, Hazrat Shoaib (A.S) is commonly described as Musa (A.S)’s father-in-law (sustaan).This event is mentioned in the story of Musa (A.S) in the Qur’an.Last verified on 25-04-2026', 0, 0, 0, 1790964559030) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_81f88c95c23db444', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'In the “Sacrilegious wars”, when Prophet Muhammad (PBUH) was 20 years of age, Quraish and their allies were led by?', '{"A":"Abu Jahal","B":"Abu Lahab","C":"Umayah bin Khalaf","D":"Harb bin Umayah"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The “Sacrilegious Wars” are known as the Fijar Wars.These occurred during the youth of Prophet Muhammad (PBUH).At that time, the Prophet (PBUH) was about 20 years old.Harb ibn Umayya led the Quraysh and their allies.These battles took place around the Ukaz fair between Quraysh and Hawazin tribes.Last verified on 27-04-2026', 0, 0, 0, 1790964559030) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d507119753938b40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who accompanied Prophet Muhammad (PBUH) on the trip to Taif?', '{"A":"Hazrat Abu Bakr (RA)","B":"Hazrat Umar (RA)","C":"Hazrat Zaid bin Haris (RA)","D":"Hazrat Ali (RA)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad (PBUH) went to Taif for دعوتِ اسلام.He was accompanied by Zayd ibn Harithah (RA).The journey took place in Shawwal 619 CE (Year of Sadness).Last verified on 27-04-2026', 0, 0, 0, 1790964559101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_015cb77b8979399f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Nation of Hazrat Noah (AS) worshiped ___ idols.', '{"A":"3","B":"4","C":"5","D":"6"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The nation of Noah worshiped five idols:WadhSuwaYaghuthYauqNasAdditional information:The duration of the Toofan-e-Noah (Flood of Noah) was around 6 months.The event occurred 2,242 years after Hazrat Adam (AS).About 80 people were with him in the boat.Hazrat Noah (AS) lived for 950 years.He was sent to Iraq.He is called the predecessor, Naji Ullah, and Shaikh ul Ambiya.His title is Abu ul Bashr Sani.After the flood, the city of Khasran was established.Last verified on 27-04-2026', 0, 0, 0, 1790964559101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_78a9b5f43f508d3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What was written on seal of the Holy Prophet (PBUH)?', '{"A":"Allah, Rasool, Muhammad","B":"Muhammad, Rasool, Allah","C":"Rasool, Allah, Muhammad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The seal of Prophet Muhammad (PBUH) had three words.These words were arranged as Allah – Rasool – Muhammad.It was engraved on a silver ring.The seal was used for official letters to kings and rulers.The seal affixed on important letters by the Prophet (SAW) was in the Custody of Hazrat Huzaifa (RA).It started being used around 7 A.H.Last verified on 27-04-2026', 0, 0, 0, 1790964559101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cc59eb2fc6be0a6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Seal of Holy Prophet (P.B.U.H) was in the custody of?', '{"A":"Hazrat Huzaifa (RA)","B":"Hazrat Bilal (RA)","C":"Hazrat Ali (RA)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The seal of Prophet Muhammad (PBUH) was made of silver.Inscription: “Allah – Rasool – Muhammad” (in three lines).It started being used around 7 A.H for official letters.The seal was kept in custody of Hazrat Huzaifa ibn al-Yaman (R.A).Last verified on 31-03-2026', 0, 0, 0, 1790964559101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fb5c3b8ea576458d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What companion of Prophet (PBUH) was awarded with the title of “The Sword of Allah”?', '{"A":"Abu Bakr Siddique (R.A)","B":"Umar Farooque (R.A)","C":"Khalid bin Waleed (R.A)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khalid ibn al-Walid (R.A) was given the title Saifullah (Sword of Allah).This title was awarded after the Battle of Mu''tah.He showed extraordinary military leadership and saved the Muslim army.Born in 592 AD in Mecca.Died in 642 AD in Homs, Syria.Major Caliphs served: Abu Bakr (RA), Umar (RA)Last verified on 27-04-2026', 0, 0, 0, 1790964559101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_055aa503ca2b5c66', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'In the beginning Prophet Muhammad ﷺ worked as a shepherd for?', '{"A":"Banu Ummayya","B":"Banu Asad","C":"Banu Saad","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad ﷺ worked as a shepherd at the age of 12 years in his early life.He used to graze goats for Banu Saad tribe.This work taught him patience and responsibility.Later, he became a successful merchant (businessman).His honest nature earned him the title Al-Amin (The Trustworthy).Banu Saad is also known for fostering the Prophet ﷺ in his childhood through Hazrat Halimah Saadia (RA).Last verified on 26-04-2026', 0, 0, 0, 1790964559101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_10f00a90a7ea1e65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'To which Prophet were the Ten Commandments revealed?', '{"A":"Hazrat Musa (A.S)","B":"Hazrat Adam (A.S)","C":"Hazrat Idrees (A.S)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Ten Commandments were given to Hazrat Musa (A.S).They are divine moral and legal instructions from Allah.These commandments are part of the teachings given on Mount Sinai.They emphasize worship of One God and ethical behavior.They are also mentioned in Islamic and Biblical traditions.Last verified on 26-04-2026', 0, 0, 0, 1790964559101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d72f2ff3a171bc0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The last wife of Prophet Muhammad (SAAW)?', '{"A":"Sawada","B":"Ayesh","C":"Maria","D":"Maimuna"}', 'D', NULL, 0, 0, 0, 1790964559101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6dff0333a4771950', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The following Prophet suffered from blindness in his old age?', '{"A":"Hazrat Younas (AS)","B":"Hazrat Ishaq (AS)","C":"Hazrat Ismaeel (AS)","D":"Hazrat Yaqoob (AS)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Yaqoob (AS) became blind in his old age.His blindness was caused due to deep sorrow for Hazrat Yusuf (AS).Later, his eyesight was restored by Allah after reunion.This event is mentioned in the Holy Quran (Surah Yusuf).He is also known as Prophet Jacob in English.His story teaches patience (Sabr) and trust in Allah (Tawakkul).Last verified on 25-04-2026', 0, 0, 0, 1790964559158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_84681739a686388d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Prophet was staying at the house of ______ on the night of Miraj.', '{"A":"Umme-e-Hani","B":"Fatima R.A","C":"Abu Bakar R.A","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790964559158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8e7e91f884359ebb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'When the first wahi was revealed to the Holy Prophet ﷺ?', '{"A":"August 630 A.D","B":"August 610 A.D","C":"August 600 A.D","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Wahi (revelation) was revealed to the Holy Prophet Muhammad ﷺ in 610 ADLocation: Cave of Hira (Ghar Hira) on Jabal al-Noor.Date: Monday, Ramadan (roughly August 610 AD).Age of Prophet ﷺ: 40 lunar years, 6 months, and 12 days.Verses Revealed: The first five verses of Surah Al-`Alaq ("Iqra'' bismi rabbik...").Last updated by NA on 23-April-2026', 0, 0, 0, 1790964559158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d85cb6651e65995d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Prophet Muhammad ﷺ lived in Madina for _____ years.', '{"A":"13 years","B":"11 years","C":"10 years","D":"5 years"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad ﷺ lived in Madina for 10 years.At the age of 53 Prophet Muhammad ﷺ migrated to Madina.He stayed in Medinah for 10 years from the year 622 to 632 (1 to 10 Hijri).Additional Information:Prophet Muhammad ﷺ lived in Makkah for the first 53 years of his life.Last verified on 10-06-2026', 0, 0, 0, 1790964559158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_483b8b381c198f43', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Holy Prophet PBUH was blessed with Prophethood in the age of ____?', '{"A":"25","B":"40","C":"35","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad PBUH have at the age of 40.He and his wife had six children — two boys (who did not live into adulthood) and four girls. By the time he was 40, he began having religious visions that would change his life. This is Prophet Muhammad''s mosque in Medina.At the age of 40 in 11 BH (610 CE), Muhammad is said to have received his first verbal revelation in the cave called Hira, which was the beginning of the descent of the Quran that continued up to the end of his life.Last verified on 02-04-2026', 0, 0, 0, 1790964559158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_155e3d42c0840fa9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet is called as Najiullah?', '{"A":"Hazrat Musa (AS)","B":"Hazrat Essa (AS)","C":"Hazrat Noah (AS)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Nuh (Noah) lived for 950 years.He preached about the Oneness of Allah to his people for 950 years, but only a few accepted his message.An entire chapter in the Holy Qur’an, Surah Nuh (71st Surah), is dedicated to his struggle and message.Titles of Prophet Nuh (AS):Naji Ullah (The Saved by Allah)Shaikh-ul-Ambiya (Elder among the Prophets)Abu-ul-Bashr Sani (Second Father of Mankind)He is also called a predecessor due to his early role in guiding mankind after Prophet Adam (AS).Last verified on 30-03-2026', 0, 0, 0, 1790964559158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e16675d2772b432b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet was thrown into well by his Brothers?', '{"A":"Hazrat Ibrahim (AS)","B":"Hazrat Yousaf (AS)","C":"Hazrat Yaqoob (AS)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Yousaf (AS) was 15 years old when his brothers thrown him into the wall.Hazrat Yousaf (AS) remained in the well for three days.Last verified on 30-03-2026', 0, 0, 0, 1790964559158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9f98ccb3931f75df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who was the angel that delivered messages to Prophet Muhammad ﷺ from Allah?', '{"A":"Hazrat Israfeel (علیہ)","B":"Hazrat \tMikael (علیہ)","C":"Hazrat \tJibrael (علیہ)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Jibrael (AS) delivered the Message to every Prophet from Hazrat Adam to Muhammad (PBUH).Additional information:Izrail – The Angel of DeathIsrafil – The day of resurrection.Mikāal – Responsible for bringing rain and thunder to Earth.Last verified on 17-03-2026', 0, 0, 0, 1790964559158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ae8b118ac8085438', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'How many times Prophet Musa (A.S) is mentioned in the Holy Qur’an?', '{"A":"146 Times","B":"136 Times","C":"126 Times","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Musa (A.S) is mentioned about 136 times in the Holy Qur’an.Prophet Musa (A.S) was given the Torah (Tawrat) as a divine book.He is one of the Ulul-Azm prophets (the prophets of strong determination).Additional information:Ibrahim (A.S) – about 69 timesNuh (A.S) – about 43 timesLut (A.S) – about 27 timesIsa (A.S) – about 25 timesLast verified on 14-03-2026', 0, 0, 0, 1790964559219) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_750869ede22477f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Where did the Prophet (S.A.W) and Abu Bakr take shelter before proceeding to Al-Madinah?', '{"A":"Syria","B":"Cave of Soor","C":"Mount of Uhud","D":"Cave of Hira"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During the Hijrah in 622 AD (1 AH), Prophet Muhammad ﷺ and Hazrat Abu Bakr (RA) hid in the Cave of Thawr to avoid the Quraysh who were pursuing them.They stayed there for three days before continuing their journey to Madinah.Last verified on 07-03-2026', 0, 0, 0, 1790964559219) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a1a682b726afdf13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'After Tofaan-e-Noah Hazrat Noah''s (AS) boat stopped at a mountain. What is the name of this mountain?', '{"A":"Koh-e-Marwa","B":"Koh-e-Safa","C":"Koh-e-Jabal","D":"Koh-e-Jodi"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Noah''s (AS) boat (Ark) stopped at Koh-e-Judi, Turkey.The duration of the Toofan-e-Noah (Flood of Noah) was around 6 months.The event occurred 2,242 years after Hazrat Adam (AS).About 80 people were with him in the boat.Additional information:Hazrat Noah (AS) lived for 950 years.He was sent to Iraq.He is called the Predecessor, Naji Ullah, and Shaikh ul Ambiya.His title is Abu ul Bashr Sani.After the flood, the city of Khasran was established.The nation of Noah worshiped five idols:WadhSuwaYaghuthYauqNasLast verified on 06-03-2026', 0, 0, 0, 1790964559219) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8a62c9808d2c1944', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Prophet Muhammad ﷺ belonged to __________ family.', '{"A":"Makki","B":"Quraishi","C":"Hashmi","D":"Madni"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad belonged to the Banu Hashim (Hashimite) clanNamed after his great-grandfather, Hashim ibn Abd Manaf, this clan was part of the Adnani Quraish. Tribe: QurayshParents: Abdullah ibn Abd al-Muttalib and Aminah bint WahbNOTE:The Banu Hashim held a prestigious position in Mecca, often responsible for providing water to pilgrims at the Kaaba. Last updated 18-02-2026', 0, 0, 0, 1790964559219) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_20dcae64a27bdc1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which companion of the Holy Prophet (SAW) were included in the scribes of revelation?', '{"A":"Hazrat Abdullah bin Masood (RA)","B":"Hazrat Usman (RA)","C":"Hazrat Umar (RA)","D":"Hazrat Zaid bin Sabit (RA)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Zaid bin Sabit (RA) was one of the closest companions of the Holy Prophet (SAW) and was included among the scribes of revelation.He was responsible for writing down the divine revelations received by the Prophet (SAW).He was known for his excellent memory, literacy, and dedication to the Prophet''s mission.', 0, 0, 0, 1790964559219) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f2935dc556770fbd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet is known as Jadd-ul-Anbiya?', '{"A":"Hazrat Adam (A.S)","B":"Hazrat Ibrahim (A.S)","C":"Hazrat Nooh (A.S)","D":"Hazrat Muhammad (s.a.w.w)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazarat Ibrahim A.s is the Abu ul Ambiya ( Father of ProphetsHazrat Ibraheem is known as Jadd-ul-Anbiya.The grave of Hazrat Ibraheem (علیہ) in Israel.Hazrat Ibrahim (AH) name is mentioned in the Holy Quran 67 times.Hazrat Ibraheem As had two wives Hazrat Hajra and Hazrat Sarah.Hazrat Ibraheem As Had Two Sons Hazrat Ismail As And Hazrat Ishaq (As)Hazrat Ibraheem (A.S) met with Holy Prophet ﷺ on the 7th heaven.Hazrat Ibraheem (AS) was sent to Jorden after leaving Hazrat Hajirah and Hazrat Ismaeel in But’ha valley.AGM 02.05.2023', 0, 0, 0, 1790964559219) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e2df706f689a56ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which prophet slept for 100 years?', '{"A":"Hazrat Moosa (A.S)","B":"Hazrat Idrees (A.S)","C":"Hazrat Uzair (A.S)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Uzair is introduced as one of the prophets of God sent to the Children of Israel. The Quran makes mention of his name only once in surah Tawbah verse 30The Holy Quran tells the story of Prophet Uzair عَلَيْهِ ٱلسَّلَامُ as a Prophet who died for 100 years and live again***ND29-1-2023', 0, 0, 0, 1790964559219) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_57be3b0a77ec3248', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'How many sons did Hazrat Adam (A.S) have?', '{"A":"3","B":"2","C":"1","D":"4","E":"None of these"}', 'A', NULL, 0, 0, 0, 1790964559219) ON CONFLICT(id) DO NOTHING;
