INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e2a29897099829c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who did accompany the Holy Prophet (SAW) in the migration to Madina?', '{"A":"Hazrat Usman (RA)","B":"Hazrat Abu Bakar (RA)","C":"Hazrat Umar (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There they stayed for three days and three nights.On September 24, 622 (1st Hijri) Hazrat Abu Bakar (AS) accompanied the Prophet(SAW) in the migrationQaswa (camel) which the Holy Prophet (SAW) was riding in the migration of MadinaMuhammad ﷺ and Hazrat Abu Bakr hid inside a cave on the Mount of Thawr.Surah Yaseen is recited by Hazrat Muhammad (PBUH) during migrationABOUT ABU BAKARAbu Bakr Abdullah was a companion and, through his daughter Aisha.a father-in-law of the Islamic prophet Muhammad.first of the Rashidun Caliphs', 0, 0, 0, 1790964559558) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_72292da6b6aaadac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'How many years did Hazrat Khadija (R.A) spend with Prophet Muhammad (S.A.W)?', '{"A":"25 years","B":"15 years","C":"20 years","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Khadija (R.A) was the first wife of Prophet Muhammad (S.A.W.).She was married to him for 25 years.She was 15 years older than the Prophet.She is honored as "The Mother of Believers."She is one of the "ladies of heaven" in Islam.', 0, 0, 0, 1790964559558) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_be57a1d12a60624f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'How many years Hazrat Noah (A.S) was lived?', '{"A":"750","B":"550","C":"950","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Duration of Tofaan e Noah around 6 months.Hazrat Noah lived for 950 years. About People were with him in the boat. 80 people After the how many years of Hazrat Adam A.S the event of Toofan-e-Noah occurred. 2242', 0, 0, 0, 1790964559558) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cebf9d9f957ceef2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Holy Prophet (PBUH) appointed Hazrat Muaaz Bin Jabal as the governor of ______?', '{"A":"Madina","B":"Makkah","C":"Yemen","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muadh ibn Jabal was a companion of the Islamic Prophet Muhammad (PBUH).He was from the Ansar tribe of Banu Khazraj.He was renowned for his vast knowledge and understanding of Islam.The Prophet Muhammad (PBUH) referred to him as "the one who will lead the scholars into Paradise."He was appointed by the Prophet (PBUH) as the governor of Yemen.', 0, 0, 0, 1790964559558) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ca3e9c6d98d7fb04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who performed the Ghusl (ritual washing) of Prophet Muhammad (ﷺ) after his passing?', '{"A":"Hazrat Abu Bakr (RA)","B":"Hazrat Ali (RA)","C":"Hazrat Usman (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazoor Pak (PBUH) was given his last ghusl by his cousin and son-in-law Ali ibn Abi Talib (RA).Holy Prophet Muhammad (ﷺ) died on 8th June 632 AD on Monday.He died at the age of 62.He was buried at al-Masjid an-Nabawi (the Mosque of the Prophet).', 0, 0, 0, 1790964559558) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2f3b4c18cfa86b2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'After Hijrat to madina, what first important thing was done by the Holy prophet (SAW)?', '{"A":"Built a mosque for prayers","B":"Built his house","C":"Created Bait-ul-Mal","D":"Raised an Army"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet (SAW) first built a mosque for prayers, Masjid-e-Nabawi.It is served as a center for religious, social, and political activities, uniting the Islamic community.This mosque was built with the help of the Ansar (helpers) and Muhajirun (migrants) and was completed in the first year of Hijra (622 CE).', 0, 0, 0, 1790964559634) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1adf42ec986d023e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Mosque of Prophet ﷺ was damaged due to fire in the reign of ______?', '{"A":"Motasim Billah","B":"Aurangzeb","C":"Shahjahan","D":"Razia Sultana","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Isḥaq Muḥammad ibn Harun al-Rashid, better known by his regnal name al-Muʿtaṣim biʾllāh, was the eighth Abbasid caliph, ruling from 833 until his death in 842.A younger son of Caliph Harun al-Rashid, he rose to prominence through his formation of a private army composed predominantly of Turkic slave-soldiers.', 0, 0, 0, 1790964559634) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_db8fb22323c14468', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet earned his living by making wallets?', '{"A":"Hazrat Suilaiman (AS)","B":"Hazrat Hood (AS)","C":"Hazrat Dawood (AS)","D":"Hazrat Yahya (AS)","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sulaymān ibn Dāwūd was, according to the Quran, a Malik and Nabī of the Israelites. Islamic tradition generally holds that he was the third King of Jewish people, and wise ruler for the nation.', 0, 0, 0, 1790964559634) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_19a6565841d15345', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Companions of Holy Prophet SAW at Hudabiya was ____?', '{"A":"1300","B":"1400","C":"1500","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was a pivotal treaty between Muhammadﷺ, representing the state of Medina, and the Qurayshi tribe of Mecca in January 628 (Dhu al-Qi''dah, AH 6).', 0, 0, 0, 1790964559634) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_514a50c23d40afa6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'For ___ years Haleema took care of Prophet (PBUH).', '{"A":"6","B":"7","C":"8","D":"9"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For 6 years, Halima took care of the Prophet (PBUH)Foster Mother: Prophet Muhammad ﷺTribe: Banu Sa''d, HawazinOrigin: Arab Bedouin womanHusband: Harith bin Abdul Uzza (RA)Died: 630 CE in MadinaAdditional information3 Foster Mothers of Prophet ﷺHazrat Halima Saadia (RA)Hazrat Suwaiba (RA)Hazrat Khawla (RA)Last updated: 13-09-2026', 0, 0, 0, 1790964559634) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a2e224dbe78cd126', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who suggested the name "Ahmed" for Holy Prophet (PBUH)?', '{"A":"Hazrat Amina","B":"Hazrat Abdullah","C":"Hazrat Abdul Mutalib","D":"Hazrat Qasim","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The name "Ahmed" was suggested by Hazrat Amina (R.A) while the name "Muhammad" was suggested by Hazrat Abdul Mutalib.', 0, 0, 0, 1790964559634) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_53323f81470770e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Sahabi made the ring of Holy Prophet Muhammad (S.A.W)?', '{"A":"Hazrat Ya''ala bin Ummyah (R.A)","B":"Hazrat Usman (R A)","C":"Hazrat Khuzefa (R.A)","D":"Hazrat Ali (R.A)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ya''ala bin Ummyah (R.A.) made the ring of Holy Prophet Muhammad (S.A.W).The ring was used by the Prophet SAW for sealing documents and correspondences.', 0, 0, 0, 1790964559634) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_652db3f8b1e869d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What was the religion of the forefathers of the Holy Prophet (SAW)?', '{"A":"Christianity","B":"Deen-e-Ibraheemi","C":"Buddhism","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The religion of the forefathers of the Holy Prophet (SAW) was Deen-e-Ibraheemi.It followed the monotheistic teachings of Prophet Ibrahim (AS).', 0, 0, 0, 1790964559634) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ceea486383616506', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What was the relation between Hazrat Haroon and Hazrat Musa (AS)?', '{"A":"Brothers","B":"Cousions","C":"Both","D":"Father and son"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Musa (Kaleemullah) and Hazrat Haroon (A.S) were brothers and prophets of God.Hazrat Musa (A.S) is buried in Ohud, KSA.Hazrat Haroon (A.S) is buried in Jordan.Hazrat Haroon (A.S) met the Holy Prophet ﷺ on the 5th heaven.Zubaida, wife of Haroon ur Rasheed.She was the mother of Al-Ameen and Al-Haroon.', 0, 0, 0, 1790964559711) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_862681f117e0bd4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'For how years Hazrat Abdul Muttalib (R.A) took care of Prophet (SAW)?', '{"A":"2","B":"7","C":"5","D":"3"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abd al-Muttalib Shaybah ibn Hashim, born in 497 A.D and died in 578 A.DHe was the grandfather of Prophet Muhammad (SAW).He took care of the Prophet (SAW) for 2 years after the death of his mother.', 0, 0, 0, 1790964559711) ON CONFLICT(id) DO NOTHING;
