INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e699a5dbe8a22dd8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet was famous for his Patience?', '{"A":"Hazrat Haroon (AS)","B":"Hazrat Ayub (AS)","C":"Hazrat Loot (AS)","D":"Hazrat Musa (AS)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Ayyub (Job) is known for his patienceHe was tested with Skin Disease for 18 Years ·He was the prophet of Allah during the era between Musa and Yaqub Prophet.Ayyub is mentioned in the Holy Quran four times. The Bible also refers to Ayyub''s patience, with James 5:11 calling him the "master of patience".**ND13-1-2023ND5-2-2023', 0, 0, 0, 1790964559711) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3221cc0422aef4d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet is called the Father of Muslims?', '{"A":"Hazrat Nooh (A.S)","B":"Hazrat Adam (A.S)","C":"Hazrat Abraheem (A.S)","D":"Hazrat Muhammad (ﷺ)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ibrahim is called the Father of MuslimThe Qur''an refers to him as the friend of God (4:125) and the father of prophetsAdditional InformationHazrat Ibrahim A.S remained on fire for 40 daysKhalil Ullah is the title of Hazrat Ibrahim (A.S)Hazrat Ibrahim (A.S) was born in IraqHazrat Ibrahim''s (AH) name is mentioned in the Holy Quran 67 times.Abraham had two children,1. Isaac2. Ismael,RY30012023ND-21-5-2023', 0, 0, 0, 1790964559711) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_92555f59cf4255cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'To which clan of Quraish Prophet Muhammad (PBUH) belong?', '{"A":"Tamim","B":"Bano Bakr","C":"Bannu Hashim","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Family of the Prophet Hazrat Muhammad ﷺ was Hashmi and the Tribe was Quraish.***Holy Prophet Hazrat Muhammad ﷺ great-grandfather was Hashim ibn Abd Manaf, for whom the tribe is named.Members of this clan are referred to as Hashmi.Banu Hashim is a clan in the Quraysh tribe.**** RY18012023', 0, 0, 0, 1790964559711) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_83309c1913e116c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Hazrat Ibrahim A.S remained in fire ___ days.', '{"A":"45 days","B":"40 days","C":"35 days","D":"20 days","E":"10 days"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation important question : Namrud ordered throwing Hazrat Ibrahim (A.S) into the fireNimrod, the king of Babylon, commanded his men to throw Prophet Ibrahim (AS) into a huge pit of burning fireHazrat Ibrahim A.S remained on fire for 40 daysKhalil Ullah is the title of Hazrat Ibrahim (A.S)Hazrat Ibrahim (A.S) was born IraqHazrat Ibrahim''s (AH) name is mentioned in the Holy Quran 67 times.Abraham had two children,1. Isaac2. Ismael,****agm.04.03.23ND5-2-2023', 0, 0, 0, 1790964559711) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cfca8d00aa288be5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What is the title of Hazrat Ibrahim (A.S)?', '{"A":"Khalil Ullah","B":"Kalim Ullah","C":"Saif Ullah","D":"Jad-ul-Anbia"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khalilullah means friend of GodKhalil Ullah is the title of Hazrat Ibrahim (A.S)Hazrat Ibrahim (A.S) was born IraqNamrud ordered throwing Hazrat Ibrahim (A.S) into the fireHazrat Ibrahim A.S remained on fire for 40 daysHazrat Ibrahim''s (AH) name is mentioned in the Holy Quran 67 times.Abraham had two children,1. Isaac2. Ismael,Additional Information:Prophet Isa (Jesus) was known as ''Ruhullah'' (i.e. the spirit of God) ,Prophet Musa (Moses) was known as ''Kalimullah'' (i.e. one who speaks with God)AGM 5.2.23', 0, 0, 0, 1790964559795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b4dbfc5823c383ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Holy Prophet used to go to a Mosque on every 17th Ramadan, state the name of Mosque?', '{"A":"Masjid al-Haram","B":"Quba Mosque","C":"Al Masjid an Nabawi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet (PBUH) used to visit Quba Mosque on the 17th of Ramadan.It holds significance as the first mosque built in Islam.It is located in Medina.', 0, 0, 0, 1790964559795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_40c721fdcf225ed6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet of Allah had minimum age?', '{"A":"Hazrat Ibrahim (AS)","B":"Hazrat Muhammad (SAW)","C":"Hazrat Musa (AS)","D":"Hazrat Easa (AS)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Easa (AS) was around 33 years old.Hazrat Ibrahim (AS) was around 195 years old.Hazrat Muhammad (SAW) was around 63 years old.Hazrat Musa (AS) was around 125 years old.Hazrat Adam (AS) was around 1000 years old.', 0, 0, 0, 1790964559795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_174e4e65098534d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'How many times the mother of Hazrat Ismail (AS) ran from Hill of Safa and Marwa in search of Water?', '{"A":"5","B":"6","C":"7","D":"8"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Hajra, the mother of Hazrat Ismail (AS), ran between the hills of Safa and Marwa seven times in search of water.This act is commemorated during the Hajj pilgrimage, specifically in the ritual of Sa''i.The running b/w Safa and Marwa seven times is called Sayee.', 0, 0, 0, 1790964559795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_348b92993647bba1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'To whom did The Holy Prophet(SWA) go immediately after the revelation of the first Wahi?', '{"A":"Warqa Bin Nofal","B":"Hazrat Abu Bakr( RA)","C":"Hazrat Khadija (RA)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation پہلی وحی کے وقت رسول اللہ صلی اللہ علیہ وسلم کی عمر کتنی تھی؟40 years 6 monthsWhen the first wahi was revealed to the Holy Prophet ﷺ?610AD****What was the age of Rasool Ullah (PBUH) at the time of the first Wahi?40 years 6 months********How many verses (Ayats) were in the first Wahi?5********Name the first prescriber of wahi in Makkah.Sharjeel-ibn-Hasana Kandi***Who was the first writer of “Wahi” in Quraish?Hazrat Zaid bin Sabit (RA)********The first Wahi was descended on Cave Hira.پہلی وحی غارحرا میں نازل ہوئی تھی۔****ND10-1-2023***ND28-1-2023', 0, 0, 0, 1790964559795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_76c963abee9307ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which Prophet''s nation received the azab (punishment) of mosquitoes?', '{"A":"Hazrat Ibrahim (AS)","B":"Hazrat Musa (AS)","C":"Hazrat Nuh (AS)","D":"Hazrat Ayyub (AS)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Azab of Mosquitoes was sent to the nation of Hazrat Ibrahim (AS).It was directed specifically at the arrogant king Namrood (Nimrod) and his blasphemous army.', 0, 0, 0, 1790964559795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8c32b296abe3e28c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Name of first biggest lair who announced the false Prophet-hood?', '{"A":"Muslima  kazab","B":"Tulayha","C":"Kazab","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muslima kazab مسلمہ کذابHe claim false Prophet-hood in the life of Muhammad', 0, 0, 0, 1790964559795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_efd7afd870b1ca06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'On which Prophet Taurat (Torat) was revealed?', '{"A":"Hazrat Issa","B":"Hazrat Mussa","C":"Hazrat Ibrahim","D":"Hazrat Dawood"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Torah" means "Law" in Hebrew.The Torah has a range of meanings.It refers to the first five books of the Hebrew Bible.It is also known as the Five Books of Moses or Chameesha Choomshey Torah in Hebrew.It encompasses the laws and teachings given to the Israelites.The Torah contains 187 chapters and 5,852 verses.There are four Holy BooksThe Torat revealed to MusaThe Zabur revealed to Dawud The Injil (Gospel) revealed to Isa The Quran was revealed to Muhammad.', 0, 0, 0, 1790964559795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_01ee5ea7b0524ec3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'To whom Hazrat Khadija (R.A) took to the Holy Prophet (SAW) after discussing firstly about the prophethood?', '{"A":"Ummay Hani","B":"Musairn","C":"Warqa bin Nofal","D":"Baheera","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khadija (R.A) took the Holy Prophet (SAW) to Warqa bin Nofal after discussing firstly about the prophethood.Waraqah ibn Nawfal was the cousin Uncle of Hazrat Khadija (RA).Hazrat Khadija (RA) took him to Waraqah bin Naufal who was a Christian convert and used to read the Gospel in Arabic.Khadija (RA) was the first wife of the Holy Prophet (PBHU).Additional InfoProphethood has been finished on the Prophet Hazrat Muhammad (PBUH)The Prophethood is belief in All the Prophets of Allah.Prophethood is attained by Bestowed by Allah***', 0, 0, 0, 1790964559863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ddb4ab34deefdbda', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The comb was invented by Prophet?', '{"A":"Ibrahim (AS)","B":"Daud (AS)","C":"Nuh (AS)","D":"Sulaiman (AS)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ibrahim (AS) is a prominent example of faith in Judaism, Christianity, and Islam.He is also credited with inventing the comb.', 0, 0, 0, 1790964559863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e1374cea0b4c4ad7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'After how many months of migration of Prophet (PBUH) to Madina the change of Qibla occurred?', '{"A":"15","B":"16","C":"17","D":"18"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The change of Qibla occurred after the 18 months of migration of the Holy Prophet (PBUH) to Madina the change of Qibla occurred In 624 AD During the Zohar prayer, the change of Qibla happened.In 2 Hijri years, Qibla has changedMasjid al-Qiblatain is one of the three oldest mosques in Islamic historyThe first Qibla Muslims prayed for is Al-Aqsa mosque المسجد الأقصى (Bait Al-Maqdis بيت المقدس)***', 0, 0, 0, 1790964559863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e00b08eb9d022fc8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Prophet Muhammad (PBUH) was buried in ___', '{"A":"Taif","B":"Makka","C":"Madina","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Holy Prophet Hazrat Muhammad (PBUH)''s grand grandfather was Hashim ibn Abd Manaf, for whom the tribe is named. Members of this clan are referred to as Hashmi. Banu Hashim is a clan in the Quraysh tribe. So the Family of the Prophet Hazrat Muhammad (PBHU) was Hashmi and the Tribe was Quraish.', 0, 0, 0, 1790964559863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b1015e3a4714f79a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Hazrat ___________ was the foster mother of Holy Prophet.', '{"A":"Hazrat Haleema","B":"Hazrat Ruqya","C":"Hazrat Summaya","D":"Hazrat Bushra"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Halimah and her husband were from the tribe of Sa''d.3 foster mothers of the Holy Prophet Hazrat Halema Saadia (RA) Hazrat Khola (RA) Hazrat Suwaiba (RA)', 0, 0, 0, 1790964559863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0e7e24bfc6f9623a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which year was declared Year of Sorrow by the Holy Prophet (PBUH)?', '{"A":"617 AD","B":"618 AD","C":"620 AD","D":"619 AD","E":"616 AD"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Year of Sadness Year of sorrow (عام الحزن) is the Hijri era when Muhammad''s wife Hadilla and her uncle and guardian Abu Talib died. This year almost coincided with 619 AD, the tenth year since the first revelation of Muhammad.Explanation:Hazrat Khadija was the wife of the Holy Prophet (P.B.U.H).Hazrat Abu Talib was the uncle of the Holy Prophet (p.b.u.h)Year of sorrow means غم کا سال', 0, 0, 0, 1790964559863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c60c0ccf7ecacc5d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Warqa bin Naufal was the follower of ________ at the time of the first revelation of the Prophet of Islam.', '{"A":"Christianity","B":"Judaism","C":"Religion of Abraham","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Warqa bin Naufil was considered a Christian priest. Warqa bin Naufil also known as ‘Abdul ‘Uzza,He was the first man to verify Prophet''s first timeHe used to write the writing with Hebrew letters.He was the paternal cousin of Khadijah bint Khuwaylid.', 0, 0, 0, 1790964559863) ON CONFLICT(id) DO NOTHING;
