INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d39e3c03df0c682b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The holy prophet (PBUH) participated in the war of Fijar in which century?', '{"A":"Seventh","B":"Sixth","C":"Eighth","D":"Ninth","E":"Fifth"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Harb ibn Umayya was the father of Abu Sufyan۔When Prophet Muhammed ﷺ was 20 there was a battle during the Okaz fair between Quraysh (with Kanana) and Hawazin.This battle was called the Al-Fijar battle.', 0, 0, 0, 1790964559942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a99d95dc83b2d40e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Holy Prophet (PBUH) gave the title of_________ to Hazrat Salman Farsi ?', '{"A":"Naqeeb-e-Islam","B":"Sultan-ul-Khair","C":"Afzal-ul-Bashr","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salman was a companion of the Islamic prophet Muhammad.First Persian who converted to Islam.He was referred to by the kunya Abu Abdullah. Born: 568 AD, JayDied: Ctesiphon, IraqFull name: Rōzbeh', 0, 0, 0, 1790964559942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3ac08b02c997e446', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Hazrat Musa(A.S.) married the daughter of?', '{"A":"Hazrat Yaqub A.S","B":"Hazrat Shoaib A.S","C":"Hazrat Esa A.S","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bibi Safoora the wife of (Prophet Moosa) was the daughter of Prophet: Hazrat Shoaib A.SHazrat Musa also known as Kaleemullah was one of 124,000 prophets of God.Moses, also known as Moshe RabbenuHazrat Musa was granted 9 miraclesHazrat Musa (A.S) met with Holy Prophet ﷺ on the 6 heaven***ND29-1-2023', 0, 0, 0, 1790964559942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_de982bf2e3b91e79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'How many days before incident of (feel) elephant, prophet Mohammad (Saw) was born?', '{"A":"50 Days","B":"40 Days","C":"30 Days","D":"20 Days"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation this year is called Amm ul Fail****RY30012023', 0, 0, 0, 1790964559942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dbeb4fd4a8eee35b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What was the age of Holy Prophet when his mother died?', '{"A":"6","B":"4","C":"3","D":"8"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet was 6 years old when his mother diedHazrat Bibi Amina (R.A) is the mother of the Holy Prophet (PBUH).The mother of the Holy Prophet (PBUH) was buried at AbwaAminah bint Wahb was a woman of the clan of Banu Zuhrah in the tribe of QurayshwhileThe Holy Prophet was At eight he lost his grandfather.Muhammad''s father, Abdullah, died almost six months before he was born', 0, 0, 0, 1790964559942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f613dfe89ea7ac7d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What was the seal of prophet (p.b.u.h) made of ____?', '{"A":"Iron","B":"Gold","C":"Silver","D":"Brass"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mohammedﷺ had a seal made of silver, with the words "Allah - Rasool - Muhammad".Islamic official seal started in 7 A.HThe seal affixed on important letters by the Prophet (SAW) was in the Custody of Hazrat Huzaifa (RA).RY30012023', 0, 0, 0, 1790964559942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2e9bec2dc48dc47e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'King of ______ tore away the message of Prophet SAW.', '{"A":"Iraq","B":"Syria","C":"Egypt","D":"Iran"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The King of Iran Khusro Pervaiz tore away the message of the Prophet. Khosrow II reportedly tore up the document, saying, "A pitiful slave among my subjects dares to write his name before mine" Abdullah ibn Hudhafah delivered the Prophet Muhamma''s message to Iran''s king Sh27-8-2023', 0, 0, 0, 1790964559942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ad0729daeea58c17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who was the Prophet which first laid the foundation of Masjid-e-Aqsa?', '{"A":"Hazart Muhammad ﷺ","B":"Hazart Daood ( A.S)","C":"Hazart Suleman (علیہ)","D":"Hazart Ibrahim ( A.S)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Aqsa Mosque, located in the Old City of Jerusalem,In Masjid e Aqsa the word Aqsa means Far awayHazrat Ibrahim ( A.S) was the Prophet which first laid the foundation of Masjid-e-AqsaAl Masjid Al Aqsa was the first qibla in Islam.It was built 40 years after Al Masjid Al Haram in Makkah.', 0, 0, 0, 1790964559942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_95eb97c6e4d482a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Holy Prophet ﷺ had 10 paternal Uncles and ___ paternal aunts?', '{"A":"5","B":"6","C":"7","D":"9","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Holy Prophet ﷺ had 10 paternal Uncles and 6 paternal auntsThey were: Bayda BarraAtikaSafiyyaArwaUmaymaND29-5-2023', 0, 0, 0, 1790964560013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8ddf98e259094cc0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What is the literal meaning of Nabi?', '{"A":"A person who conveys the message of Allah","B":"A person who acts according to Shariah","C":"A person who behaves nicely","D":"A person who believes in the unity of Allah","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are 124000 nabi in islam 4 Rasool have holy books:1) Hazrat Musa(A.S) (Book: Toraat) 2) Hazrat Daood(A.S) (Book : Zaboor) 3) Hazrat Issa(A.S) (Book: Anjeel) 4) Hazrat Muhammad (S.A.W) (Book: Quran e majeed)', 0, 0, 0, 1790964560013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d137d7e62af96e1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Name the Sahabi who is a cousin and son in law of the Holy Prophet (SAW)?', '{"A":"Hazrat Ali (RA)","B":"Hazrat Zaid bin Haris (RA)","C":"Hazrat Zaid bin Sabit (RA)","D":"Hazrat Usman (RA)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fatimah was married in AD 624 to Ali ibn Abi Talib (l. AD 601-661), a cousin of Prophet Muhammad, and the marriage lasted to the end of her days.Hazrat Ali (R.A) was attacked with a poisoned sword On 19th Ramazan 40th Hijri,before the time of FAJAR prayers to the mosque of Kufa.He died on the 21st of Ramadan 40 A.H.He was buried in Najaf al-Ashraf (Iraq).', 0, 0, 0, 1790964560013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_eb98226ee2746175', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who was made governor of North Yemen by Holy Prophet?', '{"A":"Hazrat Amer Ibn Alas","B":"Hazrat Abu Musa Ashri","C":"Hazrat Maaz Bin Jabal","D":"All of these","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Musa al-Ash''ari was at various times governor of Basra and Kufa and was involved in the early Muslim conquest of Persia.', 0, 0, 0, 1790964560013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_845cf6280da35029', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The relatives of Prophet (PBUH) in the first migration to Abyssinia were:', '{"A":"Abbas (R.A)","B":"Abu Bakkar (R.A) and Ayesha (R.A)","C":"Ali (R.A) and Fatima (R.A)","D":"Usman (R.A) and Ruqayya (R.A)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The relatives of the Prophet (PBUH) in the first migration to Abyssinia were: Usman (R.A) and Ruqayya (R.A)***The first migration of the Companions and relatives of the Prophet Muhammad ﷺ was to Abyssinia (Ethiopia)The Migration to Abyssinia Dated 6 BH (613/14 CE).Start date: 613 ADParticipants: A group of twelve men and four womenAlso known as:Hijrah il-al-Habshah ***Abdul bin Zubair (R.A) was the first child born after the migration (hijrah)', 0, 0, 0, 1790964560013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ec75d177966e0928', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which is the greatest of all sins according to the Holy Prophet (SAW)?', '{"A":"Lie","B":"Backbiting","C":"Flattering","D":"Shirk"}', 'D', NULL, 0, 0, 0, 1790964560013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_563aadd5d99d9297', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Prophet (SAW) used to meditate in __________ before revelation.', '{"A":"Mount Hira","B":"Mount Uhad","C":"Jabl-e-Arafat","D":"Mount Soor"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet (SAW) used to meditate in Mount Hira before revelation.رسول اللہ صلی اللہ علیہ وسلم وحی سے پہلے کوہ حرا میں مراقبہ کیا کرتے تھے۔meditate غور و فکر کرنا', 0, 0, 0, 1790964560013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f2229dfb8685edd1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The bond of "Muwakhaat" was created by the Holy Prophet (PBUH) between:', '{"A":"Muslims & Non-Muslims","B":"Muslims & Jews","C":"People of Makkah and Madina","D":"Ansaar and Muhaajireen"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At the time of migration from Makkah to Madina.', 0, 0, 0, 1790964560013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_15dbbb6e58cddd67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Holy Prophet (PBUH) passed away in the age of:', '{"A":"60","B":"61","C":"62","D":"63"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The founder of Islam Hazrat Muhammad (PBUH) passed away at the age of 63.History:Holy Prophet was born in 571 A.D 22nd April (Day-Monday)Mother: AminaFather name AbdullahFamily: QuraishBorn in MakkahDied in 632 ADProphet Muhammad ﷺ had three sons and four daughters.Hazrat Muhammad PBUH Had 11th Wives.', 0, 0, 0, 1790964560079) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_aba753783af8628a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which of the following was the Teacher of Hazrat Musa (AS) ?', '{"A":"HAZRAT KHIZAR (A.S","B":"Muhammad Bin Ibrahim","C":"Hazrat Ibrahim(A.S)","D":"Hazrat Ishaq"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Khizar A.S. is known as teacher of Hazrat Musa (A.S.). Hazrat Musa is also known as Kaleemullah was one of 124,000 prophets of God.Moses, also known as Moshe Rabbenu, was the most important prophet in Judaism. messenger, prophet, wali, slave or angel, who guards the sea, teaches secret knowledge and aids those in distress.', 0, 0, 0, 1790964560079) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_eb688350017f5dd5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who was the first poet who was rewarded by Holy Prophet PBUH?', '{"A":"Kaab Bin Zuhair","B":"Abu Jandal","C":"Usamah Bin Zaid","D":"Maalik Bin Dinar","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Hasaan ibn e sabit (R.A) was the first poet of Islam.', 0, 0, 0, 1790964560080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cd04ef218d58a344', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who was the first father-in-law of Prophet Muhammad (S.A.W)?', '{"A":"Abu Bakar","B":"Khuwaylid","C":"Haris","D":"Hamza"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khuwaylid ibn Asad was a man of Banu Quraysh and mainly recognized for being the father of Khadijah bint Khuwaylid, the wife of the Islamic prophet Muhammad (PBUH).', 0, 0, 0, 1790964560080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_434baa22e7209d84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'In the History of Islam only sahabi without seeing Prophet:', '{"A":"Abu Ayyub al-Ansari","B":"Awais Karni","C":"Imam Bukhari","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Awais Karni (RA) in the history of Islam only sahabi without seeing Holy Prophet (ﷺ)...Awais Karni was born in Asir region of Saudi Arabia in 594CE. He was 28 years of age when the Holy Prophet (ﷺ) migrated to Madinah۔ND11-4-2023', 0, 0, 0, 1790964560080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2999d6a0c9dff3a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Where is the grave of Hazrat Dawood (علیہ)?', '{"A":"Israel","B":"Lebanon","C":"Syria","D":"Jordan","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Najibullah is the title of Hazrat Dawood (AS) The holy book Zaboor revealed to Hazrat Dawood (AS)Hazrat Dawood (AS) is buried in Israel.Hazrat Dawood is called caliph of Allah.Hazrat Dawood (AS) is mentioned in the Holy Quran for 16 times.Bani Israel unanimously acknowledged Hazrat Dawood A.S as their king*******VU CBT FIA PAPER 23-12-2021', 0, 0, 0, 1790964560080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9be4f785f24fa3c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', '_______ were the sons of Hazrat Ibrahim (AH).', '{"A":"Hazrat Haroon & Hazrat Yahya (A.S)","B":"Hazrat Haroon & Hazrat Ishaq (AH)","C":"Hazrat Ismail & Hazrat Haroon (AH)","D":"Hazrat Ismail & Hazrat Ishaq (AH)","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abraham (A.S) had two children, Hazrat Isaac and Hazrat Ismael, who both later became prophets.', 0, 0, 0, 1790964560080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7098bac3db4e0714', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The Holy Prophet (PBUH) started to preach openly in ……Nabvi.', '{"A":"4th Nabvi","B":"5th Nabvi","C":"6th Nabvi","D":"7th Nabvi"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet (PBUH) started to preach openly in the 4th Nabvi***The Holy Prophet (PBUH) first openly preached Islam on Jabil-e-Safa and addressed it after the conquest of Makkah in the same place.23 years did Hazrat Muhammad ﷺ preach Islam during his lifetimeHazrat Musab ibn Umair (RA was the first preacher of Islam appointed by Hazrat Muhammad ﷺ for the people of Madina', 0, 0, 0, 1790964560080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b641ad198a214915', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'What is relation between Hazrat Ibrahim and Hazrat Loot?', '{"A":"Nephew","B":"Uncle","C":"Brother","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Lut was the paternal nephew of Prophet Ibrahim.The grave of Prophet Lot is inside a mosque in Beni Naim village in West Bank.Ibrahim ibn Muhammad Dhu al-Hijjah 8 AH ; c. March/April 630 CEMedinaSH1--8-2023', 0, 0, 0, 1790964560164) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6302599d9089964b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who was the first caliph of after Holy Prophet', '{"A":"Hazrat Umar","B":"Hazrat Abu Bakar","C":"Hazrat Ali","D":"Hazrat Usman"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Who was the First Caliph?Hazrat Abu Bakar was the first caliph after Holy Prophet.Hazrat Abu Bakar remained Chalipha 8 June 632 – 23 August 634***Who was the second Caliph?Hazrat Umar(R.A.)***Who was the Third Caliph of Islam? Hazrat Usman(R.A.)***Who was the fourth Caliph? Hazrat Ali (R.A.)Hazrat Ali(R.A.) Caliph period from 656 till 661 CE***Which sahabi proposed the name of Hazrat Abu Bakr (R.A) for the first Caliphate of Islam?Hazrat Umar (R.A)ND10-3-2023', 0, 0, 0, 1790964560164) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c7793d8fe78436ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Hazrat Ibrahim (AS) is buried in_____?', '{"A":"Madina","B":"Makkah","C":"Iraq","D":"Jerusalem","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation important question : Namrud ordered throwing Hazrat Ibrahim (A.S) into the fireNimrod, the king of Babylon, commanded his men to throw Prophet Ibrahim (AS) into a huge pit of burning fireHazrat Ibrahim A.S remained on fire for 40 daysKhalil Ullah is the title of Hazrat Ibrahim (A.S)Hazrat Ibrahim is buried in Jerusalem, Israel. Hazrat Ibrahim (A.S) was born IraqHazrat Ibrahim''s (AH) name is mentioned in the Holy Quran 67 times.Abraham had two children,1. Isaac2. Ismael,****', 0, 0, 0, 1790964560164) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d78a675f2f8af230', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'At the age of 25 years the Holy Prophet (Peace be upon him) went in to a business trip to which country?', '{"A":"Syria","B":"Basra","C":"Damascus","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Prophet''s first business trip was to Syria at age 12 with his uncle Abu Talib (RA).During this journey, he met a monk named Bahira in Basra, Syria. Shab-e-Miraj refers to a separate miraculous night journey of Prophet Muhammad (PBUH', 0, 0, 0, 1790964560164) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3aa2ab9ca0e6cb7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'He would have been prophet. If I were not the last one, the prophet (PBUH) said this about', '{"A":"Hazrat Abu Bakr (RA)","B":"Hazrat Umar (RA)","C":"Hazrat Usma (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Umar (RA) was born in 583 ADFarooq was the title of Hazrat Umar (R.A.)At 27 age, Hazrat Umar (RA) embraced IslamHazrat Umar (RA) established Islamic calendar Hazrat Umar (RA) was established the department of Police, Education and Intelligence', 0, 0, 0, 1790964560164) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c4a8f2258f1110e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'The following prophet was the maternal grandfather of Hazrat Ayub (AS)', '{"A":"Hazrat Haroon (AS)","B":"Hazrat Loot (AS)","C":"Hazrat Musa (AS)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Loot (AS) was the maternal grandfather of Hazrat Ayub (AS)', 0, 0, 0, 1790964560164) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c8bd937ac2dd738a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Which incident took place on 24th September 622 AD in the life of Prophet Muhammad ﷺ?', '{"A":"He was attacked","B":"He fell ill","C":"He migrated to Madina","D":"He was stopped to travel","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On September 24, 622, the prophet Muhammad completes his Hegira, or “flight,” from Mecca to Medina to escape persecution.', 0, 0, 0, 1790964560164) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_isl_sahaba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Companions & Sahaba', 'top_islamic', 70, 1790964560219) ON CONFLICT(id) DO UPDATE SET total_mcqs = 70;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d1e314eda607a9a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Hamza is _________ of Muhammad (PBUH)?', '{"A":"Cousin","B":"Uncle","C":"Nephew","D":"Son"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Relationship: Paternal uncle of Prophet Muhammad (PBUH)Embraced Islam: 5th NabawiMartyred: Battle of Uhud on 22 March 625Title: Asadullah (Lion of Allah)Last updated by NA ON 16-09-2026', 0, 0, 0, 1790964560282) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e5a965912588f572', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'What is the name of the father of Hazrat Ayesha (R.A.)?', '{"A":"Hazrat Abu Bakr ( RA)","B":"Hazrat Umar (RA)","C":"Hazrat Usman (RA)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ayesha (R.A.), the beloved wife of Prophet Muhammad (PBUH)Father: Abu Bakr al-Siddiq (R.A.)Mother: Umm Rumman (R.A.)Death: 17 Ramadan, 58 AH (678 CE) at 67 yearsPlace: MadinahFuneral Prayer: Led by Abu Hurairah (R.A.) after Tahajjud.Last updated by NA on 23-April-2026', 0, 0, 0, 1790964560282) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1db98aa31a3d6d15', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Which companion was the first to accept Islam among men?', '{"A":"Hazrat Abu Bakr (RA)","B":"Hazrat Umar (RA)","C":"Hazrat Usman (RA)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Bakr (RA) was the first adult man to accept Islam.Additional information:First Woman: Khadijah bint Khuwaylid (RA)First Child: Ali ibn Abi Talib (RA)First Freed Slave: Zayd ibn Harithah (RA)First Slave: Bilal ibn Rabah (RA)Last verified on 07-07-2026', 0, 0, 0, 1790964560282) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_efad1b6ecfd4bf28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Usman Bin ____ was the key holder of Kabba', '{"A":"Talha","B":"Asad","C":"Saad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Key Keeper: Hazrat Usman bin Talha (RA)Family: Banu Abd al-DarThe Prophet (SAW) declared: The key was entrusted to his family permanently.This event took place after the Conquest of Makkah (8 AH / 630 AD).Last updated: 13-09-2026', 0, 0, 0, 1790964560282) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e7ffc1c9de8e72d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Sahabi is declared as Imam ul Fuqaha?', '{"A":"Hazrat Ali","B":"Abdullah Bin Abbas","C":"Maaz Bin Jabal","D":"None of These"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مُعاذ بن جبل was a sahabi (companion) of the Islamic prophet Muhammad.He was an Ansar of Banu Khazraj He compiled the Quran with five companionsOther names (إمام الفقهاء)(كنز العلماء) (أعلم الأمة بالحلال والحرام)', 0, 0, 0, 1790964560282) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4dba1e922f780c77', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'When Hazrat Ali (AS) shifted capital from Madina to Kufa?', '{"A":"657 CE (36 AH)","B":"658 CE (37 AH)","C":"659 CE (38 AH)","D":"669 AD"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali (R.A.) shifted the capital from Madina to Kufa in 657 AD (36 AH).The decision was made after the Battle of the Camel (Jang-e-Jamal).Kufa was chosen because of its strategic military and political importance.From Kufa, Hazrat Ali (R.A.) governed the Islamic state during his caliphate.Kufa remained the capital until his martyrdom in 661 AD (40 AH).He is buried in Najaf.Last verified on 30-04-2026', 0, 0, 0, 1790964560282) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a454217923199157', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'What was the real name of Hazrat Abu Bakr (R.A)?', '{"A":"Abdullah ibn Usman","B":"Abu Turab","C":"Sadiq e Akber","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The real name of Hazrat Abu Bakr (R.A.) was Abdullah ibn Usman.His father was Usman ibn Amir, commonly known as Abu Quhafa.As-Siddiq was his famous title.He was the first Caliph of Islam (632–634 AD).Last verified on 30-08-2026', 0, 0, 0, 1790964560282) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e1e7798d63922d08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Umar Farooq was martyred on 1st Muharram__________?', '{"A":"26 A.H.","B":"25 A.H.","C":"24 A.H.","D":"27 A.H.","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Umar Farooq was martyred on 1st Muharram 24 A.HDate of Attack: 26th Dhu al-Hijjah, 23 A.H.Date of Passing: 1st Muharram, 24 A.H.Attacker: Abu Lu''lu''a al-Majusi (Firoz)Place: Masjid an-Nabawi in Medina during the Fajr prayerPosition: 2nd Rashidun CaliphCaliphate: 13–24 AHAdditional informationThe wife of Prophet Muhammad (PBUH), Hazrat Hafsah (رضہ) was the daughter of Umar Farooq (R.A)Last updated 26-07-2026 by NA', 0, 0, 0, 1790964560282) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ed9f66f19cd29c1d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Name the Sahabi who narrated maximum number of Ahadis?', '{"A":"Hazrat Zaid bin Sabit R.A","B":"Hazrat Zaid bin Haris R.A","C":"Hazrat Abu Hurrairah R.A","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abd Ar-Rahman ibn Sakhr was a companion of Prophet Muhammad (PBUH).Known by the kunyah: Abu Hurairah.Most prolific narrator of Hadith, credited with 5,374 Hadiths.Born 603 CE in Al Jabour, Arabia (present-day Al Bahah, KSA).Died 681 CE in Medina, resting at Al-Baqi'', Medina.Last verified on 30-03-226', 0, 0, 0, 1790964560363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_66fc27efc9b9ea8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Why was Hazrat Umar (RA) given the title "Al-Farooq"?', '{"A":"Because he compiled the Holy Quran","B":"Because he migrated first to Madinah","C":"Because he distinguished between truth and falsehood","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Umar (RA) was given the title "Al-Farooq" because he distinguished between truth and falsehood.Al-Farooq means "the one who distinguishes between right and wrong."Second Caliph: 634–644 AD (13–23 AH)Predecessor: Hazrat Abu Bakr (RA)Successor: Hazrat Uthman (RA)Last verified on 19-07-2026', 0, 0, 0, 1790964560363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_065516574e815101', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Ali (R.A) was martyred in the city of?', '{"A":"Najaf","B":"Kufa","C":"Madina","D":"Karbala"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali (R.A) was martyred in the city of Kufa (Iraq) when he was attacked during Fajr prayer.He was struck by a poisoned sword on 19 Ramadan 40 A.H (661 CE).He passed away two days later on 21 Ramadan 40 A.H.He was the 4th Caliph of Islam.He was first Imam of Shia Muslims.His burial place is Najaf, Iraq.Last verified on 22-06-2026', 0, 0, 0, 1790964560363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_aa1ca529e6a94621', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Usman (RA) was martyred in ______?', '{"A":"23 Hijri","B":"30 Hijri","C":"35 Hijri","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Usman (R.A)BelongedQurayshBornMakkahCaliphThird caliphCaliphate23 to 35 HijjahCaliphate644 to 656 CETitlesZun-Noorain & Jame-al-QuranMartyred18th Zul-Hijjah 35 A.HMartyrdom dayFridayWivesRuqayyah (RA) & Umm-e-Kulthum (RA)Full NameUsman bin AffaanDeath causeMartyred by rebelsLast verified on 12-06-2026', 0, 0, 0, 1790964560363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9f254472a660dd82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'What was the duration of Hazrat Ali’s (R.A) Khilafat?', '{"A":"4 years","B":"3 years","C":"5 years (4 years and 9 months)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali (R.A) ruled as Caliph for about 4 years and 9 months (656–661 CE).His caliphate began in 35 AH (656 CE) after the martyrdom of Hazrat Uthman (R.A).It ended in 40 AH (661 CE) with his martyrdom in Kufa.Last verified on 10-06-2026', 0, 0, 0, 1790964560363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_575e702561b43d46', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Which tribe of Quraish, Hazrat Umar (R.A), belonged to?', '{"A":"Banu Addi","B":"Banu Hashim","C":"Banu Umayyah","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Umar (RA) belonged to the Banu Adi clan of Quraysh.He was the second Caliph of Islam.His caliphate lasted from 634 CE to 644 CE.He succeeded Hazrat Abu Bakr (RA).Last verified on 26-04-2026', 0, 0, 0, 1790964560363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_493d084a17f685c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'In how many provinces, Hazrat Umar (RA) divided the Muslim Empire for administrative purposes?', '{"A":"10","B":"12","C":"8","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790964560363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_376ad226413164fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Bilal (RA) was buried in?', '{"A":"Jannat-ul-Baqi","B":"Kufa","C":"Basra","D":"Damascus"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bilal ibn Rabah (R.A) was a famous companion of Prophet SAW.He was a first Mu’azzin of Islam.He was buried in Damascus (Syria).After the Prophet ﷺ, he migrated and spent his later life in Syria.He is remembered for his beautiful Azan and strong faith.The Prophet Muhammad ﷺ highly respected him and called him “Sayedina Bilal”.Last verified on 28-04-2026', 0, 0, 0, 1790964560363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_31580132398f7ec6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Salma (RA) was Hazrat Abu Bakr''s (RA) Mother. She was given the title?', '{"A":"Umm-e-Abdullah","B":"Umm-ul-Khair","C":"Umm-ul-Ayal","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Salma (RA) was the mother of Hazrat Abu Bakr (RA).She was honored with the title “Umm-ul-Khair”.The title means “Mother of goodness”.She supported her son and the mission of Islam.Hazrat Abu Bakr (RA) was the first Caliph of Islam.Last verified on 26-04-2026', 0, 0, 0, 1790964560433) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_514f0e760ffe7b46', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Asad Ullah is the title of which companion?', '{"A":"Hazrat Umar","B":"Hazrat Ali","C":"Hazrat Usman","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790964560433) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d57f6bfd67fbf7aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'In which year did Hazrat Umar (R.A) embrace Islam?', '{"A":"610 AD","B":"612 AD","C":"616 AD","D":"620 AD"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Umar (R.A) embraced Islam in 616 AD at the age of 32 years.This was the 6th year of Prophethood (6 Nabvi).He accepted Islam after hearing verses of Surah Taha.He later became the second Caliph (634–644 AD).Last verified on 02-04-2026', 0, 0, 0, 1790964560433) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_db6dd34881a7e232', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Ali (RA) belongs to which tribe?', '{"A":"Banu Hashim","B":"Banu Khazeema","C":"Banu Asad","D":"Banu Atiyah"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali ibn Abi Talib was a close companion, cousin, and son-in-law of Prophet Muhammad.He belonged to the Banu Hashim clan of Quraish tribe in Makkah.He was known as Abu Turab and Asadullah (Lion of Allah).He ruled as the 4th Caliph (656–661 AD) andHe was martyred in 661 AD.Last verified on 25-04-2026', 0, 0, 0, 1790964560433) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a4fdf6d3baed9012', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Ali (R.A) was martyred in which month of Islamic calendar?', '{"A":"Ramazan","B":"Shawal","C":"Rajab","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali (R.A) was poisoned by a sword. On 19th Ramazan 40th HijriBefore the time of the FAJAR prayers to the mosque of Kufa.He was buried in Najaf al-Ashraf (Iraq).***', 0, 0, 0, 1790964560433) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a36221affa98fda6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Who was the mother of Hazrat Usman (RA)?', '{"A":"Hazrat Arwa (RA)","B":"Hazrat Atiqah (RA)","C":"Hazrat Asma (RA)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Usman (RA), also known as Uthman ibn Affan.He was a companion of the Prophet Muhammad (PBUH).He was the third caliph of Islam.His mother was Arwa bint Kurayz (Arvi).His father was Affan ibn Abi al-Asad.Last verified on 19-03-2026', 0, 0, 0, 1790964560433) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e2dd7cb7c8c59719', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Usman (R.A) was martyred at the age of _____?', '{"A":"82","B":"60","C":"75","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Usman (R.A)BelongedQurayshBornMakkahCaliphThird caliphCaliphate23 to 35 HijjahCaliphate644 to 656 CETitlesZun-Noorain & Jame-al-QuranMartyred18th Zul-Hijjah 35 A.HMartyrdom dayFridayWivesRuqayyah (RA) & Umm-e-Kulthum (RA)Full NameUsman bin AffaanDeath causeMartyred by rebelsLast verified on 18-03-2026', 0, 0, 0, 1790964560433) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_75012b2eb90cdf60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Which servant of Hazrat Khadija was alongside Hazrat Muhammad SAW during a business trip?', '{"A":"Zonair","B":"Maisra","C":"Kameera","D":"Sebalitah"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During Prophet Muhammad ﷺ’s early business trips for Hazrat Khadija (RA), he was often accompanied by trusted servants.Maisra was the servant who traveled with him and helped manage trade and goods safely.These trips helped build Prophet ﷺ’s reputation for honesty and trustworthiness.Last verified on 01-02-2026', 0, 0, 0, 1790964560433) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7b0202ed5b1db172', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Ali (R.A) was martyred in __________ Hijrah?', '{"A":"36","B":"38","C":"40","D":"42"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali (R.A) was attacked with a poisoned sword On 19th Ramazan 40th Hijri,before the time of FAJAR prayers to the mosque of Kufa.He died on the 21st of Ramadan 40 A.H or 28 January 661 CE.He was buried in Najaf al-Ashraf (Iraq).***', 0, 0, 0, 1790964560530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_774d9640a93d9d36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'What the period of Hazrat Usman (RA) as third caliph of Islam?', '{"A":"4 years","B":"8 years","C":"10 years","D":"12 years"}', 'D', NULL, 0, 0, 0, 1790964560530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_839a26dcdcc92d20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Khalid Bin Waleed (RA) embraced Islam in which Hijri?', '{"A":"8th A.H","B":"7th A.H","C":"9th A.H","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Conversion to Islam and service under Muhammad. In the year 8 AH ( c. 629) Khalid embraced Islam in Muhammad''s presence alongside the Qurayshite Amr ibn al-As; the modern historian Michael Lecker comments that the accounts holding that Khalid and Amr converted in 8 AH are "perhaps more trustworthy".', 0, 0, 0, 1790964560530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8d17850318c0902d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'What is the title of Hazrat Ali (RA)?', '{"A":"Haider","B":"Siddique","C":"Ghani","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Haider is one of the titles of Hazrat Ali (RA).It means "Lion" and reflects his bravery and valor in various battles.', 0, 0, 0, 1790964560530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_86f0fa52981ec6a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Who freed Hazrat Bilal (RA) from slavery?', '{"A":"Hazrat Abu Bakr (RA)","B":"Hazrat Umar (RA)","C":"Hazrat Usman (RA)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Bakr (RA) freed Hazrat Bilal (RA) from slavery.Bilal (RA) was a slave of Umayyah ibn Khalaf, a harsh master who tortured Bilal for embracing Islam.Abu Bakr (RA) purchased and freed Bilal, who later became a prominent companion of the Prophet Muhammad (SAW) and a renowned mu''adhin (caller to prayer).', 0, 0, 0, 1790964560530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cde2567df5367296', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'When Hazrat Abu Bakr (RA) the Caliph?', '{"A":"631 CE","B":"632 C.E","C":"635 C.E","D":"637 C.E"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Caliphate EraAbu Bakr – 11–13 Hijri/ A.D. 632–634Umar ibn al-Khattab – 13–23 Hijri / A.D. 634–644Uthman ibn ‘Affan – 23–35 Hijri / A.D. 644–656Ali ibn Abi-Talib – 35–40 Hijri / A.D. 656–66', 0, 0, 0, 1790964560530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_27e17004469e1c1d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Khadija belonged to the tribe of ___?', '{"A":"Banu Asad","B":"Banu Khazeema","C":"Banu Hashim","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790964560530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c1f3bf206fedffa2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Umar (RA) tenure of Khilafat was _____?', '{"A":"4 years 5 month","B":"7 years 5 month","C":"10 years 5 month","D":"12 years 5 month"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ʿUmar ibn al-Khaṭṭāb was the second Rashidun caliph, ruling from August 634 until his assassination in 644.', 0, 0, 0, 1790964560530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f31160945124daf8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'When was Hazrat Ali (R.A) martyred?', '{"A":"19 Ramzan 40 A.H","B":"21 Ramzan 40 A.H","C":"23 Ramzan 40 A.H","D":"25 Ramzan 40 A.H"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali (R.A) was attacked with a poisoned sword On 19th Ramazan 40th Hijri,before the time of FAJAR prayers to the mosque of Kufa.He died on the 21st of Ramadan 40 A.H or 28 January 661 CE.He was buried in Najaf al-Ashraf (Iraq).', 0, 0, 0, 1790964560617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e8b38810ca1d4e54', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'What is the tittle of Hazrat khadija?', '{"A":"Ameerat-Quraysh al-Tahirah","B":"Khadīja al-Kubra","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Khadija (RA) is commonly regarded by Muslims as the Mother of the MuslimsKhadijah bint Khuwaylid(R.A), was the first wife and first follower of the Islamic prophet MuhammadﷺKhadijah married three times and had children from all her marriages.1. she first married Atiq ibn ''A''idh ibn'' Abdullah Al-Makhzumi2. Second Malik ibn Nabash ibn Zargari ibn at-Tamimi.3. Third Muhammad ﷺ***Hazrat Khadija''s (رضہ) Father''s name was Khuwaylid ibn Asad and her mother''s name was Fatima bint za’idah.', 0, 0, 0, 1790964560617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dcd7ca25ee824295', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'When did Hazrat Hamza embraced Islam?', '{"A":"Seventh Nabvi","B":"Sixth Nabvi","C":"Fifth Nabvi","D":"Eighth Nabvi"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Hamza, the uncle of Hazrat Muhammad (PBUH).He embraced Islam in the sixth Nabvi year (616 CE).He was martyred in the Battle of Uhud on 22 March 625 at Mount Uhud, Medina.', 0, 0, 0, 1790964560617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9aa844b60dd51b28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Which companion narrated the most number of Hadith?', '{"A":"Hazrat Umar (R.A)","B":"Hazrat Abu Bakr (R.A)","C":"Hazrat Anas Bin Malik (R.A)","D":"Hazrat Abu Hurairah (R.A)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Hurairah (R.A) narrated the most number of Hadith, with over 5374 Hadiths attributed to him.He was a close companion of Prophet Muhammad (PBUH) and dedicated much of his life to preserving the Prophet''s teachings.', 0, 0, 0, 1790964560617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3baaba149d5c0bd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Where is Hazrat Ayesha (R.A) buried?', '{"A":"Makkah","B":"Jannat-ul-Baqi","C":"Jerusalem","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790964560617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0d5a95d00bc57dde', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Who killed Hazrat Umar (RA)?', '{"A":"Abdul Rehman Ibn Maljam","B":"Abu Lulua Firuz","C":"Quresh Makkah","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Umar was assassinated by the Persian slave Abu Lulua Firuz.He was martyred on 24 A.H 1st Muharram at the age of 60-61 years.He was the second Rashidun caliph, ruling from 13 to 24 Hijri.The wife of Prophet Muhammad (PBUH) Hazrat Hafsah (رضہ) was the daughter of Umar Farooq (R.A).', 0, 0, 0, 1790964560617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_eb571f8935efcb75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Khadijat ul Kubra is buried at ?', '{"A":"Mecca","B":"Madina","C":"Jannat-ul-Baqee","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790964560617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0ffe82e320c208ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Name the woman, after Hazrat Khadija (RA) who embraced Islam?', '{"A":"Hazrat Labala bint Haris","B":"Hazrat Ayesha","C":"Umm e Habiba","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lubaba bint Haris (R.A) was the second woman to convert to Islam, on the same day as Khadijah (R.A).Lubaba belonged to the Hilal tribe.', 0, 0, 0, 1790964560617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_02236032e98b37a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Name the sister of Hazrat Umar (R.A.) who first accepted Islam?', '{"A":"Khadija","B":"Fatima","C":"Ayesha","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fatima bint al-Khattab was a Companion of the Islamic prophet Muhammad. She was the sister of Umar ( r. 634–644) and Zayd ibn al-Khattab.', 0, 0, 0, 1790964560699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cc139e9a68245d77', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Which book written by The book attributed to Hazrat Ali R.A?', '{"A":"Nehjul  Balagha","B":"Siah Bukhari","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nahj al-balagha is the best-known collection attributed to Ali ibn Abi Talib It was compiled by al-Sayyid al-Radi in the late 4th/10th century (finished in 400/1009-10).', 0, 0, 0, 1790964560699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_94049580660eb999', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'The name of Hazrat Bilal''s (R.A) master was ______ ?', '{"A":"mutim bin Adi","B":"Abdullah bin Rawaha","C":"Umayyah bin Khailf","D":"Sohail bin Amro"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Bilal''s (R.A) master was Umayyah bin KhailfBilal was known for his hard work and loyalty to his master, Umayyah ibn KhalafUmayya ibn Khalaf was an Arab slave master ***Bilal''s mother was abducted as a child and sold as a slave.He was also the first muezzin (prayer caller) in the Muslim faith.The Title of Bilal ibn Rabah: Sayyid al-MuaddinHe was Born: 580 AD, MeccaHe was Died: on March 2, 640 AD, in Damascus, SyriaHis Place of burial is Bab el Saghir Cemetery, Damascus, Syria', 0, 0, 0, 1790964560699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0e15702cd634cb3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Which punishment was introduced by Hazrat Umar (RA)?', '{"A":"Exile","B":"Death","C":"Imprisonment","D":"Cutting of hands"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During the caliphate of Hazrat Umar (RA), imprisonment was introduced as a punishment for certain crimes.Prior to this, punishments were largely limited to fines, lashes, or death.', 0, 0, 0, 1790964560699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dd22a817ab1dcfde', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'What was the cause of death of Hazrat Usman (RA)?', '{"A":"Martyred by rebels","B":"Died in battlefield","C":"Natural Death","D":"None of the above"}', 'A', NULL, 0, 0, 0, 1790964560699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dffd566b505599fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'When Hazrat Umar conquered Bait Ul Maqdas in ____ A.H.', '{"A":"16 A.H","B":"13 A.H","C":"8 A.H","D":"4 A.H"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Umar ibn Abd al-Aziz, commonly known as Umar II, was the eighth Umayyad caliphUmar ibn Abd al-Aziz called the first Mujaddidand sixth righteous caliph of Islam after Hasan Ibn AliUmar ibn Abd al-Aziz was Born 2 November 682 in Medina, Umayyad CaliphateDied 5 February 720 (aged 37)Hazrat Umar conquered Bait Ul Maqdas in 16 A.H.ND18-5-2023', 0, 0, 0, 1790964560699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5f14d21738421579', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'First Mujadid was Hazrat Umar bin Abdul Aziz. Who was the second one?', '{"A":"Ahmad Sirhindi","B":"Imam Ghizali","C":"Ibn-e-Taimya","D":"Shah Waliullah","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aḥmad al-Fauqi al-Sirhindi is second is a second MujahidHe is also known as Imam RabbaniHe was born on 26 June 1564 died on 10 Dec 1624.He is also known as Mujadad Alf-Sani.Additional informationUmar ibn Abd al-Aziz, commonly known as Umar IIHe was the eighth Umayyad caliphHe called the first MujaddidHe was born 2 November 682 in MedinaDied on 5 February 720 Hazrat Umar conquered Bait Ul Maqdas in 16 A.H.ND18-5-2023', 0, 0, 0, 1790964560699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_86d98d827a06d090', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'For how long, was the caliphate of Hazrat Usman (RA) tested?', '{"A":"6 years","B":"8 years","C":"10 years","D":"12 years"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Caliph Uthman ruled for a total of twelve years between 644 and 656. This made him the longest reigning caliph out of the Rashidun CaliphsHazrat Usman (R.A)BelongedQurayshBornMakkahCaliphThird caliphCaliphate23 to 35 HijjahCaliphate644 to 656 CE(12 year)TitlesZun-Noorain & Jame-al-QuranMartyred18th Zul-Hijjah 35 A.HMartyrdom dayFridayWivesRuqayyah (RA) & Umm-e-Kulthum (RA)Full NameUsman bin AffaanDeath causeMartyred by rebels', 0, 0, 0, 1790964560699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_00020e2d705621c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Umar (RA) was Caliph for______years.', '{"A":"10 years","B":"4 years","C":"2 years","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Umar ibn al-Khattab was the second caliph of Islam.He was ruled for 10 years from 634 CE to 644 CE.He succeeded Hazrat Abu Bakr.He was instrumental in expanding the Islamic state.', 0, 0, 0, 1790964560770) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_346ff9c44f0bd6a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Which Sahabi was known as Brain of Arab?', '{"A":"Hazrat Amr bin Al-Aas","B":"Hazrat Khalid bin Walid","C":"Hazrat Umar Farooq","D":"Hazrat Ameer Hamza"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Holy Prophet (PBUH) gave the title Brain of Arab to Hazrat Amr bin al-Aas R.A.Hazrat Amr bin Al-Aas was the Arab commander.He led the Muslim conquest of Egypt.He served as Egypt''s governor in 640–646 and 658–664.Hazrat Amr bin Al-Aas embraced Islam in 629 AD.He was Born: 573 AD Mecca, Hejaz.He was Died: 664 AD (aged 90–91) Egypt, Umayyad Caliphate.', 0, 0, 0, 1790964560770) ON CONFLICT(id) DO NOTHING;
