INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d2e5d74d99b9341c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Ali (R.A) martyred at the age of __________.', '{"A":"67","B":"60","C":"28","D":"55","E":"70"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali (R.A) was attacked with a poisoned sword On 19th Ramazan 40th Hijri,before the time of FAJAR prayers to the mosque of Kufa.He died on the 21st of Ramadan 40 A.H or 28 January 661 CE.He was buried in Najaf al-Ashraf (Iraq).******ND03-12-2022RY29012023ND23-2-2023', 0, 0, 0, 1790964560829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1b9868bbe0293546', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Who was the first companion to be buried in Jannatul Baqi?', '{"A":"Aisha","B":"Asad Bin Zararah","C":"Safiyyah Bint Abdul Mutalib","D":"Uthman Vin Mazourn"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Uthman Ibn Madhoon died on the 3rd of Sha''ban in the 3rd year of Hijrah.The first companion buried in Al-Baqi was Uthman Ibn Madhoon He was considered the first companion of Muhammad (PBUH) from the Muhajirun to be buried in the cemetery.whileHazrat Khadija (RA) was the only Ummul Momineen who was not buried in Jannatul Baqi.ND21-2-2023', 0, 0, 0, 1790964560829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_31aecfab0cb19b97', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Khalid Bin waleed died in:', '{"A":"642 AD","B":"625 AD","C":"580 AD","D":"535 AD"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khalid Ibn Al-Walid died in 642 was buried in Homs, Syria.Place of birth: MeccaPlace of death: Khaled Ibn Walid Mosque, Medinaburied in Homs, Syria.Hazrat Khalid Bin Waleed (RA) embraced Islam in 8th A.HHijriThe name of the horse of Hazrat Khalid bin Waleed was AshjarND29-5-2023', 0, 0, 0, 1790964560829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_91c572444204c3a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Khadija and Hazrat Abu Talib died in?', '{"A":"620 A.D","B":"619 A.D","C":"618 A.D","D":"617 A.D","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Khadijah died in Ramadan of the year 10 after the Prophethood, i.e., in November AD 619, Prophetﷺ uncle and protector Abu Talib died same year. Muhammad later called this tenth year the Year of Sorrow,', 0, 0, 0, 1790964560829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_771bf0221eda12e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Qamoos temple was conquered by Hazrat Ali (R.A) during which war?', '{"A":"Battle of Badr","B":"Battle of Camel","C":"Battle of Khaybar","D":"Battle of Tabbok"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Khaybar was fought in the year 628 between Muslims and the Jews living in the oasis of Khaybar, located 150 kilometers (93 mi) from Medina, Saudi Arabia. This battle was fought in Sevent Hijri.Muslims won the battle.', 0, 0, 0, 1790964560829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5c4f8566e357b286', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Umar was born on  which hijri?', '{"A":"1st Muharram 22 A.H","B":"1st Muharram 23 A.H.","C":"584 AD","D":"1st Muharram 25 A.H."}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He (RA) was born in 584 ADHe embraced martyrdom on 1st Muharram 23 AH.Hazrat Umar Farooq was martyred on 24 A.H 1st Muharram****Full name: Umar ibn Al-KhattābHe was the second Rashidun caliph, ruling from August 634 until his assassination in 644 (13 to 24 Hijri).The wife of Prophet Muhammad (PBUH) Hazrat Hafsah (رضہ) was the daughter of Umar Farooq (R.A)', 0, 0, 0, 1790964560829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5c3d76d38ac0c857', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'What is the title of Hazrat Usman?', '{"A":"Compiler of Quran","B":"Sword of Allah","C":"Lion of Allah","D":"Kalimullah","E":"None of these"}', 'A', NULL, 0, 0, 0, 1790964560829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2f9316cc51a465ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'After Hazrat Umar to whom lady ,script of Musaef Abu Bakar wa handed over ? _____?', '{"A":"Hazrat Ayesha","B":"Hazrat Hifsa","C":"Hazrat Safia","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During the 23 years of Muhammad''s time as a prophet, the verses of the Quran were memorized as they were revealed, and about 42 scribes wrote the verses on different materials such as paper, cloth, bone fragments and leather.The Quran collected between two binders by Abu Bakr was transferred to Umar after he died.After Umar died, it was transferred to his daughter Hazrat Hifsa', 0, 0, 0, 1790964560829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_45810badc9684574', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Abu Bakr Siddiq (R.A.) caliphate Era is from _____ Hijri ?', '{"A":"11 to 12 Hijri","B":"11 to 13 Hijri","C":"11 to 14 Hijri","D":"11 to 15 Hijri"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Caliphate EraAbu Bakr – 11–13 Hijri/ A.D. 632–634Umar ibn al-Khattab – 13–23 Hijri / A.D. 634–644Uthman ibn ‘Affan – 23–35 Hijri / A.D. 644–656 Ali ibn Abi-Talib – 35–40 Hijri / A.D. 656–66RK120223', 0, 0, 0, 1790964560914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0f01729b9836173a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Who did Hazrat Khadija (RA) send to ask Hazrat Muhammad ﷺ about marrying her?', '{"A":"Brother","B":"Mother","C":"Father","D":"Friend","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Friend of Khadija (رضہ) Nafeesa carried the message of Nikah.At the time of the marriage, Hazrat Khadijah was 40 years old. Muhammad was 25 years old.Hazrat Khadija was the first wife of Prophet Muhammad ﷺ Additional InformationShe belonged to the tribe of Banu AsadShe married Three times in life.She was the daughter of Khuwaylid ibn Asad and Fatima bint ZaidahHazrat Khadija (R.A) Died on 10 Ramadan BH 3 MeccaShe passed away when she was 65 and Prophet Muhammad ﷺ was 50 years old.She was buried in Jannat al-Mualla, Mecca', 0, 0, 0, 1790964560914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_12be93bb043baf0b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Hazrat Khadija (RA) is commonly regarded by Muslims as the _______.', '{"A":"Mother of the Muslims","B":"Mother of all Females","C":"Mother of the Universe","D":"Mother of Islam","E":"None of these"}', 'A', NULL, 0, 0, 0, 1790964560914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_69614c30c748a64f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'How many daughters Hazrat Khadija (RA) had with Hazrat Muhammad ﷺ?', '{"A":"One","B":"Three","C":"Two","D":"Four","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Holy Prophet had Four Daughters from Hazrat Khadija.Hazrat Zainab (married to Abual Bin Aas Bin Rabbi)Hazrat Ruqayah (married to Hazrat Usman bin Affan)Hazrat Umme Kalsoom (married with Hazrat Usman bin Affan after the death of Hazrat Ruqayah)Hazrat Fatima (married to Hazrat Ali)Additional Information:Prophet Muhammad ﷺ had three sons Hazrat Qasim Hazrat AbdullahHazrat Ibrahim All of his children were born to Hazrat Khadijah (RA) except one son Ibrahim, who was born to Hazrat Maria al-Qibtiyah (RA).', 0, 0, 0, 1790964560914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f29840576706f9a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'Who was the slave of Hazrat Khadija?', '{"A":"Mysra","B":"Bilal","C":"Both","D":"None"}', 'A', NULL, 0, 0, 0, 1790964560914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f48da042c0677443', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_sahaba', 'What was the age of Hazrat Khadija (RA) when married to Hazrat Muhammad ﷺ?', '{"A":"20","B":"30","C":"35","D":"40","E":"45"}', 'D', NULL, 0, 0, 0, 1790964560914) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_isl_khulafa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Khulafa-e-Rashideen', 'top_islamic', 17, 1790964560974) ON CONFLICT(id) DO UPDATE SET total_mcqs = 17;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ec08647a20ebe56e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'When is the first caliph in the Umayyad dynasty?', '{"A":"Hazrat Usman (R.A)","B":"Hazrat Muawiya (R.A)","C":"Hazrat Umar bin Abdul Aziz (R.A)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Umayyad Caliphate was founded by Muawiya I,Reign: 661–680 ADStart of Rule: After the end of the First Muslim Civil War and a peace treaty with Hasan ibn Ali.Moved the Caliphate’s capital to Damascus, SyriaAdditional information:Umayyad Dynasty started: 661 ADUmayyad Dynasty ended: 750 ADLast Caliph: Marwan II (744–750 AD)Last updated NA on 10-09-2026', 0, 0, 0, 1790964561060) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3583b8610023d15e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'Hazrat Abu Bakr (RA), the first Khalifa (Caliph) ruled for approximately how many years (duration)?', '{"A":"Two","B":"Three","C":"Four","D":"Five"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Bakr (RA), the first Caliph of Islam, ruled for approximately 2 years (2 years, 2 months, and 14 days).His caliphate lasted from 8 June 632 CE to 23 August 634 CE.He became the first Caliph after the death of Prophet Muhammad (ﷺ).He passed away due to illness in August 634 CE.Additional information:Umar ibn al-Khattab: 10 years, 6 months, and 4 daysUthman ibn Affan: 11 years, 11 months, and 18 daysAli ibn Abi Talib: 4 years, 9 months, and 7 daysLast verified on 07-07-2026', 0, 0, 0, 1790964561060) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d870519a651558c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'Egypt was conquered during the caliphate of which Caliph?', '{"A":"Hazrat Abu Bakr (RA)","B":"Hazrat Umar (RA)","C":"Hazrat Usman (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Caliph: Hazrat Umar ibn al-Khattab (RA) (634–644 AD)Commander: Amr ibn al-Aas (RA)Conquest Period: 640–642 AD (19–21 AH)Key Victory: Capture of Babylon Fortress (641 AD)Capital Established: Fustat (641 AD), the first Islamic capital of Egypt.Last verified on 20-07-2026', 0, 0, 0, 1790964561060) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_46e513c7839717ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'Which Muslim Caliph had all his four sons caliph too?', '{"A":"Hazrat Umar (RA)","B":"Abdul Malik bin Marwan","C":"Hazrat Abu Bakr (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abdul Malik bin Marwan (5th Umayyad Caliph)Reign: 12 April 685 – 9 October 705Had 4 sons who became Caliphs:Al-Walid I (705–715 CE)Sulayman (715–717 CE)Yazid II (720–724 CE)Hisham (724–743 CE) Last updated 17 july 2026 by NA', 0, 0, 0, 1790964561060) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1c9df0f17aaaa145', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'During the Orthodox Caliphate, who had the longest tenure?', '{"A":"Hazrat Ali (RA)","B":"Hazrat Usman (RA)","C":"Hazrt Umar (RA)","D":"Hazrat Abu Bakr Siddique (RA)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Usman (RA) had the longest tenure among the Rashidun (Orthodox) Caliphs.Additional information:Abu Bakr – 632–634 CE (2 years - Shortest Tenure)Umar ibn al-Khattab – 634–644 CE (10 years)Uthman ibn Affan – 644–656 CE (12 years - Longest Tenure)Ali ibn Abi Talib – 656–661 CE (5 years)Hasan ibn Ali – 661 CE (about 6 monthsLast verified on 03-07-2026', 0, 0, 0, 1790964561060) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_89e0b9a11d763335', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'Who was the second Caliph?', '{"A":"Hazrat Usman (R.A.)","B":"Hazrat Umar (R.A.)","C":"Hazrat Ali (R.A.)","D":"Hazrat Abu Bakar (R.A.)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Four Caliphs of Islam:Hazrat Abu Bakr (R.A.) → First Caliph (632–634 CE)Hazrat Umar (R.A.) → Second Caliph (634–644 CE)Hazrat Usman (R.A.) → Third Caliph (644–656 CE)Hazrat Ali (R.A.) → Fourth Caliph (656–661 CE)Last verified on 30-06-2026', 0, 0, 0, 1790964561060) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_144c2e5a6f9199b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'Apostasy movement took place in the khilafat of Hazrat _____?', '{"A":"Hazrat Abu Bakr (R.A)","B":"Hazrat Umar (R.A)","C":"Hazrat Usman (R.A)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Apostasy (Ridda) Movement took place during the Khilafat of Hazrat Abu Bakr (R.A).After the death of Prophet Muhammad (PBUH), some tribes refused to pay Zakat and left Islam.Hazrat Abu Bakr (R.A) launched campaigns to bring unity in the Muslim Ummah.He successfully suppressed all apostate tribes.Last verified on 25-04-2026', 0, 0, 0, 1790964561060) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fa29d7e95dbfaf1d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'Who was the first Caliph of Islam?', '{"A":"Hazrat Umar (R.A.)","B":"Hazrat Ali (R.A.)","C":"Hazrat Usman (R.A.)","D":"Hazrat Abu Bakar (R.A.)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Caliph: Hazrat Abu Bakr (June 8, 632 – August 23, 634)Second Caliph: Hazrat Umar (R.A.)Third Caliph: Hazrat Usman (R.A.)Fourth Caliph: Hazrat Ali (R.A.) (656–661 CE)Sahabi who proposed Hazrat Abu Bakr for the Caliphate: Hazrat Umar (R.A.)Last verified on 13-03-2026', 0, 0, 0, 1790964561060) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7c8b8d7c26801aa4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'Who among the Pious Caliphs (Khulfa-e-Rasheen) died a natural death?', '{"A":"Hazrat Abu Bakr (R.A","B":"Hazrat Ali ( R.A)","C":"Hazrat Usman( R.A)","D":"Hazrat Umar (R.A)"}', 'A', NULL, 0, 0, 0, 1790964561139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_06d16d0674cce88e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'Pious-Caliphate lasted for about:__________ Years?', '{"A":"30 years","B":"40 years","C":"50 years","D":"None"}', 'A', NULL, 0, 0, 0, 1790964561139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_be8a0e83a379d0c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'What city was the capital city of the Umayyad Caliphate?', '{"A":"Jerusalem","B":"Baghdad","C":"Damascus","D":"Mecca"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Capitals: Damascus, HarranGovernment: MonarchyCurrencies: Dirham, Gold dinar, Fals______________________________________The Umayyad Caliphate was the second of the four major caliphates established after the death of Hazrat Muhammad (PBUH)', 0, 0, 0, 1790964561139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dcadac7ba9ad9a09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'When was Baitul Muqaddas conquered during Rashidun Caliphate?', '{"A":"635 AD (13th Hijir)","B":"636 AD (14th Hijri)","C":"637 AD (15th Hijri)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Umar ibn Abd al-Aziz, commonly known as Umar II, was the eighth Umayyad caliph.Umar ibn Abd al-Aziz called the first Mujaddid.He was sixth righteous caliph of Islam after Hasan Ibn Ali.Umar ibn Abd al-Aziz was born on 2 November 682 in Medina, Umayyad Caliphate.Died on 5 February 720 (aged 37)Hazrat Umar conquered Bait Ul Maqdas in 15 A.H.', 0, 0, 0, 1790964561139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_38c7745f3a1fea05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'Who was the fourth Caliph?', '{"A":"Hazrat Usman (R.A.)","B":"Hazrat Ali (R.A.)","C":"Hazrat Umar (R.A.)","D":"Hazrat Abu Bakar (R.A.)","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Who was the First Caliph?Hazrat Abu Bakar was the first caliph after Holy Prophet.Hazrat Abu Bakar remained Chalipha 8 June 632 – 23 August 634***Who was the second Caliph?Hazrat Umar(R.A.)***Who was the Third Caliph of Islam? Hazrat Usman(R.A.)***Who was the fourth Caliph? Hazrat Ali (R.A.)Hazrat Ali(R.A.) Caliph period from 656 till 661 CE***Which sahabi proposed the name of Hazrat Abu Bakr (R.A) for the first Caliphate of Islam?Hazrat Umar (R.A)ND10-3-2023', 0, 0, 0, 1790964561139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b1121632e67770db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'The Rashidun Caliphate lasted for ______?', '{"A":"30 years","B":"40 years","C":"50 years","D":"10 years"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Rashidun Caliphate (Hazrat AbuBakr, Hazrat Umar, Hazrat Usman, Hazrat Ali رضی اللہ) lasted for 30 years from 632 CE to 661 CE. Name Period Total Time Rashidun Dynasty A.H. 11–40 / A.D. 632–661 30 years Abu Bakr A.H. 11–13 / A.D. 632–634 2 years ''Umar ibn al-Khattab A.H. 13–23 / A.D. 634–644 10 years ''Uthman ibn ''Affan A.H. 23–35 / A.D. 644–656 12 years ''Ali ibn Abi-Talib A.H. 35–40 / A.D. 656–661 5 years Umayyad Dynasty A.H. 41–132 / A.D. 661–750 91 years', 0, 0, 0, 1790964561139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_62a84f2760fffffb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'The Umayyad Caliphate was overthrown in 751 A.D by Abbasids after the ____?', '{"A":"Battle of Islam","B":"Battle of Arabs","C":"Battle of Tribes","D":"Battle of Zab"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Umayyad Caliphate was overthrown in 750/751 ADAbbasids defeated the Umayyads in the Battle of the ZabBattle of the Zab is also known as the Battle of the Great Zab River Battle of the Zab (750 AD): The Abbasid forces, led by Abu al-Abbas al-Saffah, Defeated the army of the last Umayyad caliph, Marwan II.Abbasid Revolution (747–750 AD): The revolution began in 747 in Khorasan, Fueled by non-Arab Muslims (Mawali) and Shia supporters against Umayyad rule.****Last updated by NS on 01 MAY 2026', 0, 0, 0, 1790964561139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4584f9a8cdfb5d98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'Who was the Third Caliph of Islam?', '{"A":"Hazrat Usman(R.A.)","B":"Hazrat Ali(R.A.)","C":"Hazrat Umar(R.A.)","D":"Hazrat Abu Bakar(R.A.)","E":"None of these"}', 'A', NULL, 0, 0, 0, 1790964561139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7e553e7d28416b6c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_khulafa', 'Banu Abbas Khilafat ended in which hijri ?', '{"A":"656 hijri","B":"658 hijri","C":"660 Hijri","D":"666 hijri"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Abbasid dynasty or Abbasids were an Arab dynasty that ruled the Abbasid Caliphate between 750 and 1258. They were from the Qurayshi Hashimid clan of Banu Abbas, descended from Abbas ibn Abd al-Muttalib. Abbasid dynasty by the Mongols under Hulagu KhanAl-Mustaʿṣim, (born 1212—died 1258), the last ʿAbbāsid caliph in BaghdadThe first Abbasid caliph, Abu al-ʿAbbas al-Saffah,', 0, 0, 0, 1790964561195) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_isl_hadith', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Hadith & Fiqh', 'top_islamic', 35, 1790964561257) ON CONFLICT(id) DO UPDATE SET total_mcqs = 35;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_97ad916be660d5d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Siha-e-Sitta are ______ books of Hadith.', '{"A":"Two","B":"Three","C":"Five","D":"Six"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Siha-e-Sitta (Sihah al-Sittah) are the six authentic books of Hadith in Sunni Islam.Sahih al-Bukhari – Compiled by Imam Muhammad al-Bukhari – 7,275 Ahadith.Sahih Muslim – Compiled by Imam Muslim ibn al-Hajjaj – 9,200 Ahadith.Sunan al-Nasa''i – Compiled by Imam al-Nasa''i – 5,270 Ahadith.Sunan Abi Dawud – Compiled by Imam Abu Dawood – 4,800 Ahadith.Jami'' al-Tirmidhi – Compiled by Imam al-Tirmidhi – 3,956 Ahadith.Sunan Ibn Majah – Compiled by Ibn Majah – 4,000 Ahadith.Last verified on 07-07-2026', 0, 0, 0, 1790964561344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2c1ff4331187ac48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'In the books of Islamic Jurisprudence, Law of Inheritance is called?', '{"A":"Ilm Ul Figh","B":"Ilm Ul Arooz","C":"Ilm Ul Faraid","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Law of Inheritance in Islamic Jurisprudence: Ilm-ul-Faraid (علمُ الفرائض)Also called: Faraid (فرائض)Meaning: Islamic law governing inheritance and the distribution of property', 0, 0, 0, 1790964561344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6c3bd2190942ac3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'What is the literal meaning of Ijtihad?', '{"A":"Consensus","B":"Attempt","C":"Law","D":"Power"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ijtihad is an important concept in Islamic jurisprudence (Fiqh).It refers to using independent reasoning to derive Islamic rulings.It is used when clear guidance is not found in the Quran or Sunnah.Root word: J-H-D (effort / struggle).Last verified on 09-05-2026', 0, 0, 0, 1790964561344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5782a9ff4d6c2e58', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'One pair of books is not among the Sahahe Sitta? Sahih Bukhari, Sahih Muslim, Sahih Bukhari, Sunnan Tirmizi, Sahih Bukhari, Shamall Tirmizi, Sahih Bukhari, Sunnan Ibn-e-Maja', '{"A":"Sahih Bukhari, Sahih Muslim","B":"Sahih Bukhari, Sunnan Tirmizi","C":"Sahih Bukhari, Shamail Tirmizi","D":"Sahih Bukhari, Sunnan Ibne Maja"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sahih Bukhari, Shamail Tirmizi is not among the Sahahe Sitta, as it is a different book written by Imam Tirmidhi.The Sahahe Sitta (Six Authentic Books) are:Sahih BukhariSahih MuslimSunnan TirmiziSunnan Abu DawudJami'' at-Tirmidhi (Sunnan Tirmizi)Sunnan Ibne MajaLast verified on 28-04-2026', 0, 0, 0, 1790964561344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_29a64bc8823cab81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'When was the Qibla changed from Masjid al-Aqsa to Masjid al-Haram?', '{"A":"Shaban 1 AH","B":"Ramadan 1 AH","C":"Shaban 2 AH","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Qibla was changed in 2 AH (624 AD).It happened during the Zuhr (Dhuhr) prayer.This event took place about 18 months after Hijrah in Madinah.The Qibla was changed from Bait al-Maqdis (Al-Aqsa Mosque) to Kaaba.Masjid al-Qiblatain is the mosque where this change occurred.The first Qibla of Muslims was Al-Aqsa Mosque.The change of Qibla is mentioned in the Holy Quran (Surah Al-Baqarah).Last verified on 25-05-2026', 0, 0, 0, 1790964561344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7508223d00d24eab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Ijma means _____?', '{"A":"Reasoning by analogy","B":"Consensus","C":"Illustrious write","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ijma Literally, ''consensus'' or ''agreement''.It is regarded as a binding, infallible authority in Sunni jurisprudence.The names of two kinds of consensus are:Ijma al-ummah - a whole community consensus.Ijma al-aimmah - a consensus by religious authorities.Last verified on 07-07-2026', 0, 0, 0, 1790964561344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f41bfc1a95ab4ebe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'What is the term for the principle of analogical reasoning in Islamic jurisprudence?', '{"A":"Ijma","B":"Qiyas","C":"Istihsam","D":"Istidial"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qiyas (قياس) is the principle of analogical reasoning in Islamic jurisprudence.It involves using reasoning by analogy to derive a ruling or judgment in a particular case.It is based on a similar case or principle established in the Quran, Hadith, or previous juristic decisions.Additional information:Quran (the holy book of Islam)Hadith (the sayings and actions of the Prophet Muhammad)Ijma (consensus of the Muslim community)Qiyas (analogical reasoning)Last verified on 10-05-2026', 0, 0, 0, 1790964561344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dc80e8951f58e2ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'What is the real meaning of Qiyas?', '{"A":"Searching","B":"Judging","C":"Consensus","D":"Thinking"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qiyas (قياس) is means Islamic jurisprudence (fiqh).To derive legal rulings, primarily accepted among Sunni schools of law.Components of Qiyas: To be valid, it requires four elements:Asl (Original Case): The case with an existing ruling in the Quran or Sunnah (e.g., prohibition of wine)Farʿ (New Case): The new case requiring a ruling (e.g., modern synthetic drugs).Illah (Effective Cause): The shared reason for the ruling (e.g., intoxication).Hukm (Ruling): The legal ruling (e.g., prohibition)Last updated question NS on 09 MAY 2026', 0, 0, 0, 1790964561344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1f9b51f914e400d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'What was the real name of Imam Bukhari (R.A)?', '{"A":"Muhammad bin Ismaeel","B":"Muhammad Ismaeel","C":"Muhammad Ibraheem","D":"Ismaeel bin Ibraheem"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Imam Bukhari (RA) was a great Islamic scholar and hadith compiler.His full name was Abu Abdullah Muhammad ibn Ismail al-Bukhari.Additional information:Born: 20 July 810 AD in Bukhara (present-day Uzbekistan).Died: 1 September 870 AD (buried in Xoʻja Ismoil, Uzbekistan)Hadith memorized: Around 70,000+ HadithsFamous book: Sahih al-BukhariEra: 9th Century (Abbasid period)Last updated question by NA on 07 May 2026', 0, 0, 0, 1790964561425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3b1812469dd46a9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', '"Al-Risalah" on Usul-ul-Fiqh was written by?', '{"A":"Imam Ghazali","B":"Imam Shafi''i","C":"Imam Malik","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Al-Risalah” is the first systematic book on Usul-ul-Fiqh.It lays down principles of Islamic jurisprudence.It was written by Imam Shafi’i.The book explains sources of Islamic law like Quran and Sunnah.Last verified on 27-04-2026', 0, 0, 0, 1790964561425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1b0763f467cc9673', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'The book of Hadith ‘Al Muwatta’ was written by _______?', '{"A":"Imam Azam abu Hanifa","B":"Imam Ahmed bin Hambal","C":"Imam Malik","D":"Imam Hanbal"}', 'C', NULL, 0, 0, 0, 1790964561425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cabb4a80eb2524b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Give the name, who compiled first work of Hadith Sahifa-e-Sadiqa?', '{"A":"Imam Muslim (رضہ)","B":"Hazrat Abu Bakar (رضہ)","C":"Hazrat Abu Hurairah (رضہ)","D":"Hazrat Abdullah bin Amr (رضہ)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abdullah ibn Amr ibn al-As (R.A) compiled Sahifa-e-Sadiqa, the first written collection of Hadith.He was a close companion of Prophet Muhammad (PBUH).Birth: 616 AD (Mecca)Death: 683 AD (Egypt)Governor of Egypt: 664 AD (January to February)Last verified on 27-04-2026', 0, 0, 0, 1790964561425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_972707b3dcdbdf79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'The wine was prohibited (haram) in ______ A.H.', '{"A":"3rd","B":"4th","C":"2nd","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wine (alcohol) was prohibited in stages in Islam.The final and complete prohibition came in 4 A.H.This ruling is mentioned in the Quran in Surah Al-Ma’idah.Last verified on 26-04-2026', 0, 0, 0, 1790964561425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f6e97c305c48bc37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'In which Hijri year was Riba (usury/interest) declared haram (forbidden)?', '{"A":"8 A.H","B":"9 A.H","C":"10 A.H","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Riba (interest/usury) was declared completely haram in 9 A.H.The ruling was revealed in the final period of Islam.It is mentioned in Surah Al-Baqarah (2:278–279).Last verified on 26-04-2026', 0, 0, 0, 1790964561425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3a0e036bcd764673', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Arbeen is the book of Hadith in which there are _____ Hadith.', '{"A":"20 Hadith","B":"50 Hadith","C":"40 Hadith","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Arba''in al-Nawawiyyah is a famous Hadith book.It was compiled by Imam Nawawi.The word “Arbaeen” means forty (40).The book contains 40 selected Hadiths on important Islamic teachings.Last verified on 21-04-2026', 0, 0, 0, 1790964561425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e4ff2ab534fd96bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Who is considered the compiler of the most authentic collection of hadith?', '{"A":"Muslim","B":"Abu Dawud","C":"Ibn Majah","D":"Bukhari"}', 'D', NULL, 0, 0, 0, 1790964561425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_396e37298bb5031b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Which type of Hadith has numerous narrators at each level of the chain, making it impossible to be fabricated?', '{"A":"Ahad Hadith","B":"Da''if Hadith","C":"Mutawatir Hadith","D":"Hasan Hadith"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Mutawatir Hadith is narrated by so many people at each stage that it is inconceivable they all agreed to lie. This ensures its authenticity.', 0, 0, 0, 1790964561516) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_882ff2e5ff2d9f3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'What is term for the hadith narrated by a single reliable narrator throughout the chain of transmission?', '{"A":"Hasan","B":"Sahih","C":"Gharib","D":"Daif"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gharib (غريب) is a term used in hadith studies to describe a hadith that is narrated by a single reliable narrator throughout the chain of transmission.This means that the hadith is narrated by only one person at each level of the isnad (chain of transmission), making it a unique or solitary narration.', 0, 0, 0, 1790964561516) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_97799f125f6c6b29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'How many kinds of Ijma are there?', '{"A":"Two","B":"Four","C":"Three","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ijma can be operated where: The Quran and Hadith have not clarified a certain aspect of LawIjma Literally, ''consensus'' or ''agreement''.The names of two kinds of consensus are:ijma al-ummah - a whole community consensus.ijma al-aimmah - a consensus by religious authorities.ND7-5-2023', 0, 0, 0, 1790964561516) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_33f2446493919f92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'What is the meaning of Sunnah?', '{"A":"The way or practice of Prophet SAW","B":"Ahadith","C":"Way of living","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are three types of Sunnah. The first is the sayings of the prophet – Sunnah Qawliyyah/Hadith. The second is Sunnah Al Filiyya.Third Sunnah Taqririyyah', 0, 0, 0, 1790964561516) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_33d19a18170ec872', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'What is the literal Meaning of Hadith?', '{"A":"History of Islam during period of Holy Prophet","B":"History of Islam during Pious Caliphate meaning of the word","C":"Sayings of the Holy Prophet (S.A.W.S)","D":"Life history of the Holy Prophet before migration to Madinah"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation نبی کریم صلی اللہ تعالی علیہ وآلہ وسلم کے قول اور فعل کی خبر کو حدیث کہا جاتا ہے۔', 0, 0, 0, 1790964561516) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_155b436c5aa19c8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Masjid-e-Haram is located in ______?', '{"A":"Madina","B":"Taif","C":"Makkah","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid-e-Haram is located in Makkah.It is the largest mosque in the world and surrounds the Kaaba.It is the most sacred site in Islam.', 0, 0, 0, 1790964561516) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d176f306c65c396d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Sahih Bukhari was compiled by_____?', '{"A":"Mohammad bin Ismael Bukhari","B":"Imam Malik","C":"Imam Humbal","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790964561516) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_65a720952d46a228', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Hadith-e-Taqriri means hadith which?', '{"A":"Include some statement or acts of some of the companions of Prophet Muhammad SAW","B":"It is not attributed to Prophet SAW directly","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hadith-e-Taqriri refers to the statements or actions of the companions that the Prophet Muhammad (PBUH) silently approved without objection.This type of hadith indicates implicit approval from the Prophet SAW.This making it a valid source of Islamic teachings.', 0, 0, 0, 1790964561516) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_070db0d49a9c8c52', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Imam Muhammad bin Ismail al-Bukhari wrote which book of hadith?', '{"A":"Abu dawood","B":"Tirmizi","C":"Sahih Bukhari","D":"Sahih Muslim"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The following are the six most famous books of Hadith:All Muhadith (Hadith writers) were Persian.1. Sahih Bukhari2. Sahih Muslim3. Jame Tirmizi4. Sunan Abu Dawood5. Sunan Al Sughra6. Sunan ibn Maja', 0, 0, 0, 1790964561602) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_116766c1cb304f17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Who has narrated the most Hadith in females?', '{"A":"Hazrat Ayesha R.A","B":"Hazrat Zainab R.A","C":"Hazrat Qulsoom R.A","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790964561602) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_227bd3857755c063', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'What was the relationship between Imam Bukhari and Imam Hanbal?', '{"A":"Father - Son","B":"Teacher - Student","C":"Student - Teacher","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Imam Bukhari (810-870 CE) was a renowned Islamic scholar and compiler of the hadith collection "Sahih al-Bukhari".Imam Ahmad ibn Hanbal (780-855 CE) was a prominent Islamic scholar and founder of the Hanbali school of thought.Imam Bukhari was a student of Imam Ahmad ibn Hanbal.He attended Imam Hanbal''s lectures and learned from him.Imam Bukhari is said to have greatly respected Imam Hanbal and considered him as one of his teachers.', 0, 0, 0, 1790964561602) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c22934a65e4b04c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Fatwa Kazi Khan is the authentic fatwa of which sect?', '{"A":"Fiqah Hanfia","B":"Fiqah Shafi","C":"Fiqah Hanbali","D":"Fiqah Jafriya"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Fatwa Kazi Khan" is an authoritative fatwa collection of the Fiqah Hanfia (Hanafi) sect.The Fatwa-e-Qazi Khan consists of two volumes.It containing 500 verses from the Holy Qur''an and 290 Traditions of the Holy Prophet SAW.It covering marriage, dower, divorce, legitimacy, and guardianship of minors.', 0, 0, 0, 1790964561603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fb6d643375f4593f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'The literal meaning of ''Qiyas'' is', '{"A":"To assess","B":"To think","C":"Independent verdict","D":"To make research"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790964561603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9ed7e329b4cef1b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'How many Ahadis does the Sahih Bukhari contain?', '{"A":"8821","B":"7275","C":"5636","D":"6722","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ND21-2-2023', 0, 0, 0, 1790964561603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_71ae152844c121d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Al-Muwatta is written by?', '{"A":"Imam Hambal","B":"Imam Abu Hanifa","C":"Imam Malik","D":"Ahmad ibn Hanbal","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Muwaṭṭa of Imam Malik written in the 8th-century Al-Muwatta compiled In the Arabic languageFirst published in 1989.****Al-Muwatta contains approximately 1,720 hadith divided amongst the following hadith terminology as follows:1) 600 marfu hadith2) 613 mawquf hadith3) 285 maqtu hadith4) 222 mursal hadiths********VU CBT FIA PAPER 16-12-2021ND-21-5-2023', 0, 0, 0, 1790964561603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5c6a5872ad36b304', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Which one is called Mashar -ul- Haram?', '{"A":"Muzdalifah valley","B":"Arafat","C":"Makkah","D":"Mina valley"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The border of Muzdalifah is marked by a large purple signpost.There is also a masjid called Mashar Al Haram, which means "holy monument".', 0, 0, 0, 1790964561603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f4a51f6bd8245088', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'A book on collection of Ahadis of Sahih Bukhari is', '{"A":"Imam bukhari","B":"Imam malik","C":"Imam Abu Hanifa","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sahih al-Bukhari is a hadith collection and a book of sunnah compiled by the Uzbek scholar Muḥammad ibn Ismā''īl al-Bukhārī Sahih Al Bukhari contains around 2,600 ahadith without repetitions and 7,563 ahadith with repetitions. It is an important book in Islamic literaturepart of the Kutub al-Sittah,97 chapters.', 0, 0, 0, 1790964561678) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_22d797cb3d4eb0dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'Ijma can be operating where?', '{"A":"The Quran and Hadith have not clarified a certain aspect of Law","B":"When Shoora is not present","C":"Both a & b","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ijma can be operated where: The Quran and Hadith have not clarified a certain aspect of LawIjma Literally, ''consensus'' or ''agreement''.The names of two kinds of consensus are:ijma al-ummah - a whole community consensus.ijma al-aimmah - a consensus by religious authorities.ND7-5-2023', 0, 0, 0, 1790964561678) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bcab8051880093c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_hadith', 'There are ________ schools of thought in Islamic fiqh.', '{"A":"4","B":"5","C":"8","D":"9"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation the terminological meaning of ''Fiqh is "deep understanding"Fiqh refers to the body of Islamic law extracted from detailed Islamic sources There are the following Five Schools of Islamic Thought.HanafiMalikiShafi΄iHanbaliND19-3-2023', 0, 0, 0, 1790964561678) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_isl_history', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Islamic History', 'top_islamic', 44, 1790964561745) ON CONFLICT(id) DO UPDATE SET total_mcqs = 44;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_10e2def2876b541b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'When the first migration to Abyssinia took place?', '{"A":"612 AD","B":"616 AD","C":"613 AD","D":"615 AD"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first migration of Muslims was to Abyssinia (Habsha) in Makkah.First migration: 6 BH (Before Hijrah)This event is known as Hijrah il-al-Habshah.Ruler: King Negus (Najashi)Group: About 12 men and 4 women (first batch)Including Prophet Muhammad''s relatives Usman Ghani (R.A) and Ruqaiyah (R.A).Surah Anfal mentions the migration of the Holy Prophet SAW.Additional information:The second migration to Abyssinia occurred in 616 A.D.This group comprised 83 men and 18 to 19 women.Last updated by NA on 09-09-2026', 0, 0, 0, 1790964561831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5b73cf74a19cfdff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'How many Ghazwat occurred in the 4th year of Hijrah?', '{"A":"2","B":"1","C":"3","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Two (2) Ghazwat took place in the 4th year of Hijrah.The two Ghazwat were Ghazwa Banu Nadir and Ghazwa Badr al-Sughra.Additional information:1 AH: 0 Ghazwat2 AH: Battle of Badr3 AH: Battle of Uhud5 AH: Battle of the Trench (Ahzab)Verified & Updated', 0, 0, 0, 1790964561831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3322fbd26181ba88', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Who is the Current Secretary General of OIC?', '{"A":"Ismail Ould Cheikh Ahmed","B":"Yousef bin Ahmad Al-Othaimeen","C":"Hussein Ibrahim Taha","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ismail Ould Cheikh Ahmed is the Current Secretary-General of OIC.He is elected for a five-year term starting August 28, 2026.He belongs to the Mauritanian.Last verified on 02-09-2026', 0, 0, 0, 1790964561831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_58df29b89cd54956', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Pakistan hosted the second Islamic Summit of OIC in _____?', '{"A":"1963","B":"1969","C":"1971","D":"1974"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan hosted the 2nd Islamic Summit Conference of the OIC from 22–24 February 1974 in Lahore.An Extraordinary OIC Summit was also held later in 1997 in Islamabad on Pakistan’s Golden Jubilee.Additional information:1st Summit: Rabat, Morocco – September 19693rd Summit: Makkah, Saudi Arabia – 25–28 January 1981Last verified on 07-03-2026', 0, 0, 0, 1790964561831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_64166e5f9f8cb618', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Who was the first preacher of Islam appointed/sent by/to Hazrat Muhammad ﷺ for the people of Madina (before his migration)?', '{"A":"Hazrat Musab ibn Umair (RA)","B":"Hazrat Jafar Tayyar (RA)","C":"Hazrat Ayub Ansari (RA)","D":"Hazrat Usman (RA)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Musab ibn Umayr was appointed the first ambassador of Islam.He embraced Islam in 614 CE.He was sent to Yathrib (Medina) to prepare the city for the forthcoming Hijra after the first pledge with the ansar. A man of Medina named Asad ibn Zurara assisted him.He died in the Battle of Uhud in 625 CE.Last verified on 21-04-2026', 0, 0, 0, 1790964561831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6050e18952aca573', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'What was the first written constitution (First Tehriri Dastoor) of the world?', '{"A":"The Treaty of Hudaibiya","B":"Meesaq-e-Madina","C":"The Khutaba-e-Hajja-tul-widah","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Meesaq-e-Madina / Constitution of MedinaYear: 622 CE (1 AH)Place: Medina, ArabiaIssued by: Prophet Muhammad (PBUH)Total articles: 47 (commonly cited)Last verified on 23-06-2026', 0, 0, 0, 1790964561831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_baa29f42aeaedf2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'How many Countries are members of OIC?', '{"A":"55","B":"56","C":"57","D":"69"}', 'C', NULL, 0, 0, 0, 1790964561831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b46dc826f743390e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Where is the headquarters of the Islamic Educational, Scientific and Cultural Organization (ICESCO) located?', '{"A":"Islamabad, Pakistan","B":"Jeddah, Saudi Arabia","C":"Rabat, Morocco","D":"Ankara, Türkiye"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct Answer: C) Rabat, MoroccoMost important for exams: OIC Headquarters → Jeddah, Saudi Arabia COMSTECH Headquarters → Islamabad, Pakistan COMCEC Headquarters → Ankara, Türkiye ICESCO Headquarters → Rabat, Morocco Islamic Development Bank Headquarters → Jeddah, Saudi Arabia', 0, 0, 0, 1790964561831) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c376576907387fc7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Where is the headquarters of the Organization of the Islamic Conference (OIC) located?', '{"A":"Jeddah","B":"Khatmando","C":"Geneva","D":"Makkah"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Headquarters: Jeddah, Saudi ArabiaOIC stands for Organization of Islamic Cooperation.Foundation Date: 25 September 1969Official Languages: Arabic, English, FrenchTotal Members: 57 countriesFirst Summit: Rabat, MoroccoSignificance: Largest international organization after the UN.Last verified on 10-05-2026', 0, 0, 0, 1790964561915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f2517d65564cadfd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'When Hijra started?', '{"A":"12th Rabi-ul-Awwal of 14th year of Nabawat","B":"12th of Rabi-ul-Awwal of 12th year of Nabawat","C":"12th of Rabi-ul-Awwal of 13th year of Nabawat","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hijra means migration of Prophet Muhammad (PBUH) from Makkah to Madina.Hijra started on 12th Rabi-ul-Awwal, 13th year of Nabawat.Islamic calendar begins from Hijra in 622 CE.Islamic lunar year has 354 or 355 days.Madina became the first Islamic state after Hijra.Last verified on 09-05-2026', 0, 0, 0, 1790964561915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_528b7fd2f0a09f45', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'The Capital of Ummayed Dynasty was?', '{"A":"Baghdad","B":"Cairo","C":"Damascus","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Capital: Damascus (Syria)Rule period: 661–750 CEFounder: Muawiyah IType of government: Hereditary monarchyEnded after: Abbasid Revolution (750 CE)Last verified on 22-06-2026', 0, 0, 0, 1790964561915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_79b5bacdaaf3ca6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'In which year was OIC founded?', '{"A":"December 7, 1985","B":"4 April 1949","C":"September 25, 1969","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation OIC (Organization of Islamic Cooperation)Foundation Date: 25 September 1969Headquarters: Jeddah, Saudi ArabiaOfficial Languages: Arabic, English, FrenchTotal Members: 57 countriesFirst Summit: Rabat, MoroccoSignificance: Largest international organization after the UNLast verified on 20-06-2026', 0, 0, 0, 1790964561915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2f93a0353ce0f791', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Who is the last ruler/caliph of the Ummayed dynasty?', '{"A":"Mustanser Billa","B":"Haroon","C":"Marwan II","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Ruler (Founder):Muawiya IReign: 661–680 ADLast Ruler:Marwan IIReign: 744–750 ADAdditional information:The Umayyad Caliphate was the first major Islamic dynasty after the Rightly Guided Caliphs.It was founded after the end of the Rashidun Caliphate in 661 AD.The dynasty ruled a vast empire from Spain to Central Asia.It ended in 750 AD after defeat by the Abbasids.Last verified on 31-05-2026', 0, 0, 0, 1790964561915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7eaa8643268dc915', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'The first ever International treaty in Islamic History is known as?', '{"A":"Bait-e-Rizwan","B":"Treaty of Madina","C":"Hilf-ul-Fazool","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first treaty in Islamic history is known as the Treaty of Hudaybiyyah.A crucial 10-year peace agreementDate: March 628 CE (Dhu al-Qadah, 6 AH)Location: Hudaybiyyah, near MeccaBetween Muslims, Jews, and other tribes.Last updated question NS on 10-09-2026', 0, 0, 0, 1790964561915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_23574b9157bb970a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'According to Islamic law the share of wife in property is _____?', '{"A":"2/3","B":"1/8","C":"Half","D":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NOTE: According to the question, the correct answer is none of these because it did not ask about the specific shares of a wife in husbands property. In Islamic inheritance law (Faraid), the share of a wife depends on whether the husband leaves children or not.If the husband has children, the wife receives 1/8th of the property.If the husband has no children, the wife receives 1/4th of the property.This is based on the Quranic injunctions in Surah An-Nisa (4:12).Islamic law clearly outlines fixed shares for all heirs.Last verified on 02-04-2026', 0, 0, 0, 1790964561915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_521c705380662740', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Baghdad city was established as the Capital of Abbasid Dynasty by?', '{"A":"Harun Rasheed","B":"As - Saffah","C":"Al - Mansoor","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Mansoor established Baghdad as the capital Baghdad was founded on 30 July 762 CE.It is the circular City of Peace (madinat al-salam)It is the capital of IraqThe second-largest city in the Arab world It is located on the Tigris riverIt has 11 DistrictLast updated by NA on 28 April 2026', 0, 0, 0, 1790964561915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d42de89f1980ecd8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Imam-e-Dar-ul-Hijrat was a title of ______?', '{"A":"Imam Shaafi","B":"Imam Malik","C":"Imam Ahmad","D":"Imam Ahmad ibn Hanbal"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The title Imam-e-Dar-ul-Hijrat was given to Imam Malik.Birth → 711 AD (Madinah)Death → 795 AD (Madinah)Book → Al-MuwattaHadith Count → ~1,720 HadithField → Fiqh (Maliki School of Thought)Last verified on 21-04-2026', 0, 0, 0, 1790964562006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_44d15b54abe451bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Which of the following is the second source of Islamic laws?', '{"A":"Qiyas","B":"Hadith (Sunnah)","C":"History","D":"Ijma"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Islamic jurisprudence, the sources of Islamic law are:Quran (the holy book of Islam)Hadith (the sayings and actions of the Prophet Muhammad)Ijma (the consensus of the Muslim community)Qiyas (analogy or reasoning)Last verified on 25-04-2026', 0, 0, 0, 1790964562006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ddeb71d3b5d73594', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'When Second migration took place to Habshah?', '{"A":"605 AD","B":"630 AD","C":"620 AD","D":"616 AD"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Migration to Habshah (613 A.D.)Participants: 12 men, 4 womenNotable Figures: Uthman ibn Affan (R.A), Ruqayyah (R.A)Reason: Escape persecution in MeccaSecond Migration to Habshah (616 A.D.)Participants: 83 men, 18–19 womenPurpose: Larger group sought safety and freedom to practice IslamBoth migrations are referenced in Surah Anfal.Habshah (Abyssinia) was ruled by a just Christian king (Negus) who granted Muslims protection.Last verified on 04-04-2026', 0, 0, 0, 1790964562006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9aa6cb72d7dfa292', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Which of following important event took place in the 6th year of Hijra?', '{"A":"The prohibition of wine","B":"The battle of Ahab","C":"The Misaq-e-Madina","D":"Sulah Hudaibiya"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The treaty allowed for a temporary truce between Muslims and Quraysh.Additional information:Year Signed: 628 AD / 6 HijriMonth: Dhu al-Qi’dah (March 628)Duration: 10 yearsClauses: 7Location: Near the tree called HudaybiahKey Signatories:Muslims: Prophet Muhammad ﷺ, Ali ibn Abi Talib (scribe)Quraysh Mecca: Suhail bin AmarLast verified on 02-02-2026', 0, 0, 0, 1790964562006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_19394e96ffe60cc1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'When Abbasid defeated Ummayad in__________?', '{"A":"650 AD","B":"350 AD","C":"750 AD","D":"790 AD","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Year: 750 CE (132 AH)Battle: Battle of the Great Zab (northern Iraq)Leaders: Abu Muslim led the revolt; Caliph Marwan II led the UmayyadsResult: Fall of Damascus and rise of the Abbasid Caliphate*********Remember Tipsیاد کرنے کے لیےRashidin -30 yearsUmayyad -100 yearsAbbasid - 500 yearsOttoman Empire - 600 yearsLast updated 25-07-2026 by NA', 0, 0, 0, 1790964562006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_08851cbbc2d7bade', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Who was the first child born after the migration (hijrah)?', '{"A":"Abu Salma (R.A)","B":"Abdul bin Zubair (R.A)","C":"Abdul bin Qasim (R.A)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abd Allah ibn al-Zubayr ibn al-Awwam born May 624 Abd Allah ibn al-Zubayr ibn al-Awwam was the leader of a caliphate based in Mecca that rivaled the Umayyads from 683 until his death.Burial Jannat al-Mu''alla, MeccaND14-7-2023', 0, 0, 0, 1790964562006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cb396c55a7517298', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', '______ was called month of migration.', '{"A":"Muharram","B":"Shaaban","C":"Ramzan","D":"Rabiul Awal"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rabiul Awal is called the month of migration.This is the month when Prophet Muhammad (s.a.w.w) and his followers migrated from Mecca to Medina in June 622 CE.Rabiul Awal is the 3rd Islamic month.', 0, 0, 0, 1790964562006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e474fbd546c8aad7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Bait-e-Rizwan (Pledge of the Tree) took place in ______ Hijrah?', '{"A":"5 A.H","B":"6 A.H","C":"2 A.H","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bait-e-Rizwan/Pledge of the Tree was made 628/6 AH.Bait-e-Rizwan took place in 6th Hijrah.Bait Rizwan was the pledge taken to get revenge on Hazrat Usman (RA) under the tree known as RizwanBait-e-Rizwan is also known as Bait-e-Shajra made under the Keekar tree.On this occasion, Muhammad gathered his nearly 1,400 Sahaba and called them to pledge to fight until death and revenge the death of Hazrat Usman******RY 15-01-2023***ND29-1-2023', 0, 0, 0, 1790964562006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a03a4e739800a20e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'How long was the period of Abbasid dynasty?', '{"A":"698","B":"508","C":"408","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation From 750 - 12581st ruler: As-SuffahLongest tenure: Rashidun*********Remember Tipsیاد کرنے کے لیےRashidin -30 yearsUmayyad -100 yearsAbbasid - 500 yearsOttoman Empire - 600 years', 0, 0, 0, 1790964562092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e6c78e3761e6cc34', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Charter of Medina (Misaq-e-Madina) was drafted by Muhammad ﷺ himself. In which Hijra Charter of Madina was drafted?', '{"A":"3rd","B":"2nd","C":"1st","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Constitution of Medina/Charter of Madina میثاق مدینہ Signed: First Hijri/622 AD Between: Muslims, Jews & other non-muslims Clauses: 47Note: The Medina Charter consists of 47 clauses.23 clause governed the relationship between Muslims, between Ansar and Muhajirin, while the remaining 24 clauses governed the relations of Muslims with non-Muslims, the Jews and others.', 0, 0, 0, 1790964562092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_38ab38bb9c18c923', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Qazf in Islamic law is imposed on ______?', '{"A":"Theft","B":"Fraudulent","C":"False accusation of Zina","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qazf in Islam is imposed on: False accusation of ZinaHad –e- Qazaf (false Accusation) is: 80 LashesLashes means: کوڑےFirst Muslim who faced the frst ever ordinance of Qazf: Hasan ibn Sabit, Mustah ibn Asasa, Hamnah ibn Jahsh', 0, 0, 0, 1790964562092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1b844e072c06fd3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'What is payable on agricultural products under Islamic Law?', '{"A":"Fitrah","B":"Hadiya","C":"Jizya","D":"Ushr"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ushr is a 10% tax on the harvests of irrigated land or harvest from rain-watered land and 5% on Land dependent on well water.Ushr is given after sowing the seeds when the agricultural produce appears.', 0, 0, 0, 1790964562092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e0931a64edc0334e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Organization of Islamic Cooperation (OIC) has ______ official languages.', '{"A":"4","B":"3","C":"6","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation OIC has Arabic, English, and French as its three official languages.Additional information:The Organization of Islamic Cooperation (OIC), founded on September 25, 1969.It initially had 25 founding members.It is headquartered in Jeddah.Formerly known as the Organization of the Islamic Conference, it changed its name on June 28, 2011.With 57 current member countries.Jakarta is the largest city among OIC member nations.Last verified on 08-06-2026', 0, 0, 0, 1790964562092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_826248fc574327d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Where did Hazrat Muhammad (PBUH) and Hazrat Abu Bakar (R.A) stay during migration to Madinah?', '{"A":"Taaif","B":"Mount Uhad","C":"Syria","D":"Cave of Soor"}', 'D', NULL, 0, 0, 0, 1790964562092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6ae9466b401a01eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'First Migration to Habsha was in _______ Nabvi.', '{"A":"3rd","B":"6th","C":"4th","D":"1st"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The First Migration to Abyssinia (Ethiopia) 613 CE (4th Nabvi)Participants: A group of twelve men and four womenThe relatives of Prophet Muhammad (PBUH) in the first migration to Abyssinia were Usman Ghani (R.A) and Ruqaiyah (R.A)Also known as:Hijrah il-al-Habshah ***Additional Information***The 1st Migration to Abyssinia (Ethiopia) 613 CEThe 2nd Migration to Abyssinia (Ethiopia) 616 CEThe Ethiopian Empire also formerly known by the exonym Abyssinia', 0, 0, 0, 1790964562092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_23dfab0dc0363431', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Who ruled Ottoman Turkey in the 16th century?', '{"A":"Mehmat","B":"Selim","C":"Usman","D":"Suleiman"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the 16th century, Ottoman Turkey was primarily ruled by Suleiman the Magnificent, reigning from 1520 to 1566.He was succeeded by his son Selim II, who ruled from 1566 to 1574, continuing his father''s policies.During the 16th and 17th centuries, the Ottoman Empire was controlling much of Southeast Europe, Western Asia, the Caucasus, North Africa, and the Horn of Africa.', 0, 0, 0, 1790964562092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2d6f6193c953f4eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Where was the second OIC Summit Conference held?', '{"A":"Lahore","B":"Islamabad","C":"Karachi","D":"none of the above"}', 'A', NULL, 0, 0, 0, 1790964562160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ade364a37ec9f2b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'The permanent Secretariat of OIC is located in _______', '{"A":"Makkah","B":"Madina","C":"Jeddah","D":"Riyadh"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation OIC Members: 57 member statesOIC Headquarters: Jeddah, Saudi ArabiaOIC Founded: September 25, 1969OIC Official languages: Arabic; English; FrenchRK15.06.2023', 0, 0, 0, 1790964562160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_012f04d558d6883c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Which OIC conference was held in Pakistan?', '{"A":"22–25 September 1969","B":"22–24 February 1974","C":"25–29 January 1981","D":"16–19 January 1984"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation OIC role in Pakistan-Bangladesh relationshipIt was under the pretext of the 2nd summit of OIC held in Lahore between 22 and 24 February 1974This event is also known as the Lahore Summit. It was a significant gathering where 36 member states participated1st Extraordinary summit of OIC held in Islamabad between 23–24 March 1997', 0, 0, 0, 1790964562160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_33f91e449df2559e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Abbasids ruled over most of the Islamic World from 750 AD till?', '{"A":"1259","B":"1258","C":"1260","D":"1256"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation From 750 - 12581st ruler: As-SuffahLongest tenure: Rashidun*********Remember Tipsیاد کرنے کے لیےRashidin -30 yearsUmayyad -100 yearsAbbasid - 500 yearsOttoman Empire - 600 years', 0, 0, 0, 1790964562160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_32a3ca87c641f837', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', '4th source of Islamic law?', '{"A":"Qiyas","B":"The Sunnah","C":"The Holy Book","D":"ljma"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation fourth source of ShariaThe primary sources of Islamic law are the Holy Book (The Quran), The Sunnah (the traditions or known practices of the Prophet Muhammad ), Ijma'' (Consensus), and Qiyas (Analogy)Qiyas or analogical reason is the fourth source of Sharia for the majority of Sunni jurisprudence. It aims to draw analogies to a previously accepted decision', 0, 0, 0, 1790964562160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_77680cdcc2cfd984', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'There were _______ men and _______ women in the first migration to Abyssinia?', '{"A":"10/4","B":"12/4","C":"14/4","D":"12/3"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Migration to Abyssinia (Ethiopia) Dated 6 BH (613/14 CE).Start date: 613 ADParticipants: A group of twelve men and four womenThe relatives of Prophet Muhammad (PBUH) in the first migration to Abyssinia were Usman Ghani (R.A) and Ruqaiyah (R.A)Also known as:Hijrah il-al-Habshah The Ethiopian Empire also formerly known by the exonym Abyssinia', 0, 0, 0, 1790964562160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8b47bdddea38f8a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'The organization of Islamic cooperation (OIC) also known as the organization of Islamic conference formula was created in', '{"A":"1963","B":"1969","C":"1971","D":"1979"}', 'B', NULL, 0, 0, 0, 1790964562160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_972a1e4373892d01', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'What was the total number of migrated people in the second migration to Abyssinia?', '{"A":"21","B":"70","C":"91","D":"101"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Migration comprised eleven men and four women (15 migrated people) the Second Migration comprised eighty-three men and fourteen women. (101 migrated people)Ja’far bin Abi Talib (RA) was the head of this group of immigrants (second migration)Muslims migrated twice to Habshah (Abyssinia) first in 613 CE and second in 616 CE to flee from the persecutions of Quraysh***ND29-1-2023', 0, 0, 0, 1790964562160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4f412a0a3f70c5c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Jehad was allowed in ___Hijrah ?', '{"A":"2nd","B":"3rd","C":"4th","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To Strive Hard is the literal meaning of 41 times the word jihad appears in Quran', 0, 0, 0, 1790964562227) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6f60b59057764639', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'Islamic calendar (Hijra) commenced from?', '{"A":"621 AD","B":"618 AD","C":"623 AD","D":"622 AD","E":"624 AD"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Islamic lunar calendar, which begins its count from the Islamic New Year in 622 CE Islamic lunar calendar has only 354 or 355 days in its year."Hijri calendar was started in16 HijriIslamic Calendar starts from HijriIslamic calendar established by: Hazrat Umar (R.A)*****', 0, 0, 0, 1790964562227) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_09b043ba2364fc1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'What is the most important event of Sixth Hijrah?', '{"A":"Conquest of Makkha","B":"Conquest of Khyber","C":"Treaty of Huddaibiah","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The treaty of Huddaibiah was a pivotal treaty between Muhammad, representing the state of Medina, and the Qurayshi tribe of Mecca in January 628. The points of the treaty of Hudaibiya.1. The Muslim shall perform their pilgrimage in the upcoming year 2. they would stay in peace at Mecca for three days including the years onward with no arms except sheathed swords. *****6th year of Prophethood: Umar (ra) became a Muslim', 0, 0, 0, 1790964562227) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_63ca5d9dacab68c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_history', 'After how many years is the OIC summit held?', '{"A":"1 year","B":"3 years","C":"6 years","D":"7 years"}', 'B', NULL, 0, 0, 0, 1790964562227) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_isl_ethics', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Ethics & Morality', 'top_islamic', 10, 1790964562288) ON CONFLICT(id) DO UPDATE SET total_mcqs = 10;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7787d8e0228b0c05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_ethics', 'In 20th century, normative ethics became more complex as they are not only concerned rightness and wrongness but also interested in different kinds of moral?', '{"A":"Values","B":"Status","C":"Conducts","D":"Thinkings"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the 20th century, normative ethics became more complex as it focused not only on rightness and wrongness but also on different kinds of moral values.Normative ethics studies the principles and values that guide moral behavior.It helps determine what people ought to do based on ethical values.Last verified on 21-07-2026', 0, 0, 0, 1790964562370) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_493ea23a51554b48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_ethics', 'A conventional morality deals with the level of custom at different levels which is also a branch of?', '{"A":"Ethics","B":"Science","C":"Religion","D":"Philosophy"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Conventional morality deals with the level of customs and social norms and is a branch of Ethics.It refers to moral standards based on society''s accepted rules and traditions.Individuals follow these norms to gain social approval and maintain order.Last verified on 21-07-2026', 0, 0, 0, 1790964562371) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3158acc81e96f4d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_ethics', 'It is special business of ethics to _____ our intuitions, both their own consistency among themselves and by critical comparison of our own intuitions with those of others.', '{"A":"Test","B":"Ignore","C":"Condemn","D":"Compare"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is the special business of ethics to test our intuitions for consistency and compare them critically with those of others.Ethics examines whether our moral judgments are logical, fair, and consistent.It helps improve moral reasoning through critical analysis.Last verified on 21-07-2026', 0, 0, 0, 1790964562371) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_904a30898570eee1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_ethics', 'Direct or intuitive judgment plays a far larger in normative sciences, and especially in ______ than it does in the physical description.', '{"A":"Psychology","B":"Sociology","C":"Ethics","D":"Religion"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct or intuitive judgment plays a far larger role in Ethics than in the physical sciences.Ethics is a normative science that evaluates what is morally right and wrong.It relies on moral reasoning, values, and intuitive judgment rather than only observation.Last verified on 21-07-2026', 0, 0, 0, 1790964562371) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5df58ae89a5eda53', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_ethics', 'Ethics deals with the standards by which we judge human action to be ________ or wrong.', '{"A":"Right","B":"Illegal","C":"Bad","D":"Evil"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ethics deals with the standards by which we judge human actions to be right or wrong.It is the branch of philosophy concerned with moral values and principles.Ethics helps individuals distinguish between acceptable and unacceptable behavior.Last verified on 21-07-2026', 0, 0, 0, 1790964562371) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ab6688aacb733896', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_ethics', 'The moral judgment has tended to deal with the inner causes of action rather than the outward?', '{"A":"Actions","B":"Conducts","C":"Duties","D":"Righter"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Moral judgment tends to deal with the inner causes (intentions or motives) of an action rather than the outward actions.In ethics, a person''s intention is often considered more important than the external act alone.Moral evaluation considers both motive and behavior.Last verified on 21-07-2026', 0, 0, 0, 1790964562371) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1f59c3bcef97a28c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_ethics', 'A normative ethics deal with ''what is right and wrong'', also known as?', '{"A":"Sociology","B":"Psychological Morality","C":"Moral theory","D":"Philosophical morality"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Normative ethics deals with what is right and wrong and is also known as moral theory.It establishes principles and standards for determining morally correct behavior.It answers the question: "What ought a person to do?"Last verified on 21-07-2026', 0, 0, 0, 1790964562371) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bc0da2f9e12b5904', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_ethics', 'Which of the following has been defined as the normative science of conduct, and conduct is a collective name for voluntary action?', '{"A":"Religion","B":"Ethics","C":"Sociology","D":"Literature"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ethics is defined as the normative science of conduct, and conduct is a collective name for voluntary actions.It studies what is morally right and wrong and provides principles for good behavior.Ethics guides individuals in making responsible and moral decisions.Last verified on 21-07-2026', 0, 0, 0, 1790964562371) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_49c27a476a269b39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_ethics', 'According to Kant, ethics meant by virtue', '{"A":"Honesty","B":"determination","C":"Virtue","D":"Husne-Amal"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kant distinguishes between virtue, which is a strength of will to do one’s duty from duty, and particular virtues, which are commitments to particular moral ends that we are morally required to adopt. Among the virtues Kant discusses are those of self-respect, honesty, thrift, self-improvement, beneficence, gratitude, sociability, and forgiveness.', 0, 0, 0, 1790964562443) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8a4f17ec786a71ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_ethics', 'Ethics is a system of______?', '{"A":"Moral/Principles","B":"Guiding","C":"Value","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ethics is a normative science. It is concerned with what ought to be done rather than what is the case.It differs from positive science.A positive science, natural science or descriptive science is concerned with what is.It deals with facts and explains them by their causes.', 0, 0, 0, 1790964562443) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_isl_general', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'General Islamic Studies', 'top_islamic', 503, 1790964562568) ON CONFLICT(id) DO UPDATE SET total_mcqs = 503;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b893258a8534b71a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Sihah-e-Sitta are the six books of _____?', '{"A":"Tafseer e Quran","B":"Serat e nabvi","C":"Fiqah","D":"Hadith"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Siha-e-Sitta 1. Sahih al-Bukhari — Imam Bukhari — 7,275 Ahadith2. Sahih Muslim — Imam Muslim — 9,200 Ahadith3. Sunan an-Nasa’i — Imam Nasa’i — 5,270 Ahadith4. Sunan Abu Dawood — Imam Abu Dawood — 4,800 Ahadith5. Jami at-Tirmidhi — Imam Tirmidhi — 3,956 Ahadith6. Sunan Ibn Majah — Ibn Majah — 4,000 AhadithNote: Muwatta Imam Malik is a famous early Hadith collection, but it is not one of the six books of Siha-e-Sitta.Last updated by NA ON 16-09-2026', 0, 0, 0, 1790964562669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_54c5ac3e9f3e78fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many pieces of cloth are used for a woman’s shroud (Kafan)?', '{"A":"3","B":"4","C":"5","D":"7"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total Pieces: 5Izar: Lower-body coveringQameez: Sleeveless garmentKhimar: Head coveringSinnah: Chest coveringLifafah: Outer sheet covering the whole body', 0, 0, 0, 1790964562669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a4e4b2601e9f66d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Treaty of Hudaybiyyah took place in which Hijri?', '{"A":"5th","B":"7th","C":"4th","D":"6th","E":"8th"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Signed: 6 AH / 628 CEPlace: Hudaybiyyah, near MakkahDuration: 10 yearsMuslims’ Representative: Prophet Muhammad ﷺQuraysh Representative: Suhail bin AmrScribe: Hazrat Ali (RA)Clauses: 7Mentioned as: Fath-e-Mubeen in Surah Al-FathHudaybiyyah: Name of a place, not a tree.Last question 14-09-2026', 0, 0, 0, 1790964562669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_79d548163690540b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which is the second month of Islamic Calendar?', '{"A":"Rabi-ul-Awwal","B":"Rajab","C":"Safar","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 12 Islamic MonthsMuḥarram (محرم الحرام)Ṣafar (صفر المظفر)Rabi al-Awwal (ربیع الاول)Rabi al-Thani / Rabi al-Sani (ربیع الثانی)Jumada al-Awwal (جمادی الاول)Jumada al-Thani (جمادی الثانی)Rajab (رجب المرجب)Shaʿban (شعبان المعظم)Ramadan (رمضان المبارک) – Month of fastingShawwal (شوال المکرم)Dhu al-Qaʿdah (ذوالقعدہ الحرام)Dhu al-Hijjah (ذوالحجہ الحرام) – Month of HajjLast verified on 14-03-2026', 0, 0, 0, 1790964562669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e82cb26cbb801953', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who accepted Islam first in Women?', '{"A":"Hazrat Amina (RA)","B":"Hazrat Khadija (RA)","C":"Hazrat Hafsa (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khadijah bint Khuwaylid (RA) was the first woman to accept Islam.Known for: First wife of MuhammadTitle: Ameerat-Quraysh al-TahirahAdditional information:First adult man: Khadijah bint Khuwaylid (RA)First Child: Ali ibn Abi Talib (RA)First Freed Slave: Zayd ibn Harithah (RA)First Slave: Bilal ibn Rabah (RA)Last updated: 13-09-2026', 0, 0, 0, 1790964562669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e19a6b913f60a5da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who is known as Adam-e-Sani (Abu-ul-Bashr Sani)?', '{"A":"Hazrat Nooh (علیہ)","B":"Hzarat Moosa (علیہ)","C":"Hazrat Adam (علیہ)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Nooh is known as Adam-e-Sani (Abu-ul-Bashar Sani) (Second Adam).After the great flood, most of humanity perished.Hazrat Nooh’s followers helped restart humanity, similar to Hazrat Adam (علیہ السلام).Symbolizes rebirth of mankind and continuation of human civilization.Last verified 30-03-2026', 0, 0, 0, 1790964562669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a50d1bc9cd1a3d9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Al-Hudaibiyah Treaty was written/signed by?', '{"A":"Usman Ghani (رضہ)","B":"Umar Farooq (رضہ)","C":"Abu Bakr Siddique (رضہ)","D":"Ali Al-Murtaza (رضہ)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Al-Hudaibiyah Treaty was signed in 6 AH for 10 years.It was scribed by Ali ibn Abi Talib (R.A).Hudaibiyah is the name of tree.It is referred to as "Fatah Al-Mubeen" (the clear victory) in Surah Al-Fatah.It was a pivotal agreement between Muhammad SAW representing Medina and the Qurayshi tribe of Mecca.Suhail bin Amr signed on behalf of Mecca.It contained 7 clauses.Last verified on 01-04-2026', 0, 0, 0, 1790964562669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e15a4c11fad8be64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The wealth or property left by deceased is called?', '{"A":"Taraka","B":"Sadaqa","C":"Asaba","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The wealth or property left by a deceased person is called TarakaTaraka means فوت ہونے والے انسان کی دولت It is the basis of the Islamic system of inheritance (Faraid).Additional information:Asabah: The residuaries who take whatever remains of the estate after the fixed-share heirs receive their portions.Last updated NA on 10-09-2026', 0, 0, 0, 1790964562669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_769448bb8dfa411a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Sulah-e-Hudaibiya was signed for how many years?', '{"A":"5","B":"10","C":"7","D":"3"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Signed in 6 AH, valid for 10 years.Scribed by Ali ibn Abi Talib (R.A).Suhail bin Amr signed on behalf of Mecca.Hudaibiyah is the name of a tree.Occurred during the time of Prophet Muhammad ﷺ.Between Muhammad ﷺ (representing Medina) and the Qurayshi tribe of Mecca.Called "Fatah Al-Mubeen" (the clear victory) in Surah Al-Fatah.Contained 7 clauses.Last updated NA on 10-09-2026', 0, 0, 0, 1790964562757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_aeb72aebde8fd1ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the Last writer Kitab-e-wahi?', '{"A":"Hazrat Ali(RA)","B":"Hazrat Abi bin Kaab(RA)","C":"Hazrat Umar (RA)","D":"Hazrat Abu Hurairah (RA)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Last Writer: Hazrat Abi bin Kaab(RA)Role: Katib-e-Wahi (Scribe of the Divine Revelation)Additional information:کاتِبِ وَحی کے اردو معانی: پوشیدہآنحضرت صلی اللہ علیہ وسلم پر جو وحی نازل ہوئی تھیHazrat Sharjeel (R.A) is the first writer of Wahi, and he wrote BismillahLast updated by NA on 09-09-2026', 0, 0, 0, 1790964562757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6cc6285c22683e1d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Name the angels who are appointed to put Questions to the dead''s in their graves?', '{"A":"Munkar and Nakeer","B":"Hazrat Jabreel","C":"Hazrat Mikeel","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The angels who question the dead in the grave are Munkar and Nakir.They appear after burial to test the faith and belief of the deceased.The dead person is asked about Allah, Prophet Muhammad (SAW), and religion.Correct answers lead to peace in the grave, while wrong answers lead to punishment.This is part of the belief in Akhirah (Hereafter) in Islam.Last verified on 25-06-2026', 0, 0, 0, 1790964562757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_97090fdaf17b0ed5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What are the meaning of Sariyya?', '{"A":"A poetess","B":"A famous Arabian saint","C":"A battle not attended by Holy Prophet (PBUH)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sariyya refers to a military expedition or battle in which the Prophet Muhammad (PBUH) did not personally participate.These were usually led by his companions to spread Islam or defend the community.Additional information:Ghazwa: A battle attended by Holy Prophet (PBUH).Last verified on 09-09-2026', 0, 0, 0, 1790964562757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_87a130ad8ff5f12b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Give the fundamental beliefs of Islam in the proper order?', '{"A":"Tauheed, Alhami Kutub, Risalat, and Malaika","B":"Tauheed, Risalat, Malaika, Alhami Kutub and Akhirat","C":"Tauheed, Risalat, Alhami Kutub, Akhirat and Malaika","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The fundamental beliefs of Islam are known as Arkan-e-Iman (Articles of Faith).Tauheed — Belief in the Oneness of Allah.Risalat — Belief in the Messengers of Allah.Malaika — Belief in the Angels.Alhami Kutub — Belief in the Divine Books.Akhirat — Belief in the Hereafter.Last verified on 09-09-2026', 0, 0, 0, 1790964562757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f4b662d0d70f318e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the conqueror of Central Asia?', '{"A":"Abu Ubaida Bin Jarrah","B":"Qutayba Bin Muslim","C":"Saad Bin Abi Waqas","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Qutaybah ibn MuslimCaliphate: UmayyadPosition: Governor of KhurasanTenure: 705–715 CEMajor region: Transoxiana (Central Asia)Bukhara: Conquered during 706–709 CESamarkand: Conquered in 710–712 CELast verified on 09-09-2026', 0, 0, 0, 1790964562757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_16359fb322a05979', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The First Ashra of Ramadan is known as?', '{"A":"Days to seek refuge from Hellfire","B":"Days of Forgiveness","C":"Days of Mercy","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "1st Ashra of Ramadan is "Days of mercy" (Rehmat).2nd Ashra of Ramadan is "Days of forgiveness" (Maghfirayat).3rd Ashra of Ramadan is "Days of refuge from hell fire" (Jahanum ke aag sa nijahat).Last verified on 09-09-2026', 0, 0, 0, 1790964562757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0a0430c435d52f16', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The first Muslim who sacrificed one of his eyes in the way of Allah?', '{"A":"Abu Salma","B":"Zubair bin Al-Awwan","C":"Usman bin Mazoon","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Hazrat Usman bin Mazoon (RA)Status: Early companion of Prophet Muhammad (ﷺ)Place: MakkahInjury: Lost/suffered injury to one eyeReason: Suffered persecution for the sake of IslamKnown for: Patience and sacrifice in the way of AllahLast verified on 09-09-2026', 0, 0, 0, 1790964562757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_595b61f77eb8deb9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Tragedy of Karbala took place in the year _____?', '{"A":"71 Hijri","B":"79 Hijri","C":"61 Hijri","D":"82 Hijri"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Karbala took place on Muharram 10 61 A.H (October 10, 680)In Karbala, present-day Iraq.It was fought between the army of the second Umayyad Caliph, Yazid I, and a small army led by Hussain ibn Ali (AS).The Umayyad Caliph Muawiyah I had nominated his son Yazid as his successor.Last verified on 25-04-2026', 0, 0, 0, 1790964562825) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d15c308ba9261697', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was a good Player of flute?', '{"A":"Hazart Idrees (AS)","B":"Hazart Yahya (AS)","C":"Hazart Dawood (AS)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Dawood (AS) is known for being a good player of flute.Holy Book: ZaburSpecial blessing: Beautiful and melodious voiceAssociated with: Glorification of Allah by birds and mountainsKnown for: Beautiful recitation and voiceLast verified on 09-09-2026', 0, 0, 0, 1790964562825) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4a6efc41abc66cbc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many months are there in the Islamic calendar?', '{"A":"10","B":"12","C":"14","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are 12 months in the Islamic (Hijri) calendar:Muḥarram, محرم الحرامṢafar, صفر المظفرRabi al Awwal, ربیع الاولRabi al Sani, ربیع الثانیJumada al Awwal, جمادی الاولJumada al Thani, جمادی الثانیRajab, رجب المرجبShaban, شعبان المعظمRamadan (fasting), رمضان المبارکShawwal, شوال المکرمDhu al Qadah, ذوالقعدۃ الحرامDhu al Hijjah, ذوالحجۃ الحرامLast verified on 20-07-2026', 0, 0, 0, 1790964562825) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_19f9a3b3334260f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which is the first month of Islamic Calendar?', '{"A":"Muharram","B":"Rajab","C":"Jamadi-ul-Awwal","D":"Safar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 12 Islamic MonthsMuḥarram (محرم الحرام)Ṣafar (صفر المظفر)Rabi al-Awwal (ربیع الاول)Rabi al-Thani / Rabi al-Sani (ربیع الثانی)Jumada al-Awwal (جمادی الاول)Jumada al-Thani (جمادی الثانی)Rajab (رجب المرجب)Shaʿban (شعبان المعظم)Ramadan (رمضان المبارک) – Month of fastingShawwal (شوال المکرم)Dhu al-Qaʿdah (ذوالقعدہ الحرام)Dhu al-Hijjah (ذوالحجہ الحرام) – Month of HajjLast verified on 14-03-2026', 0, 0, 0, 1790964562825) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e7b18e2f6a0de8cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Zun-Noorain is the title of _____?', '{"A":"Hazrat Abu Bakar","B":"Hazrat Umar","C":"Hazrat  Usman","D":"Hazrat Ali"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Usman ibn Affan was titled Zun-Noorain (Having Two Lights).He married two daughters of Prophet Muhammad (PBUH):Hazrat RuqaiyyaHazrat Umm-e-KulsoomThe title signifies honor of having two lights from Prophet’s family.Last verified on 30-03-2026', 0, 0, 0, 1790964562825) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b8a14215e0311ab5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Before accepting Islam, Hazrat Salman Al-Farsi (RA) belonged to which religion?', '{"A":"Zoroastrianism (Fire Worship)","B":"Christianity","C":"Judaism","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Religion: Zoroastrianism (Fire Worship)Birthplace: Persia (Iran)Later Religion: ChristianityAccepted Islam: In Madinah after meeting Prophet Muhammad (ﷺ)Famous Contribution: Suggested digging the Battle of the Trench (Ghazwa-e-Khandaq).Last verified on 11-07-2026', 0, 0, 0, 1790964562825) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e0c9d4bee46c7df3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Name the person whose house become the center of preaching of Islam?', '{"A":"Hazrat Abu Bakar","B":"Hazrat Arqam","C":"Hazrat Usman","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Arqam ibn Abi al-Arqam was a companion of Prophet Muhammad (PBUH).His house (Dar-e-Arqam) became the first center of Islamic preaching in Makkah.Early Muslims gathered there to learn Islam secretly.Birth → 597 A.DDeath → 675 A.DLast verified on 03-04-2026', 0, 0, 0, 1790964562825) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_759248eedc95f5fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Bait ul Muqadas conquered in the reign of _____?', '{"A":"Hazrat Abu Bakar R.A","B":"Hazrat Umar R.A","C":"Hazrat Usman R.A","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Umar conquered Bait Ul Maqdas in 15 A.H.Umar ibn Abd al-Aziz, commonly known as Umar II, was the eighth Umayyad caliph.Umar ibn Abd al-Aziz called the first Mujaddid.He was sixth righteous caliph of Islam after Hasan Ibn Ali.Umar ibn Abd al-Aziz was born on 2 November 682 in Medina, Umayyad Caliphate.Died on 5 February 720 (aged 37).Last verified on 06-09-2026', 0, 0, 0, 1790964562825) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_53e1418e663f6815', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many essential belief are there in Iman-e-Mufassal?', '{"A":"7","B":"5","C":"6","D":"2"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Seven essential belief are there in Iman-e-Mufassal.The meaning of Iman Mufassal:The belief in detail.Seven essential beliefs are there in Iman-e-Mafassal:1. Faith in God.2. Faith in holy angels.3. Faith in all holy Books.4. Faith in all holy Prophets.5. Faith in the Day of Judgement.6. Faith in everything good or bad is decided by God (Taqdir).7. Faith in life after death.Last verified on 16-05-2026', 0, 0, 0, 1790964562889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2a45d5438ad55c37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In which country Mount Judi (Cudi) also known as Mount Qardū exits?', '{"A":"Turkey","B":"Iraq","C":"Egypt","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Country: TurkeyMountain: Mount Judi / QardūMentioned in: Quran, Surah Hud 44Historical significance: Landing of Noah’s ArkRegion: Southeastern AnatoliaLast verified on 04-04-2026', 0, 0, 0, 1790964562889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_71b88c66d60bb192', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many Farz are there in Ghusul?', '{"A":"3","B":"4","C":"5","D":"6"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Islamic purification, Ghusl (ritual bath) has 3 Fard (obligatory acts).These are necessary for the bath to be valid according to Fiqh rules.Ghusl is required after major impurity (Janabat, Haiz, Nifas).Without completing these 3, Ghusl is not valid.Last verified on 25-04-2026', 0, 0, 0, 1790964562889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_349246108afb62f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which was the first capital of Islamic common wealth?', '{"A":"Madina","B":"Makkah","C":"Taif","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First capital: MadinaHijrah year: 622 AD (1 AH)Country: Saudi ArabiaRole: First Islamic state centerFamous mosque: Masjid al-NabawiLast verified on 27-04-2026', 0, 0, 0, 1790964562889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9bac430458da8cee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', '“Divine Decree” refers to?', '{"A":"Qadar","B":"Zakat","C":"Sawm","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qadar (قدر) means the Divine Decree or Divine Destiny of Allah.It refers to Allah’s knowledge, will, and determination concerning all things.Belief in Qadar is one of the fundamental articles of Islamic faith (Iman).It is commonly translated as Divine Decree, Predestination, or Destiny.Last verified on 02-09-2026', 0, 0, 0, 1790964562889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_05db1b9902cfc58c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the name of Hazrat Aminah''s (RA) father?', '{"A":"Wahb ibn Abd Manaf","B":"Hashim","C":"Abdul Muttalib","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Father: Wahb ibn Abd ManafMother: Barrah bint Abdul UzzaHusband: Abdullah ibn Abdul MuttalibSon: Prophet Muhammad (ﷺ)Tribe: Banu Zuhrah (Quraysh)Verified & Updated', 0, 0, 0, 1790964562889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6891513d3093d144', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Idols in Kaba before Islam numbered?', '{"A":"360","B":"260","C":"330","D":"300"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Number of idols in Kaaba: 360Famous idol: HubalWorshippers: Quraysh of MakkahRemoval of idols: Conquest of Makkah (630 AD / 8 AH)Place: Kaaba, MakkahLast verified on 02-07-2026', 0, 0, 0, 1790964562889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6066c8dbba1a24c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is it named to run between Safa and Marwa?', '{"A":"Sayee","B":"Rami","C":"Hajjar-e-Aswad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sayee is the act of walking or running seven times between the hills of Safa and Marwa in Makkah.It is a required ritual in Hajj and Umrah.Additional information:Location: Masjid al-Haram, MakkahPerformed after: Tawaf (circumambulation of Kaaba)Next ritual after Sayee: Hujjaj go to MinaSymbolism: Hajar’s search for water for her son, Prophet Ismael (PBUH)Last verified on 15-03-2026', 0, 0, 0, 1790964562889) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_401dfaba7abb6992', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Social Boycott of Banu Hashim was continued for _____ years.', '{"A":"3","B":"4","C":"5","D":"8"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Social Boycott of Banu Hashim started in the 7th year of Prophethood (Nabvi).It was imposed by the Quraysh of Makkah against Banu Hashim and early Muslims.The boycott continued for 3 years (7th–10th Nabvi).Last verified on 03-04-2026', 0, 0, 0, 1790964562962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e3d7d8f4053823cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many tribes of jews were there in Medina?', '{"A":"3","B":"2","C":"5","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There were three major Jewish tribes in Madinah.Banu QaynuqaBanu NadirBanu QurayzaPeriod: During the Prophet''s (ﷺ) migration and early Madinan periodVerified & Updated', 0, 0, 0, 1790964562962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_54ebea87664bd37c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is Grandfather father of Hazrat Muhammad SAW?', '{"A":"Hazrat Abdul Muttalib","B":"Hazrat Abu Talib","C":"Hazrat Abbas","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Family of the Holy Prophet Muhammad (ﷺ):Father: Hazrat Abdullah (R.A)Mother: Hazrat Amina (R.A)Grandfather: Hazrat Abdul MuttalibGrandmother: Fatimah bint AmrUncle: Hazrat Abu Talib (chief guardian in youth)(Also: Hamza, Abbas, Abu Lahab — other uncles)Last verified on 02-09-2026', 0, 0, 0, 1790964562962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_37a862a9e016e4fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Name the mother of Hazrat Yousaf (AS)?', '{"A":"Nafeesa","B":"Raheel","C":"Sara","D":"Zainab"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The mother of Hazrat Yousaf (AS) was Hazrat Raheel (Rachel).Hazrat Yousaf (AS) was one of the twelve sons of Hazrat Yaqub (AS).Brother (same mother): Hazrat Binyamin (Benjamin) (AS)Surah: Surah Yusuf (12th Surah of the Holy Qur''an)Last verified on 25-04-2026', 0, 0, 0, 1790964562962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_281ab4cc8bcfedd0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Halima belonged to the tribe of ______?', '{"A":"Banu Hashim","B":"Banu Khazeema","C":"Banu Saad","D":"Banu Atiyah"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tribe: Banu SaadFull name: Halima Saadia (RA)Relation: Foster mother of Prophet Muhammad ﷺFoster care: About 6 yearsTribal affiliation: Banu Saad was part of Hawazin.Last verified on 01-09-2026', 0, 0, 0, 1790964562962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bd387443a4ce9b5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In which islamic month Laylat al-Qadr is happened?', '{"A":"Ramzan","B":"Shaban","C":"Hajj","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Laylat al-Qadr (Night of Decree/Power) occurs in the last ten nights of Ramadan.It is described in the Qur’an as better than a thousand months.It is the blessed night on which the Qur’an was revealed.It is sought particularly on the odd nights of the last ten nights: 21st, 23rd, 25th, 27th, and 29th Ramadan.Last verified on 01-09-2026', 0, 0, 0, 1790964562962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_39b48f909e0e0914', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Stones for Ramy-e-Jamarat are picked up from?', '{"A":"Mina","B":"Muzdalifah","C":"Arfat","D":"Medina"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pilgrims traditionally collect pebbles (Rami stones) at Muzdalifah for the stoning of the Jamarat.They collect these pebbles after leaving Arafat on the 9th of Zil-Hajj.The pebbles are used for Ramy-e-Jamarat in Mina.This ritual commemorates Prophet Ibrahim’s (AS) rejection of Satan.Last verified on 28-08-2026', 0, 0, 0, 1790964562962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3c4cddf32fbdb6bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which day is called Yawm-e-Tarwiyah?', '{"A":"8th Dul Hijjah","B":"9th Dul Hijjah","C":"10th Dul Hijjah","D":"11th Dul Hijjah"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Yawm-e-Tarwiyah is the 8th of Dhul Hijjah. It is the first day of Hajj.Additional information:9th Dhul Hijjah: Day of Arafat (Wuquf-e-Arafat)10th Dhul Hijjah: Eid-ul-Adha (Yawm-un-Nahr)11th Dhul Hijjah: First day of Ayyam al-Tashreeq12th–13th Dhul Hijjah: Remaining days of Ayyam al-TashreeqVerified & Updated', 0, 0, 0, 1790964562962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7be58e32187ba56b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Muzdalifah is situated ___?', '{"A":"Between Kaaba and Mina","B":"Betwee Mina and Arafat","C":"Between Safa and marwa","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muzdalifah is situated southeast of Mina.It is on the route between Mina and the Plain of Arafat.Pilgrims stay at Muzdalifah after leaving Arafat on 9th Zil-Hajj.They collect pebbles there for the symbolic stoning of the Jamarat.Maghrib and Isha prayers are offered together at Muzdalifah.Last verified on 28-08-2026', 0, 0, 0, 1790964563033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a590049bfdef4a18', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Abbreviated Letters Alif Laam Meem, Ya Seen, Ha Meem, etc. are known as the Huroof _____?', '{"A":"Al-Muqattaat","B":"Al-Shamsi","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alif Laam Meem (الم), Ya Seen (يس), Ha Meem (حم) are examples of Huroof al-Muqatta''at.These are disjointed/abbreviated letters found at the beginning of certain Surahs of the Qur’an.Their exact meaning is known only to Allah.They occur at the beginning of 29 Surahs of the Qur’an.Last verified on 26-08-2026', 0, 0, 0, 1790964563033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_88c39a0a044b572d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In which sea was Pharaoh (Firon) and his troops were drowned?', '{"A":"Dead Sea","B":"Black Sea","C":"Red Sea","D":"Mediterranean Sea"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pharaoh (Firon) and his army were drowned in the Red Sea while pursuing Prophet Musa (Moses) (AS) and the Israelites.Allah parted the sea for Prophet Musa (AS) and his followers to cross safely.When Pharaoh and his army followed them, the waters returned and they were drowned.This event is mentioned in the Qur’an, including Surah Al-Baqarah (2:50) and Surah Yunus (10:90–92).Last verified on 26-08-2026', 0, 0, 0, 1790964563033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_262741c490b64a5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'A person who recites Kalma of Islam verbally not heartilly is called?', '{"A":"Munafiq","B":"Muslim","C":"Murtad","D":"Momin"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A person who reads the Kalima of Islam verbally and calls himself Muslim but disbelieves it heartily is called a “Hypocrite” (Munafiq).Munafiq is a person who in public and in the community shows that he is a Muslim but rejects Islam In Islam, the munafiq or false Muslims or false believers.The hypocrisy itself is called nifāq (نفاق).Last verified on 23-08-2026', 0, 0, 0, 1790964563033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_48e0cb6663df4aed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Atique is the title of _____?', '{"A":"Hazrat Umar (R.A.)","B":"Hazrat Usman (R.A.)","C":"Hazrat Abu Bakr (R.A.)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Atiq (عَتِیق) is a famous title of Hazrat Abu Bakr (R.A.).He was the first Caliph of Islam.He succeeded the Holy Prophet Muhammad ﷺ after his demise.His caliphate lasted from 632 to 634 AD.Last verified on 23-08-2026', 0, 0, 0, 1790964563033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6147b4d399ae8998', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Name the Angel who takes out souls of life bearing creatures?', '{"A":"Hazrat Israfeel (AS","B":"Hazrat Jibraeel (AS)","C":"Hazrat Izraeel (AS)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Izra''eel (AS): Responsible for taking the souls of living beings.Additional information:Hazrat Jibra''eel (AS): Responsible for bring Allah’s message and commands to his prophets (AS)Hazrat Mika''eel (AS): Responsible for rain and sustenance.Hazrat Israfeel (AS): Responsible for blowing the Trumpet (Sur) on the Day of Judgment.Last verified on 16-07-2026', 0, 0, 0, 1790964563033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5beb38bd358a5a62', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Maseeh ul Islam is the title of _____?', '{"A":"Hazrat Abu Zar Ghaffari R.A","B":"Hazrat Abu Talha R.A","C":"Hazrat Ali R.A","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Dharr Al-Ghifari was the fourth or fifth person converting to Islam and from the Muhajirun. Died: 652 AD, Al RabathaFull Name: Abu Dharr al-Ghifari al-Kinani', 0, 0, 0, 1790964563033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1f0fa762976ab0c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Imam Al Nasai was born in _____?', '{"A":"214 Hijri","B":"216 Hijri","C":"212 Hijri","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Imam Al-Nasai, a renowned Islamic scholar and compiler of the Sunan al-Sughra (one of the six canonical hadith collections), was born in 214 Hijri (AH) or 829 CE.Imam Al-Nasai passed away in 303 Hijri (AH) or 915 CE.', 0, 0, 0, 1790964563033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f73c31bec9f1072b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Imam Ahmad bin Hanbal was born in ______?', '{"A":"164 A.H","B":"163 A.H","C":"162 A.H","D":"161 A.H"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Imam Ahmad bin Hanbal was born in 164 A.H in Baghdad.He passed away in 241 A.H.He was a notable Islamic scholar.He was the founder of the Hanbali school of jurisprudence, having studied under Imam Shafi''i.Last verified on 05-08-2026', 0, 0, 0, 1790964563104) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8c483079888080f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who conquered the fort of Qamus?', '{"A":"Hazrat Ibrahim (R.A)","B":"Hazrat Umar (R.A)","C":"Hazrat Usman (R.A)","D":"Hazrat Ali (R.A)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ali ibn Abi Talib (RA) conquered the Fort of Qamus.This happened during the Battle of Khaybar.The fort belonged to the Jewish tribe of Khaybar (Banu Nadir).Year: 7 AH / 628 ADMuslim martyrs: 15Opponents killed: ~93Last verified on 27-04-2026', 0, 0, 0, 1790964563104) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7c58e9981de4052b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Hafsa was the daughter of _______?', '{"A":"Hazrat Usman","B":"Hazrat Ali","C":"Hazrat Umer","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Hafsa (RA) was the daughter of Hazrat Umar ibn al-Khattab (RA), the second Caliph of Islam.Her mother was Zaynab bint Maz''un (RA).She became one of the Mothers of the Believers (Ummahat al-Mu''minin) after marrying Prophet Muhammad ﷺ.The marriage took place in Sha''ban, 3 AH (625 CE).Hazrat Hafsa (RA) was known for her knowledge, piety, and preservation of the Qur''an.Last verified on 05-08-2026', 0, 0, 0, 1790964563104) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5e800878ef07c58a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The biggest/largest Islamic country by area is _____?', '{"A":"Sudan","B":"Libya","C":"Kazakhstan","D":"Egypt"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largest Muslim country by area is Kazakhstan.Largest Muslim country by Population is Indonesia.Additional information:World Largest country by area is Russia.World Largest Country by Population is India.Last verified on 27-07-2026', 0, 0, 0, 1790964563104) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1a6236588789ae1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In which hijri year Qibla was change?', '{"A":"4","B":"3","C":"5","D":"2"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It happened during the month of Sha''ban, 2 AHWhile the Prophet ﷺ was leading the Dhuhr (or Asr) prayer Masjid al-QiblatainThe verse revealed was Surah Al-Baqarah 2:144: "Turn your face toward Al-Masjid Al-Haram..."Additional information:The first Qibla Muslims prayed for is Al-Aqsa mosque المسجد الأقصى (Bait Al-Maqdis بيت المقدس)***Last updated 24-07-2026 by NA', 0, 0, 0, 1790964563104) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5be89bc460ad4438', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is meant by Rami al-Jamarat?', '{"A":"Sacrificing an animal during Hajj","B":"Stoning the pillars representing Satan","C":"Drinking Zamzam water","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rami al-Jamarat is a mandatory Hajj ritualinvolving the symbolic stoning of three pillars in Mina10th Dhu al-Hijjah: Only the Jamrat al-Aqabah (the largest pillar) is stoned.11th & 12th Dhu al-Hijjah: All three pillars (Small, Medium, Large) are stoned in order.The act of throwing stones at the Jamarat is known as “Rami”.Last updated by NA on 26 April 2026', 0, 0, 0, 1790964563104) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e5dadb94b0eb5c12', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the real name of Najashi, the King of Abyssinia?', '{"A":"Asmaha","B":"Numan","C":"Habib","D":"Fasi"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Real Name: Asmaha ibn AbjarTitle: Najashi (Negus)Kingdom: Aksum (Abyssinia, present-day Ethiopia)Muslims migrated to Abyssinia: 615–616 CEReign: 614–630 CE (approximately 17 years)Last verified on 22-07-2026', 0, 0, 0, 1790964563104) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c6b137f48146a99e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first male martyr (Shaheed) of Islam?', '{"A":"Hazart Zaid Bin Haris (RA)","B":"Hazrat Shoaib Roomi (RA)","C":"Hazrat Yasir ibn Amir (RA)","D":"Hazrat Haris bin Halla (RA)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Yasir ibn Amir (RA), was the first male martyr (Shaheed) in Islam.Additional information:His wife Hazrat Sumayyah bint Khayyat (RA), is the first female martyr (Shaheedah) of Islam.Hazrat Harith bin Abi Hala (RA) is the first child martyr (Shaheed).Last verified on 01-07-2026', 0, 0, 0, 1790964563104) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_084370670760e870', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who is called Umar-e-Sani?', '{"A":"Hazrat Umar bin Abdullah R.A","B":"Hazrat Umar bin Khataab R.A","C":"Hazrat Umar bin Abdul Azeez R.A","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Umar bin Abdul Azeez R.A is known as "Umar-e-Sani" (the second Umar).He was the eighth Umayyad caliph.He ruled from 717 to 720 CE.He was known for justice and piety.He followed the principles of Hazrat Umar (RA).Last update 0n 21-07-2026 by NA', 0, 0, 0, 1790964563184) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c645f50a90018975', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who accepted Islam first in Children?', '{"A":"Hazrat Usman (RA)","B":"Hazrat Umar (RA)","C":"Hazrat Ali (RA)","D":"Hazrat Bilal (RA)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali (RA) was the first child to accept Islam.He was the cousin of the Prophet Muhammad ﷺ.Son-in-law of the Islamic prophet MuhammadHe became the fourth Caliph of Islam.Ruled from 656 CE until his assassination in 661Tribe: Quraysh (Banu Hashim)Father: Abu Talib ibn Abd al-MuttalibMother: Fatima bint AsadLast update 0n 21-07-2026 by NA', 0, 0, 0, 1790964563184) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_822733c9213860a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'When Abraha launched an attack on Ka’aba?', '{"A":"570 BC","B":"571 BC","C":"577 BC","D":"573 BC"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abraha was the ruler of Yemen.His army included elephants, so the event is called the Year of the Elephant.Allah protected the Kaaba and destroyed Abraha''s army.The event occurred around 570 CE, the traditional year of the birth of Prophet Muhammad ﷺ.Last update 0n 21-07-2026 by NA', 0, 0, 0, 1790964563184) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_af29a3a7709ae47a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the founder of Sikhism (Sikh religion)?', '{"A":"Veshnu","B":"Shiva","C":"Guru Nanak","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Guru Nanak DevFounderSikhismBorn1469Born inNankanaDied1539Resting placeKartarpurLast verified on 21-07-2026', 0, 0, 0, 1790964563184) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_96e1f1d6c5d91e81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The most national holistically minded today would admit that we have some _____ to all humanity.', '{"A":"Obligations","B":"Duties","C":"Rights","D":"Values"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The most nationally holistic-minded people today admit that we have some duties to all humanity.Ethics teaches that every individual has responsibilities not only to their nation but also to humanity as a whole.These duties promote peace, justice, and human welfare.Last verified on 21-07-2026', 0, 0, 0, 1790964563184) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0665cbb352ddfee0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The level at which an individual judges ''what is right and what is wrong'' has been called the level of?', '{"A":"Consciousness","B":"Morality","C":"Conduct","D":"Ethics"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Morality is the level at which an individual judges what is right and what is wrong.It refers to a person''s principles and standards of good and bad behavior.Morality guides individuals in making ethical decisions in daily life.Last verified on 21-07-2026', 0, 0, 0, 1790964563184) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1b7fa9dc3c3827d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which of the following was the first slave to accept Islam?', '{"A":"Hazrat Bilal","B":"Hazrat Osama","C":"Hazrat Suleman","D":"Hazrat Zaid bin Haris"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Freed Slave: Zayd ibn Harithah (RA)Additional information:First woman: Khadijah bint Khuwaylid (RA)First adult man: Khadijah bint Khuwaylid (RA)First Child: Ali ibn Abi Talib (RA)Last verified on 07-07-2026', 0, 0, 0, 1790964563184) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6856a497dc3f8077', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Torah is the holy book of which Religion?', '{"A":"Jews","B":"Judaism","C":"Zoroastrians","D":"Both A & B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jews and Judaism, because "Jews" refers to the people who follow the religion, and "Judaism" is the name of the religion itself.Religion: JudaismFollowers: JewsBooks in the Torah: 5 (Pentateuch)Revealed to: Prophet Musa (Moses, A.S.)Revealed at: Mount Sinai (over 3,000 years ago, according to Jewish tradition)Last verified on 21-07-2026', 0, 0, 0, 1790964563184) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f3b2de7644903d71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who bears the title of Ameen-ul-Ummat (Trustee/Trustworthy of the Ummah)?', '{"A":"Hazrat Umar","B":"Hazrat Abu Akbar","C":"Hazrat Abu Ubaidah Bin Jarah","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Ubaidah bin al-Jarrah (RA) was one of the Ashra Mubashra.He was given the title Ameen-ul-Ummat (Trustee of the Ummah).He was known for honesty, trustworthiness, and leadership.He played an important role in Islamic conquests in Syria.He was among the closest companions of the Prophet (PBUH).Last verified on 28-04-2026', 0, 0, 0, 1790964563242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1935cbaf7d24a589', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'When does the treaty (truce) of Hudaibiya take place?', '{"A":"6th Hijri","B":"7th Hijri","C":"8th Hijri","D":"9th Hijri"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Al-Hudaibiyah Treaty was signed in 6 AH for 10 years.It was scribed by Ali ibn Abi Talib (R.A).Hudaibiyah is the name of tree.It is referred to as "Fatah Al-Mubeen" (the clear victory) in Surah Al-Fatah.The event occurred during the time of the Islamic Prophet Muhammad SAW.It was a pivotal agreement between Muhammad ﷺ representing Medina and the Qurayshi tribe of Mecca.Suhail bin Amr signed on behalf of Mecca.It contained 7 clauses.Last verified on 01-04-2026', 0, 0, 0, 1790964563242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4ecf91f2a96a9c5b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who is called the conqueror of Egypt?', '{"A":"Saad bin Abi Waqas","B":"Amr ibn al-Aas","C":"Khalid bin Waleed","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amr ibn al-Aas (RA) is called the conqueror of Egypt.He led the Muslim conquest of Egypt during 640–646 AD.The conquest was carried out under the Rashidun Caliphate.Later, he also served as the governor of Egypt.He was appointed commander by Hazrat Abu Bakr (RA) and served under Hazrat Umar (RA).Last verified on 26-04-2026', 0, 0, 0, 1790964563242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_364521ce7d44937f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who is remembered as first Muslim (Islam) socialist?', '{"A":"Hazrat Miqsad (RA)","B":"Hazrat Talha bin Usaid (RA)","C":"Hazrat Abuzar Ghaffari (RA)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Hazrat Abu Zar Ghaffari (R.A.)Tribe: Banu GhifarStatus: Among the earliest MuslimsKnown For: Simplicity, justice, and support for the poorDied: 652 AD (32 AH)Last verified on 19-07-2026', 0, 0, 0, 1790964563242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_48f5200a7e5f3891', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What do you understand by "Bait ul Ateeq"?', '{"A":"The Holy Kaaba","B":"Masjid-e-Nabvi","C":"Bait-Ul-Muqadas","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Bait ul Ateeq” refers to the Holy Kaaba.It means the “Ancient House of Allah”.It is the first house built for worship on Earth.Muslims face it during prayers (Qiblah).It is located in Makkah, Saudi Arabia.Last verified on 25-04-2026', 0, 0, 0, 1790964563242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_39b9bc2aceba8b6c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first female martyr (Shaheed) of Islam?', '{"A":"Hazrat Nafeesa (RA)","B":"Hazrat Sumaiyyah (RA)","C":"Hazrat Umm-e-Aimen (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Sumayyah bint Khayyat (RA) is the first female martyr (Shaheedah) of Islam.Additional information:Hazrat Yasir ibn Amir (RA), was the first male martyr (Shaheed) in Islam.Hazrat Harith bin Abi Hala (RA) is the first child martyr (Shaheed).Last verified on 01-07-2026', 0, 0, 0, 1790964563243) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_90c6489e43a39b59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who among the following is not in Ashara-e-Mubashara?', '{"A":"Hazrat Umar (RA)","B":"Hazrat Abu Obaida (RA)","C":"Hazrat Abu Huraira (RA)","D":"Hazrat Saeed bin Zaid (RA)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Huraira (R.A.) was not among the Ashara-e-Mubashara.Ashara-e-Mubashara are the ten Companions whom Prophet Muhammad (ﷺ) gave the glad tidings of Paradise.Hazrat Abu Bakr (R.A.)Hazrat Umar (R.A.)Hazrat Uthman (R.A.)Hazrat Ali (R.A.)Hazrat Talha bin Ubaidullah (R.A.)Hazrat Zubair bin Al-Awwam (R.A.)Hazrat Abdur Rahman bin Awf (R.A.)Hazrat Sa''d bin Abi Waqqas (R.A.)Hazrat Saeed bin Zaid (R.A.)Hazrat Abu Ubaidah ibn Al-Jarrah (R.A.)Last verified on 18-07-2026', 0, 0, 0, 1790964563243) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3ea8d2a42eb8a258', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Al-Sab''a Al-Masani means?', '{"A":"Surah Fatiha","B":"Surah yaseen","C":"Surah Rahman","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Sab''a Al-Masani refers to Surah Al-Fatihah.It means "The Seven Repeated Verses" because Surah Al-Fatihah has 7 verses and it is recited in every Rak''ah of Salah.It is mentioned in Qur''an 15:87.Surah Al-Fatihah is the opening chapter of the Qur''an.Last verified on 18-07-2026', 0, 0, 0, 1790964563243) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_51256165d04a4fd2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Zam Zam is the spring of water that emerged from beneath the feet of Hazrat Ismaeel (A.S). What is the meaning of Zam Zam?', '{"A":"To burst","B":"To continue","C":"To stop","D":"To flow"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zam Zam means "to stop."The Zamzam Well is located within the Masjid al-Haram in Mecca, Saudi Arabia.It 20 meters (66 feet) east of the Kaaba.Millions of pilgrims visit the well each year during Hajj or Umrah to drink its water.Last verified on 30-06-2026', 0, 0, 0, 1790964563320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ad99be2d84c31904', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which Holy Book is called the Old Testament?', '{"A":"The Zuboor","B":"The Torait (Bible)","C":"The Injeel","D":"The Quran"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Torait (Tawrat) is known as the Old Testament in the Bible. It was revealed to Prophet Musa (Moses A.S.). It contains laws and teachings given to the Israelites.Additional information:Zabur → Revealed to Prophet Dawood (A.S.)Injeel → Revealed to Prophet Isa (A.S.)Qur''an → Revealed to Prophet Muhammad (ﷺ)Last verified on 02-04-2026', 0, 0, 0, 1790964563320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5270c36610c489a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Miraj Shareef event occurred on _____?', '{"A":"8th nabvi","B":"9th nabvi","C":"10th nabvi","D":"11th nabvi"}', 'C', NULL, 0, 0, 0, 1790964563320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_027e0557592589e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Jannat-ul-Baqi is situated in _____?', '{"A":"Madina","B":"Makkah","C":"Taif","D":"Jeddah"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jannat al-Baqīʿ, located in Medina, Saudi Arabia.It is the oldest and first Islamic cemetery.It situated southeast of the Prophet''s Mosque.It contains the graves of some of Prophet Muhammad''s family and friends.The first companion buried there was Uthman Ibn Madhoon.Hazrat Khadija (RA) is the only Ummul Momineen not buried in Jannat al-Baqīʿ.Last verified on 25-04-2026', 0, 0, 0, 1790964563320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7cf570ae5e1ef348', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Cave Hira is in the _______ mountain.', '{"A":"As-Safa","B":"Uhud","C":"Al-Noor","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cave Hira (Ghar-e-Hira) is located on Jabal Al-Noor mountain.Jabal Al-Noor also Called the “Mountain of Light” or “Hill of Illumination”.It takes around 45 minutes to reach the top.Muhammad SAW first received revelation in a Mount Hira cave.The Holy Qur’an was revealed from 610-632 AD.Last verified on 30-03-2026', 0, 0, 0, 1790964563320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f3a899b5fb9499ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The kissing or touching of Hajr-e-Aswad is known as?', '{"A":"Istelam","B":"Tawaf","C":"Saee","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Istelam means kissing Hajr-e-Aswad (the Black Stone) or touching it.Aswad means کالا یا سیاہ رنگ کاIt is located in the eastern corner of the Kaaba.It is performed during Tawaf in Hajj and Umrah.It shows love and respect for the Sunnah of Prophet Muhammad (PBUH).Last verified on 16-05-2026', 0, 0, 0, 1790964563320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_55f79936c917d53b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The portion of the wall of Kaba which is between its door and Hajr-e-Aswad is called ____?', '{"A":"Haram","B":"Hateem","C":"Al-Multazim","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The portion of the Kaaba''s wall between its door and Hajr-e-Aswad is called Al-Multazim.It is a blessed place where pilgrims often make du''a (supplication).Many people hold onto this part of the Kaaba while praying.It is located on the eastern wall of the Kaaba.Last verified on 02-08-2026', 0, 0, 0, 1790964563320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2d2f0acae4e9abd5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The famous "Dome of the Rock" at Jerusalem was built by?', '{"A":"Abdul Malik","B":"Hisham","C":"Marwan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Completed: 691–692 CE by Umayyad Caliph Abd al-MalikLocation: Temple Mount, Old City of JerusalemBuilt on: Site of the Second Jewish TempleHistorical Fact: Original temple destroyed in 70 CE by RomansSignificance: Important Islamic shrine and landmarkLast verified on 15-01-2026', 0, 0, 0, 1790964563320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a30cfbef194a2aa4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The religion which considers Hazrat Mikael (AS) superior/preferred to/on Hazrat Jibrael (AS)?', '{"A":"Christianity","B":"Jewism","C":"Islam","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jews considered Hazrat Mikael (A.S.) superior to Hazrat Jibrael (A.S.).They accepted Mikael (A.S.) but showed hostility towards Jibrael (A.S.).The Qur''an rejected this attitude.Allah declared that whoever is an enemy to Jibrael (A.S.) is opposing Allah''s command.This is mentioned in Surah Al-Baqarah.Verified & Updated', 0, 0, 0, 1790964563416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9225cdcf6bc4ac31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'A land tax imposed on the non-Muslims cultivators and landlords is known as ______?', '{"A":"Jizya","B":"Kharaj","C":"Khums","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A land tax imposed on non-Muslim cultivators and landlords was known as KharajNon-Muslim subjects paid kharaj on their lands; Muslim landowners generally paid ''ushrAdditional information:Jizyah: Personal tax on eligible non-Muslim adult malesKhums: One-fifth (20%) of war booty and certain other specified gainsZakat: 2.5% annual tax on eligible Muslim wealthUshr: One-tenth (10%) of agricultural produce from naturally irrigated Muslim-owned landLast updated by NA on 09-09-2026', 0, 0, 0, 1790964563416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_600088289d184dd2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The nation of Samood (Samud) was preached by?', '{"A":"Hazrat Yakoob (AS)","B":"Hazrat Salih (AS)","C":"Hazrat Loot (AS)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Salih (AS) was sent by Allah to guide the nation of Samood.The people of Samood lived in Al-Hijr (northwestern Arabia).They were skilled at carving houses into mountains.Punishment: A mighty earthquake and a terrible blast destroyed the nation.Famous Miracle: The pregnant she-camel (Naqatullah) came out of a rock by Allah''s command.Last verified on 26-04-2026', 0, 0, 0, 1790964563416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_83301d0d941d1a32', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which tribe was from the generation of Hazrat Ismaeel (A.S.)?', '{"A":"Banu Asd","B":"Banu Umayya","C":"Banu Abbas","D":"Banu Quraysh"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Banu Quraysh tribe, which is the tribe of the Prophet Muhammad (PBUH), is indeed descended from Hazrat Ismaeel (A.S.).Hazrat Ismail (AS) is called ''Zabeeh Ullah'' (Zabiullah).He was Son of Hazrat Ibrahim (A.S) & Hazrat Hajra (A.S).Prophet Ismail (AS) and Prophet Ishaq (AS) are Brothers.Last verified on 09-07-2026', 0, 0, 0, 1790964563416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_219219ded72fff28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is Istelam?', '{"A":"Salam to Kaaba","B":"Kissing Hajr-e-Aswad","C":"Praying at Muqam-e-Ibrahim","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Istelam means kissing Hajr-e-Aswad (the Black Stone) or touching it.Aswad means کالا یا سیاہ رنگ کاIt is located in the eastern corner of the Kaaba.It is performed during Tawaf in Hajj and Umrah.It shows love and respect for the Sunnah of Prophet Muhammad (PBUH).Last verified on 16-05-2026', 0, 0, 0, 1790964563416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_22c4cfecec26cd98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The number of Ashab-e-Kahf was?', '{"A":"5","B":"6","C":"7","D":"8"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Number of Ashab-e-Kahf: 7They took refuge in a cave to protect their faith and slept for 309 years by the will of Allah.Surah: Surah Al-Kahf (18th chapter)Verses: 9–26Dog''s name: Qitmeer (Qitmīr)The word "Kahf" means "a cave in a mountain."Last verified on 03-07-2026', 0, 0, 0, 1790964563416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fdf68c1fb9846845', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The term ''Aqeedah'' (literal meaning) in Islam refers to?', '{"A":"The tie of knot","B":"Religious creed and beliefs","C":"Islamic law","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aqeedah means both "the tie of a knot" (literal meaning) and "religious creed and beliefs" (Islamic meaning).The Arabic root "ʿAqd" (عقد) means to tie or bind firmly.In Islam, Aqeedah refers to the firm beliefs that every Muslim must hold.Last verified on 07-07-2026', 0, 0, 0, 1790964563416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_83b321a1f5b5bbe4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the meaning of Tauheed?', '{"A":"The Oneness of Allah","B":"The Prophethood","C":"Angels","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790964563416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ac05ba273878b4b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who holds the key to Kabba?', '{"A":"Hazrat Usman bin Affan (RA)","B":"Hazrat Usman bin Talha (RA)","C":"Hazrat Bilal (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad entrusted the key to Uthman ibn Talha (RA) This took place after the Conquest of Makkah (8 AH / 630 AD).The descendants of Uthman ibn Talha, known as the Al-Shaibi familyThe Prophet (SAW) declared the trust would remain with that family forever.The role of the keykeeper is called Sadanah al-Kaaba. Last updated by NS on 06-09-2026​', 0, 0, 0, 1790964563555) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b8b33119ce0437b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Aitekaaf (Seclusion) during the month of Ramzan is ____?', '{"A":"Sunnah","B":"Mustahab","C":"Wajib","D":"Nafl"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aitekaaf during Ramadan is Sunnah Muakkadah (an emphasized Sunnah).It is highly recommended.It is usually observed during the last 10 days of Ramadan.The purpose of Aitekaaf is to devote oneself to worship, prayer, and remembrance of Allah.It was the regular practice of Prophet Muhammad (ﷺ).Last verified on 07-07-2026', 0, 0, 0, 1790964563555) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2c6e2e77f027c76d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In which year, the order of the Hijab for women was revealed?', '{"A":"3rd A.H","B":"4th A.H","C":"5th A.H","D":"6th A.H"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hijab order year: 4 A.HRelated Surahs: An-Nur (24), Al-Ahzab (33)Main concept: Modesty and covering (Purdah)Purpose: Moral protection of societyRevelation place: Madinah (Medinan verses)Last verified on 27-04-2026', 0, 0, 0, 1790964563555) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d4887d2549c62781', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the punishment of Had-e-Qazf (false Accusation)?', '{"A":"50 Lashes","B":"70 Lashes","C":"80 Lashes","D":"90 Lashes"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The punishment of Had-e-Qazaf (false accusation of Zina) is 80 lashes.Qazaf means making a false accusation of Zina (adultery/fornication) against a chaste person without producing four witnesses.Lashes mean کوڑےQuranic Reference: Surah An-Nur (24:4)Last verified on 02-07-2026', 0, 0, 0, 1790964563555) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8c46c4c854e70983', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Compilation of Ahadith is called _____?', '{"A":"Tadveen","B":"Jama al Hadith","C":"Maariz","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The compilation of Ahadith is called Tadveen (تدوین).It refers to the systematic collection, writing, and arrangement of the sayings and actions of the Holy Prophet ﷺ.Malik ibn Anas was the first to undertake a comprehensive and systematic compilation of Hadith.His famous Hadith collection is Al-Muwatta.Last verified on 03-07-2026', 0, 0, 0, 1790964563555) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_97807e61a99fa257', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who establishes Bait Ul Mal?', '{"A":"Hazrat Abu Bakar (RA)","B":"Hazrat Umar ibn al-Khattab (RA)","C":"Hazrat Usman (RA)","D":"Hazrat Ali (RA)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Umar ibn al-Khattab (RA) established the system of Bait-ul-Mal.He appointed Abdullah ibn Masud (RA) as its custodian.Bait-ul-Mal means the House of Wealth / Public Treasury.It was used to manage Islamic state finances.This system ensured fair distribution of resources.Last verified on 27-04-2026', 0, 0, 0, 1790964563555) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c6f37bfea7265281', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who is first muazzin of Islam is?', '{"A":"Hazrat Bilal","B":"Hazrat Umar","C":"Abu Bakar","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Azan (Fajr Prayer) in Islam was called in 1 A.H.It was established after the migration to Madinah.Bilal ibn Rabah (RA) was the first Muezzin.He is known as Sayyid al-Mu’azzinin (Leader of Muezzins).He was chosen by Prophet Muhammad (PBUH).The purpose was to call Muslims to prayer.Last verified on 28-04-2026', 0, 0, 0, 1790964563555) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b03c9cf108aa6147', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the old name of Madina?', '{"A":"Bakkah","B":"Hujaz","C":"Najad","D":"Yasrab"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The old name of Madinah (Medina) was Yathrib (Mentioned as Yasrab in Quran, Chapter 33 (Al-Aḥzāb).Renamed Madīnat an-Nabī (“City of the Prophet”) After Prophet Muhammad SAW’s migration in 622 CELocated in the Hejaz region, Saudi Arabia.*****Last updated by NA on 25-April-2026', 0, 0, 0, 1790964563555) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d2ca816f24a900e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who is the gatekeeper of hell?', '{"A":"Sabeel","B":"Maalik","C":"Rizwan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maalik (مالک) is the gatekeeper of Hell (Jahannam).Maalik is described as the chief guardian of the angels of Hell.He is mentioned in the Quran in Surah Az-Zukhruf (43:77).He is known as the keeper of Hellfire.Additional information:Rizwan (رضوان) → Gatekeeper of Heaven (Jannah)Jibreel (علیہ السلام) → Angel of revelationIsrafeel (علیہ السلام) → Angel who will blow the trumpet on the Day of JudgmentMikaeel (علیہ السلام) → Angel associated with provision and natural phenomenaLast verified on 30-06-2026', 0, 0, 0, 1790964563633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1793aebee03513f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The meaning of word Risalat is _____?', '{"A":"Leader","B":"Guide","C":"Messenger","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Risalat means Messenger or conveying a message.The word Risalat is derived from the Arabic word “Rasal”, which means to send.In Islamic terms, it refers to conveying the message of Allah to His servants through Prophets.Prophets are called Messengers of Allah (Rusul) because they deliver His guidance.Last verified on 24-06-2026', 0, 0, 0, 1790964563633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f6f0cd9fbcd8df3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Injeel means?', '{"A":"Peace","B":"Sign","C":"Good news","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Injeel Meaning: “Good News”.It is lso called Gospel (means Truth)It is the holy book revealed by Allah to Hazrat Isa (A.S).It was revealed in Hebrew.Last verified on 24-06-2026', 0, 0, 0, 1790964563633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_65b234d4e8abbbdc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Name the Creation of Allah who are made of smokeless fire?', '{"A":"Jinns","B":"Plants","C":"Angels","D":"Animals"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jinns are a creation of Allah made from smokeless fire.They are invisible to humans but have free will, unlike angels.Mentioned in the Quran: Surah Al-Rahman (55:15) and Surah Al-Hijr (15:27).Last verified on 08-03-2026', 0, 0, 0, 1790964563633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c2d7bf928cc57e21', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Current Hijri/Islamic year is?', '{"A":"1446 AH","B":"1447 AH","C":"1448 AH","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The current Hijri year is 1448 AH (After Hijrah), which started on 17 June 2026.Starting event: Hijrah of Prophet Muhammad SAW from Makkah to Madina (622 AD)Introduced by: Hazrat Umar (RA) (17 AH/638 AD)Additional information:Total months: 12Normal year: 354 days (Solar year 365 days)Leap year: 355 days (Solar year 366 days)Each month: 29 or 30 days (Solar year 30 or 31 days)Islamic year is 10–11 days shorter than the Gregorian year (lunar cycle).Last verified on 21-06-2026', 0, 0, 0, 1790964563633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_91dd565b2cca1062', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Laws about Inheritance revealed in ___ A.H.', '{"A":"1","B":"2","C":"3","D":"4"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Islamic law of inheritance is a system outlined in the Qur’an and Prophet Muhammad’s (PBUH) traditions.It ensures fair distribution of a deceased person’s estate among heirs.Found in Surah Al-Nisa (Chapter 4), Verses 11, 12, and 176.Verse 11 was revealed after the Battle of Uhud in 3 A.H.This law forms the foundation of Islamic inheritance rules used till today.Last verified on 31-03-2026', 0, 0, 0, 1790964563633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5f751e7e4da8b835', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the foster sister of Hazrat Muhammad (PBUH)?', '{"A":"Haleema","B":"Saadia","C":"Sheema","D":"Ruqayya"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sheema was the foster sister of Prophet Muhammad (PBUH).She was the daughter of Haleema Saadia (R.A.), the Prophet’s foster mother.The Prophet (PBUH) was raised in the Banu Saad tribe.He stayed with Haleema Saadia (R.A.) during his early childhood.Last verified on 11-06-2026', 0, 0, 0, 1790964563633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3b2c86a4c0095374', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first Ummayed Caliph?', '{"A":"Abu Ubaidah (رضہ)","B":"Ameer Muawiyah (رضہ)","C":"Khalid bin Waleed (رضہ)","D":"Amr bin Al-Aas (رضہ)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muawiya I (RA) became the first caliph of the Umayyad Caliphate.He assumed power after the period of Ali ibn Abi Talib (RA).Umayyad rule: 661 – 750 ADFirst Caliph: Muawiya I (661–680 AD)Last Caliph: Marwan II (744–750 AD)Birth: 602 AD (Mecca)Death: 680 AD (DamascusLast verified on 27-04-2026', 0, 0, 0, 1790964563633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_171b50fcb1919694', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the real name Shah Wali Ullah?', '{"A":"Qutubddin Ahmed Faruqi","B":"Qutubddin Ahmed Siddiqui","C":"Qutubddin Ahmed","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Real name of Shah Waliullah is Qutubuddin Ahmad Syed.He wrote 51 books.He was Born in 21 February 1703 in Phulat, Mughal Empire.He was died in 20 August 1762 (aged 59) Dehli, Mughal Empire.He was first time in history translated the Holy Quran into the Persian Language.He was born in the reign of Aurangzeb.Last verified on 11-06-2026', 0, 0, 0, 1790964563714) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f32cec3f5e9de641', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The original name of Abu Jahal was?', '{"A":"Amr bin Hashim","B":"Abha bin Hashim","C":"Saleh bin Hashim","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The original name of Abu Jahal was Amr bin Hisham.He was a leader of the Quraysh tribe in Makkah.Muslims called him Abu Jahal (Father of Ignorance) due to his opposition to Islam.He was known among Quraysh as Abu Hakam (Father of Wisdom).He was killed in the Battle of Badr (624 CE).Last verified on 11-06-2026', 0, 0, 0, 1790964563714) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f9e0e421b8c14932', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Habsha is the old name of ___?', '{"A":"Damascus","B":"Ethiopia","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Habsha is the historic name for Ethiopia.It is located in the Horn of Africa.The Migration to Abyssinia, also known as the First Hegira.Last verified on 19-03-2026', 0, 0, 0, 1790964563714) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a858629da2dab5eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What does Al-Anfal means?', '{"A":"The Spoils of War","B":"The Heights","C":"The Repentance","D":"The Purgatory"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surah Al-Anfal means “The Spoils of War (مالِ غنیمت)”.It is the 8th chapter of the Holy Quran.The Surah contains 75 verses.It was revealed after the Battle of Badr.It mainly discusses rules of war, faith, and victory.Last verified on 20-04-2026', 0, 0, 0, 1790964563714) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_13a43f85f8450f1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazart Ali (R.A) married Hazart Fatima (R.A) in which hijri?', '{"A":"1st","B":"2nd","C":"3rd","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ali (RA) married Hazrat Fatimah (RA) in 2nd Hijri year.The marriage took place in 1 Dhu al-Hijjah, 2 AH (24 February AD 624).This is one of the most blessed marriages in Islamic history.Hazrat Fatimah (RA) was the beloved daughter of Prophet Muhammad (PBUH).Hazrat Ali (RA) was the cousin and son-in-law of the Prophet (PBUH).Last verified on 02-06-2026', 0, 0, 0, 1790964563714) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7a6878dc13260275', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which principle best reflects Islamic respect for humanity?', '{"A":"Authority-based treatment","B":"Conditional dignity","C":"Universal respect with justice / Universal justice-based respect","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Islam teaches equal dignity for all human beings.Respect is based on humanity, not race, status, or wealth.Justice is a core principle in treating every individual fairly.All humans are honored as creations of Allah.Last verified on 24-05-2026', 0, 0, 0, 1790964563714) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6096dfd9aae9bc20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ahzab means?', '{"A":"Ditch","B":"Allies","C":"Khandaq","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Ahzab means "allies" اتحادی.It is the 33rd chapter (surah) of the Quran.There are 73 verses.Last verified on 18-05-2026', 0, 0, 0, 1790964563714) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_92e74dab45aa8362', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The tax collected from Non-Muslim living under the Islamic government is called?', '{"A":"Sariya","B":"Jaziya","C":"Qazaf","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jizya is a poll tax historically imposed on non-Muslims in Muslim states.In India, Qutb-ud-din Aibak was the first to impose Jizya.The tax was abolished by Mughal ruler Akbar in the 16th century but reintroduced by Aurangzeb in the 17th century.Additional information:Kharaj was a land tax imposed on non-Muslim cultivators and landlords.Last verified on 18-05-2026', 0, 0, 0, 1790964563714) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e0870af95b2a4d0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the title of Tafseer written by Mufti Muhammad Shafi?', '{"A":"Tafseer-e-Jalalayn","B":"Maariful Qur’an","C":"Tafseer Ibn Kathir","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Author: Mufti Muhammad Shafi (رحمہ اللہ)Name of Tafseer: Maariful QuranLanguage: UrduPublication Period: 20th CenturyStyle: Easy explanation + scholarly tafseerLast verified on 18-05-2026', 0, 0, 0, 1790964563798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_031f30d201459585', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Muhammad (SAW) went to Syria with Hazrat Abu Talib (RA) at the age of ______?', '{"A":"24 years","B":"35 years","C":"12 years","D":"15 years"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At age 12, Prophet Muhammad (PBUH) traveled to Syria with his uncle Abu Talib (RA)Met a Christian monk Bahira in Basra, Syria who noticed signs of prophethoodLast verified on 08-02-2026', 0, 0, 0, 1790964563798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d3d4c8061163fd64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Tahira was the title of which of the following?', '{"A":"Hazrat Khadija (R.A)","B":"Hazrat Ayesha (R.A)","C":"Hazrat Hafsa (R.A)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Al-Tahira” means the pure and chaste woman.It was the title of Hazrat Khadija (R.A).She was the first wife of Prophet Muhammad (PBUH).She was the first woman to accept Islam.She is known for her great support and sacrifice for Islam.Last verified on 25-04-2026', 0, 0, 0, 1790964563798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_efb5607021ce6636', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Muslim invaded Spain in _____?', '{"A":"701 A.D","B":"711 A.D","C":"717 A.D","D":"727 A.D"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 711 AD, Tariq initiated the conquest of SpainLeading to the establishment of the Emirate of CordobaHe was the Umayyad commander Launched the Muslim conquest of the Iberian PeninsulaHe led a Berber army across the Strait of GibraltarDefeated the Visigothic King Roderic at the Battle of Guadalete"Gibraltar" is derived from the Arabic name Jabal ṬāriqThe conquest lasted from 711 to 718 ADLast updated by NS on 06 May 2026', 0, 0, 0, 1790964563798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f436cf8ddc7a6da9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which is fourth month of the Islamic Calendar?', '{"A":"Rabi-ul-Awwal","B":"Rajab","C":"Rabi-us-Sani","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 12 Islamic MonthsMuḥarram (محرم الحرام)Ṣafar (صفر المظفر)Rabi al-Awwal (ربیع الاول)Rabi al-Thani / Rabi al-Sani (ربیع الثانی)Jumada al-Awwal (جمادی الاول)Jumada al-Thani (جمادی الثانی)Rajab (رجب المرجب)Shaʿban (شعبان المعظم)Ramadan (رمضان المبارک) – Month of fastingShawwal (شوال المکرم)Dhu al-Qaʿdah (ذوالقعدہ الحرام)Dhu al-Hijjah (ذوالحجہ الحرام) – Month of HajjLast verified on 14-03-2026', 0, 0, 0, 1790964563798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4b37a895d2859ccb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is Ushr?', '{"A":"1/10th of the whole property","B":"1/5th of precious stones","C":"1/10th produce of agriculture","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ushr is a 10% tax on harvests from irrigated or rain-watered land.5% on harvests from land dependent on well water.Last verified on 16-05-2026', 0, 0, 0, 1790964563798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e5fed88b0f59bf21', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Muzdalifah is an area between?', '{"A":"Makkah and Madina","B":"Makkah and Mina","C":"Madina and Mina","D":"Arafat and Mina"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muzdalifah is located between Mina and Arafat in Muzdalifah.Pilgrims stay there on the night of 9th Zul-Hijjah during Hajj.Maghrib and Isha prayers are offered together at Muzdalifah.Pebbles are collected there for Rami at Mina.It is also called “Al-Ibtah” meaning a flat area.Additional information:Around 49 or 70 pebbles are collected from Muzdalifah.These pebbles are thrown at the three Jamarat in Mina symbolizing rejection of the devil.Last verified on 16-05-2026', 0, 0, 0, 1790964563798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f1822a1c875a4610', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who are called Umm-ul-Momineen?', '{"A":"The sisters of the Holy Prophet (PBUH)","B":"The wife  of the Holy Prophet (PBUH)","C":"The mothers of the Islamic community","D":"The female scholars of early Islam"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Umm-ul-Momineen" (أم ٱلْمُؤْمِنِين‎) is an Arabic phrase meaning "Mothers of the Believers."It is a title given to the wives of the Islamic Prophet Muhammad SAW as a sign of respect.The title is derived from verse 33:6 of the Quran.Muslims use this title before or after referring to these women.Last verified on 13-05-2026', 0, 0, 0, 1790964563798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2e86d4b95687f841', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Current Hijri Year is ______(Click)?', '{"A":"Hazrat Usman (RA)","B":"Hazrat Abu Bakar (RA)","C":"Hazrat Umar (RA)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Hijri calendar was officially started by Hazrat Umar (RA).It is based on the migration (Hijrah) of Prophet Muhammad (PBUH) in 622 AD.This event marks the beginning of the Islamic era.It consists of 12 lunar months.It is still used for Islamic events and dates today.Last verified on 25-04-2026یہ سوال ضرور پڑھیںCurrent Hijri Year is ______(Click)?', 0, 0, 0, 1790964563878) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_78b1ae02a7f73dab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Basically, Booty is the right of ______?', '{"A":"Allah and his Prophet (PBUH)","B":"Makkans","C":"The Non-Muslim","D":"The Muslims"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Islamic teachings, booty (Ghanimah) refers to wealth gained during lawful battle.The Holy Quran clearly explains its distribution and ownership.Initially, its authority belongs to Allah and His Prophet (PBUH).The rule of booty is mentioned in Surah Al-Anfal.One-fifth (Khums) was reserved for collective welfare and needy groups.Last verified on 12-05-2026', 0, 0, 0, 1790964563878) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0531ca3e27bbcadc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Sadaq-e-Eid-ul-fitr has been proclaimed in the year?', '{"A":"2 Hijri","B":"3 Hijri","C":"4 Hijri","D":"5 Hijri"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sadaqat-ul-Fitr (Fitrana) is a compulsory charity in Islam.It is given before the Eid-ul-Fitr prayer.It was made obligatory to purify the fasts of Ramadan.It also helps poor people to celebrate Eid.It was proclaimed in the 2nd Hijri year.Last verified on 11-05-2026', 0, 0, 0, 1790964563878) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_88360d775f29713c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'On which place, first Wahi was descended?', '{"A":"Sore Cave","B":"Hira Cave","C":"Khana-Kaaba","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Location of the first wahi: Cave HiraIn: 610 ADAt the Age of 40 years 6 monthsNumber of verses: 5Prescriber of wahi in Makkah: Sharjeel-ibn-Hasana KandiFirst writer of Wahi in Quraish: Hazrat Zaid bin Sabit (RA)Last updated by NA on 25-April-2026', 0, 0, 0, 1790964563878) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_eb60cf710bd0c5b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which Angel is appointed providing for Rain, Food (Sustenance)?', '{"A":"Hazrat Israil A.S","B":"Hazrat Israfeel A.S","C":"Hazrat Meekail A.S","D":"Hazrat Jibriel A.S"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Meekail (A.S) is responsible for providing rain, sustenance, and food to creatures.Additional information:Hazrat Jibriel (A.S) – Brings Allah’s revelations to prophets.Hazrat Israfeel (A.S) – Will blow the trumpet on the Day of Judgment.Hazrat Izrail (A.S) – Angel of death, takes souls at the time of death.Last verified on 16-03-2026', 0, 0, 0, 1790964563878) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_79c9b55fe7b68b6f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Mujadid Alif Sani is title of _____?', '{"A":"Shah Waliullah","B":"Syed Ahmed Shaheed","C":"Sheikh Ahmad Sirhindi","D":"Syed Ahmad Khan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mujaddid Alif Sani is the title given to Sheikh Ahmad Sirhindi.He was a great Islamic scholar and reformer of the 11th century Hijri.He worked to revive true Islamic teachings during the Mughal era.He strongly opposed un-Islamic beliefs like Din-i Ilahi.Additional information:Birth: 26 May 1564Death: 10 December 1624 (age 60)Birthplace: Sirhind (India)Period: Mughal Emperor Akbar’s reignMajor works: Risal-e-Nabuwat, Isbat-ul-NabatLast verified on 09-05-2026', 0, 0, 0, 1790964563878) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_14295e2706c48c43', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who started Jihad/stood against the Akbar''s new religion Din-e-Illahi?', '{"A":"Shah Wali Ullah","B":"Mujadad Alif Sani","C":"Maulana Bakhtiar Kaki","D":"Mirza Abdul Qadir"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mujadad Alif Sani initiated the Jihad against Din-e-Illahi.Sheikh Ahmad Sirhindi, also known as Imam Rabbani.It is a religious movement introduced by Emperor Akbar in 1582.Origin: Fatehpur Sikri, Agra, Mughal EmpireMembers: 19Other name Tawhid-i-Ilahi(توحید الهی)Last verified on 30-04-2026', 0, 0, 0, 1790964563878) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0685686c9f1f4320', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The third Source of Islamic Fiqah is?', '{"A":"The Quran","B":"The Sunnah","C":"The consensus of the Sharia Experts (Ijma)","D":"Analogical reasoning (Qiyas)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The primary sources of Islamic law are:The QuranThe Sunnah (traditions of the Prophet Muhammad SAW)Ijma (consensus among Muslim jurists)Qiyas (analogy)Last verified on 30-04-2026', 0, 0, 0, 1790964563878) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e816272a92011043', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Mekail (AS) is deputed by Almighty Allah to perform the following tasks?', '{"A":"To bring rain and blowing winds","B":"To bring revelation","C":"To capture the spirit at the time of death","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Mikail (AS) is an archangel in Islam responsible for bringing rain, providing sustenance, and controlling winds.Additional information:Hazrat Jibrail (AS): Brings revelation to prophetsHazrat Izrail (AS): Captures souls at the time of deathHazrat Israfil (AS): Will blow the trumpet on Qiyamah (Day of Judgment)Last verified on 10-02-2026', 0, 0, 0, 1790964563943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_26e7dee4d8e835ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Police Force/Department/System was first established by which caliph?', '{"A":"Hazrat Ali (RA)","B":"Hazrat Abu Bakr (RA)","C":"Hazrat Umar (RA)","D":"Hazrat Usman (RA)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The police system was first established by Umar ibn al-Khattab.He was the second Caliph (634–644 CE).A proper system of law enforcement and public safety was organized.He also introduced the Hijri calendar.He established systems like Bait-ul-Mal (treasury) and judiciary.Last verified on 30-04-2026', 0, 0, 0, 1790964563943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9efd9e7b5f894e84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who wrote the book “Kitab al Kharaj”?', '{"A":"Imam Abu Yusuf","B":"Imam Shafi","C":"Imam Abu Hanifa","D":"Muhammad Al Shaybani"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Yusuf wrote the famous book Kitab al-Kharaj.He was a student of Imam Abu Hanifa.The book deals with Islamic taxation and state revenue system.It was written for the Abbasid Caliph Harun al-Rashid.Last verified on 28-04-2026', 0, 0, 0, 1790964563943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2fe4f7eaff8f68c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Abdullah bin Abbas (R.A) was given the title of?', '{"A":"Interpreter of Islam","B":"Treasurer of Islam","C":"Sea of Knowledge","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abdullah bin Abbas (RA) was a great companion of the Prophet (PBUH).He was known as “Bahr-ul-Ilm (Sea of Knowledge)”.He was highly skilled in Tafsir (Quranic interpretation).He was among the most knowledgeable companions in Islamic teachings.Last verified on 26-04-2026', 0, 0, 0, 1790964563943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3cfcd064bc2e523b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Bair-e-Rooma was ______?', '{"A":"A mosque in Room","B":"A famous Inn in Madina","C":"A sweet drinking water well","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bi’r Ruma was a famous well in Madina.It was known for its sweet and fresh water.The Prophet Muhammad ﷺ encouraged its purchase for public use.It was bought by Uthman ibn Affan (R.A).It became a charitable endowment (Waqf) for Muslims.Last verified on 28-04-2026', 0, 0, 0, 1790964563943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5936d4ee63d81bc7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first writer of "Wahi"?', '{"A":"Hazrat Bilal (RA)","B":"Hazrat Ali (RA)","C":"Hazrat Khalid bin Saeed (RA)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first writer of Wahi (Revelation) in Makkah was Khalid ibn Sa''id (R.A).He belonged to the Quraysh tribe.In Madinah, main scribe → Zayd ibn Sabit (R.A)Compilation of Qur’an → Abu Bakr (R.A) eraLast verified on 28-04-2026', 0, 0, 0, 1790964563943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c710857d28dc5594', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the real name of Imam Abu Hanifa?', '{"A":"Sabit bin Numan","B":"Numan bin Sabit","C":"Muhammad bin Numan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Hanifa’s real name was Nu‘man ibn Sabit ibn Zuta ibn Marzuban.He was born in 699 AD (80 AH) in Kufa.He is the founder of the Hanafi Fiqh.Died in 767 AD (150 AH) in Baghdad.Known as Al-Imam Al-Azam (The Great Imam) and Siraj al-A’imma (Lamp of the Imams).Last verified on 28-04-2026', 0, 0, 0, 1790964563943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6f7f22eaa75be555', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Science, astronomy, writing with pen, sewing and weapons were made by ____ first of all.', '{"A":"Hazrat Shees (AS)","B":"Hazrat Uzair (AS)","C":"Hazrat Yaqoob (AS)","D":"Hazrat Idrees (AS)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Idris (A.S) is considered among the earliest pioneers of knowledge and skills.He is associated with science, astronomy, and writing with a pen.He also introduced sewing (stitched clothes).He is often linked with early development of civilization.Additional information:Ship building → Hazrat Nuh (A.S)Iron work → Hazrat Dawood (A.S)Construction → Hazrat Ibrahim (A.S)Last verified on 28-04-2026', 0, 0, 0, 1790964563943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_83a5bc67c57aa824', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who were Ashaab-e-Suffah?', '{"A":"Who were Ashaab-e-Suffah? Ansaar (RA) who stayed near the Masjid-e-Quba","B":"Ansaar (RA) who stayed near the Masjid-e-Nabvi","C":"Mahajirs (RA) who stayed near the Masjid-e-Nabivi","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ashaab-e-Suffah were poor companions from the Muhajirun.They stayed in a shaded platform (Suffah) in Masjid-e-Nabvi.They had no homes or wealth after migration.Total members (approx.) → 70–300 companions.Last verified on 28-04-2026', 0, 0, 0, 1790964564009) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_06da7c7bf079a520', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Wealth obtained from a mine is liable to?', '{"A":"Zakat","B":"Sulus","C":"Rubah","D":"Khumus"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wealth obtained from mines is subject to Khumus (one-fifth).Khumus means 20% of certain types of wealth.It is mentioned in the Qur''an (Surah Al-Anfal 8:41).It applies to treasures, minerals, and war gains.It is more emphasized in Shia jurisprudence, but exists in Sunni sources too.Last verified on 28-04-2026', 0, 0, 0, 1790964564009) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8dc8258a812943ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who has given more than five thousand Ahadith?', '{"A":"Hazrat Abdullah bin Abbas (RA)","B":"Hazrat Hazrat Ibne Umer (RA)","C":"Hazrat Hurairah (RA)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Hurairah (R.A) narrated the largest number of Ahadith.He reported about 5,374 Ahadith.He stayed in close companionship with the Prophet (PBUH).He accepted Islam in 7 AH.Additional information:Abdullah ibn Umar (R.A) → 2630 AhadithAnas ibn Malik (R.A) → 2286 AhadithAisha (R.A) → 2210 AhadithIbn Abbas (R.A) → 1660 AhadithLast verified on 28-04-2026', 0, 0, 0, 1790964564009) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c4f259f3322e9ec7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which country is called the Land of Prophets?', '{"A":"Saudi Arabia","B":"Syria","C":"Palestine","D":"Iraq"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Palestine is the land of prophets.Because many prophets were born, lived, or died there, Including Ibrahim, Lut, Dawood, Suleiman, Musa, Zakariya, Yahya, and Isa (A.S).Baitul-Maqdis (Jerusalem) in Palestine was the first Qibla for Muslims.Muslims prayed facing it for 14 years before the Qibla changed to Kaaba in 2nd Hijri.Last updated by NA on 25-April-2026', 0, 0, 0, 1790964564009) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ce3a31f781705033', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who introduced the Jail System?', '{"A":"Hazrat Abu Bakar (R.A)","B":"Hazrat Umar (R.A)","C":"Hazrat Usman (R.A)","D":"Hazrat Ali (R.A)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Jail System in Islam was introduced by Umar ibn al-Khattab (R.A).He was the 2nd Caliph of Islam.His rule lasted from 634–644 AD (10 years).Accepted Islam: 616 AD (at the age of 32 years).Last verified on 28-04-2026', 0, 0, 0, 1790964564009) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9784fdc14435f584', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the name of the sacred book of Zoroastrianism?', '{"A":"Vedas","B":"Zend Avesta","C":"Upanishads","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sacred book of Zoroastrianism is the Zend Avesta (Avesta).It contains teachings of the prophet Zoroaster (Zarathustra).It focuses on the concept of good vs evil (Ahura Mazda vs Angra Mainyu).It is one of the oldest religious texts in the world.It was originally written in the Avestan language.Last verified on 27-04-2026', 0, 0, 0, 1790964564009) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_26bbd79faa5a7dde', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In which Sura the law of inheritance mentioned?', '{"A":"Surah Noor","B":"Surah \tMa’ida","C":"Surah \tNisa","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Laws of inheritance were revealed in 3 A.H.They are mainly mentioned in Surah An-Nisa.This Surah provides detailed shares for heirs.It is a Madani Surah focusing on social laws.Juz: 4–6Verses: 176Rukus: 24Hizb: 8–11Last verified on 27-04-2026', 0, 0, 0, 1790964564009) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8672fcd950b3fd84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Islamic virtue "Ihsan" means?', '{"A":"Outer worship","B":"Spiritual beauty in worship/Perfection","C":"Superiority","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ihsan is a high level of faith in Islam.It means doing worship with perfection and sincerity.A person worships Allah as if he is seeing Him.It represents inner beauty and spiritual excellence.It is higher than Islam and Iman in rank.Last verified on 27-04-2026', 0, 0, 0, 1790964564009) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b6671b893dd61eb8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the meaning of Vishnu?', '{"A":"The preserver","B":"The helper","C":"The destroyer","D":"The creator"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vishnu is one of the major deities in Hinduism.He is known as the Preserver (Protector of the Universe).He maintains balance and order in the world (Dharma).He is part of the Hindu Trinity (Trimurti).The other two are Brahma (Creator) and Shiva (Destroyer).Last verified on 27-04-2026', 0, 0, 0, 1790964564101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_40401cb43eee50e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The day when pilgrims slaughter their animals and offer sacrifice is called?', '{"A":"Yum-e-Nehr","B":"Yum-e-Arafah","C":"Yum-e-Tarwiyah","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Day: 10th Dhul HijjahName: Youm al-Nahr (Day of Sacrifice)Associated festival: Eid al-AdhaHajj days: 8th–13th Dhul HijjahMain ritual: Qurbani (sacrifice)Last verified on 27-04-2026', 0, 0, 0, 1790964564101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3fcab7c0b3b75bb5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Kitab-ul-Umm was written by ______?', '{"A":"Imam Shafi","B":"Imam Hambal","C":"Imam Abu Hanifa","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kitab-ul-Umm was written by Imam Shafi’i, a renowned Islamic jurist.It is considered the first major book of Fiqh.The book explains Islamic laws and jurisprudence in detail.Its teachings form the basis of the Shafi’i school of thought.Published between 1903–1907 in printed form.Last verified on 01-04-2026', 0, 0, 0, 1790964564101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c40664b712378d08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What are the third belief in Iman-e-Mufassal?', '{"A":"Angles of Allah","B":"The Books of Allah (The Divine Scriptures)","C":"Prophets","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The third belief in Iman-e-Mufassal is faith in the Books of Allah.Muslims believe Allah revealed divine books for guidance.7 Beliefs of Iman-e-Mufassal)Faith in AllahFaith in AngelsFaith in BooksFaith in ProphetsFaith in Day of JudgmentFaith in Taqdir (destiny)Faith in Life after deathLast verified on 27-04-2026', 0, 0, 0, 1790964564101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f5e72a33731ed9b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who among the following was a Historian, justice, philosopher as well as Politician?', '{"A":"Abu Bakar Muhammad Yahya","B":"Abdur Rehman bin Khaldun","C":"Shams ud din bin Khalkan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abdur Rehman bin Khaldun was an Arab sociologist, philosopher, and historian. Born: May 27, 1332, in TunisDied: March 17, 1406, in EgyptHe made major contributions to historiography, sociology, economics, and demography.His best-known book is the "Muqaddimah" or "Prolegomena" ("Introduction").Last verified on 27-04-2026', 0, 0, 0, 1790964564101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3bd0ed73c82052a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which one of the following is included amongst the Ashra Mubashra?', '{"A":"Hazrat Saad Bin Zubair","B":"Hazrat Saad Bin Abada","C":"Hazrat Saad Bin Abi Waqas","D":"Hazrat Hamza"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ashra Mubashra are those Companions of Prophet Hazrat Muhammad (P.B.U.H), who were given Good News in their life that they will be awarded Heaven.Following is the List with Names of Ashra Mubashra:Hazrat Abu Bakar (R.A)Hazrat Umer Farooq (R.A)Hazrat Usman (R.A)Hazrat Ali (R.A)Hazrat Zubair ibn-e-Awam (R.A)Hazrat Talha (R.A)Hazrat Abdul Rehman bin-e-Auf (R.A)Hazrat Abu Obaida bin-al-Jarah (R.A)Hazrat Saad bin-e-Abi Waqas (R.A)Hazrat Saeed bin-e-Zaid (R.A)Last verified on 02-04-2026', 0, 0, 0, 1790964564101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_aeb18b76d0f04e3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who declared Nile River as Sayed Ul Anhar??', '{"A":"Hazrat Usman (RA)","B":"Hazrat Ali (RA)","C":"Hazrat Umar (RA)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Umar ibn al-Khattab (RA) declared the Nile River as Sayed ul Anhar (Chief of Rivers).This happened during his caliphate (634–644 AD).The Nile River was highly valued for its importance to Egypt.Length of Nile River: ~6650 kmOrigin: Lake Victoria (East-Central Africa)Last verified on 27-04-2026', 0, 0, 0, 1790964564101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4145b6ff58efc9c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'First census of Islamic world was held in _____ period.', '{"A":"Hazrat Usman (RA)","B":"Hazrat Umar (RA)","C":"Hazrat Ali (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first census in the Islamic world was conducted during the period of Umar ibn al-Khattab (RA).It was done to manage the growing Islamic state efficiently.The census helped in organizing tax (Zakat & Jizya) and military records.It took place during his caliphate (634–644 AD).Last verified on 27-04-2026', 0, 0, 0, 1790964564101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_44da086c91aada38', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is charged from Non-Muslims in an Islamic country instead of Ushr?', '{"A":"Jizya","B":"Khiraj","C":"Ushr","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jizya is a tax taken from non-Muslims in an Islamic state.It is charged instead of Ushr/Zakat which Muslims pay.In return, non-Muslims receive protection and state services.It is part of the Islamic financial system.Last verified on 26-04-2026', 0, 0, 0, 1790964564174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a9b73cb911a6c7cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first commander of the Islamic Army?', '{"A":"Hazrat Hamza (R.A)","B":"Hazrat Ali (R.A)","C":"Hazrat Usman (R.A)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Hamza (RA) is regarded as the first commander of the Islamic army.He was the uncle of Prophet Muhammad (PBUH).He was also known as “Sayyid-ush-Shuhada” (Leader of Martyrs).He led the first Islamic expedition (Sariyyah) in early Madinah period.He was martyred in the Battle of Uhud in 3 AH.Last verified on 26-04-2026', 0, 0, 0, 1790964564174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_eb51cde8b5c03516', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who conquered Persia for the first time?', '{"A":"Hazrat Saad bin Abi Waqas (R.A)","B":"Hazrat Abdullah bin Ali (R.A)","C":"Hazrat Usama bin Zaid (R.A)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Saad bin Abi Waqqas (RA) led the Muslim conquest of Persia.He was the commander in the famous Battle of Qadisiyyah.This battle opened the path to the fall of the Sassanid Empire.The conquest took place during the Caliphate of Hazrat Umar (RA).Battle of Qadisiyyah was the decisive battle against the Persian Empire.The Persian Empire was one of the two superpowers of that era (Byzantine and Persian).Last verified on 26-04-2026', 0, 0, 0, 1790964564174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_70caeb8c8ac0e4bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the old name of Ethiopia?', '{"A":"Abbasinya","B":"Andorra","C":"Mesopotamia","D":"Constantinople"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The old name of Ethiopia was AbyssiniaLandlocked country on the Horn of Africa.Capital is Addis Ababa.Currency is the Birr.The official language is Amharic.Located in the Continent of Africa.Primary Religion is Islam and Christianity.Head of Govt is Prime Minister Abiy Ahmed.Parliament is called the Federal Council and the House of Representatives.Last updated by NS on 20-April-2026', 0, 0, 0, 1790964564174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_379216a6ee341fcd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Muhammad (SAW) gave the key of Bait Ullah permanently to Hazrat _____?', '{"A":"Umara Bin Utba","B":"Hanzla bin Abi Aamir","C":"Usman bin Talha","D":"Abdullah Bin Aamir"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The key of Baitullah (Kaaba) was entrusted by the Holy Prophet Muhammad (SAW).This event took place after the Conquest of Makkah (8 AH / 630 AD).The key was given to Hazrat Usman bin Talha (RA) from the Banu Abd al-Dar family.The Prophet (SAW) declared that this trust will remain in his family forever.Last verified on 21-04-2026', 0, 0, 0, 1790964564174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_306538e8d443d3ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who is called Malik-ut-Tajjar?', '{"A":"Hazrat Usman Ghani (R.A)","B":"Hazrat Umar Farooq (R.A)","C":"Hazrat Abu Bakar (R.A)","D":"Hazrat Ali (R.A)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Usman Ghani (RA) is known as Malik-ut-Tajjar (King of Traders).He was a very successful and wealthy merchant.3rd Caliph: Hazrat Usman (RA) (644–656)Purchased Well of Ruma for المسلمينFunded Army of TabukAmong the Ashra Mubashra (10 promised Jannah)Last verified on 26-04-2026', 0, 0, 0, 1790964564174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5f1466c47d2f8662', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Taloot was the father-in-law of?', '{"A":"Hazart Yaqoob (AS)","B":"Hazart Dawood (AS)","C":"Hazart Sulaiman (AS)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Taloot (Saul) was a righteous king of بني إسرائيل.He was the father-in-law of Hazrat Dawood (AS).Hazrat Dawood (AS) married Taloot’s daughter after victory over Jalut (Goliath).Taloot was chosen by Allah to lead the Israelites in battle.This event is mentioned in the Holy Quran (Surah Al-Baqarah).Last verified on 25-04-2026', 0, 0, 0, 1790964564174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_59ed6413efe788e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Zaboor means?', '{"A":"Signs","B":"Law","C":"Melodious/Pieces","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Zabur was revealed to Hazrat Dawood (A.S).Its literal meaning is Melodious songs or pieces.The word Zabur is the Arabic name for the Psalms.It contains praises and hymns of Allah.It was sent for guidance and spiritual reflection.Last verified on 25-04-2026', 0, 0, 0, 1790964564174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d16f411fa5ebfb27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In which year of Hijri was the order to demolish Masjid Zarar?', '{"A":"2 AH after the Battle of Badr","B":"5 AH after the Battle of Uhud","C":"7 AH after the Treaty of Hudaybiyyah","D":"9 AH after the Battle of Tabuk"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid al-Dirar was built in Medina by Abu Amir and 12 hypocrites near Masjid Quba.It is mentioned in the Holy Quran in Surah At-Tawbah.The mosque was used for anti-Islamic activities and conspiracy against Muslims.In 630 CE (9 AH), Prophet Muhammad (PBUH) ordered its destruction.This happened after the Expedition of Tabuk, due to its harmful purpose.Last verified on 25-04-2026', 0, 0, 0, 1790964564254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bacd9db76309b745', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who built Bait al Hikmat?', '{"A":"Hakim Mohammed Said","B":"Khalifa Abu Jafar al-Mansur","C":"Caliph Harun al-Rashid","D":"Caliph Mamoon Rashid"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Caliph Al-Ma''mun played the key role in developing Bait al-Hikmat (House of Wisdom) in Baghdad.It became a major center of learning, research, and translation during the Islamic Golden Age.Scholars from different fields worked there, especially in science, philosophy, and medicine.It was established during the Abbasid Caliphate period (9th century CE).Last verified on 25-04-2026', 0, 0, 0, 1790964564254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d911532e99c6d141', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Grand Mosque at Damascus was built by?', '{"A":"Umar bin Abdul Aziz","B":"Walid bin Abdul Malik","C":"Abdul Malik","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Great Mosque of Damascus is also known as the Umayyad Mosque.It was built by the Umayyad Caliph al-Walīd I between 705 and 715 CE.It is located in the old city of Damascus.It is the capital of Syria.It is one of the largest and oldest mosques in the world.The mosque opened in 715 AD.Last verified 25-04-2026', 0, 0, 0, 1790964564254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_79869e3f35d9e210', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first Muslim to interpret Qur''an in English in 1905?', '{"A":"Dr. Muhmamd Iqbal","B":"Sir Syed Ahmed Khan","C":"Dr. Khalifa Abdul Hakeem","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Muslim to publish an English translation/interpretation of the Qur''an in 1905 was Dr. Muhammad Abdul Hakim Khan.Additional information:Urdu (First translation): Shah Abdul Qadir & Shah Rafiuddin (Mojaz-ul-Quran)Punjabi (First translation): Tauqir Amaan KhanSindhi (First translation): Akhund AzizullahEnglish (First translation): George SaleFirst translation in India: SindhiFirst translation in the world: PersianLast verified on 25-04-2026', 0, 0, 0, 1790964564254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e7425af605042518', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The meaning of the word Al-Hadid is?', '{"A":"The Stone","B":"The Iron","C":"The Sword","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Hadid is an Arabic word meaning “Iron.”It is also the name of the 57th Surah of the Quran.Iron is mentioned as a strong and beneficial metal for mankind.Last verified on 25-04-2026', 0, 0, 0, 1790964564254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4c2a2e8e3ec45211', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the conqueror of Spain?', '{"A":"Tariq bin Ziad","B":"Musa bin Naseer","C":"Muhammad bin Qasim","D":"Khalid bin Waleed"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The conqueror of Spain was Tariq ibn Ziyad.He led the Muslim army in 711 AD and began the conquest of the Iberian Peninsula.He defeated the Visigothic ruler King Roderic at the Battle of Guadalete.His landing place is famously known as Jabal al-Tariq (Gibraltar).Last verified on 25-04-2026', 0, 0, 0, 1790964564254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7e7d6f46d148892c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'After sleeping for 100 years, he again woke up?', '{"A":"Hazrat Salih (AS)","B":"Hazrat Musa (AS)","C":"Hazrat Uzair (AS)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet: Uzair (A.S)Nation: Bani IsraelEvent: Death for 100 years and revivalLesson: Allah has complete power over life and deathPurpose: To show a sign for mankindMentioned in Surah Al-Baqarah (2:259)Last verified on 25-04-2026', 0, 0, 0, 1790964564254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1d4ae07162676e66', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'For how many months Hazrat Hasan (R.A) remained khalifa?', '{"A":"14 Months","B":"13 Months","C":"15 Months","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Hasan ibn Ali became caliph after the martyrdom of Hazrat Ali (RA) in 661 AD.Duration: 14 monthsFather: Hazrat Ali ibn Abi TalibGrandfather: Prophet MuhammadKnown for: Peace agreement and unity of MuslimsLast verified on 25-04-2026', 0, 0, 0, 1790964564254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e2856ca8765c417b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The first revealed book was ______?', '{"A":"Taurat","B":"Zaboor","C":"Injeel","D":"Quran"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation List of Holy Books with Prophet Names:Taurat (Torah) - Hazrat Musa (Moses) (AS)Zabur (Psalms) - Hazrat Dawood (David) (AS)Injil (Gospel) - Hazrat Isa (Jesus) (AS)Quran - Hazrat Muhammad (PBUH)Last verified on 25-04-2026', 0, 0, 0, 1790964564331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2487bc9682e9a3aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Where is Masjid ul Hanif located where almost 70 prophets are buried?', '{"A":"Medina","B":"Mina","C":"Palestine","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid e Hanif is in Mina.It is located in MedinaMore than 70 prophets are buried there.Last verified on 25-04-2026', 0, 0, 0, 1790964564331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0092783c87896778', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who conquered Bait-tul-Maqdas?', '{"A":"Ertugrul Ghazi","B":"Musa bin Nusair","C":"Salahuddin Ayyubi","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salahuddin Ayyubi conquered Bait-ul-Maqdas (Jerusalem) in 1187 AD.He defeated the Crusaders in the famous Battle of Hattin.He was the founder of the Ayyubid dynasty and ruled Egypt and Syria.His victory restored Muslim control over Jerusalem after the Crusades.Last verified on 25-04-2026', 0, 0, 0, 1790964564331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8555a51670583e36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In which Nabvi year the Social Boycott of Banu Hashim was started?', '{"A":"7th Nabvi","B":"5th Nabvi","C":"3rd Nabvi","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Social Boycott of Banu Hashim started in the 7th year of Prophethood (Nabvi).It was imposed by the Quraysh of Makkah against Banu Hashim and early Muslims.The boycott continued for 3 years (7th–10th Nabvi).Last verified on 03-04-2026', 0, 0, 0, 1790964564331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0496a4bf655532d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which daughter of Hazrat Abu Bakar who become the wife of Hazrat Muhammad (SAW)?', '{"A":"Hazrat Ayesha","B":"Umm e Habiba","C":"Hazrat Maria","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790964564331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7d5e6cf40081effc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who made Soap for the first time?', '{"A":"Hazrat Nooh (AS)","B":"Hazrat Ibrahim (AS)","C":"Hazrat Adam (AS)","D":"Hazrat Saleh (AS)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Saleh invented Soap.He was a prophet of the nation Samood.He is buried in Lebonan.Last verified on 23-04-2026', 0, 0, 0, 1790964564331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a1b746e25a826fff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Batha Valley is situated in _____?', '{"A":"Egypt","B":"Madina","C":"Makkah","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Batha is associated with Riyadh (capital of Saudi Arabia) region.It is part of the central Arabian Peninsula (Najd area).Riyadh is one of the most important modern cities of Saudi Arabia.Makkah was conquered in 8th Hijri (630 AD) by Prophet Muhammad ﷺ.Madinah is located in the Hijaz region, west of Saudi Arabia.Last verified on 21-04-2026', 0, 0, 0, 1790964564331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4beb63953c07c98d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Masjid-e-Qiblatain is located in ____?', '{"A":"Macca","B":"Madina","C":"Jerusalem","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid al-Qiblatain is located in Medina.It is where Prophet Muhammad (P.B.U.H) changed the direction of prayer (Qibla) from Masjid al-Aqsa to Masjid al-Haram During the Zuhr prayer.The mosque has two domes and two minarets.It was founded by Sawad ibn Ghanam ibn Ka''ab and first opened in 1987.It is traditionally believed to have been built by Abraham and Ishmael.Last verified on 30-03-2026', 0, 0, 0, 1790964564331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_507f4503d77aa69d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Zou-Shadatian is title of ____?', '{"A":"Hazrat Ammar Bin Yasir (رضہ)","B":"Hazrat Huzaifa Bin Yaman(رضہ)","C":"Hazrat Khuzima Bin Sabit (رضہ)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The title Zul-Shahadatayn (ذوالشہادتین) means “the one whose testimony equals two witnesses.”This لقب was given to Khuzaymah ibn Thabit.The Prophet Muhammad (PBUH) accepted his testimony as equal to two witnesses.This was due to his strong faith and truthfulness.Last verified on 21-04-2026', 0, 0, 0, 1790964564392) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_65a170ad0079cc49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Yousuf was the son of _______?', '{"A":"Hazrat Ismail","B":"Hazrat Loot","C":"Hazrat Yaqoob","D":"Hazrat Nooh"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Yousuf (AS) was the son of Hazrat Yaqoob (AS) and mother: Raheel.He was one of twelve sons of Hazrat Yaqoob (AS).Known for his ability to interpret dreams and his story is a lesson in patience and faith.Additional information:Stayed in the well for three days.Sold as a slave in Egypt; bought by Zulaikha.Real brother: Bin Yameen.Mentioned 27 times in the Holy Quran.Burial place: Palestine.Last verified on 09-03-2026', 0, 0, 0, 1790964564392) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_18187d2637c5fe7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which holy book is called ‘Gospel’?', '{"A":"Quran","B":"Zaboor","C":"Turat","D":"Injeel","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Injeel is also called the Gospel.Gospel means truth. Revealed by Allah to Hazrat Esa (AS).Injeel means good news. Last updated NA 13-04-2026', 0, 0, 0, 1790964564392) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1c8125aaee527275', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Baitul Mamoor is on ______ Heaven.', '{"A":"6th","B":"4th","C":"3rd","D":"7th"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Baitul Mamoor is on seventh Heaven. The house located directly above the Kabah on Earth, Where 70,000 angels perform tawaaf (circumambulation) daily and never return. There are seven heavens in Islam. 1) Dar al-Salam 2) Dar al-Jalal 3) Jannatul Mava 4) Jannatul Khuld 5) Jannatul Adan 6) Jannatul Firdous 7) Jannatul Naeem ** Last updated NA 13-04-2026', 0, 0, 0, 1790964564392) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9d7671c9c93a8242', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the meaning of Hijr-e-Aswad?', '{"A":"Black Stone","B":"White Stone","C":"Green Stone","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hajr-e-Aswad means “Black Stone.”It is a sacred stone fixed in the Kaaba, Makkah.It was given from Heaven to Prophet Ibrahim (AS).Originally white, Hajr-e-Aswad turned black due to sins of people (according to tradition).Last verified on 02-04-2026', 0, 0, 0, 1790964564392) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_58110e4c9b90ef26', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Masjid-e-Khief is located in ________?', '{"A":"Muzdilifa","B":"Minna","C":"Arafaat","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid al-Khayf is located in Mina, near Makkah.The Prophet Muhammad (PBUH) offered prayers here and delivered a sermon during Hajjat al-Wada (10 AH).In this mosque almost 70 Prophets are buried.Last verified on 03-04-2026', 0, 0, 0, 1790964564392) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_adac2af8903cfd17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ada Bin Hatim Tai embraced Islam in which Hijri?', '{"A":"8th Hijri","B":"9th Hijri","C":"10th Hijri","D":"11th Hijri"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adi ibn Hatim accepted Islam in 9th Hijri (630 AD).He was the son of Hatim al-Tai, a famous Arab known for generosity.Before accepting Islam, Adi remained opposed to Islam for about 20 years.Last verified on 03-04-2026', 0, 0, 0, 1790964564392) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9df409663d266106', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the fifth righteous caliph of Hijaz?', '{"A":"Hazrat Umar ibn Abd al-Aziz","B":"Hazrat Abu baker","C":"Hazrat Usman","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Umar ibn Abd al-Aziz was a just ruler of the Umayyad Caliphate.He ruled from 717 to 720 A.D.He died in 720 A.D (101 A.H) at the age of 39 years.Known as the 5th Rightly Guided Caliph due to his justice and reforms.Last verified on 02-04-2026', 0, 0, 0, 1790964564393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_54e1b7039d84f3e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The ritual of standing at Arafat (Wuquf) takes place on which day of Dhul-Hijjah?', '{"A":"7th","B":"8th","C":"9th","D":"10th"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wuquf (Standing at Arafat) is a key ritual of Hajj.It takes place on 9th Dhul-Hijjah.It is also called Yawm-e-Arafat.Pilgrims gather on the Plains of Arafat to pray and seek forgiveness.They perform combined Dhuhr and Asr prayers and supplicate (du’a).This ritual is essential for Hajj to be valid.Last verified on 02-04-2026', 0, 0, 0, 1790964564454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1221c42194570e9f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Imam Shafi took the office of ''Religious Judgement'' at the age of ______?', '{"A":"13 years","B":"14 years","C":"15 years","D":"16 years"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Name: Abū ʿAbdullāh Muhammad ibn Idrīs al-ShāfiʿīFounder of: Shafi‘i school of FiqhAge when given Fatwa: 15 yearsBirth: 767 AD, GazaDeath: January 19, 820 AD, Old Cairo, EgyptBurial Place: قبة الامام الشافعی, EgyptMajor Contribution: Principles of Islamic jurisprudence (Usul al-Fiqh)Last verified on 01-04-2026', 0, 0, 0, 1790964564454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_40f9af871b72afd3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Khalid bin Waleed belonged to the tribe ______?', '{"A":"Banu Ummayya","B":"Banu Zuhra","C":"Banu Makhzoom","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khalid bin Waleed was a famous Muslim military commander.He belonged to the Banu Makhzoom of Quraysh in Makkah.He is known as “The Sword of Allah” for his role in early Islamic battles.He played a key role in the Battle of Uhud, Battle of Mu’tah, and the conquest of Persia and Arabia.Last verified on 01-04-2026', 0, 0, 0, 1790964564454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_97b0075461ee797c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the seventh month of Islamic calendar?', '{"A":"Rajab","B":"Ramzan","C":"Muharram","D":"Shawal"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 12 Islamic MonthsMuḥarram (محرم الحرام)Ṣafar (صفر المظفر)Rabi al-Awwal (ربیع الاول)Rabi al-Thani / Rabi al-Sani (ربیع الثانی)Jumada al-Awwal (جمادی الاول)Jumada al-Thani (جمادی الثانی)Rajab (رجب المرجب)Shaʿban (شعبان المعظم)Ramadan (رمضان المبارک) – Month of fastingShawwal (شوال المکرم)Dhu al-Qaʿdah (ذوالقعدہ الحرام)Dhu al-Hijjah (ذوالحجہ الحرام) – Month of HajjLast verified on 14-03-2026', 0, 0, 0, 1790964564454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_44c0f04dfaddef30', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is meant by Allah''s attribute Al-Bari?', '{"A":"The Generous","B":"The Maker","C":"The Glorious","D":"The Aware"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Bari (الباري) means "The Maker" or "The Creator", emphasizing Allah''s power and ability to create and shape everything in existence.Additional information:Ar-Rahman (الرحمن): The Most MercifulAl-Wadud (الودود): The Loving OneAl-Hakeem (الحكيم): The WiseAl-Aleem (العليم): The All-KnowingAl-Qadir (القدير): The PowerfulThe Generous: Al-Kareem (الكريم)The Glorious: Al-Majid (المجيد)The Aware: Al-Khabir (الخبير)Last verified on 31-03-2026', 0, 0, 0, 1790964564454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1b6f341e3b9c16e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The first/oldest masjid (Mosque) on the surface of earth is _____?', '{"A":"Masjid-i-Aqsa","B":"Masjid-e-Quba","C":"Masjid-ul-Haram (Bait-ul-Allah)","D":"Masjid-i-Nabvi"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid al-Haram is the first mosque on Earth.It surrounds the Kaaba, originally built by Prophet Ibrahim (A.S) and Prophet Ismail (A.S).Additional information:Masjid Al-Aqsa → Built/rebuilt by Prophet Sulaiman (A.S).First mosque in Islam: Quba MosqueBuilt after Hijrah: 622 AD (Masjid-e-Quba)Last verified on 30-03-2026', 0, 0, 0, 1790964564454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f7e2216888c80e3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Where was Gautama Buddha born?', '{"A":"Bodh Gaya, India","B":"Lumbini, Nepal","C":"Sarnath, India","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gautam Budha was born in Lumbini, Nepal in 623 BC.Language of discourse/lectures of Budhha was: Pali He was the founder of Buddhism.Last verified on 16-03-2026', 0, 0, 0, 1790964564454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_78d02403bffa0b24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the significant event of 27 Rajab of the 10th year of Prophethood?', '{"A":"Boycott","B":"Migration","C":"Isra and Miraj","D":"Pledge of Aqaba"}', 'C', NULL, 0, 0, 0, 1790964564454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0c0f30ab5e617f05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which Angel will blow the trumpet (Sur) at the Day of Judgment?', '{"A":"Hazrat Jabrail","B":"Hazrat Israfil","C":"Hazrat Mikail","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Angel commissioned to blow the Trumpet (Sur) on the Day of Judgment is Israfil Munkar and Nakir – The angels responsible for questioning the soul of a person who has died', 0, 0, 0, 1790964564524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9879edea80d9969e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The oldest revealed divine (holy) book is ____?', '{"A":"Tawrat","B":"Zaboor","C":"Injeel","D":"Quran"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Torah is the compilation of the first five books Tawrat (Torah): Revealed to Prophet Musa (Moses).Additional informationFirst revealed Holy book: TawratSecond revealed Holy book: ZaboorThird revealed Holy book: Injeel Last revealed holy book: Quran', 0, 0, 0, 1790964564524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6da266b5ac2b6c49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Dhat an-Nataqain is title of?', '{"A":"Hazrat Fatima","B":"Hazrat Ayesha","C":"Hazrat Asma","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She received from Muhammad the title Dhat an-NitaqaynMeaning "She of the Two Belts". She was married to Zubayr ibn al-Awwam shortly before the Hijra.', 0, 0, 0, 1790964564524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_297382f317d5b6ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Sulah Hudaybiyyah was signed between Muslim and _______?', '{"A":"Jews of Madina","B":"Kharjis","C":"Christian","D":"Quraish"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The treaty allowed for a temporary truce between Muslims and Quraysh.Additional information:Year Signed: 628 AD / 6 HijriMonth: Dhu al-Qi’dah (March 628)Duration: 10 yearsClauses: 7Location: Near the tree called HudaybiahKey Signatories:Muslims: Prophet Muhammad ﷺ, Ali ibn Abi Talib (scribe)Quraysh Mecca: Suhail bin AmarLast verified on 02-02-2026', 0, 0, 0, 1790964564524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4a171ee275b4249d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Largest Muslim country in the world by landmass/area is ____?', '{"A":"Mali","B":"Pakistan","C":"Indonesia","D":"Kazakhstan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kazakhstan is the largest muslim country by area. Indonesia is the largest country by population.Kazakhstan spans an area of approximately 2.7 million square kilometres.Kazakhstan is the ninth (9th) largest country in the world.Kazakhstan is the largest landlocked country in the World.', 0, 0, 0, 1790964564524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_80e7218e919155c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who wrote the book ‘Hujjat Allah Al Baligha’?', '{"A":"Imam Malik","B":"Imam Shafi","C":"Shah Wali Ullah","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Conclusive Argument From God (Hujjat Allah al Baligha)The Conclusive Argument of God is the masterwork of Shah Wallah of Delhi (1762)Originally published on: 1979Author of Hujjat Allah al Baligha: Shah Waliullah DehlawiEditor of Hujjat Allah al Baligha : Marcia Hermansen****nd9-2-2023', 0, 0, 0, 1790964564524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b3491fb36edb36af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Siddique and______the title given to Abu bakkar Siddique?', '{"A":"Pious","B":"Tahir","C":"Ateeque","D":"None of above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Saddique and Ateeque the title given to Abu Bakkar Siddique:The first Caliph of Islam. Al-Siddiq means "the truthful."Atiq means "the one set free" or "noble". Abu Bakr Burial in Al-Masjid an-Nabawi, MedinaA title conferred by Prophet Muhammad after Abu Bakr, who immediately believed in the story of Isra and Miraj.Last updated by NA on 26 April 2026', 0, 0, 0, 1790964564524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cbc76c5bc9391eed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Current Hijri Year is ______?', '{"A":"623AD","B":"622AD","C":"628AD","D":"630AD"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Hijri calendar was started in 622ADIslamic Calendar starts from HijriIslamic calendar officially established by: Hazrat Umar (R.A) ibn al-Khattab.The Prophet''s migration or hijra in 622AD marks the beginning of the Hijri year calendar and gives the calendar its name.The Islamic calendar is based on 12 lunar months یہ سوال ضرور پڑھیںCurrent Hijri Year is ______?', 0, 0, 0, 1790964564524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ab54eb7020faa2b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who purchased the well of Ruma and declared it as a trust?', '{"A":"Hazrat Ali","B":"Hazrat Umar","C":"Hazrat Usman","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Uthman bin Affan bought the well and gifted it to Muslims and declared it as a Waqf.', 0, 0, 0, 1790964564588) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_55f218e0a6a9ced8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who is Hazrat Sobia (RA)?', '{"A":"Mother of Abdur Rehman Bin Auf (RA)","B":"Mother of Hazrat Talha Bin Zubair (RA)","C":"Mother of Hazrat Hamza (RA)","D":"Mother of Musoad Bin Umair (RA)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Sobia (RA) was the Mother of Hazrat Hamza (RA)**** Sobia was the maidservant of Prophet (PBUH) uncle Abu Lahab, who was the first one to have the honor of feeding the Prophet (PBUH). The Prophet liked her so much and was grateful to her and her children till she died in the seventh year A.H (after Hijra)', 0, 0, 0, 1790964564588) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ca3936dddddcac0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Alhambra palace is located in ______?', '{"A":"Spain","B":"India","C":"Turkey","D":"Indonesia"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On a hill overlooking the Spanish city of Granada stands the Alhambra, a palace built by princes belonging to the Muslim Nasrid dynasty (1238–1492) in the 14th century.', 0, 0, 0, 1790964564588) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c98593b634af0381', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Masjid-e-Nimra is situated in _____?', '{"A":"Plains of Arafat","B":"Madina","C":"Taif","D":"Jeddah"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid-e-Nimra is situated in the Plains of Arafat, Makkah.Pilgrims gather at Masjid-e-Nimra on the 9th day of Dhu al-Hijjah.It is also known as the "Musalla".The Prophet Muhammad (PBUH) delivered his Farewell Sermon at this location.Pilgrims perform Dhuhr and Asr prayers combined at Masjid-e-Nimra during Hajj.', 0, 0, 0, 1790964564588) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_854aed9501517ae9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which of the following Prophets (AS) is known as Safiullah?', '{"A":"Hazrat Younas (AS)","B":"Hazrat Ibrahim (AS)","C":"Hazrat Adam (AS)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Adam (AS) is known as Safiullah, meaning "the chosen one of Allah."He is considered the first prophet in Islam and the father of mankind.', 0, 0, 0, 1790964564588) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_11f9a24c3bbda975', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which caliph of the Muslims ordered the compilation of Ahadith and send to the conquered territories?', '{"A":"Hazrat Umar bin abdul Aziz","B":"Hazrat Umar","C":"Hazrat Usman","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Umar ibn Abd al-Aziz, was the eighth Umayyad caliph. He made various significant contributions and reforms to the society, and he has been described as and was called the first Mujaddid and sixth righteous caliph of Islam after Hasan Bin Ali according to some Muslim Scholars.', 0, 0, 0, 1790964564588) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f254f92c8b277b6c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Abu Bkar (RA) died in:', '{"A":"10th Hijrah","B":"11th Hijrah","C":"13th Hijrah","D":"15th Hijrah"}', 'C', NULL, 0, 0, 0, 1790964564588) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c5caab49721aee4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which is the biggest Islamic country with respect to population?', '{"A":"Egypt","B":"Indonesia","C":"Pakistan","D":"Saudi Arabia","E":"Iran"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Indonesia is the largest while Pakistan is the second largest Islamic country in the world with regard to population.Overall, China is the largest, India second, USA third, Indonesia fourth & Pakistan is the fifth largest country in terms of population.', 0, 0, 0, 1790964564588) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9168350c0f4ed418', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What does the term "Hypocrite" refer to?', '{"A":"Single-faced","B":"Double-faced","C":"Straight-forward","D":"Honest"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A hypocrite is someone who presents a false appearance of being virtuous or loyal.But actually harbors different intentions or beliefs.', 0, 0, 0, 1790964564657) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_69dc55b935e593e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', '"INFAQ" means ____?', '{"A":"Fighting with enemies of Islam","B":"Spending wealth for the cause of Islam","C":"Travelling from Mecca to Medina","D":"Delivering a speech against infidals"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Infāq s an Arabic word meaning spending or disbursement. but also carries the sense of doing so simply to please God without asking for any favor or hoping for a return.The word ʾinfāq is mentioned once in the Qurʾān in Q17:100The imperative form of the verb (ʾanfiqū) (أَنفِقُوا) appears 18 times in the QurʾānInfāq is different from zakat, which is obligatory on Muslims, or sadaqahND28-4-2023', 0, 0, 0, 1790964564657) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6a75e92bacfe43d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Treaty of Hudaybiyyah was concluded in which Hijri year?', '{"A":"9","B":"7","C":"8","D":"6","E":"10"}', 'D', NULL, 0, 0, 0, 1790964564657) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e39c61dd0cb25e08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which is the second largest Religion in the World?', '{"A":"Christianity","B":"Islam","C":"Hinduism","D":"Buddhism"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Islam is the second-largest religion in the WorldList of World''s largest Religions.1. Christianity (31.2%)2. Islam (24.1%)3. No religion (16%)4. Hinduism (15.1%)5. Buddhism (6.9%)6. Folk religions (5.7%)7. Other religions (0.5%)8. Sikhism (0.3%)9. Judaism (0.2%)', 0, 0, 0, 1790964564657) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_47b8e5063e4c2de5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The literal meaning of Jihad?', '{"A":"To Strive Hard","B":"To Conquer","C":"To Stand Hard","D":"Way of Allah"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The literal meaning of jihad is "striving," "struggling," or "exerting utmost effort."Jihad becomes first in.2AH 41 times the word jihad appears in the Quran Last updated 12 april 2026', 0, 0, 0, 1790964564657) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_08d7f4fe5c71d24e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Bait-e- Rizwan was made to take the revenge of', '{"A":"Hazrat Hamza (RA)","B":"Hazrat Usman (RA)","C":"Hazrat Ali (RA)","D":"Hazrat Umer (RA)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bait-e-Rizwan took place in 6th Hijrah.Bait Rizwan was the pledge taken to get revenge of Hazrat Usman (RA) under the tree known as RizwanBait-e-Rizwan is also known as Bait-e-Shajra made under the Keekar tree.****', 0, 0, 0, 1790964564657) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_43577f40544f4d00', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Literal meaning of "Iblees" is:', '{"A":"Angry one","B":"Disputation","C":"Deprived one","D":"Disappointed one"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The meaning of the name Iblees is disappointed in God''s mercy,خدا کی رحمت سے مایوس، شیطان، خبیث', 0, 0, 0, 1790964564657) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_185dffa9c086b67b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which of the following is fasting in Ramadan, the ninth month of the Islamic Year?', '{"A":"Salah","B":"Tasbeeh","C":"Sawm","D":"Taraweeh"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fasting during the month of Ramadan was made obligatory (wajib) during the month of Sha''ban (8th Month)Fasting was the 4th fundamental pillar of IslamFasting (Soam) is declared as armorFasting was made obligatory in 10th Shaban,2 A.HThe function of fasting is To Make the Sacrifice of Body and SoulSaum (fasting) resembles Hadith with a Shield5 days are prohibited ممنوع for fasting throughout the Year', 0, 0, 0, 1790964564657) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5e8624b2f89cbb4f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The voluntary donations that Muslims may choose to give (in addition to Zakah) is called?', '{"A":"Fitrah","B":"Khums","C":"Kanz","D":"Sadaqah"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sadaqah means وہ چیز جو خدا کے نام پر دی جائےSadaqah refers to voluntary donations that Muslims give out of kindness, apart from the obligatory Zakah.It is given anytime and in any amount.', 0, 0, 0, 1790964564732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_32293fe392d43967', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Where Hazrat Essa was born?', '{"A":"Gaza Strip","B":"Tel Aviv","C":"Bait Ul Lehm","D":"Makkah","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The city Bait Ul Lehm is situated in Jerusalem.The holy book Injeel was revealed on Hazrat Esa AsHazrat Isa (As) is known Rohullah', 0, 0, 0, 1790964564732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_94a5f9e5a98081ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the original name of Iblis?', '{"A":"Azazil","B":"Janaha","C":"Chaleepa","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Azazil is usually seen as the original name of IblisThe word ''Iblis'' (إِبْلِيس) comes from the word Balasa (بَلَسَ), which means ''to despair''Azazil is the name of Satan because he despairs from all goodnessliblis is the leader of the devils (shayāṭīn) in Islam. Iblis was thrown out of heaven after he refused to prostrate himself before AdamND5-2-2023', 0, 0, 0, 1790964564732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dacb12eb714bada9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first Katib-e-Wahi?', '{"A":"Hazrat Umar R.A","B":"Hazrat Ali R.A","C":"Hazrat Sharjeel R.A","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sharjeel bin Hasana — First prescriber of Wahi in Makkah. Khalid bin Saeed — First writer of Wahi among Quraysh.', 0, 0, 0, 1790964564732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6b12e32c5d53d979', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ashab e Kahf slept for how many years?', '{"A":"302","B":"305","C":"309","D":"311"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "kahf" means "the cave in the mountain"the sura is named "kahf" because it speaks about the story of the Companions of the CaveAshab e Kahf slept for 309 yearsThe number of Ashab-e-Kahf was 7The story of Ashab al-Kahf is narrated in the eighteenth chapter of the Quran, called “al-Kahf” In verses 9-26سورہ کہف میں اصحاب کہف کے ساتھ کتا جانور کا ذکر آیا ہےQitmeer is the name of the dog in Surah Kahf.', 0, 0, 0, 1790964564732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4e3a4b4cc31f3855', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ramzan is the _______ month of Islamic calendar?', '{"A":"2nd month","B":"3rd month","C":"6th month","D":"9th month"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ramzan is the 9th month of Islamic calendar.Fast was obligatory in 2nd Hijri.Ramadan is divided into three stages-First Ashra (Rehmat), Second Ashra (Maghfirat) Third Ashra (Nijaat).Last update 0n 21-07-2026 by NA', 0, 0, 0, 1790964564732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ae114799402b9d14', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many holy books are there in Islam?', '{"A":"1","B":"2","C":"3","D":"4"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are four Holy BooksThe Torat revealed to MusaThe Zabur revealed to Dawud The Injil (Gospel) revealed to Isa The Quran was revealed to Muhammad.', 0, 0, 0, 1790964564732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b8129d0d859351bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ruma was the mother of _____?', '{"A":"Hazrat Talha (R.A)","B":"Hazrat Ali (R.A)","C":"Hazrat Hamza (R.A)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ruma was the mother of Hazrat Talha (R.A), a famous companion of Prophet Muhammad ﷺ.Hazrat Talha (R.A) is known for his bravery and generosity in early Islamic history.', 0, 0, 0, 1790964564732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_493c4d90e2833e77', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'From which Word ‘Aqeeda’ is Derived?', '{"A":"Aqleed","B":"Aqaid","C":"Aqd","D":"Taqleed"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word ‘Aqeeda’ is derived from the Arabic root ‘Aqd’, which means to tie or bind firmly.عقیدہ عربی لفظ "عَقد" سے نکلا ہے، جس کا مطلب ہے باندھنا یا مضبوطی سے باندھنا۔عقیدہ دل میں کسی بات پر پختہ یقین رکھنے کو کہتے ہیں، جیسے اللہ پر ایمان۔', 0, 0, 0, 1790964564801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bb50c0357afa2e40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Younis (AS) remained in the abdomen of fish for how many days?', '{"A":"30 days","B":"40 days","C":"20 days","D":"10 days","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Younis remained in the abdomen of fish for 40 days.Surah Younis is the 10th chapter (surah) of the Quran with 109 verses (ayat).His named after the prophet Yunus (Jonah).He is mentioned in the holy Quran: 4 timesHazrat Younis (AS) is called Dhun-Nun', 0, 0, 0, 1790964564801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1370c7799f84e4fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the name of Hazrat Muhammad parental grandmother?', '{"A":"Fatimah bint Amr","B":"Barrah bint Abdul Uzza","C":"Halah bint Wahab","D":"Amina bint Wahb"}', 'A', NULL, 0, 0, 0, 1790964564801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4b6d2bc13bcce274', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Tariq bin Ziyad conquered Spain the year?', '{"A":"Rajab, 92 Hijri (711 AD)","B":"Ramzan, 93 Hijri (712 AD)","C":"Safar, 94 Hijri (713 AD)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tariq bin Ziyad initiated the Muslim conquest of Spain in 711 ADInitiated the Muslim conquest of the Iberian Peninsula (present-day Spain and Portugal) Against the Visigothic Kingdom in 711–718 AD.Initial Landing: April 711 AD.Decisive Battle: The Battle of Guadalete on July 19, 711 AD.Additional information The Rock of Gibraltar is named after him ("Jabal Ṭāriq" - Mountain of Tariq).Last updated question by NS on 11 May 2026', 0, 0, 0, 1790964564801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5ea5f21f01164b63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Abu Bakar (R.A) was died in ______?', '{"A":"13th Hijra","B":"11th Hijra","C":"10th Hijra","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Bakar (رضہ) Born: October 27, 573 AD, Mecca, Saudi ArabiaHazrat Abu Bakar (رضہ) Died: August 23, 634 AD, Medina, Saudi Arabia', 0, 0, 0, 1790964564801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fc994001c65fc84d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many Doors of hell are there?', '{"A":"7","B":"6","C":"5","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The doors of hell are seven.The gate keeper of hell is MalikThe doors of heaven are eight. The gatekeeper of heaven is Rizwan.****Name of 7 doors of hell:Jahannam was reserved for Muslims who had committed grave sins.al-Laza (the blaze) for the Jews.al-Hutama (the consuming fire) for the Christians.al-Sa''ir for the Sabians.al-Saqar (the scorching fire) for the Zoroastrians.al-jahim (the hot place) for the idolaters.al-Hawiya (the abyss) for the hypocrites.', 0, 0, 0, 1790964564801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_50fd2f6ebbf4e766', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How Hazrat Salman Farsi (RA) was freed as a slave?', '{"A":"On the request of Prophet (PBUH) to the owner","B":"Hazrat Usman (RA) paid the price to the owner","C":"Prophet (PBUH) and his companions carried out plantation in the garden in lieu thereof","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Salman (R.A.) was released from slavery by the Prophet (S.A.W.) who paid his Jewish slave-owner a stipulated price and who himself planted an agreed number of date palms to secure his manumission.Salman was a companion of the Islamic prophet Muhammad.First Persian who converted to Islam.He was referred to by the kunya Abu Abdullah. Born: 568 AD, JayDied: Ctesiphon, Iraq', 0, 0, 0, 1790964564801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6b880aeae4e55f2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first ambassador of Islam?', '{"A":"Hazrat Hamza R.A","B":"Hazrat Abu Bakr R.A","C":"Mus‘ab bin ‘Umair R.A","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mus’ab ibn Umayr was appointed the first ambassador of Islam and was sent to Yathrib (Medina) to prepare the city for the forthcoming Hijra after the first pledge with the Ansar. A man of Medina named Asad ibn Zurarah assisted him.', 0, 0, 0, 1790964564801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_94bfabc5d4dfca9b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Where is Hajr-e-Aswad situated?', '{"A":"Western Corner of Kaaba","B":"Eastern Corner of Kaaba","C":"Northern Corner of Kaaba Corner of Kaaba","D":"Southern Corner of Kaaba"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hajr-e-Aswad, or the Black Stone, is located in the eastern corner of the Kaaba in the Grand Mosque in Mecca, Saudi Arabia.The Black Stone is a revered Islamic relic believed to have been set into the Kaaba by the Prophet Muhammad (SAW) in 605 CE, five years before his first revelation.', 0, 0, 0, 1790964564858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fada4b9825df1732', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Abu Jahl (Amr bin Hisham) was the Chief of which clan?', '{"A":"Banu Taim","B":"Banu Hashim","C":"Banu Makhzum","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Jahal’s actual name was Amr ibn Hisham he was commonly known as Abu Hakam (“Father of Wisdom”)He belonged to the Sons of Mahzum clan of the tribe of Quraysh in Makkah.Abu Jahal was not a real uncle of the Prophet (ﷺ) [not his father’s real brother] but his father’s cousin.Cause of death is Beheaded at the Battle of BadrKnown for being the enemy of MuhammadNote:in some question, the spelling was written as Amr, Amer, Umer, Omer', 0, 0, 0, 1790964564858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9c52ecf13c6c1504', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What does Israel mean?', '{"A":"Man of God","B":"Liked by God","C":"Friend of God","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Israel is a name that originates from the Hebrew language.It means "he who struggles with God" or "man of God".This name was given to Jacob, the son of Isaac, after he wrestled with an angel and won (Genesis 32:28).From then on, Jacob was known as Israel, and his descendants were called the Children of Israel.', 0, 0, 0, 1790964564858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a41e41a2a87e5a51', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Shoot means _____?', '{"A":"One tawaf of kaba","B":"One running between Saffarf and Marwa","C":"Stay in Arfat","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation One tawaf of Kaaba is known as a Shoot.Tawaf is a mandatory step in Umrah and certain types of Hajj.Tawaf basically refers to the act of circumambulating the Holy Ka''abah in Masjid al-Haram in reverence to God...5 Types of Tawaf in IslamTawaf-al-Umrah.Tawaf-al-Qudoom.Tawaf-al-Ifada or Tawaf al Ziyarah.Tawaf-al-Widaa.Nafl Tawaf.', 0, 0, 0, 1790964564858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e44f4c51c2079529', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The largest idol named in Kaba was ____?', '{"A":"Hubal","B":"Jabal","C":"Tabal","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest idol named in Kaba was Hubal.Idol means بت360 idols in Kaba before Islam اسلام سے پہلے کعبہ میں 360 بتHubal was a god worshiped by Quraysh at the Kaaba in Mecca. Muhammad entered Mecca in 630, he destroyed the statue of Hubal from the Kaaba along with the idols of all the other pagan gods.5 idols are mentioned in Surah NuhThe nation of Noah worshiped 5 idols', 0, 0, 0, 1790964564858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_04201ece40d88b05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Shaikh Ahmad Sirhindi (Mujaddid Alif Sani) was born on ______?', '{"A":"971 AH","B":"987 AH","C":"569 AH","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ahmad al-Fārūqī al-Sirhindī was an Indian Islamic scholar, Hanafi jurist, and member of the Naqshbandī Sufi.Ahmad Sirhindi was born on 26 May 1564 in the village of Sirhind, PunjabDied: December 10, 1624, Sirhind, IndiaPlace of burial: Hazrat Seyfeddin Farooqi, Rauza Sharif, Fatehgarh Sahib, IndiaBooks: The Juristic Sufism of Ahmad Sirhindi, Beweis Des ProphetentumsND15-10-2023', 0, 0, 0, 1790964564858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9936e94dec98e2b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which of the following Prophets was known As Abu-ul-Arab (Father of the Arabs)?', '{"A":"Hazrat Ibrahim (AS)","B":"Hazrat Ismael (AS)","C":"Hazrat Yaqoob (AS)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ismael (AS) is called Abu-ul-Arab (Father of the Arabs) because Arab tribes trace their lineage through him.He settled in Makkah and married into the Jurhum tribe, giving rise to Arab ancestry.', 0, 0, 0, 1790964564858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d584cc6b2d4ccafd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Amina (RA) mother of Hazrat Muhammad (SAW) belonged to which tribe?', '{"A":"Banu hashim","B":"Banu muttlib","C":"Banu zuhra","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Amina was the mother of Hazrat Muhammad PBUH.She was died when the age of Holy Prophet is 6 years.', 0, 0, 0, 1790964564858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f9bed3c63daa2fe7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the meaning of Wahi?', '{"A":"Expression","B":"Excitation","C":"Revelation","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The literal meaning of "Wahi" is: Allah''s Message or RevelationTwo kinds of Wahi are there:1. Wahee-e-Matlu:It means the revelation which God has transmitted in His own words and speech2. Wahee-e-Ghair Matlu:It is the revelation that Allah projected in the heart of the Holy Prophet.', 0, 0, 0, 1790964564919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8bcb14d7b06efd0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In the Islamic era, the Postal System was established by ________?', '{"A":"Hazrat Umar Farooq","B":"Hazrat Usman E Ghani","C":"Hazrat Amir Muawiya","D":"Abdul Malik Bin Marwan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ameer Muawiyah (R.A) established Postal SystemPurposes: speed up the arrival of intelligence from his outlying provinces.***About Ameer Muawiyah (R.A)Mu''awiya I was the founder and first caliph of the Umayyad Caliphate serving from 661 until his death. He became caliph less than thirty years after the death of the Islamic prophet MuhammadﷺMuawiyah was appointed as the Governor of Syria after his brother Yazid ibn Abu Sufyan died', 0, 0, 0, 1790964564919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dc131a50e886b6ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The duty of Hazrat Israfeel (Israfil) (PBUH) is?', '{"A":"To bow the trumpet on the day of judgment","B":"Incharge of protection","C":"In charge of the life of living creatures","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is believed that the Angel Israfil (PBUH) will blow a trumpet to announce the Day of Judgement .2 times the trumpet will be blown by Hazrat Israfil (PBUH)Israfil (PBUH) is the commander of the angels carrying out the command resurrectionwhile Azrael (PBUH) is the leader of the angels carrying out the command to take life**ND16-1-2023', 0, 0, 0, 1790964564919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_83c109ad3cd12aa6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The basic doctrines (beliefs) of Islam are?', '{"A":"Three","B":"Four","C":"Seven","D":"Six"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are seven things that are essential for a Muslim to believe in.the Islamic faith is known as Iman-e-Mufassal.1. Faith in God;2. Faith in His angels;3. Faith in His revealed Books;4. Faith in all of His messengers or Prophets;5. Faith in the Last Day or the Day of Judgement;6. Faith in the doctrine of predestination, which lays down that everything good or bad is decided by God), (Taqdir) and7. Faith in life after death.', 0, 0, 0, 1790964564919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_70559ce8cd859c28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The most populous Islamic country of the world is _____?', '{"A":"Pakistan","B":"Iran","C":"Indonesia","D":"Saudi Arabia"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The biggest Islamic country with the area is Kazakhstan.The country with the largest number of Muslims overall is Indonesia, nearly 13% of the world''s total population of Muslims. Rank Name % of Country that is Muslim % of World''s Muslim Population 1 Indonesia 87% 13% 2 Pakistan 96% 11% 3 India 15% 11% 4 Bangladesh 91% 8% 5 Nigeria 50% 5% 6 Egypt 95% 5% 7 Iran 100% 4% 8 Turkey 98% 4% 9 Algeria 98% 2% 10 Iraq 99% 2%', 0, 0, 0, 1790964564919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8ef20d55482d78b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Quba Mosque located in ______?', '{"A":"Makkah","B":"Madina","C":"Islamabad","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid-e-Quba also known as the very 1st Masjid of Islam, Founded by the Prophet Muhammad صلی الله علیہ وسلم.Mosque Taqwa is the second name of mosque Quba. It is located in Madina.Quba mosque is mentioned in Surah-al-Taubah.', 0, 0, 0, 1790964564919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_862671174259514f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The fundamental faiths in Islam are _____?', '{"A":"Prophethood","B":"Monotheism","C":"Day of Judgment","D":"All of these"}', 'D', NULL, 0, 0, 0, 1790964564919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_24469d33a079e61a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'According to Muslim personal law, marriage age for males and females is respectively ______?', '{"A":"18 and 16","B":"16 and 18","C":"16 and 14","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Muslim Personal Law:The marriageable age for males is 18 years.The marriageable age for females is 16 years.', 0, 0, 0, 1790964564919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a5e123d0657bb895', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Islamic Summit Conference was held in Lahore in _____?', '{"A":"1972","B":"1974","C":"1973","D":"1975"}', 'B', NULL, 0, 0, 0, 1790964564980) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9e74af08a0c47324', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Al-Tafseer Al-Kabir was written by ______?', '{"A":"Ismail bin Kathir","B":"Imam Ghazali","C":"Fakhr al-Din al-Razi","D":"Imam Razi"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Tafseer al-Kabir (Mafatih al-Ghayb) is a famous Quranic commentary written by Imam Fakhr al-Din al-Razi.It is renowned for its depth in theology, philosophy, and rational discussions along with tafseer.', 0, 0, 0, 1790964564980) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2be09c2b1eec16b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The last month of the Islamic Calendar is:', '{"A":"Safar","B":"Shawal","C":"Jamadi-ul-Awwal","D":"Zilhaj"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The last month of the Islamic (Hijri) calendar is Dhu al-Hijjahknown as the "month of pilgrimage."Additional information12-month name Muḥarram, محرم الحرامṢafar, صفر المظفرRabi al Awwal ربیع الاولRabi al Sani ربیع الثانیJumada al Awwal جمادی الاولJumada al Thani جمادی الثانیRajab, رجب المرجبShabanشعبان المعظمRamadan(fasting), رمضان المبارکShawwal شوال المکرمDhu al Qadah ذوالقعدۃ الحرامDhu al Hijjah ذوالحجۃ الحرام:**** Each month begins approximately at the time of the new moon.Last updated by NA on 25-April-2026', 0, 0, 0, 1790964564980) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_78cc4d8d1ac52b90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Al Aqsa Mosque located in _______?', '{"A":"Saudi Arabia","B":"Turkey","C":"Spain","D":"Jerusalem"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Aqsa Mosque, located in the Old City of Jerusalem.In Masjid-e-Aqsa the word Aqsa means Far away.Hazart Ibrahim ( A.S) was the Prophet which first laid the foundation of Masjid-e-Aqsa.Masjid-e-Aqsa was the first qibla in Islam.It was built 40 years after Masjid-ul-Haram in Makkah.', 0, 0, 0, 1790964564980) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a19dc62c4d4436ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The permission for Tayammum was granted in _____?', '{"A":"3 A.H","B":"2 A.H","C":"1.A.H","D":"4 A.H","E":"8 A.H"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tayammum is the Islamic act of dry Ritual purification using purified sand or dustin Al-Ma''idah contains the order of wuzu, Ghusal, and TayammumTayammum is valid only for one obligatory SalahTayammum is obligatory on 4 (AH)while Wazu is obligatory on 5(AH)****nd9-2-2023', 0, 0, 0, 1790964564980) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2a69c2f7d3d30000', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is meaning of Al-Baqarah?', '{"A":"Goat","B":"Elephant","C":"Cow","D":"Spider"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Baqarah (The Cow or The Heifer) is the second and longest chapter of the Quran, with 286 verses.It derives its name from the story of the cow (vv. 67-73).Verse 282, the longest verse, is known as ''āyatu d-dayn.It consists of 25,500 letters and is positioned in Juzʼ 1–3.The chapter has 40 Rukus and is classified as Medinan.Hazrat Ibrahim (علیہ السلام) is mentioned 13 times.The verse 183 describes the obligation of fasting (soam).Surah Aal-e-Imran is the second longest surah of Holy Quran.Surah Al-Kausar is the shortest surah of Holy Quran.', 0, 0, 0, 1790964564980) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9cc9380ef312fd5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which is the Arabic word known as Nimaz?', '{"A":"Soam","B":"Salat","C":"Fatah","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Arabic, "Salat" (صلاة) is the term for the five daily prayers in Islam.It is also known as "Nimaz" in Urdu and other languages.', 0, 0, 0, 1790964564980) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_cca4b20d94d1b6e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the First Wife of Hazrat Muhammad ﷺ?', '{"A":"Hazrat Khadija (RA)","B":"Hazrat Sauda (RA)","C":"Hazrat Ayesha (RA)","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790964564980) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a9954dc8f5a282fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ghazi Ilm-ud- Din killed Rajpal on which date?', '{"A":"24th March 1929","B":"06th March 1929","C":"28th April 1929","D":"06th April 1929"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ilam Din murdered Rajpal, the publisher of the pamphlet “Rangila Rasul”, on April 6, 1929.He died on May 22, 1929 Central Jail, MianwaliMohammed Ali Jinnah and Farrukh Hussain filed an appeal to the Lahore High Court against the death sentence. Born: December 4, 1908, LahoreFull name: Ilm Deen', 0, 0, 0, 1790964565059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b96918c1612fb143', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Arafat is gathering is held on ______?', '{"A":"7 Zil Hajj","B":"8 Zil Hajj","C":"9 Zil Hajj","D":"10 Zil Hajj"}', 'C', NULL, 0, 0, 0, 1790964565059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ec1f8ef9d5f5e684', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The enforcement of 80 lashes as punishment for consuming alcohol (sharab) is attributed to which Caliph?', '{"A":"Abu Bakr Siddiq (R.A)","B":"Umar ibn al-Khattab (R.A)","C":"Uthman ibn Affan (R.A)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The punishment of 80 lashes for alcohol consumption was standardized during the caliphate of Umar ibn al-Khattab (R.A) (634–644 CE).This was based on his ijtihad (juridical reasoning) and consultation with companions, considering alcohol’s societal harm.', 0, 0, 0, 1790964565059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f0c46efa502103f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is meaning of Qayas?', '{"A":"Reasoning in analogy","B":"Reasoning by analogy","C":"Reasoning on analogy","D":"Reasoning at analogy"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qayas refers to "reasoning by analogy" in Islamic jurisprudence (Fiqh).It is legal rulings are derived by analogical reasoning from established principles to new situations.', 0, 0, 0, 1790964565059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8d72c2c4f5d2d11c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Tahleel means Recitation of _______?', '{"A":"Namaz","B":"Kalimahs","C":"Quran","D":"Surah","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word Tahlil is the verbal noun of the form 2 verb Hallala (هَلَّلَ) which literally means ''"to praise" or "to acclaim".', 0, 0, 0, 1790964565059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dafee3827c0de616', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Islamic year starts from/begin with the month of ____?', '{"A":"Shawal","B":"Ramzan","C":"Muharram","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Islamic (Hijri) year begins with the month of Muharram, the first month in the Islamic lunar calendar.It marks the migration (Hijrah) of Prophet Muhammad (PBUH) from Makkah to Madinah.List of Islamic MonthsMuḥarram, محرم الحرامṢafar, صفر المظفرRabi al Awwal, ربیع الاولRabi al Sani, ربیع الثانیJumada al Awwal, جمادی الاولJumada al Thani, جمادی الثانیRajab, رجب المرجبShaban, شعبان المعظمRamadan (fasting), رمضان المبارکShawwal, شوال المکرمDhu al Qadah, ذوالقعدۃ الحرامDhu al Hijjah, ذوالحجۃ الحرام', 0, 0, 0, 1790964565059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d87b42b898521ce7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Jihad become obligatory in which Hijri?', '{"A":"1AH","B":"2AH","C":"3AH","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jihad (Qital Fi Sabilillah) becomes obligatory in 2 AHIn Islam, jihad by the sword is superior to all Jihad.To Strive Hard is the literal meaning of Jihad41 times the word jihad appears in the QuranSyed Ahmad Shaheed started the Jihad movementLast update 0n 21-07-2026 by NA', 0, 0, 0, 1790964565059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_160d5064fa22e481', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'According to treaty of Hudaibiyah, a truce was declared between Muslims and Quraish for ___ years.', '{"A":"5","B":"7","C":"10","D":"12"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Hudaibiyah Treaty was Signed In the 6H for 10 Years.It was scribed by Ali Al-Murtaza (R.A).Hudabia is the name of the tree.It is called Fatah Al-Mubeen in Surah Al-FatahIt was Signed In the 6H for 10 Years.The event took place during the time of the Islamic prophet Muhammad.It was a pivotal treaty between:* Muhammad, representing the state of Medina,* and the Qurayshi tribe of Mecca Suhail bin Amar signed the Treaty of Hudaibiya on behalf of the Quraish Mecca.7 clauses did the treaty of Hudaybiyyah containND-21-5-2023', 0, 0, 0, 1790964565059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f721279f7278042c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many days Hazrat Muhammad (SAW) stayed at Ghar-e-Saur?', '{"A":"3","B":"4","C":"5","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Companions: Prophet Muhammad (PBUH) and Hazrat Abu Bakr (R.A.)Location: Cave of Thawr, near Makkah, Saudi ArabiaPurpose: They took refuge there while escaping the Quraysh during the Hijrah.Stay: They remained in the cave for three days.Miracle: A spider''s web at the entrance helped conceal the cave.Additional informationGhar-e-Saur:Other Name: Ghar-e-Thawr (Cave of Thawr)Mountain: Jabal Thawr (Mount Thawr)Last updated 27-07-2026 by NA', 0, 0, 0, 1790964565118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_503b29a9b6a8b355', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What do you understand by Tahleeq?', '{"A":"Kalmaas in loud voice during Tawaf","B":"First circle of Tawaf","C":"Cutting of hair","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tahleeq (تحلیق) refers to the act of shaving or trimming the head as a ritual during Islamic pilgrimages, particularly Hajj and Umrah.Quranic Reference:"You will surely enter the Sacred Mosque (Masjid al-Haram), if Allah wills, in safety, with your heads shaved and [hair] shortened."— Surah Al-Fath (48:27)', 0, 0, 0, 1790964565118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_aaf19ca19425cf3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Masjid al-Jinn is located in _____?', '{"A":"Makkah","B":"Madina","C":"Iraq","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid al-Jinn (مسجد الجن) is situated in Makkah, Saudi Arabia, near the Al-Haram Mosque.It marks the spot where a group of jinn (supernatural beings) reportedly listened to Prophet Muhammad (PBUH) recite the Quran (Surah Al-Jinn).', 0, 0, 0, 1790964565118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_59faf052d21e680e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The first question will be asked on the Day of Judgment is about  _____?', '{"A":"Fasting","B":"Zakat","C":"Hajj","D":"Namaz","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Namaz commanded in Quran for 700 times.Salat made compulsory in the 10th Nabvi.Salat Juma became Farz in Madina 2H.***', 0, 0, 0, 1790964565118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_63805b0ffd35defc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the religion of majority of Arabs before Islam?', '{"A":"Buddhism","B":"Jewish","C":"Idolatrous","D":"Christian"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Worshipers of IdolsWorship was directed to various Gods and goddesses, including Hubal and the goddesses al-Lāt, al-''Uzzā, and Manāt, at local shrines and temples such as the Kaaba in Mecca.', 0, 0, 0, 1790964565118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4f38765e28adab53', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The second Ashra of Ramadan is known as ____?', '{"A":"Ashra-e-Rehmat","B":"Ashra-e-Maghfirat","C":"Ashra-e-Najat-e-Naar-e-Jahannum","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "1st Ashra of Ramadan is "Days of mercy" (Rehmat).2nd Ashra of Ramadan is "Days of forgiveness" (Maghfirayat).3rd Ashra of Ramadan is "Days of refuge from hell fire" (Jahanum ke aag sa nijahat).', 0, 0, 0, 1790964565118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_34d489269fc61934', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Imam Muslim was born in ______?', '{"A":"817 AD","B":"818 AD","C":"811 AD","D":"815 AD"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Imam Muslim was born in 202 AH (817 CE) or 204 AH or 206 AH Khurasan.He belonged to a noble Arab tribe called ''Qushair''.', 0, 0, 0, 1790964565118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_89de6a9f4036f4ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Arab worship before Islam ____?', '{"A":"Fire","B":"Idols","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Before Islam, Arabs worshipped both idols and fire.Idol worship was widespread in pre-Islamic Arabia.Fire worship was also practiced in some regions.', 0, 0, 0, 1790964565118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_93a6add4ade76fae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What does the word “Islam” literally mean?', '{"A":"Submission","B":"Peace","C":"Religion","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word “Islam” means “submission to the will of God.” The fundamental belief of Islam is “There is only one God, and Muhammad is his prophet.” Derived from the Arabic triliteral root s-l-m (س-ل-م), There are five pillars of IslamLast updated question by NA on 07 May 2026', 0, 0, 0, 1790964565194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1199eaa079d5eec6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which is the oldest and largest mosque in the world?', '{"A":"Faisal Mosque","B":"Al-Masjid an-Nabawi","C":"Great Mosque of Mecca","D":"Istiqlal Mosque"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Very confusing questionMasjid-ul-Haram is the first masjid on the surface of the earth.whileMasjid-e-Quba is the first masjid in history of Islam.***Masjid Aqsa built by Hazrat Sulman A.S. whilemasjid quba is built after Hazrat Muhammad saw arrived in Madina.ND27-12-2022', 0, 0, 0, 1790964565194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3d1231834ae5c6e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is meant by Youm-e-Arafat and what is done on that day?', '{"A":"8th Zul-Hajj, Stay at Arafat before Asur","B":"7th Zul-Hajj, Stay at Arafat After Zuhr","C":"9th Zul-Hajj, Stay at Arafat before Maghrib","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 9th Zul-Hajj Pilgrim gathering day.It is Day of forgiveness.It is Day of Farewell sermon.It is Day of Deep prayer.It is Day of Blessings sought.', 0, 0, 0, 1790964565194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2278990c9b611afc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which Tawaf is known as Welcome Tawaf?', '{"A":"Tawaf Al-Wadaa","B":"Tawaf-ul-Qudoom","C":"Tawaf al-Ifadha","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is performed on arrival the Makkah whether for Umrah, Hajj, Business or a visit. It is also known as “Welcome Tawaf”. The performing of this Tawaf is a Sunnah for non-residents of Makkah.', 0, 0, 0, 1790964565194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d7bdec632ca72ceb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many Articles/Clauses were there in the charter of Madina?', '{"A":"37","B":"47 (53)","C":"57","D":"67"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Constitution of Medina (میثاق مدینہ)Composed of approximately 47 clausesSigned: First Hijri/622 ADBetween Muslims, Jews, and other non-MuslimsClauses: 47 (23 governing relations between Muslims, and 24 governing relations between Muslims and non-Muslims, including Jews).نوٹ: میثاقِ مدینہ 47 یا 53 شقوں پر مبنی تھا۔ کچھ روایات میں 47 اور کچھ میں 53 شقوں کا ذکر ہے۔Last updated question by NS on 11 May 2026', 0, 0, 0, 1790964565194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_50591ced2a0722f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In which language Injeel (Bible) was revealed?', '{"A":"Hebrew","B":"Arabic","C":"Latin","D":"Greek"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Injeel was the holy book revealed by Allah to Hazrat Esa (AS).Injeel means good news. Injeel is also called Gospel.Gospel means truth. Injeel was revealed in Hebrew.', 0, 0, 0, 1790964565194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b22ebdf7febda1fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the Youngest daughter of Hazrat Muhammad ﷺ?', '{"A":"Hazrat bibi Fatima (رضہ)","B":"Hazrat bibi Zainab (رضہ)","C":"Hazrat bibi Umm Kulthum (رضہ)","D":"Hazrat bibi Ruqayyah (رضہ)","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Controversy. There is much controversy between Sunni and Shia regarding how many daughters Muhammad had. While all Sunnis accept that he had four daughters, most Shia accepts Fatimah as his only biological daughter and that 3 women were already living in the house of Khadijah before her marriage with Muhammad.', 0, 0, 0, 1790964565194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0f76c45c0680d7bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which of the following is a key method of self-purification in Islam?', '{"A":"Sawm","B":"Salah","C":"Hajj. None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Praying: One of the best acts of worship that help with self-purification. Allah says, “He who purifies himself, who remembers the name of his Lord and prays, shall indeed be successful." (TMQ, 87:14-15). The Prophet (SAWS) told us that purifying our souls through prayer is just like purifying our bodies with water.', 0, 0, 0, 1790964565194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_035e1d333be853b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the literal Meaning of Islam?', '{"A":"To obey","B":"To have safety","C":"To bow down the neck","D":"To seek safety","E":"All of these"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "Islam" is derived from the Arabic root "S-L-M", meaning peace, submission, and safety. It conveys meanings such as obedience, seeking safety, and submitting to Allah’s will.', 0, 0, 0, 1790964565250) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_157826d15d55775c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which city is called that birth place of Islam?', '{"A":"Medina","B":"Makkah","C":"Baghdad","D":"Iraq"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Makkah (Mecca) is considered the birthplace of Islam.Hazrat Muhammad SAW, the last prophet of Islam, was born in Makkah in 571 AD.Makkah is also the city where Hazrat Muhammad SAW received his first revelation from Allah (God) in 610 AD.', 0, 0, 0, 1790964565251) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fba681e94cacd7a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Shab-e-Miraj incident takes place on _____?', '{"A":"27 Safar","B":"27 Rajab","C":"27 Ramazan","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790964565251) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e69316122962b528', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the literal meaning of Jihad?', '{"A":"Struggle","B":"Fight","C":"Exemption","D":"Sacrifice"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The literal meaning of Jihad is "struggle" or "striving".Jihad becomes first in 2 AH.41 times the word Jihad appears in Quran.', 0, 0, 0, 1790964565251) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6f050339e80bbd43', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'First Muslim mohajreen delegation comprised of _______ male and ____ female for Habsha.', '{"A":"12, 2","B":"12, 8","C":"12, 4","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First migration to Habshah (Abyssinia) took place in 613 A.D.The relatives of Prophet Muhammad (PBUH) in the first migration to Abyssinia were Usman Ghani (R.A) and Ruqaiyah (R.A).There were 12 men and 4 women in the first migration to Abyssinia.', 0, 0, 0, 1790964565251) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_10f1b312280d3dbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which two books are called Sahihain?', '{"A":"Bukhari & Muslim","B":"Muta & Muslim","C":"Ibn Maja & Muslim","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sahih Muslim, together with Sahih al-Bukhari is termed as Sahihayn.', 0, 0, 0, 1790964565251) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6929f289dadf31ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Imam Abu Hanifa is also known as?', '{"A":"Aameer-Alil-e-Sunnah","B":"Imam-e-Azam","C":"Imam-ul-Arab","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Imam Abu Hanifa is also widely known as Al-Imam Al-Aẓam (The Great Imam) and Siraj Al-Aimma (The Lamp of the Imams).Numan bin Sabit is the real name of Born: 699 (80 Hijri); Kufa, Umayyad CaliphateImam Abu Hanifa Died: in 767 (150 Hijri); in Baghdad, Abbasid CalipImam Abu Hanifa Place of burial: Abu Hanifa Mosque, Baghdad, IraqSH2-9-2023', 0, 0, 0, 1790964565251) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b7f124a2a14cf1b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Meesaq-e-Madina was signed between Muslims and?', '{"A":"Hindus","B":"Sikhs","C":"Jews","D":"Christians"}', 'C', NULL, 0, 0, 0, 1790964565251) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_17cb519a56e85ae6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the meaning of Iman-e-Mujammal?', '{"A":"The belief in brief","B":"The belief in detail","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iman means faith, and Mujmal means brief.Iman-e-Mujammal refers to faith in the basic aspects of Islam in a concise form.It is a summary declaration of all essential Islamic beliefs.It includes general acceptance of Allah, His angels, books, prophets, etc.It is recited simply and believed with the heart.Iman-e-Mufassal means belief in detail.', 0, 0, 0, 1790964565316) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0410aa7b852dd69b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which is eighth month of Islamic Calendar?', '{"A":"Rabi-ul-Awwal","B":"Ramzan","C":"Shaban","D":"Jamadi-ul-Sani"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation List of Islamic MonthsMuḥarram, محرم الحرامṢafar, صفر المظفرRabi al Awwal, ربیع الاولRabi al Sani, ربیع الثانیJumada al Awwal, جمادی الاولJumada al Thani, جمادی الثانیRajab, رجب المرجبShaban, شعبان المعظمRamadan (fasting), رمضان المبارکShawwal, شوال المکرمDhu al Qadah, ذوالقعدۃ الحرامDhu al Hijjah, ذوالحجۃ الحرام', 0, 0, 0, 1790964565316) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dae9dabd0de7ae46', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Title of Ameer-ul-Momineen was firstly assumed by ______?', '{"A":"Hazrat Umar","B":"Hazrat Usman","C":"Hazrat Abu Bakar","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The title of "Ameer-ul-Momineen" (Commander of the Faithful) was first used by Hazrat Umar ibn al-Khattab (RA).It was introduced during his caliphate to denote his leadership over the Muslim community.', 0, 0, 0, 1790964565316) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f517d6c74f105bf2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Kiramin Katbeen means _____?', '{"A":"False accusation","B":"Illustrious writers","C":"Protectors","D":"BodyGuard"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kiramin Katbeen means Honorable writers.Kiraman Katbeen are In-charge of both left and right shouldersTwo angels are appointed on each person.both of them maintains the good deeds and the other one records evil deeds.These two angels are named as Kiraman katibeen (AS)RK4323', 0, 0, 0, 1790964565316) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b6cc72f6a4046613', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the representative of Quraish at Hudaybiyyah?', '{"A":"Sohail bin Umro","B":"Sohail bin Uthman","C":"Sohail bin Hisham","D":"Sohaol bin Abdul Rahman"}', 'A', NULL, 0, 0, 0, 1790964565316) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_53bdd67a4e683c36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which two personalities passed away in the Year of Sorrow?', '{"A":"Abdul Mutalib and Amina","B":"Hazrat Khadija and Abu Talib","C":"Abu Bakar and Ayesha","D":"Qasim and Abdullah"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Khadija was the wife of Holy prophet (P.B.U.H).Hazrat Abu Talib was the uncle of the Holy prophet (p.b.u.h).Year of sorrow means غم کا سال', 0, 0, 0, 1790964565316) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d49843c102ebe9fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many months declared sacred?', '{"A":"2 month","B":"3 month","C":"4 month","D":"6 month"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Four months declared sacred such as:RajabDhū al-Qa’idaDhu al-Ḥijjah Muḥarram', 0, 0, 0, 1790964565316) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4729a66d18fb8960', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Jabal-e-Noor is situated in ______?', '{"A":"Arafat","B":"Ghar-i-Hira","C":"Ghar-i-Saur","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jabal al-Nour, also known as the "Mountain of Light"It is located in the Hejaz region of Saudi Arabia, near Mecca. Jabal al-Nour is home to the Cave of HiraWhere the Prophet Muhammad received his first revelationIt is also known as Jabal al-Quran and Jabal al-Islam', 0, 0, 0, 1790964565316) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1452154777145316', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The number of famous Islamic months are?', '{"A":"Seven","B":"Six","C":"Four","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Four of the twelve Hijri months are considered sacred: 1. Muḥarram (1). 2. Rajab (7), 3. Dhū al-Qa''dah (11), 4. Dhu al-Ḥijjah (12)', 0, 0, 0, 1790964565409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7c287888d7f11b3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ashabus Sabt means what?', '{"A":"Hinuds","B":"Jews","C":"Christians","D":"Sikhs"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ashabus Sabt means "People of the Sabbath" and refers to the Jews who were commanded to observe Saturday as a holy day.They violated the Sabbath by fishing on that day, as mentioned in the Quran (Surah Al-A''raf, 7:163).', 0, 0, 0, 1790964565409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1e6feacf97a9c4f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ozza was the name of ________?', '{"A":"Name of a tree","B":"Honour and respect","C":"A specfic goddess of Quraish","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-ʻUzzā was one of the three chief goddesses of Arabian religion in pre-Islamic times and was worshiped by the pre-Islamic Arabs along with al-Lāt and Manāt.', 0, 0, 0, 1790964565409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_81a904f274935446', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Mauwazatain means _______?', '{"A":"A book of jafferi Fiqh","B":"Two specific surah of Quran","C":"A collection of Ahadith","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Mu’awwidhatan sometimes translated as “Verses of Refuge”.Al-Mu’awwidhatan is an Arabic term referring to the last two suras (chapters) of the Qur’an, viz. al-Falaq (ch. 113), and An-Nās (ch. 114).', 0, 0, 0, 1790964565409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_03e2ca7915625279', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'When for the first time Nimaz-e-Kisoof was offered?', '{"A":"4 A.H","B":"5 A.H","C":"7 A.H","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Namaz-e-Kasoof (نماز کسوف) is offered at the time of solar eclipse.', 0, 0, 0, 1790964565409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_80d6f984eb6882b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the rate of Ushr on products of irrigated land?', '{"A":"10%","B":"25%","C":"30%","D":"40%"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ushr is typically 10% of the net yield of agricultural produce or other natural resources. (like rain, springs, or rivers) 5% for artificially irrigated land (tube wells, canals).5 Awsuq (roughly 612–750 kg) minimum yield required.Last updated 13 August 2026 by NA', 0, 0, 0, 1790964565409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_367d6589e224db65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The dead body of Muslim male is wrapped in three sheets, female is coffined in how many sheets?', '{"A":"Five Sheets","B":"Four Sheets","C":"Three Sheets","D":"Seven Sheets"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "The dead body of Muslim male is wrapped in three sheets, The dead body of Muslim women is wrapped in five sheets."', 0, 0, 0, 1790964565409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2425555add31f392', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Iblees was _____?', '{"A":"Angels (Malaika)","B":"Jinn","C":"Both A & B","D":"None of them"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iblees was a Jinn.As mentioned in the Quran (Surah Al-Kahf, 18:50).He disobeyed Allah''s command to bow to Adam due to arrogance.', 0, 0, 0, 1790964565409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0aafddcc536d3d0b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Where Hazrat Abdullah (RA) died?', '{"A":"Makkah","B":"Madina","C":"Abwa","D":"Quba"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abdullah (RA) died in Abwa**Full name : Abdullah ibn Abd al-Muttalib عَبْد ٱللَّٰه ٱبْن عَبْد ٱلْمُطَّلِبwhen Muhammad was eight years old, the very old Abd al-Muttalib became very sick and died at age 81-82 in 578-579 CEThe Resting place of Hazrat Abdullah (RA) is Jannat al-Baqi, Medina', 0, 0, 0, 1790964565472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_02749ada64d1c546', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who delivered the speech on behalf of the Muslim migrants in the court of Negus, the king of Abyssinia?', '{"A":"Hazrat Umar (RA)","B":"Hazrat Ja’far bin Abi Talib (RA)","C":"Hazrat Abu Bakr (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Ja’far bin Abi Talib (RA) eloquently defended Islam and the Muslims before Negus. His speech highlighted the oppression they faced and the teachings of Islam.', 0, 0, 0, 1790964565472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2f6c51a184229408', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the meaning of Tehlil?', '{"A":"The recitation of Tauheed","B":"The recitation of Quran Majeed","C":"The recitation of first Kalima","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tehlil means Recitation of first Kalima.', 0, 0, 0, 1790964565472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a52ccd545a3a2cbd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Falqaram (Nisab) for Camel is ______ Camels?', '{"A":"4 Camels","B":"5 Camels","C":"8 Camels","D":"10 Camels"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The amount of zakat paid on capital assets (e.g. money) and stock-in-trade and jewelry is customarily 2.5% How many camels render are to par Zakat? 5How many goats render are to pay zakat? 40How many sheep render are to pay zakat? 40Zakat is payable on gold of_________7.5 tolasZakat is payable on silver of_______52.5 tolas', 0, 0, 0, 1790964565472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9b6a4d5a1ebd375e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the backbone of the economic system of Islam?', '{"A":"Zakat","B":"Fast","C":"Hajj","D":"Namaz"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If you have 7.5 tola/3 ounces/87.48 grams of gold or52.5 tota/21 ounces/612.36 grams of silver orits cash equivalent for a full lunar year,then you are considered Sahib-e-Nisab and should pay Zakat 2.5%*********VU FIA UDC CONSTABLE PAST PAPER 31-12-2021', 0, 0, 0, 1790964565472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a3f8a414fd0f6d56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which is the oldest divine religion on the earth?', '{"A":"Christianity","B":"Taoism","C":"Hinduism","D":"Judaism"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation یہودیت کو روایتی طور پر دنیا کے قدیم ترین توحید پرست مذاہب میں سے ایک سمجھا جاتا ہے، حالانکہ 8ویں صدی قبل مسیح میں بنی اسرائیل مشرک تھے، ان کی عبادت الٰہی، بعل، اشیرا، اور آسٹارٹ سمیت دیوتاؤں کے ساتھ کی جاتی تھی۔ یہوواہ اصل میں اسرائیل کی بادشاہی اور یہوداہ کی بادشاہی کا قومی خدا تھا۔', 0, 0, 0, 1790964565472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e9d786fc23b90349', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which year is called the Year of Sorrow?', '{"A":"9th Nabvi","B":"10th Nabvi","C":"11th Nabvi","D":"12th Nabvi"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Year of sorrow means غم کا سالThe Islamic year known as Aam al-Ḥuzn is the 10th (619 CE).It is also known as the Year of Sorrow or Year of SadnessDuring this year, the Prophet Muhammad''s SAW wife, Khadija, and his uncle and protector, Abu Talib, passed away.', 0, 0, 0, 1790964565472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fd76e6273e13de48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The miracle of a pregnant female camel was sent to the nation of _____?', '{"A":"Aad","B":"Israel","C":"Samood","D":"Loot","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The She-Camel was a miraculous female camel sent by God to the people of Samood in Al-Hijr, after they demanded a miracle from the Hazrat Saleh (AS).Nation of Samood means قوم ثمود', 0, 0, 0, 1790964565472) ON CONFLICT(id) DO NOTHING;
