INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e238f08b1ce506ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In which year were the vowels inserted in the Qur’an?', '{"A":"41 Hijri","B":"42 Hijri","C":"43 Hijri","D":"40 Hijri","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vowels was introduced by hijaz bin Marwan. Vowels was Inserted in Quran by Hijaz bin Yousaf.', 0, 0, 0, 1790964565528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_47fb645af972d188', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What does Taraweeh means?', '{"A":"To Rest","B":"To Stand","C":"To Pray","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Taraweeh means To RestTaraweeh prayer is performed in congregation during Ramadan after Isha and before WitrTarawih prayers are special Muslim prayers involving reading long portions of the QuranTarawih is prayed in sets of two rakyats eachND2023-2-12', 0, 0, 0, 1790964565528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_05a876153d6f5442', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Interest was prohibited in ______ A.H.', '{"A":"8th","B":"6th","C":"4th","D":"2nd"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Interest is prohibited in Islam as it appears explicitly in the Holy Qur''an and the Sunnah of the Prophet.Interest was prohibited in 8th A.H.****RY30012023', 0, 0, 0, 1790964565528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_df78aa77021b63f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'When was the first mosque of Islam built?', '{"A":"1 AH","B":"4 AH","C":"2 AH","D":"3 AH","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Quba Mosque is a mosque located on the outskirts of MedinaThe first stones of Quba Mosque were positioned by Muhammad he arrived on his emigration from the city of Mecca to MedinaMuhammad spent 14 days in this mosque praying qaṣrthis mosque is said to be where the first Friday prayer was held, led by MuhammadVery confusing questionMasjid-ul-Haram is the first masjid on the surface of the earth.whileMasjid-e-Quba is the first masjid in history of Islam.***Masjid quba is built after Hazrat Muhammad saw arrived in Madina.****', 0, 0, 0, 1790964565528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_403344434a565fe8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ada Bin Hatam Tai embraced Islam in _____?', '{"A":"4 Hijri","B":"5 Hijri","C":"9 Hijri","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adi ibn Hatim al-Tai was a leader of the Arab tribe of Tayy Adi ibn Hatim al-Tai was one of the companions of Muhammad. Adi ibn Hatim al-Tai embarrassed Islam in 9 HijriAda Bin Hatam Tai was the son of Hatim al-Tai, ND18-5-2023', 0, 0, 0, 1790964565528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_81734541969a2010', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the important event in the month of 13th Nabvi?', '{"A":"Miraj","B":"Hijrat e Habsha","C":"Hijrat e Madina","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophet Muhammad’s migration from Mecca to Yathrib (Medina)on September 24, 622.With Hazrat Abu Bakar R.A Hijra from Makkah to Madina started in the 13th Nabvi year.Hijri year starts from this event.', 0, 0, 0, 1790964565590) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_af8049ae4347db58', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The color of the first Islamic flag was ______?', '{"A":"White","B":"Black","C":"Green","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The color of the Islamic flag is whitethe Prophet Muhammad used the white flag to represent both the leader of the Muslim army and the first Muslim state.Additional informationThe Umayyad dynasty (661–750) used white as their symbolic color as a reminder of Muhammad''s first battle at Badr The color of the Flag of the Islamic Army in Ghazwa Badr was Green, and Muslims won.ND-21-5-2023ND19112023', 0, 0, 0, 1790964565590) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0c229e0b90a2524d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which of the following is called Year of Deputations?', '{"A":"10 Hijri","B":"9 Hijri","C":"8 Hijri","D":"11 Hijri"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The year 9 Hijri (630 CE) is known as the "Year of Deputations" (عام الوفود, ''Am al-Wufud'').Because numerous delegations came to meet the Prophet Muhammad SAW and declare their allegiance to Islam.', 0, 0, 0, 1790964565590) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_18c3064050dd9bfd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Banu Quraiza, Banu Nadir, and Banu Qainuqa were three tribes of the ______?', '{"A":"Qurish","B":"Christians","C":"Muslims","D":"Jews","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation more than twenty Jewish clans indicate of which three were prominent-the Banu Nadir, the Banu Qaynuqa, and the Banu QurayzaThe Banu Nadir, led by Kab ibn al-Ashraf and Huyayy ibn Akhtabthe Banu Qurayza fought with the Awsthe Banu Qaynuqa allied itself with the tribe of Khazraj.Banu Kainuka, Banu Kaynuka, Banu Qainuqa, Banu Qaynuqa was one of the three main Jewish tribes living in the 7th century of Medina, they were expelled during the Invasion of Banu Qaynuqa after breaking the treaty known as the Constitution of MedinaND5-2-2023', 0, 0, 0, 1790964565590) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2d4e4547f761b57b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ghar-e- Sor is mentioned in ________?', '{"A":"Surah Al Inaam","B":"Surah Al Baqra","C":"Surah Al Tauba","D":"Surah Alaq"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quran''s Surah Al Tauba fortieth verse was revealed. Also known as Ghar Thawr, the Cave of Thawr has religious significance.This cave is where the Holy Prophet and his companion Abu Bakr al-Siddiq found shelter when fleeing from Quraish search parties.Both resided in this cave for three days.This event is revered among Muslims as miracles of God for Muhammad. غار ثور کہاں ہے: مکہآپ صَلَّی اللہُ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کتنے دن غار ثور میں قیام کیا: تین دنغار یار کس صحابی کو کہا جاتا ہے: حضرت ابو بکر رَضِیَ اللہُ تَعَالٰی عَنْہُ', 0, 0, 0, 1790964565590) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_644ad2922e3dbd53', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Gap between first and second Wahi was ______ months?', '{"A":"2 Years 6 months","B":"2 Years 3 months","C":"2 Years 1 month","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Mubarakpuri, the exact date of this event was Monday, the 21st of Ramadan just before sunrise, i.e. August 10, 610 C.E. – when Muhammad was 40 lunar years, 6 months and 12 days of age, i.e. 39 solar years, 3 months and 22 days.یادرکھیےکچھ جگہ پر جواب چھ ماہ بھی آتا ہے۔ تو پیپر میں اگر چھ ماہ یا دو سال چھ ماہ کا آپشن ہو تو دونوں ہی ٹھیک ہیں', 0, 0, 0, 1790964565590) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9479946116f89cd5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Sixth Wife of Hazrat Muhammad ﷺ was _______?', '{"A":"Hazrat Zainab binte Khazeema(RA)","B":"Hazrat Sauda (RA)","C":"Hazrat Salmah (RA)","D":"Hazrat Hafsa (RA)","E":"None of these"}', 'C', NULL, 0, 0, 0, 1790964565590) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_110cc299db5edf37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Muhammad (PBUH) passed away in which Hijri year?', '{"A":"10 AH","B":"11 AH","C":"9 AH","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Prophet Muhammad died on Monday at the age of 63, 12 Rabi'' al-Awwal 11 AH, which corresponds to June 8, 632 CE.Hazrat Muhammad (PBUH) Born on c. 570 CE (53 BH) Mecca, Hejaz, Arabia.', 0, 0, 0, 1790964565590) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fd9265125477e01f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Cave of Ashab-e-Kahaf located in which country?', '{"A":"Jordan","B":"Iran","C":"Turkey","D":"Jerusalem"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "kahf" means "the cave in the mountain".the sura is named "kahf" because it speaks about the story of the Companions of the CaveAshab e Kahf slept for 309 yearsThe number of Ashab-e-Kahf was 7The story of Ashab al-Kahf is narrated in the eighteenth chapter of the Quran, called “al-Kahf” In verses 9-26سورہ کہف میں اصحاب کہف کے ساتھ کتا جانور کا ذکر آیا ہےQitmeer is the name of the dog in Surah Kahf.ND10-3-2023', 0, 0, 0, 1790964565666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_02b707ec3eae6ba9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which Roman governor ordered the execution of Hazrat Essa (AS)?', '{"A":"Theodore","B":"Politus","C":"Herodus","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pontius Pilate: Roman governor of Judaea (26–36 CE) under Emperor Tiberius; ordered Jesus'' crucifixion.Hazrat Essa (AS): Known in Islam as Isa Ibn Maryam, born c. 4 BCE in Judea, Roman Empire.', 0, 0, 0, 1790964565666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5dd2bfb986e70a56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Cave of Thawr is a cave in a mountain _____?', '{"A":"Inside Makkah","B":"Inside Uhad","C":"At the outskirts of Makkah","D":"Near Madina"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Cave of Thawr is located in a mountain on the outskirts of Makkah.It is where the Holy Prophet (PBUH) and Abu Bakr (RA) sought refuge during their migration to Medina (622 C.E).This event is mentioned in Surah At-Tawbah (9:40).', 0, 0, 0, 1790964565667) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_abf75c74c03df5a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Qazaf is ______?', '{"A":"Clause in Islam","B":"Constitutional law","C":"Shariat Law","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qazaf is Clause in IslamQazf in Islam is imposed on: False accusations of ZinaHad –e- Qazaf (false Accusation) is: 80 LashesLashes mean: کوڑےFirst Muslim who faced the first ever ordinance of Qazf: Hasan ibn Sabit, Mustah ibn Asasa, Hamnah ibn JahshND18-2-2023', 0, 0, 0, 1790964565667) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_23a5372dd4d0a943', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Shawal is the __________ month of Islamic calendar?', '{"A":"9th","B":"10th","C":"11th","D":"12th"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation List of Islamic months.1) Muharram2) Safar3) Rabi’ al-awwal (Rabi’ I)4) Rabi’ al-thani (Rabi’ II)5) Jumada al-awwal (Jumada I)6) Jumada al-thani (Jumada II)7) Rajab8) Sha''ban9) Ramadan10) Shawwal11) Dhu al-Qi''dah 12) Dhu al-Hijjah', 0, 0, 0, 1790964565667) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6f3745c9ab80b39e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many months prior to the birth of Hazrat Muhammad (SAW), Hazrat Abdullah lbn-e-Abdul Matalib died?', '{"A":"Two","B":"Four","C":"Six","D":"One"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation حضرت محمد صلی اللہ علیہ وسلم کی ولادت سے چھ ماہ قبل حضرت عبداللہ بن عبدالمطلب کی وفات ہوئی۔', 0, 0, 0, 1790964565667) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_db623a6228db12cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the meaning of Al-Wahid?', '{"A":"The Noble","B":"The Unique","C":"The Alive","D":"The Powerful"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wahid, meaning "peerless", "unique". Al-Wahid is one of the 99 names of Allah.', 0, 0, 0, 1790964565667) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1612b5094f2958d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Muhammad PBUH Declared _______ key to Paradise.', '{"A":"Salat","B":"Zakat","C":"Salat","D":"Hajj"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jabir ibn Abdullah reported: The Messenger of Allah, peace and blessings be upon him, said, “The key to Paradise is prayer, and the key to prayer is ablution.”', 0, 0, 0, 1790964565667) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7ba1c1ac35209868', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Kitab-ul-Assar is compiled by _______?', '{"A":"Imam Malik (رضہ)","B":"Imam Shafi (رضہ)","C":"Imam Abu Hanifah (رضہ)","D":"Imam Humbal (رضہ)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Kitaab-ul-Aathaar" is an early Hadith book compiled by Imam Muhammad al-Shaybani (132 AH – 189 AH).It contains nearly 1,000 hadiths according to Maktaba Shamila.It is sometimes attributed to Imam Abu Hanifa.', 0, 0, 0, 1790964565754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4eac5c12f28bdbea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazart Khadija (R.A) died at _____ years age.', '{"A":"64 years","B":"63 years","C":"65 years","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790964565754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a58c80610e874ebc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the real name of Hazrat Abu Huraira (RA)?', '{"A":"Abdul Rehman Ibne Adi","B":"Abdul Rehman Ibne Talib","C":"Abdul Rehman Ibne Sakhr Ad-Dausi","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abd al-Rahman ibn Sakhr Ad-Dausi Al-Zahrani also known as Abu Hurayrahwas one of the companions of the Islamic prophet Muhammad and the most prolific narrator of hadith.Hazrat Abu Huraira (رضہ) was born in Baha, Yemen.Meaning of Huraira "little cat", "kitten"The number of hadiths narrated by Hazrat Abu Huraira R.A: 5374ND5-07-2023', 0, 0, 0, 1790964565754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_92342baddd19622a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who wrote Ar-Resala?', '{"A":"Imam Abu Hanifa","B":"Imam Malik","C":"Imam Shafi","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Risāla by ash-Shafi''i "book of the communication on the foundations of comprehension (i.e. Islamic jurisprudence) is a seminal text on the principles of Islamic jurisprudence', 0, 0, 0, 1790964565754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e5aa49ec9008a464', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The real name of Hazrat Abu Talib (R.A)was ______?', '{"A":"Haris bin Hashim","B":"Umro bin Hasham","C":"Zain bin Hasham","D":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The real name of Hazrat Abu Talib (R.A) was Abdul Manaf ibn Abdul Mutallib. He was the paternal uncle of the Prophet Muhammad (PBUH)', 0, 0, 0, 1790964565754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0a6ef7f23ae5f0f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ziarat-e-Tawaf is _____?', '{"A":"Faraz","B":"Wajib","C":"Nafli","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tawaf al-Ziyarah is a mandatory ritual (farz) during Hajj.It can be performed any time from 10th Zil Hijjah until the sunset of 12th Zil Hijjah, with 11th Zil Hijjah being most convenient.The procedure is similar to the Tawaf of Umrah and requires wudu.', 0, 0, 0, 1790964565754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f047bd1a3cda212f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the meaning of Shahadat?', '{"A":"Penitence","B":"Glorification","C":"Testimony","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shahadat name meaning is "For The Sake Of Rightfulness ".', 0, 0, 0, 1790964565754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_108bd259e195dffc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'When Imam Ghazali died?', '{"A":"503 Hijri","B":"500 Hijri","C":"505 Hijri","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Imam Ghazali was born in 1058.He died on December 19, 1111 CE.Ghazali was a prominent Islamic scholar, theologian, and philosopher known for his influential works in Islamic thought.', 0, 0, 0, 1790964565754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_82ec544631c7f2c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Last decade of Ramzan is known as?', '{"A":"Freedom from hell","B":"Kindness","C":"Forgiveness","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are the Three Ashras of Ramadan"First Ashra of Ramadan is "Days of mercy" (Rehmat),2nd is "days of forgiveness" (Maghfirayat),3rd is "days of refuge from hell fire"(Jahanum ke aag sa nijahat) "', 0, 0, 0, 1790964565846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1d5943fce6b7a101', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who constructed mosque Zarrar?', '{"A":"Muslims","B":"Kufar","C":"Disbelievers","D":"Hypocrites"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid al-Ḍirār was a mosque built by hypocrites in Medina It was later destroyed by the order of Prophet Muhammad (SAAW). This mosque was built by hypocrites in order to cause disunity among the believers, promote hypocrisy and it was a base for disbelievers as well.', 0, 0, 0, 1790964565846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8b9407bb956ce8f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Before Islam Friday was called _____?', '{"A":"یومالفرقان","B":"یوم العروبہ","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In pre-Islamic Arabia, Friday was known as "Yom al-''Arubah" or "Yawm al-''Arubah", which means "Day of Gathering" or "Day of Assembly".In Islamic tradition, Friday is considered a sacred day of worship. It is known as "Yom al-Jumu''ah" (يوم الجمعة), which means "Day of Assembly" or "Friday".', 0, 0, 0, 1790964565846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b67334555a5111d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which animal was residing with the As''hab e Kahaf?', '{"A":"Camel","B":"Donkey","C":"Dog","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "kahf" means "the cave in the mountain"the sura is named "kahf" because it speaks about the story of the Companions of the CaveQitmeer is the name of the dog in Surah Kahf.whileThe cave of Ashab e Kahaf is located in Jordan.Ashab e Kahf slept for 309 yearsThe number of Ashab-e-Kahf was 7The story of Ashab al-Kahf is narrated in the eighteenth chapter of the Quran, called “al-Kahf” In verses 9-26', 0, 0, 0, 1790964565846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_92bacdb606056802', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Al-Fozul Kabir is written by ____?', '{"A":"Qutubuddin Ahmad Siddiqui","B":"Shah Wali Ullah","C":"Qutubuddin Ahmad Faruqi","D":"Qutubuddin Fareed","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ø Real name of Shah Waliullah: Qutubuddin Ahmad Syed. Ø Shah Waliullah first time in history translated the Holy Quran in Persian Language Ø Shah Wali Ullah was born in the reign of Aurangzeb, Ø Shah Waliullah Dehlawi Born in 21 February 1703 Phulat, Mughal Empire Ø Shah Waliullah Dehlawi Died in 20 August 1762 (aged 59) Dehli, Mughal Empire', 0, 0, 0, 1790964565846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bc8f0470bc798135', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'When Hazrat Ume Kalsoom RA died?', '{"A":"628","B":"630","C":"631","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Born Hazrat Ume Kalsoom RA bint Muhammad 603 CE Mecca, Hejaz, ArabiaDied: November, 630 CE.', 0, 0, 0, 1790964565846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ccfcce7413dde589', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Muslim thinker''s category economy as ______?', '{"A":"Islamic economy","B":"Political economy","C":"Household economy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muslim thinkers categorize the economy as "Islamic economy," which is based on Islamic principles and laws.This framework emphasizes ethical and moral considerations in economic activities, including the prohibition of interest (riba) and promoting social justice.', 0, 0, 0, 1790964565846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_07cf80549a0e3f17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the meaning of Etikaf?', '{"A":"Purification","B":"Taharat","C":"Seclusion","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Seclusion تنہائیDuring the last 10 days of Ramadan (Etikaf), many Muslims spend their days and nights at the mosque in order to ensure that they are there for whichever night Laylat al-Qadr occurs.', 0, 0, 0, 1790964565846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0a21d8db1bdd8b65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Mustadrak Hakim written was by _____?', '{"A":"Imam Malik","B":"Hakim al-Nishapuri","C":"Imam Hambal","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Mustadrak ''ala al-Sahihayn is a five volume hadith collection written by Hakim al-Nishapuri (Nishapur is located in Iran).', 0, 0, 0, 1790964565939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_72d380269bdbd88d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Writer of Al Kafi Muhammad bin Yaqub Al Kuliyani died in _____?', '{"A":"235 Hijri","B":"240 Hijri","C":"329 Hijri","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He travelled to Baghdad for this reason and lived there for twenty years, engaged in teaching and pursuing academic work, until he died in 329 AH/941 CE. He is considered the foremost Shia compiler of hadith and was the author of Kitab al-Kafi.', 0, 0, 0, 1790964565939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e2807af392628ce7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who interpreted neo-Sufi concept of Islam?', '{"A":"Sayed Ahmad Barelavi","B":"Sir Sayed Ahmad","C":"Shah Wali-Ullah","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shah Wali-Ullah (1703-1762) was a prominent Islamic scholar.He was a reformer who interpreted the neo-Sufi concept of Islam.He was a member of the Naqshbandi Sufi order.Shah Wali-Ullah emphasized the importance of inner spiritual growth, purification of the heart, and the pursuit of knowledge.', 0, 0, 0, 1790964565939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_86414f5fadf1e2e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'He had knowledge of the interpretation of dreams?', '{"A":"Hazrat Issa (AS)","B":"Hazrat Yousuf (AS)","C":"Hazrat Musa (AS)","D":"Hazrat Yoonus (AS)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Yousuf (AS) had knowledge of the interpretation of dreams.Known as "The Truthful One" (/siddiq/) in the Quran for his accurate dream interpretations.The other is Abu Bakr, who knew dreams.', 0, 0, 0, 1790964565939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ba129076c84d64a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the 1st civil war in Islam?', '{"A":"Jamal","B":"Siffin","C":"Karbala","D":"Khandaq"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of the Camel, also known as the Battle of Jamel or the Battle of Basra, Battle of Jamel took place outside of Basra, Iraq, in 36 AH/656 CE. The battle was fought between the army of the fourth caliph, Hazrat Ali رضہ, on one side, and the other army led by Hazrat Aisha رضہ,', 0, 0, 0, 1790964565939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8f804d0959e5986c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Usher and Khums are _____?', '{"A":"Two prominent warriors of Islam","B":"Two months of Islamic Calendar","C":"Two kinds of Tax in Islam","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usher and Khums are Two kinds of Tax in Islam,In Islam, KHUMS خمس refers to the required religious obligation of any Muslims to pay one-fifth of their acquired wealth from certain sources toward specified causes. Khums is different and separate from other Islamic taxes such as zakat and jizya.', 0, 0, 0, 1790964565939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b30325cab9a27c8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Backbiting is like eating flesh of one''s dead _______?', '{"A":"Sister","B":"Mother","C":"Brother","D":"Uncle"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Hurayrah, has quoted Prophet Muhammadﷺ, as saying: "Do you know what backbiting is?" They said, "Allah and His Messenger know best." He then said, "It is to say something about your brother that he would dislike." Someone asked him, "But what if what I say is true?" Allah’s Messenger said, "If what you say about him is true, you are backbiting him, but if it is not true then you have slandered him."', 0, 0, 0, 1790964565939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1d5a8298b8796b12', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Ayub (AS) was famous for his _____?', '{"A":"Patience","B":"Beauty","C":"Tolerence","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790964565939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2fafde1a4ed8c81c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many essential beliefs are there in Iman-e-Mafassal?', '{"A":"4","B":"5","C":"6","D":"7"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Seven essential beliefs are present in Iman-e-Mafassal1. Faith in God.2. Faith in holy angels.3. Faith in all holy Books.4. Faith in all holy Prophets.5. Faith in the Day of Judgement.6. Faith in everything good or bad is decided by God (Taqdir).7. Faith in life after death..ND28-4-2023', 0, 0, 0, 1790964566033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9767e08f25e66c41', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Name the place where Muslims took refuge 7th year of Prophethood?', '{"A":"Arsfat","B":"Shib-e-abi Talib","C":"Ghar-e-hira","D":"Ghar-e-soar","E":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shi''b Abi Talib is a valley between the Mount Abu Qubays and the Mount Khandama in Mecca.', 0, 0, 0, 1790964566033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1d3f99ced8f75520', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Amina mother of Muhammad (PBUH) was buried in _____?', '{"A":"Makkah","B":"Madina","C":"Abwa","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amina bint Wahb ibn Abd Manaf was the mother of the Islamic Prophet Muhammad SAW.She belonged to the Banu Zuhra tribe.', 0, 0, 0, 1790964566033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3051efd4a39a4916', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many clauses did the treaty of Hudaybiyyah contain?', '{"A":"7","B":"5","C":"3","D":"none"}', 'A', NULL, 0, 0, 0, 1790964566033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_22823373e74cbbb8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Najashi became Muslim at the hand of ______?', '{"A":"Saad bin Ubada","B":"Hazrat Jafar","C":"Usman","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Najashi is also known as Ashama ibn Abjar.He was the King of Abyssinia (modern-day Ethiopia) who became a Muslim at the hands of Hazrat Jafar ibn Abi Talib, a cousin of the Prophet Muhammad (SAW).Hazrat Jafar ibn Abi Talib recited the Quran to Najashi, who was impressed by its beauty and truth, and subsequently accepted Islam.', 0, 0, 0, 1790964566033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5e86ef149decb501', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the pupil of Hazrat Abu Hurairah (RA)?', '{"A":"Hazrat Ibn Abbas","B":"Hazrat Hammad bin Zayd","C":"Hazrat Hmmam ibn Munabih","D":"Hazrat Anas bin Malik"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Hurairah (RA) was a companion of the Prophet Muhammad (SAW) and a renowned scholar.Among his pupils was Hazrat Hammam ibn Munabbih, who was a well-known scholar and narrator of hadith (Prophetic traditions).', 0, 0, 0, 1790964566033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7ab44075c8932d7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many Salats were made obligatory during the Mairaj?', '{"A":"4","B":"6","C":"5","D":"3"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Five prayers were declared compulsory in the 10th NabviNamaz commanded in Quran 700 times.Salat was made compulsory at the event of 27 Rajab ( Miraj )****Salat Juma became Farz in Madina.Hajj was made compulsory in the 09th Hijri.', 0, 0, 0, 1790964566033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ebca69fa16cc4398', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Al-Azhar Mosque was completed in which year?', '{"A":"920 AD","B":"972 AD","C":"980 AD","D":"985 AD"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Azhar Mosque is located in Cairo, Egypt.It was completed in 972 AD during the Fatimid dynasty.It is one of the oldest and most important mosques in the Islamic world.It is considered a center of Islamic learning and culture.', 0, 0, 0, 1790964566033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_addb5ea55959c7df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Name the first authority for the compilation of Ahadis?', '{"A":"Imam Ahmad","B":"Imam Bukhari","C":"Imam Maalik","D":"Imam Abu Hanifa"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Muwatta is the first compilation of Ahadis written by Imam Malik.Imam Malik was Born 711 AD, Medina, Saudi Arabia. Died: 795 AD, Medina, Saudi Arabia.', 0, 0, 0, 1790964566126) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5a272c386ed2f112', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which river is often mentioned in the Bible?', '{"A":"Colorado","B":"Ganges","C":"Jordan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Three rivers in the Bible are mentioned most often:the Euphrates,the Nile, the Jordan', 0, 0, 0, 1790964566126) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_887cec97789e7afa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hurrairah means?', '{"A":"Goat","B":"Camal","C":"Cat","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hurrairah (هُرَيْرَة) is an Arabic word that means "cat".It is also the name of a famous companion of the Islamic Prophet Muhammad, Abu Hurairah (Abu Hurairah R.A).It was known for his love of cats.', 0, 0, 0, 1790964566126) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_945af67be31953c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Bait-ul-Laham is the birth place of ________, situated in Jerusalem.', '{"A":"Hazrat Ibrahim","B":"Hazrat Shoaib","C":"Hazrat Musa","D":"Hazrat Essa","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bethlehem is a Palestinian town south of Jerusalembiblical birthplace of JesusIsa is known as Jesus in Christianity.Hazrat Isa (As) was born miraculously to the most admired woman in Islam, Maryam (Mary), who was a virgin.The Injeel book was revealed on Hazrat Esa AsHazrat Isa (As) was Born BethlehemHazrat Isa (As) is known RohullahND18-2-2023', 0, 0, 0, 1790964566126) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5759ca0e6eb3a0c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Tasbeeh of Subhana Rabi-al-Azeem is recited in?', '{"A":"Sajda","B":"Rakuh","C":"Qaada","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Tasbeeh of Subhana Rabi-al-Azeem is recited in Rukku.While the Tasbeeh of Subhana Rabi-al-Alaa is recited in Sajda.', 0, 0, 0, 1790964566126) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8388e6acd5a149fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the Second Wife of Hazrat Muhammad ﷺ?', '{"A":"Hazrat Khadeja (رضہ)","B":"Hazrat Sauda (رضہ)","C":"Hazrat Ayesha (رضہ)","D":"Hazrat Hafsa (رضہ)"}', 'B', NULL, 0, 0, 0, 1790964566126) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bb8d9118c10162ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which sin will not be forgiven by Allah?', '{"A":"Jealousy","B":"Shirk","C":"Telling lies","D":"Hypocrisy","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation شرک تمام گناہوں میں سب سے گھناؤنا اور سب سے کبیرہ گناہ ہے', 0, 0, 0, 1790964566126) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5269a95ed13ae369', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Jizya means _____?', '{"A":"Lands Cultivated by Non Muslims","B":"Poll tax on non Muslims","C":"Religious Tax","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jizya — a poll tax on non-Muslims in Muslim states.India — first imposed by Qutb-ud-din Aibak.Akbar — abolished it in the 16th century.Aurangzeb — reintroduced it in the 17th century.Additional information:Kharaj — a land tax on non-Muslim cultivators and landlords.Last updated NA on 10-09-2026', 0, 0, 0, 1790964566126) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a470703867d6ac8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Adam is a word of which language?', '{"A":"Hindi","B":"Arabic","C":"Hebrew","D":"Persian","E":"Urdu"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The height of Hazrat Adam (AS) was 90 feet.Adam is a word of Herbew language.Hebrew is official language in Israel.He was the first Muslim, as the Quran states that all the Prophets preached the same faith of Islam.Known for being the first human being.His spouse was Hawwā (حواء).Hazrat Adam (AS) was 130 years old when Shees (AS) was born.He spoke the language in the Garden of Eden.His total age was 930 years.Hazrat Adam (AS) met with the Holy Prophet ﷺ on the 1st heaven.He had 3 sons.His grave is located in Sri Lanka.', 0, 0, 0, 1790964566216) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6db936b056b295bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Abu-al-Hikam is the title of?', '{"A":"Abu Bakar","B":"Abu Jahal","C":"Abu Lahab","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Jahal, commonly known as Abu Hakam (“Father of Wisdom”) among the Quraysh, was considered a wise man.He was fatally wounded in the Battle of Badr by Mu''adh ibn ''Afrā'' and Mu''ādh ibn ''Amr.He was finally killed by Abdullah ibn Masud.He was born in 570 A.D.Abu Jahal died by beheading at the Battle of Badr.He was one of the Meccan polytheist pagan leaders from the Quraysh.', 0, 0, 0, 1790964566216) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_60a9ee59a72c5d72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Torat (Torah) means ________?', '{"A":"Peace","B":"Sign","C":"Law","D":"Good news"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Torah" means "Law" in Hebrew.The Torah has a range of meanings.It refers to the first five books of the Hebrew Bible.It is also known as the Five Books of Moses or Chameesha Choomshey Torah in Hebrew.It encompasses the laws and teachings given to the Israelites.The Torah contains 187 chapters and 5,852 verses.', 0, 0, 0, 1790964566216) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_750088f18976d3c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many disciples of Hazrat Essa (AS) assisted him in preaching?', '{"A":"18","B":"12","C":"6","D":"24"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Twelve companions assisted Hazrat Isa (AS).He was born in Bethlehem.He is known as Rohullah.The Injeel was revealed to him.', 0, 0, 0, 1790964566216) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a9b4c324b267c301', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first writer of “Wahi” in Quraish?', '{"A":"Harat Abdul Rahman bin Auf (RA)","B":"Hazrat Zaid bin Sabit (RA)","C":"Hazrat Abdulla bin Zubair (RA)","D":"Hazrat Ibn Masuod (RA)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Zaid bin Sabit (RA) was the first to record "Wahi" among the Quraish.Hazrat Abu Bakar (R.A) appointed Zaid bin Sabit to compile the Holy Quran at the request of Hazrat Umar (R.A).Sharjeel-ibn-Hasana Kandi was the first to transcribe revelations in Makkah.The last revelation was written by Abi Ibn Kaaf.Prophet Idrees (عليه السلام) was the first to write with a pen.', 0, 0, 0, 1790964566216) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3b440e579d27322a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Amir Muawiya transferred his capital form Kufa to _____?', '{"A":"Madina","B":"Makkah","C":"Damascus","D":"Baghdad","E":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amir Muawiya transferred his capital from Kufa to DamascusMu''awiya I was the founder and first caliph of the Umayyad Caliphate serving from 661 until his death. He became caliph less than thirty years after the death of the Islamic prophet MuhammadMuawiyah was appointed as the Governor of Syria after his brother Yazid ibn Abu Sufyan diedAmeer Muawiyah (R.A) established Postal SystemHazrat Abu Sufyan, Hazrat Ameer Muawiyah, and Abu Kahafa (R.A) accepted Islam at the time of the Conquest of Makkah****nd9-2-2023RY30012023', 0, 0, 0, 1790964566216) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4c33320a2a07a6a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In Which city does Pakistan run an electric public bus?', '{"A":"Karachi","B":"Lahore","C":"Sialkot","D":"Islamabad"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sindh Information Minister Sharjeel Inam Memon on Friday announced the launch of Pakistan''s first electric bus service in Karachi.The bus service is being started from Tank Chowk near Jinnah AvenueThe project will begin with 10 bus stops.ND10-3-2023', 0, 0, 0, 1790964566216) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_588fb185209665e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which Holy Book is called the New Testament?', '{"A":"The Zuboor","B":"The Injeel","C":"The Quran","D":"The Torait"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The New Testament is the second half of the Christian Bible. Christians consider the Old Testament (or Hebrew Bible/Jewish Scriptures) The New Testament is the sacred canon of Scripture.', 0, 0, 0, 1790964566216) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f2cd90e1f25b355c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many parts of each Hadis are there____?', '{"A":"Four","B":"Three","C":"Two","D":"Five"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are the two parts of each of the Hadis: Sanad and Matan1. Sanad (Chain) (Names of Transmitters)2. Matan (Words of Hadith', 0, 0, 0, 1790964566314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_85c6c4b34e8baab7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Deen e Hanif is the old name of____?', '{"A":"Christianity","B":"Islam","C":"Judaism","D":"Hinduism","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The history of Islam concerns the political, social, economic and cultural developments of Islamic civilization. Most historians accept that Islam originated in Mecca and Medina at the start of the 7th century CE.', 0, 0, 0, 1790964566314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f1c9e30113d31f09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the significance of Eid-ul-Fitr in Islam?', '{"A":"Remembrance of the sacrifice of Prophet Ibrahim (AS)","B":"Commemoration of the first revelation of the Quran","C":"Celebration of Prophet Muhammad''s birth","D":"Marking the end of the Ramadan and the fasting period","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Eid al-Fitr also called the "Festival of Breaking the Fast"Eid al-Fitr marks the end of Ramadan,and is celebrated during the first three days of Shawwal,Shawal is the 10th month of the Islamic calendar.Eid ul Fitr first performed on 2 AH***', 0, 0, 0, 1790964566314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_70243400632d26ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How long was ''Toofan-e-Nooh''?', '{"A":"5 months","B":"7 months","C":"6 months","D":"8 months"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Duration of Tofaan e Noah was around 6 months.After the 2242 years of Hazrat Adam A.S the event of Toofan-e-Noah occurred. About 80 people were with him in the boat.Hazrat Noah lived for 950 years.Noah was sent to Iraq.Nooh is called predecessor, Naji Ullah; Shaikh ul Ambiya.Abu ul Bashr Sani is title of Noah.After toofan-e-nooh, the city establish was KhasranAGM 02.05.2023', 0, 0, 0, 1790964566314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e7c3aaeb85afb412', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Against whom the Muslim ruler and Warrior Salahuddin Ayubi fought?', '{"A":"Crusaders","B":"Jews","C":"Hindus","D":"Budhs"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Crusaders صلیبیSalah ud Din Ayubi from Kurd generation.Sultan Salahuddin Ayubi was the legendary warrior who fought the Crusaders for a long time and at last, overcame them and gained victory before he pushed back the joined powers of Europe away from the Holy Land.سلطان صلاح الدین ایوبی وہ عظیم جنگجو تھے جنہوں نے طویل عرصے تک صلیبیوں کا مقابلہ کیا اورآخر کار، ان پر قابو پا لیا اور فتح حاصل کی اس سے پہلے کہ اس نے یورپ کی مشترکہ طاقتوں کو مقدس سرزمین سے پیچھے دھکیل دیا۔', 0, 0, 0, 1790964566314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fda41e8db4b6a134', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Opposite of Tauheed is__________?', '{"A":"Ablees","B":"Idol","C":"Shirk","D":"None of These"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tawhid is the indivisible oneness concept of monotheism in Islam.توحید اسلام میں توحید کا ناقابل تقسیم وحدانیت کا تصور ہے۔', 0, 0, 0, 1790964566314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_502a1fc0d846bda4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The major types of ethical issues include except?', '{"A":"Individual issues","B":"Systematic issues","C":"Corporate issues","D":"Communication issues"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The three major types of ethical issues1. Systematic issues2. Corporate issues 3. Individual issues', 0, 0, 0, 1790964566314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c37a18e96feb95be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In Islam, Obligations are called _____________?', '{"A":"Sunnat","B":"Wajib","C":"Farz","D":"Nafl"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Islam, there are five key obligations (Five Pillars of Islam) upon each Muslim. Five key obligations Consist of Shahadah, Salah, Zakat, Sawm and Hajj.', 0, 0, 0, 1790964566314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7188cbaacd950c47', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the verbal meaning of word “islam”?', '{"A":"Belief on Allah","B":"Confidence of Allah","C":"Obedience of Allah","D":"Worship of Allah"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Islam means "total surrender to the will of Allah".', 0, 0, 0, 1790964566383) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_38093433ce9063e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'To take bath on the day of Eid is:', '{"A":"Mustahabb","B":"Necessary","C":"Sunnah","D":"Farz"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Eid literally means a “festival” or “feast” in Arabic. Doing ghusl on Eid is mustahabb. It was narrated that the Prophet ﷺ did ghusl on the day of Eid. Eid Prayer is WajibEid Salat consists of two ''Rakats'' and six ''Takbirs''.There are two Eid prayers in a year, Eid-ul-fitr and Eid-ul-adha.first Eid Prayer offered by the Holy prophet in 2nd A.HND18-2-2023', 0, 0, 0, 1790964566383) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_fe33092efab952d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first converted in Islam among woman?', '{"A":"Hazrat Zainab (RA)","B":"Hazrat Khadija (RA)","C":"Hazrat Saudeh (RA)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First among women: Hazrat Khadija (RA)Hazrat Khadija (RA) was the wife of the Holy Prophet (PBUH)First among children: Hazrat Ali (RA)First among men: Hazrat Abubakr (RA)', 0, 0, 0, 1790964566383) ON CONFLICT(id) DO NOTHING;
