INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_54215ce6ca20f74c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who suggested to dig a ditch around city of Medina?', '{"A":"Hazrat Ali","B":"Hazrat Omar","C":"Hazrat Salman Farsi","D":"Hazrat Khalid bin Waleed"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On the recommendation of Hazrat SALMAN FARSI, a trench was dug around the base of MEDINA to protect all the approaches. The pagans of MECCA had failed to annihilate the Muslim base of MEDINA in the battle of UHUD, SHAW AL 3 HURA.', 0, 0, 0, 1790964566383) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_88aa35749d5d0d8f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The king of Ajam was send which one to the Hazrat Muhammad?', '{"A":"Habeeb","B":"Kabeeb","C":"Foe","D":"Friend"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790964566383) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c0410107dcdd5bf2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Bab As Silsila is one of the gate of which mosque?', '{"A":"Quba Mosque","B":"Al Aqsa Mosque","C":"Al Azhar Mosque","D":"Umayyad Mosque"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Chain Gate (Bāb as-Silsila) is one of the gates to the Al-Aqsa Mosque compound on the Temple Mount in the Old City of Jerusalem. It was previously known as David''s Gate. As it was named in the early Islamic period Bāb Daud which means David''s Gate.', 0, 0, 0, 1790964566383) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9d136ac1e912a72a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Name the first Muslims who faced the first-ever ordinance of Qazf?', '{"A":"Mistah bin Uthatha","B":"Hannah bint Jahsh","C":"Hassan bin Thabit","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qazf in Islam is imposed on: False accusation of Zina Had –e- Qazaf (false Accusation) is: 80 Lashes Lashes means: کوڑے First Muslim who faced the frst ever ordinance of Qazf: Hasan ibn Sabit, Mustah ibn Asasa, Hamnah ibn Jahsh', 0, 0, 0, 1790964566447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2d5f678e2eefb897', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'At the order of King Bakht Nasr Hazrat Uzair (AS) spent __________ years in jail?', '{"A":"50 years","B":"80 years","C":"70 years","D":"40 years"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At the order of King Bakht Nasr Hazrat Uzair (AS) spent 70 years in jail.The Holy Quran tells the story of Prophet Uzair عَلَيْهِ ٱلسَّلَامُ as a Prophet who died for 100 years and live again', 0, 0, 0, 1790964566447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_6e8f2dfebdf18e3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Masjid Mahabat Khan is located in _______ ?', '{"A":"Kohat","B":"Mardan","C":"Peshawar","D":"Hangu","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid Mahabat Khan is located in:PeshawarMahabat Khan masjid is a 17th-century Mughal-era mosqueMosque Mahabat Khan was built in 1630 and completed in 1670.Mahabat Khan Mosque build by Mughal emperor Shah JahanMosque name is related to Mughal Governor Peshawar “Nawab Mahabat Khan bin Ali Mardan Khan”.Mahabat Khan Mosque destroyed by great fire in June 1895.', 0, 0, 0, 1790964566447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2bd5efe01e4db8d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the meaning of Mann-o-Salwa, in Islam?', '{"A":"Food of Haven","B":"House of Angels","C":"Nama Rock","D":"Door of Haven"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mann-o-Salwa is a type of food that was gifted to Bani Israel (people of Prophet Musa A.S).There were two foods:One was “Mann” and the other was “Salwa”. Mann was a kind of sweetSalwa was a kind of Bird', 0, 0, 0, 1790964566447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b993e895700cf84e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'An action is right if it maximizes good for the self, This phrase refers to?', '{"A":"centralism","B":"self-reliance","C":"egoism","D":"socialism"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NA23-7-2023', 0, 0, 0, 1790964566447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8524e2c2210aa3a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Maryam (AS) migrated to __________ after the birth of Hazrat Essa at Bait’al’Lehm, Jerusalem?', '{"A":"Jordan","B":"Syria","C":"Palestine","D":"Egypt","E":"Iraq"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bethlehem is a Palestinian town south of Jerusalembiblical birthplace of JesusIsa is known as Jesus in Christianity.Hazrat Maryam (AS) migrated to Palestine after the birth of Hazrat Essa at Bait’al’Lehm, Jerusalem.Hazrat Isa (As) was born miraculously to the most admired woman in Islam, Maryam (Mary), who was a virgin.The Injeel book was revealed on Hazrat Esa AsHazrat Isa (As) was Born BethlehemHazrat Isa (As) is known Rohullah', 0, 0, 0, 1790964566447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c64197f8df9446d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ummul Momineen ___________ migrated to Abyssinia and Madina as well.', '{"A":"Hazrat Ayesha (RA)","B":"Hazrat Khadija (RA)","C":"Hazrat Ummay Habiba (RA)","D":"Hazrat Hazrat Hafsa (RA)","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Surah, Anfal mentions the migration of the Holy ProphetThe first migration to Habshah (Abyssinia) took place in 613 A.DThe relatives of Prophet Muhammad (PBUH) in the first migration to Abyssinia were Usman Ghani (R.A) and Ruqaiyah (R.A)There were 12 men and 4 women in the first migration to Abyssinia*************The second migration to Habshah took place in 616 A.DThe group of emigrants'' second migrations time comprised 83 men and 18 to 19 womenUmmul Momineen Ummay Habiba migrated to Abyssinia and Madina as well.', 0, 0, 0, 1790964566447) ON CONFLICT(id) DO NOTHING;
