INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1f32b53e7dc222f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'When did Sir Syed Ahmad set M.A.O High school in Aligarh?', '{"A":"1871","B":"1875","C":"1873","D":"1872","E":"1900"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muhammadan Anglo-Oriental College was founded in 1875 by Sir Syed Ahmad Khan, HistoryHe was initially M.A.O as a primary schoolafter two years it became Muhammadan Anglo-Oriental College.Lord Lytton inaugurated M.A.O College in 1877In MAO Intermediate classes were started in 1878in 1881 B.A. degree classes were added.In 1887, it began to prepare students to enter Thomason College of Civil Engineering at RoorkeeND23-4-2023', 0, 0, 0, 1790964566611) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bfdbf3e7d581879f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Name the Mosque which was famous for the change of Qiblah?', '{"A":"Masjid-e-Nabvi","B":"Masjid-e- Quba","C":"Masjid-e- Qiblatain","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masjid e Qiblatain is a place where Prophet Muhammad (P.B.U.H) change his direction (Qibla) from Masjid e Aqsa to Masjid ul Haraam during the Zohar namaz.Masjid al-Qiblatain is one of the three oldest mosques in Islamic historyMasjid al-Qiblatain has 2 Dome''sMasjid al-Qiblatain has 2 Minare''sit was built by Abraham and IshmaelMasjid al-Qiblatain first Opened: 1987Now the Founder of Masjid al-Qiblatain is : Sawad ibn Ghanam ibn Ka''abND5-2-2023', 0, 0, 0, 1790964566611) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f51e833012e8212f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who is called Saqi-e-Zam Zam?', '{"A":"Hazrat Ali-ul-Murtaza (R.A)","B":"Hazrat Abbas (R.A)","C":"Hazrat Abu Bakar (R.A)","D":"Imam Hussain (R.A)","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HAzrat Abbas(R.A)is called Saqi Zam Zam because he would quench the thirst of Pilgrims (Hijjis).', 0, 0, 0, 1790964566611) ON CONFLICT(id) DO NOTHING;
