INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5214923ec2af64f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which person is remembered as teacher of Madina ____?', '{"A":"Hazrat Ali","B":"Hazrat Umar","C":"Musab Bin Umair","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Musab ibn Umair was a sahabi of Muhammad. From the Banu Abd al-Dar branch of the Quraysh, He embraced Islam in 614 CE and was the first ambassador of Islam. He Died in the Battle of Uhud in 625 CE', 0, 0, 0, 1790964566611) ON CONFLICT(id) DO NOTHING;
