INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f8968897f7c28351', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Duration of Tofaan e Noah was______?', '{"A":"Six months","B":"Nine months","C":"Two months","D":"Three Months"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The duration of Tofaan e Noah was Six monthsBoat of Hazrat Noah (A.S) is called ArcHazrat Nuh (AS) remained in the boat for about six months.Boat of Noah stops in Turkey/ Jabl-e-JodiAfter Toofan-e-Noah, Khasran city was established.About 80 people were with him in the boat.After the 2242 years of Hazrat Adam A.S., the event of Toofan-e-Noah occurred.ND11-2-2023', 0, 0, 0, 1790964566611) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_12fc7f3e1d719fa7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the foster father of Hazrat Muhammad?', '{"A":"Hazrat Haris","B":"Hazrat Hamza","C":"Hazrat Khalid","D":"Hazrat Abbas"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Haris was the foster father of Hazrat Muhammad ***Ḥamzah ibn ʿAbd al-Muṭṭalib was a foster brother, companion, and paternal uncle of the Islamic prophet Muhammad. ****3 foster mothers of the Holy ProphetHazrat Halema Saadia (RA) Hazrat Khola (RA)Hazrat Suwaiba (RA)****Along with Abdullah, foster sister(s) Ameena and Sheema of Muhammad (PBUH) embraced Islam****nd9-2-2023', 0, 0, 0, 1790964566694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e8f48ee1d229384c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which of the following was the biggest idol of Quraysh?', '{"A":"Habl","B":"Uzza","C":"Manaat","D":"None of these."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest idol named in Kaba was Hubal Idol means بت360 idols in Kaba before Islam Hubal was a god worshiped by Quraysh at the Kaaba in Mecca. Muhammad entered Mecca in 630, he destroyed the statue of Hubal from the KaabIdol Sawa was destroyed by Hazrat Umar Ibn Al As R.A.Khalid ibn al-Walid to destroy al-Uzza Al-Mashallal to destroy an idol called Manāt.5 idols are mentioned in Surah NuhThe nation of Noah worshiped 5 idols****ND10-1-2023***ND29-1-2023', 0, 0, 0, 1790964566694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_64bf259b632b0392', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'For how many days Hazrat Younas remained in the abdomen of fish?', '{"A":"50","B":"40","C":"30","D":"60"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Whale fish swallowed Prophet YunusWhale fish swallowed Prophet YunusYunus ibn Matta is a prophet and messenger of God.Yunus is the 10th chapter (surah) of the Quran with 109 verses (ayat).Yunus is named after the prophet Yunus (Jonah)Yunus is the only one of the Bible''s Twelve Minor Prophets ******RY 15-01-2023***ND29-1-2023', 0, 0, 0, 1790964566694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_51a7a919356f41b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the eldest daughter of Hazrat Muhammad (PBUH)?', '{"A":"Hazrat Fatima (R.A)","B":"Hazrat Zainab (R.A)","C":"Hazrat Umm Kulthum (R.A)","D":"Hazrat Ruqayyah (R.A)","E":"None of these"}', 'B', NULL, 0, 0, 0, 1790964566694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d72427960c7c0efa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Name the shahabi who was the first one to martyr in the history of Islam ?', '{"A":"Hazrat Haris bin abi Hala","B":"Hazrat Haris bin Zaid","C":"Hazrat Abbas","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Haris bin abi Hala was first Martyr in MenSumayya became the First Martyr in Islam in Women. Yasir became the ''Second Martyr in Islam'' in Men.RK4-12-22', 0, 0, 0, 1790964566694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8f6c5804e04ea911', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the meaning of Khums?', '{"A":"One fourth","B":"One fifth","C":"One sixth","D":"One seventh","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation one fifth is the meaning of Khums**In Islam, KHUMS خمس refers to the required religious obligation of any Muslim to pay one-fifth of their acquired wealth from certain sources toward specified causes.Khums is different and separate from other Islamic taxes such as zakat and jizya.**Usher and Khums are Two kinds of Tax in Islam,', 0, 0, 0, 1790964566694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3e72c77e44fa3681', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Between whom the Charter of Medina was concluded?', '{"A":"Muslims and Jews","B":"Muslims and non-Arabs","C":"Muslims and Jews and Other non-Muslims","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Constitution of Medina/Charter of Madina میثاق مدینہ Signed: First Hijri/622 AD Between: Muslims, Jews & other non-muslims Clauses: 47Note: The Medina Charter consists of 47 clauses. 23 clause governed the relationship between Muslims, between Ansar and Muhajirin, while the remaining 24 clauses governed the relations of Muslims with non-Muslims, the Jews and others.', 0, 0, 0, 1790964566694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_43db7450997b4714', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Meesaq-e-Madina was signed between?', '{"A":"Muslims & Christians","B":"Muslims & Hindus","C":"Muslims & French","D":"Muslims & Jews"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Constitution of Medina/Charter of Madina میثاق مدینہ Signed: First Hijri/622 AD Between: Muslims, Jews & other non-muslims Clauses: 47Note: The Medina Charter consists of 47 clauses. 23 clause governed the relationship between Muslims, between Ansar and Muhajirin, while the remaining 24 clauses governed the relations of Muslims with non-Muslims, the Jews and others.', 0, 0, 0, 1790964566694) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_077af6af1f8cc748', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first son of Hazrat Muhammad(PBHU)?', '{"A":"Hazrat Abdullah","B":"Hazrat Qasim","C":"Hazrat Ibrahim","D":"Hazrat Abdurrehman","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Qasim was the first (elder) son of Hazrat Muhammad ﷺ and Hazrat KhadijahHe died at the age of only 3 and was buried in Jannat al Mualla in Makkah.Additional Information:Prophet Muhammad ﷺ had three sons and four daughters.1. Hazrat Qasim 2. Hazrat Zainab (RA)3. Hazrat Ruqayyah (RA) 4. Hazrat Umm Kulthum (RA) 5. Hazrat Fatima (RA) 6. Hazrat Abdullah7. Hazrat Ibrahim All of his children were born to Hazrat Khadijah (RA) except one son Ibrahim, who was born to Hazrat Maria al-Qibtiyah (RA).', 0, 0, 0, 1790964566779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0e3f3bd5fc5ba2ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Tragedy of Karbala took place in ________ A.D.', '{"A":"680","B":"670","C":"690","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Karbala was fought on 10 October 680 between the army of the second Umayyad caliph Yazid I and a small army led by Husayn ibn Ali, , at Karbala, Iraq.', 0, 0, 0, 1790964566779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dea2cd28940bcfc4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which Ummul Momineen was the daughter of Abu Sufyan?', '{"A":"Hazrat Ayesha","B":"Hazrat Sofia","C":"Umm e Habiba","D":"Hazrat Zanib"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Umm-ul-Momineen Bibi Umm-e-Habiba Wife of The Holy Prophet (PBUH) Real Name Ramla Daughter of Abu Sufyan Umm-ul-Momineen Mother of believers', 0, 0, 0, 1790964566779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4c07bf2478ac1b35', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Bibi Fatima (RA) was the daughter of Hazrat Muhammad (PBUH) and ________?', '{"A":"Rayhana bint Zayd","B":"Khadija bint Khuwaylid","C":"Zaynab bint Khuzayma","D":"Maria al-Qibtiyya","E":"None of these"}', 'B', NULL, 0, 0, 0, 1790964566779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3ed7fe982e629d4c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who adopted the title of Ameer-ul-Momineen for the first time?', '{"A":"Hazrat Abu Babar (RA)","B":"Hazrat Umar (RA)","C":"Waleed bin Abdil Malik (RA)","D":"Hazrat Ali (RA)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Umar (RA) adopted the title of Ameer-ul-Momineen for the first time.On his accession in 634, Umar ibn Khattab, the Second Rashidun Caliph, was given the title.According to At-Tabaqat al Kubra, When Abu Bakr died, Muslims of the time said: “We are the Mu''minin and Umar is our Amir (Commander).”After this, the title Amir al-Mu''minin was held by Umar ibn Khattab who was also the first one to be given this title.Sh19-8-2023', 0, 0, 0, 1790964566779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7f2816ec30267bf0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Number of hadiths narrated by Hazrat Abu Huraira R.A?', '{"A":"5378","B":"5374","C":"5356","D":"5837","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Hurairah R.A wrote narrations of 5374 AhadisAbu Hurairah continued collecting hadith after the death of: Muhammad from Abu Bakr, Umar, Aisha, Fadl ibn Abbas, Usama ibn Zayd, Ubayy ibn Ka''b, and Ka''b al-Ahbar.**Hazrat Abu Huraira (رضہ) was born in Baha, Yemen. Meaning of Huraira "little cat", "kitten"', 0, 0, 0, 1790964566779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4a6f4715fe02a518', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first Muhajir of Madina?', '{"A":"Hazrat Abu Salam (RA)","B":"Hazrat Zaid bin Haris (RA)","C":"Hazrat Usamah bin Zaid (RA)","D":"Hazrat Abu Hurrairah (RA)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Salam (RA)Abdullah ibn Salam was a Jew in Yathrib who belonged to the Banu Qaynuqa tribe and claimed descent from Joseph.He was widely respected and honored by the people of the city, including those who were not Jewish. He was known for his piety and goodness, righteous conduct and truthfulness.', 0, 0, 0, 1790964566779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0b63e58a83083a02', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What portion of war spoils should be deposited in Bait ul Maal???', '{"A":"117","B":"115","C":"119","D":"116"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bayt al-mal (بيت المال) is an Arabic term that is translated as "House of money" or "House of Wealth." Historically, it was a financial institution responsible for the administration of taxes in Islamic states, particularly in the early Islamic Caliphate', 0, 0, 0, 1790964566779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_9c6c487e4c4af42f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first one to embrace Islam in the land of Yemen?', '{"A":"Hazrat Owais Qarni (RA)","B":"Hazrat Zoaib bin Khabain (RA)","C":"Hazrat Abu Moosa Ashari (RA)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abu Moosa al-Ashari (RA) was indeed a significant early convert to Islam from YemenWhile not the very first individual from Yemen to embrace IslamAppointed as the governors over Yemen by the Prophet (peace be upon him)Serve in that role until the caliphate of Abu Bakr.NOTEHazrat Zoaib bin Kalaib (RA) played a role in the spread of Islam, but the first person to bring Islam to Yemen was not him. Hazrat Muadh ibn Jabal (RA), who was sent by the Prophet Muhammad (PBUH) to Yemen to teach Islam and collect Zakat.', 0, 0, 0, 1790964566862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b887f680fab3298a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Jamia Mosque of Damascus was built by', '{"A":"Hazrat Amir Muawiyya (RA)","B":"Waleed bin Abdul Malik","C":"Marwan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Great Mosque in Damascus, also known as the Umayyad Mosque, is the earliest surviving stone mosque built by the Umayyad Caliph Al Waleed I (Waleed bin Abdul Malik) between 705 and 715 AD.', 0, 0, 0, 1790964566862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_715046bb051c8030', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the eldest son of Hazrat Muhammad ﷺ?', '{"A":"Hazrat Ibrahim","B":"Hazrat Qasim","C":"Hazrat Abdullah","D":"Hazrat Abdurrehman","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Muahmmad SAW had three sons and four daughters. 1) Hazrat Qasim AS 2) Hazrat Abdullah AS 3) Hazrat Ibrahim AS', 0, 0, 0, 1790964566862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8d8ee633bb7c6d4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In Pakistan. Ushr began to be collected from the', '{"A":"Rabi crop of 1982-83","B":"Kharif crop of 1981-82","C":"Rabi crop of 1983-84","D":"None of the above"}', 'A', NULL, 0, 0, 0, 1790964566862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1750c1375e346494', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who killed Musailamah al Kazzab?', '{"A":"Wahshi ibn Harb","B":"Hazrat Khalid Bin Waleed (رضہ)","C":"Hazrat Ali (رضہ)","D":"Hinda","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Musaylimah was killed in the Battle of Yamama by Wahshi ibn Harb, the same man who had killed Muhammad''s uncle, Hazrat Hamza, in the battle of Uhud before his conversion to Islam.', 0, 0, 0, 1790964566862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a15119a783b49c01', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'When was Masjid-e-Nabvi expanded?', '{"A":"29th Hijrah","B":"31st Hijrah","C":"30th Hijrah","D":"32nd Hijrah"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Al-Masjid an-Nabawi is the second mosque built by the Islamic prophet Muhammad in Medinaمسجد نبوی is a mosque in the city of Madina in the Saudi region of the Hejazمسجد نبوی the second largest mosque and the holiest site in IslamThe construction of مسجد نبوی started in: 1 Hijirمسجد نبوی was built by the Holy Prophet (PBUH) himself, next to the house in 622 AD (first Hijri).On 29th Hijrah was مسجد نبوی expandedHeight: 104 mBurials: Abu Bakr, UmarMinaret(s): 10ND13-5-2023', 0, 0, 0, 1790964566862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a1b7134ed17befb0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Shees (A.S.) passed away at the age of:', '{"A":"912 Years","B":"928 Years","C":"948 Years","D":"952 Years"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Shees (A.S.) was the youngest son of Hazrat Adam (A.S.) Hazrat Shees (A.S.) was the second Prophet of Allah. One Day, Hazrat Adam (A.S.) got ill and called his son Shees (A.S.) and said: "O my son! Soon I am going to die as I am not well. The Almighty God sent me a revelation to appoint you as my successor and prophet. Hazrat Shees (A.S.) got ill at the age of 912 and made Anush his successor and ordered him to lead a pious and spiritual life."', 0, 0, 0, 1790964566862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ce503648b25df2c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Name the first Muslim who was fully satisfied in the matter of Treaty of Hudaibiya?', '{"A":"Hazrat Ali (RA)","B":"Hazrat Umar (RA)","C":"Hazrat Usman (RA)","D":"Hazrat Abu Bakar (RA)","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Treaty of Hudaybiyyah was an event that took place during the time of the Islamic prophet Muhammad.It was a pivotal treaty between Muhammad, representing the state of Medina, and the Qurayshi tribe of Mecca The treaty of Hudaibiyah was signed in 628 Januarywhile Sulah Hudaibiya signed for 10 yearsSulah e Hudaibiya is called Fatah Al-Mubeen in Surah Al-FatahTreaty of Hudaybiyyah was concluded in 8th Hijri.', 0, 0, 0, 1790964566862) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c2673843b6565940', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Before Ghazva Uhad, munafiq Abdullah Bin Ubbi leave the battlefield along with his ______ followers.', '{"A":"600","B":"400","C":"500","D":"300","E":"100"}', 'D', NULL, 0, 0, 0, 1790964566951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e3562ca70ef68c9c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Badshahi Masjid at Lahore _______ largest mosque', '{"A":"4th","B":"3rd","C":"6th","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Badshahi Masjid in Lahore is also called the Emperor''s mosqueIt is the third largest mosqueThey were built by Emperor Aurangzeb in 1671,Construction was completed in 1673In 1947, as symbols of the state.Architect: Nawab Zain Yar Jang BahadurOpened: 1673Height: 69 mNumber of minarets: 8', 0, 0, 0, 1790964566951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_706d3703ea9b5f39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which is the most important belief in Islam after Tauheed?', '{"A":"Belief in Aakhirat","B":"Belief in Prophethood","C":"Belief in the Holy Prophet (SAW)","D":"Belief in Angels"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muslims believe that God’s steerage has been revealed to humankind through especially appointed messengers, or prophets, throughout history, beginning with the first man, Adam, who''s taken into consideration the 1st prophet. Twenty-5 of those prophets are noted by way of name within the Quran, consisting of Noah, Abraham, Moses, and Jesus. Muslims believe that Muhammad is the last in this line of prophets, despatched for all humankind with the message of Islam.', 0, 0, 0, 1790964566951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e9b23d20b3ad2d03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Sulah Hudabia was signed in which year', '{"A":"6 hijri","B":"2 hijri","C":"4 hijri","D":"8 hijri"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hudabia is a name of tree.Treaty of Hudabia is written by Hazrat Ali', 0, 0, 0, 1790964566951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ddaf2ebce2df0d2d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Qisas means?', '{"A":"Punishment by causing similar hurt","B":"Forgiveness for Allah","C":"Get money against pain","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Qisas” means punishment by causing similar hurt at same part of the body of convict as he has caused to the victim or he’ casing his death if he has committed qatl-i-amd in exercise of the right of the victim or a wali.Some cases of hurt are usually liable to Qisas; it can be awarded as punishment in the following offences:1. Hurt 2. Qatl-i-Amd', 0, 0, 0, 1790964566951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4d12dcf2c3d48a1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'In US senate which party got majority ___', '{"A":"democratic","B":"Republicans","C":"Federalists","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Majority Party: Federalists (21 seats). Minority Party: Republicans (11 seats). Total Seats: 32.', 0, 0, 0, 1790964566951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_002bed21e296a1f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The first Msjid built by Muhammad is?', '{"A":"Masjid-ul-Haram","B":"Masjid-e-Nabavi","C":"Masjid-e-Aqsa","D":"Masjid e Quba","E":"None of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Very confusing questionدنیا پر پہلی مسجد کا نام مسجد حرام ہےMasjid-ul-Haram is the first masjid on the surface of the earth.****Masjid-e-Quba is the first masjid in history of Islam.اسلام کی پہلی مسجد/محمدﷺ نے جو پہلی مسجد بنائی وہ مسجد قبا تھی', 0, 0, 0, 1790964566951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bdbc8040f800e651', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Belief in the Day of Judgement & the afterlife (Akhira) is the _______ articles of faith.', '{"A":"Third","B":"Fifth","C":"Second","D":"Fourth","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation the meaning of Iman Mufassal:The belief in detailSeven essential beliefs are there in Iman-e-Mafassal1. Faith in God.2. Faith in holy angels.3. Faith in all holy Books.4. Faith in all holy Prophets.5. Faith in the Day of Judgement.6. Faith in everything good or bad is decided by God (Taqdir).7. Faith in life after death.***AGM 02.05.2023', 0, 0, 0, 1790964566951) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ed99e13207f21174', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the youngest son of Hazrat Muhammad ﷺ?', '{"A":"Hazrat Ibrahim","B":"Hazrat Qasim","C":"Hazrat Abdullah","D":"Hazrat Abdurrehman","E":"None of these"}', 'A', NULL, 0, 0, 0, 1790964567012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7ddd765620194c78', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many articles are essential to believe in for a Muslim?', '{"A":"1","B":"5","C":"11","D":"7"}', 'D', NULL, 0, 0, 0, 1790964567012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c02eaed99f1c500e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', '"Usher" means:', '{"A":"one tenth","B":"one fiftth","C":"one third","D":"none of theses"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usher and Khums are Two kinds of Tax in Islam"Usher" means: one-tenth Khums means "one-fifth or 20%"ND28-4-2023', 0, 0, 0, 1790964567012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_48941fc5d9f868f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The marriage between Hazrat Hafsa (رضہ) and Hazrat Muhammad ﷺ took place in____?', '{"A":"2A.H","B":"3 A.H","C":"4 A.H","D":"5 A.H","E":"9 A.H"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Muhammad ﷺ married Hafsah in Shaaban 3AH Hazrat Hafsah was the 4th wife of Hazrat Muhammad.At the time of the marriage, she was 22 years old. Muhammad was 56 years old.She was the daughter of Hazrat Umar (2nd Caliph)She was the First Woman “Hafiz e Quran”', 0, 0, 0, 1790964567012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_eea7cf003a03ba2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Literal meaning of Shirk is ?', '{"A":"To believe in one","B":"To Lie","C":"To Rectify","D":"Partnership"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Islam, shirk is the sin of idolatry are those who practice shirk, which literally means "association" and refers to accepting other gods and divinities alongside .', 0, 0, 0, 1790964567012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f2c1087118289aa3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Jewish tribe Banu Nadir expelled from Madina in which Hijri?', '{"A":"2nd Hijri","B":"3rd Hijri","C":"4th Hijri","D":"5th Hijri"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jewish tribe Banu Nadir expelled from Madina in Rabi’ al-awwal, 4 Hijri. Banu Nadir tribe were Jewish tribes who lived in Medina and were the Prophet allies. Then the battle of Banu Nadir occurred. Prophet sieged Banu Nadir with an army under the commandership of ‘Ali b. Abi Talib. During the siege.', 0, 0, 0, 1790964567012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_1e43e99b624b47cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which one is an article of Faith___?', '{"A":"Shahadat","B":"Zakat","C":"Belief in books","D":"Hajj"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Articles of Faith1 Belief in the Oneness of God. ...2 Belief in the Angels of God. ...3 Belief in the Revelations (Books) of God. ...4 Belief in the Prophets of God. ...5 Belief in the Day of Judgment. ...6 Belief in Premeasurement (Qadar) ...7 Belief in Resurrection after Death.', 0, 0, 0, 1790964567012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_8467eea07f8223e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'City of Basra inhabited in the reign of?', '{"A":"Hazrat Umar Farooq (R.A)","B":"Hazrat Abu Bakar (R.A)","C":"Hazrat Ali (R.A)","D":"Hazrat Usman (RA)","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Second caliph of Islam Hazrat Umar (RA) laid the foundation of Basra in 635 AD.Basra is an Iraqi city located on the Shatt al-Arab.', 0, 0, 0, 1790964567012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e32ed73c172225ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the name of Last Islamic month ..... ?', '{"A":"Rajab","B":"Ramaḍān","C":"Shaʿbān","D":"Dhū al-Ḥijjah."}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is based on a year of 12 months: Muḥarram, Ṣafar, Rabīʿ al-Awwal, Rabīʿ al-Thānī, Jumādā al-Awwal, Jumādā al-Thānī, Rajab, Shaʿbān, Ramaḍān (the month of fasting), Shawwāl, Dhū al-Qaʿdah, and Dhū al-Ḥijjah. Each month begins approximately at the time of the new moon.', 0, 0, 0, 1790964567102) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_063af01a1a298fbb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'At Masjid e ___first Muslim university was established', '{"A":"Nabvi","B":"zarar","C":"Cuba","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Masjid an-Nabawi, also known as Al Haram, is a mosque in the city of Medina. Masjid al Nabawi is the second holiest mosque in Islam.The second largest mosque in the world after the Masjid al-Haram in Mecca.It was built by the Prophet himself, next to the house in 622 AD.ND11-4-2023', 0, 0, 0, 1790964567102) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a3fd54cf260bb9c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ahadith were collected by the:', '{"A":"Prophet Muhammad (PBUH)","B":"Companions of the Holy Prophet","C":"Hazrat Umar (RA)","D":"All of the these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ahadith were collected by the Companions of the Holy ProphetThe first people to hear hadith were the companions who preserved it and then conveyed it to those after them. Then the generation following them received it, thus conveying it to those after them and so on.*********RY 13-12-2022', 0, 0, 0, 1790964567102) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c9c400bcb1c8a8d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was Abul Masakeen?', '{"A":"Hazrat Jafar Tyar","B":"Hazrat Ali","C":"Hazrat Umar","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ja''far was the third son of Abu Talib ibn Abdul Muttalib and Fatima bint Asad, hence a cousin of Muhammad.', 0, 0, 0, 1790964567102) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d4e3100cbc915d4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the first female shaheed of Islam?', '{"A":"Hazrat Samiya","B":"Hazrat Khadija","C":"Hazrat zaniab","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sumayyah bint Khabbāṭ was the mother of Ammar ibn Yasir and first member of the Ummah.', 0, 0, 0, 1790964567102) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_56df4cf41a4a2aa5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the name of first woman Muslim?', '{"A":"Hazrat Khdija","B":"Hazrat Zainab","C":"Hazrat Fatima","D":"Hazrat Ayesha"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Khadija belonged to the Quraish tribe. She is also known as “Khatijatul Kubra”Prophert ﷺ married her when he was 25 years old and she was 40 years old. .She passed away at the age of 65 years on the 11th of Ramadaan – 10 years after the first revelation. *******', 0, 0, 0, 1790964567102) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f2bd9b728dfda50d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazart Ali (R.A) married Hazart Fatma (R.A) in______________?', '{"A":"623 A.D","B":"624 A.D","C":"622 A.D","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazart Fatma (رضہ) marriage took place on Friday, 1 Dhu al-Hijjah AH 2 (24 February AD 624) when Fatimah was nine years old, although some sources say she was 18 years old. Hazrat Ali was 21', 0, 0, 0, 1790964567102) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_84bbb4cbd7bae425', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Qasim was the son of Hazrat Muhammad ﷺ and _______.', '{"A":"Hazrat Khadija","B":"Rayhana bint Zayd","C":"Zaynab bint Khuzayma","D":"Maria al-Qibtiyya","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Qasim was the first (elder) son of Hazrat Muhammad ﷺ and Hazrat KhadijahHe died at the age of only 3 and was buried in Jannat al Mualla in Makkah.Additional Information:All of his children were born to Hazrat Khadijah (RA) except one son Ibrahim, who was born to Hazrat Maria al-Qibtiyah (RA).Prophet Muhammad ﷺ had three sons and four daughters.Hazrat Khadija (RA) was the first wife of Hazrat Muhammad ﷺAt the time of the marriage, Hazrat Khadijah was 40 years old. Muhammad was 25 years old.', 0, 0, 0, 1790964567102) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3a23bffde3e92858', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What was the kunnlyyat of Hazrat abu bakar (ra)?', '{"A":"Abu Hamza","B":"Abu Abdullah","C":"Abu Jaffer","D":"Abu Sufeiman","E":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Bakr was a sahabi, one of the companions of Muhammad and the first Caliph of Islam. He was also Muhammad''s father-in-law through Aisha. His real name was Abdullah or Abul-Kaaba and Abu Bakr was his kunya.', 0, 0, 0, 1790964567188) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7f676c48ededa67e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Friend of Khadija (رضہ) ____ carried message of Nikah ?', '{"A":"Aimen","B":"Kulsoom","C":"Fatima","D":"Sobia","E":"Nafeesa"}', 'E', NULL, 0, 0, 0, 1790964567188) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_614049cf7809e799', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many days are prohibited for fasting throughout the Year?', '{"A":"1","B":"3","C":"5","D":"7","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fasting is haraam on the following days1.Two days of Eid (`Eidul Fitr and `Eidul Adha.).2.Three days after Eid al-Adha (the 11th, 12th and 13th of Dhu’l-Hijjah) also called al-Tashreeq.Fasting was the 4th fundamental pillar of IslamFasting (Soam) is declared as armorFasting was made obligatory in 10th Shaban,2 A.HThe function of fasting is To Make the Sacrifice of Body and SoulSaum (fasting) resembles Hadith with a Shield5 days are prohibited ممنوع for fasting throughout the YearND08-3-2023', 0, 0, 0, 1790964567188) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_698cd030b4f94272', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who was the second son of Hazrat Muhammad ﷺ?', '{"A":"Hazrat Ibrahim","B":"Hazrat Al-Qasim","C":"Hazrat Abdullah","D":"Hazrat Abdurrehman"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Abdullah was the Second son of Hazrat Muhammad and Hazrat KhadijjaHe has died at the age of 4He was buried at Jannat al-Mualla Mecca, ArabiaAdditional Information:Prophet Muhammad ﷺ had three sons and four daughters.1. Hazrat Qasim 2. Hazrat Zainab (RA)3. Hazrat Ruqayyah (RA) 4. Hazrat Umm Kulthum (RA) 5. Hazrat Fatima (RA) 6. Hazrat Abdullah7. Hazrat Ibrahim All of his children were born to Hazrat Khadijah (RA) except one son Ibrahim, who was born to Hazrat Maria al-Qibtiyah (RA).', 0, 0, 0, 1790964567188) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dc50165a3a5473ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', '_______ was the only Ummul Momineen who was not buried in Jannatul Baqi.', '{"A":"Hazrat Maria Qibtiya (RA)","B":"Hazrat Safia (RA)","C":"Hazrat Ayesha (RA)","D":"Hazrat Khadija (RA)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Khadijah bint Khuwaylid, was the first wife and first follower of the Islamic prophet Muhammad. Hazrat Khadija (RA) was buried in Makkah.Khadijah died in "Ramadan of the year 10 after the Prophethood", i.e., in November AD 619. Muhammad later called this tenth year "the Year of Sorrow", as his uncle and protector Abu Talib also died at this time.', 0, 0, 0, 1790964567188) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_70ed9ec35419f92c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Yousaf (AS) was put into the jail by the king of Egypt. He remained behind the bars for', '{"A":"2 years","B":"5 years","C":"7 years","D":"12 years"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Yousaf (AS) was put into the jail by the king of Egypt. He remained behind the bars for 5 years.Hazrat Yousaf (AS) remained in the well for 3 DAYS.', 0, 0, 0, 1790964567188) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_3f8c2a7365597f82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Ghaseel ul Malaika is the title of_____?', '{"A":"Hazrat Saad (رضہ)","B":"Hazrat Abu Dahana (رضہ)","C":"Hazrat Abu Talha (رضہ)","D":"Hazrat Hanzala (رضہ)","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hanzala earned the title of Ghaseel al-Malāʾika or the one cleansed by the angelsHanzala Ibn Abi Amir belonged to the Banu Aus tribe of the Ansar. Hanzala was just 24 years old when he died in the Battle of Uhud Hanzala was one of the companions of the Islamic prophet Muhammad***agm.5.3.23ND17-7-2023', 0, 0, 0, 1790964567188) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_07658d0681e4cc47', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Abu Tarab is the title of ____?', '{"A":"Hazrat umar","B":"Hazrat Ali","C":"Abubakr","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Turab or Father of Soil, is a title attributed to Ali ibn Abi Talib, the fourth Sunni Caliph.Asad ullah is also title of Hazrat Ali', 0, 0, 0, 1790964567188) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_4eeaa2422c1ffee6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Islamic Calendar starts from _____?', '{"A":"Hijri","B":"After birth of Muhammad (PBUH)","C":"After death of Hazrat Umar (RA)","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Islamic lunar calendar, which begins its count from the Islamic New Year in 622 CE Islamic lunar calendar has only 354 or 355 days in its year."Hijri calendar was started in16 HijriIslamic Calendar starts from HijriIslamic calendar established by: Hazrat Umar (R.A)*****', 0, 0, 0, 1790964567270) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_98307320c65bc51b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Tauheed is an _____ language word.', '{"A":"Urdu","B":"Persian","C":"Arabic","D":"Sindhi","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tauheed is an Arabic language word. توحید اسلام میں توحید کا ناقابل تقسیم وحدانیت کا تصور ہے۔', 0, 0, 0, 1790964567270) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_73471eebb6648c85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The first Charter of Human Rights is?', '{"A":"U.N. Charter","B":"International Charter","C":"French Constitution","D":"Khutba-Hajjat-ul-Vida","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Charter of human rights is Khutba-hajj at-ul-Vida. ..Khutbah Hajjatul-Wida` is in fact the First Human Charter which was given by the Messenger of Allah (صلی اللہ علیہ و آلہ وسلم) to the whole of mankind on February, 632 AD.The Hajj (pilgrimage) is known as ''Hajjatul Wida'' or the Farewell Hajj.The Prophet of Allah (PBUH) delivered a historical speech (Khutbah) on the ninth of Dhul Hijjah (the 12th and last month of the lunar year) on Friday; 10 years after Hijrah in the Uranah Valley of mount Arafat during the farewell pilgrimage.', 0, 0, 0, 1790964567270) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_5e97a2a798eb267d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Who is called Umm-Ul-Masakeen?', '{"A":"Hazrat Zainab (R.A)","B":"Hazrat Ayesha (R.A)","C":"Hazrat Khadija (R.A)","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Umm-ul-Masakeen was the title given to one of the wives of the Prophet (SAW): Hazrat Zainab benet Khuzima (RA)Umm-ul-Masakeen means mother of the poor.Hazrat Zainab benet Khuzima (RA) was the fifth wife of MuhammadZaynab was the first of Muhammad’s wives who were not from the Quraysh tribe. Zaynab''s marriage to Muhammad lasted only a few months. She died at the age of about thirty. Muhammad carried her to Jannat al-Baqi', 0, 0, 0, 1790964567270) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_0c7442204cc48b38', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many farz in Wazu?', '{"A":"4","B":"2","C":"3","D":"7"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation in Al-Ma''idah the order of WUZU is mention***وضو کے چار فرائض ہیں۔نمبر 1: چہرہ دھونانمبر 2: دونوں ہاتھوں کو کہینیوں تک دھونانمبر 3: چوتھائی سر کا مسح کرنانمبر 4:پاوں کا ٹخنیوں سمیت دھونا****RY30012023****nd9-2-2023******VU FIA CONSTABLE PAPER 2021', 0, 0, 0, 1790964567270) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7a1d6d90d3539a7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'A Muslim female is confined in:', '{"A":"8 sheets","B":"6 sheets","C":"5 sheets","D":"3 sheets"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Muslim female is confined in 05 dressed sheets.A Muslim male is coffined in 03 dressed sheets.', 0, 0, 0, 1790964567270) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2beee66c2e374ae9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'After a ------------- month at Madina, the change of Qibla occurred.', '{"A":"18","B":"19","C":"20","D":"21"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The change of Qibla occurred after the 18 months of migration of the Holy Prophet (PBUH) to Madina the change of Qibla occurred In 624 AD During the Zohar prayer, the change of Qibla happened.In 2 Hijri years, Qibla has changedMasjid al-Qiblatain is one of the three oldest mosques in Islamic historyThe first Qibla Muslims prayed for is Al-Aqsa mosque المسجد الأقصى (Bait Al-Maqdis بيت المقدس)***ND29-1-2023', 0, 0, 0, 1790964567270) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_2e1070d0b9d66cae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Umer (R.A) embraced islam in ___________ Nabvi.', '{"A":"5th","B":"6th","C":"7th","D":"8th","E":"9th"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Umar ibn al-Khaṭṭāb was the second Rashidun caliph, Umar ibn al-Khaṭṭāb ruled from August 634 until his assassination in 644.Umar was a senior companion and father-in-law of the Islamic prophet Muhammad. he became the first Muslim to openly pray at the Kaaba. Umar participated in almost all battlesAt the time he embraced Islam, Hazrat Umar R.A. was about 32 years old. He was born in 584 AD.Hazrat Umar R.A. embraced Islam in 616 AD.***ND29-1-2023', 0, 0, 0, 1790964567270) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_90d5024857c60f10', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Name The First Female False Prophetess?', '{"A":"Sajah","B":"Hiba","C":"Hinza","D":"None of them","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sajah was one of a series of people (including her future husband) who claimed prophet hood in 7th-century Arabia and was also the only female claiming to be a prophetess during the Wars of Apostasy in Early Islamic Period.AGM 15-01-2023', 0, 0, 0, 1790964567355) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dc66805ce9601766', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Muhammad (PBUH) was born about three thousand years, after:', '{"A":"Hazrat Ismaeel (A.S)","B":"Hazrat Moosa (A.S)","C":"Hazrat Eessaa (A.S)","D":"Hazrat Ibrahim (A.S"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Muhammad (PBUH) was born about three thousand years, after Hazrat Ibrahim (A.S) in 571AD at MakkahHazarat Muhammad S.A.W was born in 571 A.D.Last Prophet of Allah.His name derives from the Arabic verb hamada, meaning "to praise, to glorify." He was the first and only son of Abd Allah bin Al-Muttalib and Amina bint Wahb. Mother: Hazarat AminaFather : Hazrat AbdullahRK4-12-22', 0, 0, 0, 1790964567355) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_eeceaebed5ef6c2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hurrirah means a', '{"A":"Goat","B":"Ant","C":"Camel","D":"Cat"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cat is a domestic species of small carnivorous mammal.Abu Hurayra was one of the companions of the Islamic prophet MuhammadAbu Hurairah continued collecting hadith after the death of Muhammad from Abu Bakr, Umar, Aisha, Fadl ibn Abbas, Usama ibn Zayd, Ubayy ibn Ka''b, and Ka''b al-Ahbar5,374 Hadiths quoted by Abu Hurairah', 0, 0, 0, 1790964567355) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a2f053972e7fff76', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Which of the following was the first Non-Arab War?', '{"A":"Battle of Khaybar","B":"Battle of the Trench","C":"Battle of Mutah","D":"Battle of Hunayn"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Battle of Mutah was the first Non-Arab War***The Battle of Mu''tah took place in September 629The battle of Mauta was the first non-Arab War.3000 was the number of Muslims at the battle of Ditch.More than a thousand men engaged in the battle***The Battle of Badr was the first large-scale confrontation between Muslims and the Quraysh', 0, 0, 0, 1790964567355) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_ffecd19d988677d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What is the meaning of Niyyat?', '{"A":"Taking the responsibility","B":"keeping in view","C":"making the intention","D":"look forward"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation making the intention is the meaning of Niyyat***Niyyat is an Islamic concept: the intention in one''s heart to do an act for the sake of God (Allah)', 0, 0, 0, 1790964567355) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b5f97d4bae560d98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'How many are the Holy Books?', '{"A":"five","B":"three","C":"two","D":"four"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are four Holy BooksThe Torat revealed to MusaThe Zabur revealed to Dawud The Injil (Gospel) revealed to Isa The Quran was revealed to Muhammad.', 0, 0, 0, 1790964567355) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_a536d207324c073e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The fountain of metal copper flowed as a miracle for?', '{"A":"Hazart Yaqoob(AS)","B":"Hazart Dawood (AS)","C":"Hazart Sulaiman (AS)","D":"none of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Mountain of Metal copper flowed for Hazrat Sulaiman (A.S) as a miracle***The Mausoleum of Prophet Sulaiman (PBUH) can be found within the compound of Masjid-Al-AqsaHazrat Sulaiman (AS)Prophet Sulaiman (PBUH) was the youngest son of Prophet Dawood (PBUH) and was born in Jerusalem.Allah (SWT) bestowed him with many gifts, including the ability to speak to animals and control Jinns', 0, 0, 0, 1790964567355) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_633fb8c3ef1823de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The Hijri Calender was innovated by:', '{"A":"Hazrat AbuBakar (RA)","B":"Hazrat Ali (RA)","C":"Hazrat Usman (RA)","D":"Hazrat Umar (RA)","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Before advent of Islam, the calendar year in Arabia was: Anno Domini Islamic Calendar starts from: Hijri Islamic calendar established by: Hazrat Umar (R.A)', 0, 0, 0, 1790964567355) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_bf86548fd7d7ea4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Hazrat Bibi Fatima (RA) was buried in_________?', '{"A":"Kufa","B":"Karbala","C":"Makkah","D":"Jannat-ul-Baqi","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fatima (RA) was buried in Jannat-ul-BaqiFatima died in 11/632, within six months of Muhammad''s death.She is 4th daughter and 5th child of Hazrat Muhammad and Hazrat Khadija (RA)She was born in Makkah on the 20th of Jumada al-Thaniya 18 B.H.Title of Bibi Fatima is: Tahira, Zahra, Umm Abiha, Sayyidatu nisa-alamin and al-BatulShe married Hazrat Ali RA ( 4th Rashidun Caliphs) in 2 AHShe had 2 sons and 2 daughters: Imam HussainImam HassanZaynab Umm Kulthum', 0, 0, 0, 1790964567426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_c59aa72fb96d5282', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Modaraba relates to ?', '{"A":"Investment","B":"One person invests money and the other invests labour and experience","C":"Both persons invest money and labour","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Modaraba company is a unique and prime mode of non-interest Islamic financial system.It is a form of financial contract in which one party, the investor (Rab-ul-mal) entrusts money to another party, the financial manager (Mudarib) for the purpose of carrying out a business (Modaraba).', 0, 0, 0, 1790964567426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_12e7dc42bdd60915', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'What significant event took place on ‘Vesak day’ according to the Buddhist?', '{"A":"Lord Buddha was born","B":"Lord Buddha got enlightenment","C":"Lord Buddha died","D":"All of these","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Buddhists around the world celebrate the birth, enlightenment and death of Gautama Buddha on Vesak Day, a time of joy, peace and reflection.', 0, 0, 0, 1790964567426) ON CONFLICT(id) DO NOTHING;
