INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_500c19991cb55071', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'The religious book of the Aryans is known as', '{"A":"the Yugas","B":"The Vedas","C":"The Rekhlas","D":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aryan faith turned primarily based ordinarily on historic texts known as Vedas, which recorded and defined spiritual practices, beliefs, and philosophies. There are 4 Vedas: the Rig Veda, the Sama Veda, the Yajur Veda, and the Atharva Veda', 0, 0, 0, 1790964567426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_dd24cc83be20f33e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'Give the total number of Prophets (AS)?', '{"A":"125000","B":"123000","C":"126000","D":"124000"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 25 prophets are mentioned within the Qur''an, although some accept as true with there had been 124 000. some prophets were given holy books to pass directly to humankind. Muslims accept as true with the prophets taught the same basic ideas, most significantly perception in one god.', 0, 0, 0, 1790964567426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_b4d234979589773b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_general', 'When Persia become Iran?', '{"A":"1935","B":"1940","C":"1925","D":"1920"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1935, the Iranian government requested that all countries with which it had diplomatic relations call the country by its Persian name, Iran.', 0, 0, 0, 1790964567426) ON CONFLICT(id) DO NOTHING;